# Security
security = HTTPBearer()
optional_security = HTTPBearer(auto_error=False)

# Auth Helper Functions
async def get_current_user(credentials: HTTPAuthorizationCredentials = Depends(security)):
    """Get current authenticated user from JWT token"""
    token = credentials.credentials
    payload = verify_token(token)
    
    if not payload:
        raise HTTPException(status_code=401, detail="Invalid or expired token")
    
    user_id = payload.get("user_id")
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token payload")
    
    # Legacy `users` collection (brokers / sub-brokers / legacy clients).
    user = await db.users.find_one({"id": user_id}, {"_id": 0, "password_hash": 0, "pin_hash": 0})
    if user:
        # For sub_brokers (MFD/RIA / Real Estate partners), legacy `users`
        # rows often lack `broker_id` / `created_by`. Hydrate from the
        # partner collections so downstream APIs (e.g. POST /api/data-gathering/family
        # which requires a broker_id) keep working.
        if user.get('role') == 'sub_broker' and not (user.get('broker_id') or user.get('created_by')):
            for coll in ("Mfd_Ria_Partner", "Real_Estate_Partner"):
                partner = await db[coll].find_one({"id": user_id}, {"_id": 0, "created_by": 1, "broker_id": 1})
                if partner:
                    parent = partner.get('created_by') or partner.get('broker_id')
                    if parent:
                        user['broker_id'] = parent
                        user['created_by'] = parent
                    break
        return user
    
    # 3-way login flow (Login_Credentials) — Private Investors + Partners
    # carry their *source row id* as `user_id` in the JWT, which maps to
    # `Private_Investor_Indian_Passport.id` / `Private_Investor_Foreign_Passport.id`
    # / `Mfd_Ria_Partner.id` / `Real_Estate_Partner.id`. Expose a synthetic
    # user dict so downstream endpoints can consume it uniformly.
    login_type = payload.get("login_type")
    login_id = payload.get("login_id")
    role = payload.get("role") or {
        "broker": "broker",
        "private_investor_indian": "client",
        "private_investor_foreign": "client",
        "mfd_ria_partner": "sub_broker",
        "real_estate_partner": "re_broker",
    }.get(login_type or "", "client")
    
    coll_for_type = {
        "broker": "users",
        "private_investor_indian": "Private_Investor_Indian_Passport",
        "private_investor_foreign": "Private_Investor_Foreign_Passport",
        "mfd_ria_partner": "Mfd_Ria_Partner",
        "real_estate_partner": "Real_Estate_Partner",
    }.get(login_type or "")
    
    source_row = None
    if coll_for_type:
        source_row = await db[coll_for_type].find_one({"id": user_id}, {"_id": 0})
    
    if source_row:
        # For MFD/RIA + Real Estate partners, surface their parent broker so
        # downstream APIs (e.g. POST /api/data-gathering/family) that require
        # a non-null broker_id keep working under the 3-way login JWT.
        parent_broker_id = source_row.get('created_by') or source_row.get('broker_id')
        return {
            "id": user_id,
            "role": role,
            "name": source_row.get("name") or source_row.get("full_name") or source_row.get("client_name") or login_id or "",
            "email": source_row.get("email", ""),
            "phone": source_row.get("phone", "") or source_row.get("mobile", ""),
            "pan": source_row.get("pan") or source_row.get("pan_number") or login_id or "",
            "login_id": login_id,
            "login_type": login_type,
            "broker_id": parent_broker_id,
            "created_by": parent_broker_id,
            "client_id": user_id if role == "client" else None,
        }
    
    raise HTTPException(status_code=401, detail="User not found")


async def get_current_user_optional(credentials: HTTPAuthorizationCredentials = Depends(optional_security)):
    """Get current user if token provided, otherwise return None"""
    if not credentials:
        return None
    
    try:
        token = credentials.credentials
        payload = verify_token(token)
        
        if not payload:
            return None
        
        user_id = payload.get("user_id")
        if not user_id:
            return None
        
        user = await db.users.find_one({"id": user_id}, {"_id": 0, "password_hash": 0, "pin_hash": 0})
        return user
    except:
        return None


# Create API Router
api_router = APIRouter(prefix="/api")


# Auth Routes
@api_router.post("/auth/login-step1")
async def login_step1(login: LoginStep1):
    """Step 1: Verify login ID and Password, return temp token.
    `Login_Credentials` is the single source of truth — every authenticable
    entity (broker, MFD/RIA partner, Real Estate partner, Private Investor
    Indian/Foreign Passport) has a row there. The legacy `users` collection
    is no longer consulted for credential checks."""
    cred = await _lc_verify_login(db, login.pan, login.password)
    if not cred:
        raise HTTPException(status_code=401, detail="Invalid Login ID or Password")
    temp_token = create_access_token(
        data={
            "login_id": cred["login_id"],
            "login_type": cred["login_type"],
            "reference_id": cred.get("reference_id"),
            "step": 1,
            "source": "login_credentials",
        },
        expires_delta=timedelta(minutes=5),
    )
    return {"temp_token": temp_token}


@api_router.post("/auth/login-step2")
async def login_step2(login: LoginStep2):
    """Step 2: Verify PIN and return full access token"""
    # Verify temp token
    payload = verify_token(login.temp_token)
    
    if not payload or payload.get("step") != 1:
        raise HTTPException(status_code=401, detail="Invalid or expired temporary token")

    # Branch on token source: new Login_Credentials flow (Private Investors +
    # Partners) vs. legacy `users` flow (brokers / sub-brokers).
    if payload.get("source") == "login_credentials":
        login_id = payload.get("login_id")
        login_type = payload.get("login_type")
        reference_id = payload.get("reference_id")
        if not (login_id and login_type):
            raise HTTPException(status_code=401, detail="Invalid temporary token")

        if not await _lc_verify_pin(db, login_id, login_type, login.pin):
            raise HTTPException(status_code=401, detail="Invalid PIN")

        # Map login_type → role + fetch display data from source collection.
        role_map = {
            "broker": "broker",
            "private_investor_indian": "client",
            "private_investor_foreign": "client",
            "mfd_ria_partner": "sub_broker",
            "real_estate_partner": "re_broker",
        }
        role = role_map.get(login_type, "client")
        source_coll = _LC_META[login_type]["collection"]
        source_row = await db[source_coll].find_one(
            {"id": reference_id}, {"_id": 0}
        ) if reference_id else None

        access_token = create_access_token(
            data={
                "user_id": reference_id or login_id,
                "role": role,
                "login_id": login_id,
                "login_type": login_type,
            }
        )
        # Expose parent broker_id so frontend flows that send `user.broker_id`
        # (e.g. Data Gathering family creation) work for partners.
        parent_broker_id = (source_row or {}).get("created_by") or (source_row or {}).get("broker_id")
        user_payload = {
            "id": reference_id or login_id,
            "role": role,
            "login_id": login_id,
            "login_type": login_type,
            "name": (source_row or {}).get("name")
                or (source_row or {}).get("full_name")
                or (source_row or {}).get("client_name")
                or login_id,
            "email": (source_row or {}).get("email", ""),
            "broker_id": parent_broker_id,
            "created_by": parent_broker_id,
        }
        return {"token": access_token, "user": user_payload}

    # Login_Credentials is the only source of truth — reject any other token.
    raise HTTPException(status_code=401, detail="Invalid temporary token")


# Password Reset Routes
@api_router.post("/auth/forgot-password")
async def forgot_password(request: PasswordResetRequest, background_tasks: BackgroundTasks):
    """Request password reset - sends email with reset token for broker, sub-broker, or client"""
    pan_upper = request.pan.upper()
    email_lower = request.email.lower()
    
    user = None
    user_type = None
    
    # Check brokers first
    user = await db.users.find_one({
        "pan": pan_upper,
        "email": email_lower
    }, {"_id": 0})
    if user:
        user_type = "broker"
    
    # Check sub-brokers
    if not user:
        user = await db.sub_brokers.find_one({
            "pan": pan_upper,
            "email": email_lower
        }, {"_id": 0})
        if user:
            user_type = "sub_broker"
    
    # Check clients
    if not user:
        user = await db.Private_Investor.find_one({
            "pan_number": pan_upper,
            "email": email_lower
        }, {"_id": 0})
        if user:
            user_type = "client"
    
    if not user:
        # Don't reveal if user exists or not for security
        return {"message": "If your PAN and email match our records, you will receive a reset link"}
    
    # Create reset token (expires in 1 hour)
    reset_token = create_access_token(
        data={"user_id": user['id'], "user_type": user_type, "type": "password_reset"},
        expires_delta=timedelta(hours=1)
    )
    
    # Store reset token in database
    await db.password_resets.insert_one({
        "user_id": user['id'],
        "user_type": user_type,
        "token": reset_token,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "used": False
    })
    
    # Send reset email
    try:
        background_tasks.add_task(
            send_password_reset_link_email,
            user['email'],
            user['name'],
            reset_token
        )
    except Exception as e:
        logger.error(f"Error sending reset email: {e}")
    
    return {"message": "If your PAN and email match our records, you will receive a reset link"}


@api_router.post("/auth/reset-password")
async def reset_password(request: PasswordResetConfirm):
    """Reset password and PIN using reset token for broker, sub-broker, or client"""
    # Verify token
    payload = verify_token(request.reset_token)
    
    if not payload or payload.get("type") != "password_reset":
        raise HTTPException(status_code=400, detail="Invalid or expired reset token")
    
    user_id = payload.get("user_id")
    user_type = payload.get("user_type", "broker")  # Default to broker for backward compatibility
    
    # Check if token was already used
    reset_record = await db.password_resets.find_one({
        "user_id": user_id,
        "token": request.reset_token,
        "used": False
    })
    
    if not reset_record:
        raise HTTPException(status_code=400, detail="Reset token already used or invalid")
    
    # Validate new password and PIN
    if len(request.new_password) < 6:
        raise HTTPException(status_code=400, detail="Password must be at least 6 characters")
    
    if len(request.new_pin) != 4 or not request.new_pin.isdigit():
        raise HTTPException(status_code=400, detail="PIN must be exactly 4 digits")
    
    # Update password and PIN based on user type
    password_hash = get_password_hash(request.new_password)
    pin_hash = get_password_hash(request.new_pin)
    
    if user_type == "broker":
        await db.users.update_one(
            {"id": user_id},
            {"$set": {
                "password_hash": password_hash,
                "pin_hash": pin_hash
            }}
        )
    elif user_type == "sub_broker":
        await db.sub_brokers.update_one(
            {"id": user_id},
            {"$set": {
                "password_hash": password_hash,
                "pin_hash": pin_hash
            }}
        )
    elif user_type == "client":
        await db.Private_Investor.update_one(
            {"id": user_id},
            {"$set": {
                "password_hash": password_hash,
                "pin_hash": pin_hash
            }}
        )
    
    # Mark token as used
    await db.password_resets.update_one(
        {"_id": reset_record["_id"]},
        {"$set": {"used": True}}
    )
    
    return {"message": "Password and PIN reset successfully. You can now login with your new credentials."}



@api_router.get("/auth/verify-setup-token/{token}")
async def verify_setup_token(token: str):
    """Verify if a setup token is valid for new client password setup"""
    # Find client with this setup token
    client = await db.Private_Investor.find_one(
        {"setup_token": token},
        {"_id": 0, "id": 1, "name": 1, "email": 1, "pan_number": 1, "setup_token_expiry": 1, "password_set": 1}
    )
    
    if not client:
        raise HTTPException(status_code=400, detail="Invalid setup token")
    
    # Check if password already set
    if client.get('password_set'):
        raise HTTPException(status_code=400, detail="Password has already been set. Please use forgot password if you need to reset.")
    
    # Check if token expired
    if client.get('setup_token_expiry'):
        expiry = datetime.fromisoformat(client['setup_token_expiry'].replace('Z', '+00:00'))
        if datetime.now(timezone.utc) > expiry:
            raise HTTPException(status_code=400, detail="Setup link has expired. Please contact support.")
    
    return {
        "valid": True,
        "name": client.get('name'),
        "login_id": client.get('pan_number'),
        "message": "Your User ID is your PAN number"
    }


@api_router.post("/auth/setup-password")
async def setup_new_client_password(data: dict):
    """Set password and PIN for new client using setup token"""
    token = data.get('token')
    new_password = data.get('new_password')
    new_pin = data.get('new_pin')
    
    if not token or not new_password or not new_pin:
        raise HTTPException(status_code=400, detail="Token, password, and PIN are required")
    
    # Find client with this setup token
    client = await db.Private_Investor.find_one({"setup_token": token})
    
    if not client:
        raise HTTPException(status_code=400, detail="Invalid setup token")
    
    # Check if password already set
    if client.get('password_set'):
        raise HTTPException(status_code=400, detail="Password has already been set")
    
    # Check if token expired
    if client.get('setup_token_expiry'):
        expiry = datetime.fromisoformat(client['setup_token_expiry'].replace('Z', '+00:00'))
        if datetime.now(timezone.utc) > expiry:
            raise HTTPException(status_code=400, detail="Setup link has expired")
    
    # Validate password and PIN
    if len(new_password) < 6:
        raise HTTPException(status_code=400, detail="Password must be at least 6 characters")
    
    if len(new_pin) != 4 or not new_pin.isdigit():
        raise HTTPException(status_code=400, detail="PIN must be exactly 4 digits")
    
    # Update client with password and PIN
    password_hash = get_password_hash(new_password)
    pin_hash = get_password_hash(new_pin)
    
    await db.Private_Investor.update_one(
        {"setup_token": token},
        {"$set": {
            "password_hash": password_hash,
            "pin_hash": pin_hash,
            "password_set": True,
            "setup_token": None,  # Clear the token after use
            "setup_token_expiry": None,
            "password_set_at": datetime.now(timezone.utc).isoformat()
        }}
    )
    
    return {
        "success": True,
        "message": "Password and PIN set successfully. You can now login with your PAN number as User ID.",
        "login_id": client.get('pan_number')
    }



@api_router.get("/auth/verify-reset-token/{token}")
async def verify_reset_token(token: str):
    """Verify if a reset token is valid"""
    payload = verify_token(token)
    
    if not payload or payload.get("type") != "password_reset":
        raise HTTPException(status_code=400, detail="Invalid or expired reset token")
    
    # Check if token was already used
    reset_record = await db.password_resets.find_one({
        "token": token,
        "used": False
    })
    
    if not reset_record:
        raise HTTPException(status_code=400, detail="Reset token already used")
    
    return {"valid": True, "message": "Token is valid"}


# Customer Self-Registration
@api_router.post("/auth/customer-signup")
async def customer_signup(signup: CustomerSignup):
    """Allow customers to sign up directly"""
    # Validate PAN format (basic validation)
    pan = signup.pan.upper().strip()
    if len(pan) != 10:
        raise HTTPException(status_code=400, detail="PAN must be exactly 10 characters")
    
    # Check if PAN already exists
    existing_user = await db.users.find_one({"pan": pan})
    if existing_user:
        raise HTTPException(status_code=400, detail="PAN already registered. Please login or reset your password.")
    
    # Check if email already exists
    existing_email = await db.users.find_one({"email": signup.email.lower()})
    if existing_email:
        raise HTTPException(status_code=400, detail="Email already registered")
    
    # Validate password
    if len(signup.password) < 6:
        raise HTTPException(status_code=400, detail="Password must be at least 6 characters")
    
    # Validate PIN
    if len(signup.pin) != 4 or not signup.pin.isdigit():
        raise HTTPException(status_code=400, detail="PIN must be exactly 4 digits")
    
    # Create user account
    user_id = str(uuid.uuid4())
    user = {
        "id": user_id,
        "pan": pan,
        "name": signup.name.strip(),
        "email": signup.email.lower().strip(),
        "phone": signup.phone.strip(),
        "password_hash": get_password_hash(signup.password),
        "pin_hash": get_password_hash(signup.pin),
        "role": "client",
        "is_active": True,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "self_registered": True
    }
    
    await db.users.insert_one(user)
    
    # Create corresponding client record
    client_id = str(uuid.uuid4())
    client = {
        "id": client_id,
        "name": signup.name.strip(),
        "email": signup.email.lower().strip(),
        "phone": signup.phone.strip(),
        "pan": pan,
        "city": "",
        "is_active": True,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "created_by": "self_registration"
    }
    
    await db.Private_Investor.insert_one(client)
    
    # Link user to client
    await db.users.update_one(
        {"id": user_id},
        {"$set": {"client_id": client_id}}
    )
    
    return {
        "message": "Account created successfully! You can now login.",
        "user": {
            "id": user_id,
            "pan": pan,
            "name": signup.name,
            "email": signup.email,
            "role": "client"
        }
    }


# OTP-based signup endpoints
@api_router.post("/auth/send-otp")
async def send_signup_otp(request: OTPRequest, background_tasks: BackgroundTasks):
    """Send OTP to email for signup verification"""
    email = request.email.lower().strip()
    
    # Check if email already registered
    existing_user = await db.users.find_one({"email": email})
    if existing_user:
        raise HTTPException(status_code=400, detail="Email already registered. Please login.")
    
    # Generate 6-digit OTP
    otp = ''.join([str(random.randint(0, 9)) for _ in range(6)])
    
    # Store OTP in database with expiry (10 minutes)
    otp_record = {
        "id": str(uuid.uuid4()),
        "email": email,
        "otp": otp,
        "name": request.name.strip(),
        "phone": request.phone.strip(),
        "created_at": datetime.now(timezone.utc).isoformat(),
        "expires_at": (datetime.now(timezone.utc) + timedelta(minutes=10)).isoformat(),
        "verified": False
    }
    
    # Remove any existing OTP for this email
    await db.otp_records.delete_many({"email": email})
    await db.otp_records.insert_one(otp_record)
    
    # Send OTP email using existing email service
    try:
        from email_service import send_otp_email
        background_tasks.add_task(send_otp_email, email, request.name, otp)
    except Exception as e:
        logger.error(f"Error sending OTP email: {e}")
        # For development, log the OTP
        logger.info(f"OTP for {email}: {otp}")
    
    return {"message": "OTP sent to your email. Please check your inbox.", "email": email}


@api_router.post("/auth/verify-otp")
async def verify_signup_otp(request: OTPVerify):
    """Verify OTP and complete signup as a lead"""
    email = request.email.lower().strip()
    
    # Find OTP record
    otp_record = await db.otp_records.find_one({
        "email": email,
        "otp": request.otp,
        "verified": False
    })
    
    if not otp_record:
        raise HTTPException(status_code=400, detail="Invalid OTP. Please try again.")
    
    # Check if OTP expired
    expires_at = datetime.fromisoformat(otp_record['expires_at'].replace('Z', '+00:00'))
    if datetime.now(timezone.utc) > expires_at:
        await db.otp_records.delete_one({"id": otp_record['id']})
        raise HTTPException(status_code=400, detail="OTP has expired. Please request a new one.")
    
    # Mark OTP as verified
    await db.otp_records.update_one(
        {"id": otp_record['id']},
        {"$set": {"verified": True, "verified_at": datetime.now(timezone.utc).isoformat()}}
    )
    
    # Create lead record for verified signup
    lead = {
        "id": str(uuid.uuid4()),
        "client_id": None,
        "client_name": request.name.strip(),
        "client_pan": "",
        "client_mobile": request.phone.strip(),
        "client_email": email,
        "client_city": "",
        "opportunity_type": "general",
        "opportunity_id": None,
        "product_name": "Verified Signup",
        "product_code": "",
        "investment_amount": None,
        "interest_percentage": None,
        "notes": "Verified via email OTP",
        "status": "verified",
        "source": "otp_signup",
        "shared_by_id": None,
        "shared_by_name": None,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "updated_at": datetime.now(timezone.utc).isoformat(),
        "email_verified": True,
        "verified_at": datetime.now(timezone.utc).isoformat()
    }
    
    # Check if lead already exists
    existing_lead = await db.leads.find_one({"client_email": email})
    if existing_lead:
        await db.leads.update_one(
            {"id": existing_lead['id']},
            {"$set": {
                "client_name": request.name.strip(),
                "client_mobile": request.phone.strip(),
                "status": "verified",
                "email_verified": True,
                "verified_at": datetime.now(timezone.utc).isoformat(),
                "updated_at": datetime.now(timezone.utc).isoformat()
            }}
        )
        lead_id = existing_lead['id']
    else:
        await db.leads.insert_one(lead)
        lead_id = lead['id']
    
    return {
        "message": "Email verified successfully! Our team will contact you shortly.",
        "verified": True,
        "lead_id": lead_id
    }


@api_router.post("/auth/resend-otp")
async def resend_signup_otp(request: OTPRequest, background_tasks: BackgroundTasks):
    """Resend OTP to email"""
    email = request.email.lower().strip()
    
    # Check rate limiting - max 3 OTPs per email per hour
    one_hour_ago = (datetime.now(timezone.utc) - timedelta(hours=1)).isoformat()
    recent_otps = await db.otp_records.count_documents({
        "email": email,
        "created_at": {"$gte": one_hour_ago}
    })
    
    if recent_otps >= 3:
        raise HTTPException(status_code=429, detail="Too many OTP requests. Please try again later.")
    
    # Generate new OTP
    otp = ''.join([str(random.randint(0, 9)) for _ in range(6)])
    
    # Store new OTP
    otp_record = {
        "id": str(uuid.uuid4()),
        "email": email,
        "otp": otp,
        "name": request.name.strip(),
        "phone": request.phone.strip(),
        "created_at": datetime.now(timezone.utc).isoformat(),
        "expires_at": (datetime.now(timezone.utc) + timedelta(minutes=10)).isoformat(),
        "verified": False
    }
    
    await db.otp_records.insert_one(otp_record)
    
    # Send OTP email
    try:
        from email_service import send_otp_email
        background_tasks.add_task(send_otp_email, email, request.name, otp)
    except Exception as e:
        logger.error(f"Error sending OTP email: {e}")
        logger.info(f"OTP for {email}: {otp}")
    
    return {"message": "New OTP sent to your email.", "email": email}


# ==================== ROLE PERMISSIONS ENDPOINTS ====================

@api_router.get("/role-permissions")
async def get_role_permissions(current_user: dict = Depends(get_current_user)):
    """Get all role permissions. Broker can view and modify, others can only view their own permissions."""
    # Get permissions from database or use defaults
    permissions_doc = await db.role_permissions.find_one({"type": "master"})
    
    if permissions_doc:
        permissions = permissions_doc.get("permissions", DEFAULT_ROLE_PERMISSIONS)
    else:
        # Initialize with defaults
        await db.role_permissions.insert_one({
            "type": "master",
            "permissions": DEFAULT_ROLE_PERMISSIONS,
            "updated_at": datetime.now(timezone.utc).isoformat(),
            "updated_by": None
        })
        permissions = DEFAULT_ROLE_PERMISSIONS
    
    # Remove MongoDB _id field
    return {
        "permissions": permissions,
        "user_role": current_user.get("role"),
        "can_edit": current_user.get("role") == "broker"
    }

@api_router.put("/role-permissions")
async def update_role_permissions(
    data: RolePermissionsUpdate,
    current_user: dict = Depends(get_current_user)
):
    """Update role permissions. Only brokers can modify permissions."""
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can modify role permissions")
    
    # Validate permissions structure
    for perm in data.permissions:
        if not all(key in perm for key in ["feature", "action", "broker", "sub_broker", "client"]):
            raise HTTPException(status_code=400, detail="Invalid permission structure")
    
    # Update in database
    await db.role_permissions.update_one(
        {"type": "master"},
        {
            "$set": {
                "permissions": data.permissions,
                "updated_at": datetime.now(timezone.utc).isoformat(),
                "updated_by": current_user.get("id")
            }
        },
        upsert=True
    )
    
    return {"message": "Role permissions updated successfully", "permissions": data.permissions}

@api_router.get("/role-permissions/check/{feature}/{action}")
async def check_permission(
    feature: str,
    action: str,
    current_user: dict = Depends(get_current_user)
):
    """Check if current user has permission for a specific feature and action"""
    user_role = current_user.get("role", "client")
    
    # Get permissions
    permissions_doc = await db.role_permissions.find_one({"type": "master"})
    permissions = permissions_doc.get("permissions", DEFAULT_ROLE_PERMISSIONS) if permissions_doc else DEFAULT_ROLE_PERMISSIONS
    
    # Find matching permission
    for perm in permissions:
        if perm.get("feature") == feature and perm.get("action") == action:
            has_permission = perm.get(user_role, False)
            return {
                "feature": feature,
                "action": action,
                "user_role": user_role,
                "has_permission": has_permission,
                "description": perm.get("description", "")
            }
    
    # Default to False if permission not found
    return {
        "feature": feature,
        "action": action,
        "user_role": user_role,
        "has_permission": False,
        "description": "Permission not defined"
    }

@api_router.get("/role-permissions/user")
async def get_user_permissions(current_user: dict = Depends(get_current_user)):
    """Get all permissions for the current user based on their role"""
    user_role = current_user.get("role", "client")
    
    # Get permissions
    permissions_doc = await db.role_permissions.find_one({"type": "master"})
    permissions = permissions_doc.get("permissions", DEFAULT_ROLE_PERMISSIONS) if permissions_doc else DEFAULT_ROLE_PERMISSIONS
    
    # Filter permissions for user's role
    user_permissions = {}
    for perm in permissions:
        feature = perm.get("feature")
        action = perm.get("action")
        has_permission = perm.get(user_role, False)
        
        if feature not in user_permissions:
            user_permissions[feature] = {}
        user_permissions[feature][action] = has_permission
    
    return {
        "user_role": user_role,
        "permissions": user_permissions
    }

@api_router.post("/role-permissions/reset")
async def reset_role_permissions(current_user: dict = Depends(get_current_user)):
    """Reset role permissions to default. Only brokers can reset."""
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can reset role permissions")
    
    await db.role_permissions.update_one(
        {"type": "master"},
        {
            "$set": {
                "permissions": DEFAULT_ROLE_PERMISSIONS,
                "updated_at": datetime.now(timezone.utc).isoformat(),
                "updated_by": current_user.get("id"),
                "reset_at": datetime.now(timezone.utc).isoformat()
            }
        },
        upsert=True
    )
    
    return {"message": "Role permissions reset to default", "permissions": DEFAULT_ROLE_PERMISSIONS}


async def register_user(user_data: UserCreate):
    """Register a new user (broker or sub-broker)"""
    # Check if PAN already exists
    existing = await db.users.find_one({"pan": user_data.pan.upper()})
    if existing:
        raise HTTPException(status_code=400, detail="PAN already registered")
    
    # Validate role
    if user_data.role not in ["broker", "sub_broker"]:
        raise HTTPException(status_code=400, detail="Invalid role")
    
    # Create user
    user = {
        "id": str(uuid.uuid4()),
        "pan": user_data.pan.upper(),
        "name": user_data.name,
        "email": user_data.email,
        "phone": user_data.phone,
        "password_hash": get_password_hash(user_data.password),
        "pin_hash": get_password_hash(user_data.pin),
        "role": user_data.role,
        "created_at": datetime.now(timezone.utc).isoformat()
    }
    
    await db.users.insert_one(user)
    
    return {
        "id": user['id'],
        "pan": user['pan'],
        "name": user['name'],
        "role": user['role']
    }


