@api_router.get("/mfd-ria/interests")
async def get_sub_broker_interests(current_user: dict = Depends(get_current_user)):
    """Get interests/leads from clients linked to this sub-broker"""
    if current_user['role'] != 'sub_broker':
        raise HTTPException(status_code=403, detail="Only sub-brokers can access this endpoint")
    
    # Get client IDs linked to this sub-broker
    client_ids = await db.Private_Investor.distinct("id", {"linked_subbroker_id": current_user['id']})
    
    # Also check for clients where sub_broker_id matches
    client_ids_alt = await db.Private_Investor.distinct("id", {"sub_broker_id": current_user['id']})
    client_ids = list(set(client_ids + client_ids_alt))
    
    if not client_ids:
        return []
    
    # Get leads from these clients (check multiple possible fields)
    leads = await db.leads.find(
        {"$or": [
            {"client_id": {"$in": client_ids}},
            {"sub_broker_id": current_user['id']},
            {"shared_by_id": current_user['id']}
        ]},
        {"_id": 0}
    ).sort("created_at", -1).to_list(1000)
    
    # Enrich with client info and opportunity details
    for lead in leads:
        client = await db.Private_Investor.find_one({"id": lead.get("client_id")}, {"_id": 0, "name": 1, "email": 1, "mobile": 1, "pan": 1, "pan_number": 1})
        if client:
            lead['client_name'] = client.get('name', 'Unknown')
            lead['client_email'] = client.get('email', '')
            lead['client_phone'] = client.get('mobile', '')
            lead['client_pan'] = client.get('pan') or client.get('pan_number', '')
        
        # Get opportunity details if missing
        if not lead.get('opportunity_name') and lead.get('opportunity_id'):
            if lead.get('opportunity_type') == 'bond':
                opp = await db.Ncd_Master.find_one({"id": lead['opportunity_id']}, {"_id": 0, "name": 1})
                lead['opportunity_name'] = opp.get('name') if opp else lead.get('product_name', 'Unknown')
            else:
                opp = await db.Real_Estate_Master.find_one({"id": lead['opportunity_id']}, {"_id": 0, "building_name": 1, "unit_no": 1})
                if opp:
                    lead['opportunity_name'] = f"{opp.get('building_name', '')} - Unit {opp.get('unit_no', '')}"
                else:
                    lead['opportunity_name'] = lead.get('product_name', 'Unknown')
        elif not lead.get('opportunity_name'):
            lead['opportunity_name'] = lead.get('product_name', 'Unknown')
    
    return leads


@api_router.post("/mfd-ria/bulk-upload/clients")
async def bulk_upload_clients_by_subbroker(
    file: UploadFile = File(...),
    current_user: dict = Depends(get_current_user)
):
    """Bulk upload clients by sub-broker - all entries go to broker for approval"""
    if current_user['role'] != 'sub_broker':
        raise HTTPException(status_code=403, detail="Only sub-brokers can use this endpoint")
    
    if not file.filename.endswith('.csv'):
        raise HTTPException(status_code=400, detail="Only CSV files are accepted")
    
    content = await file.read()
    csv_text = content.decode('utf-8')
    
    import csv
    from io import StringIO
    
    reader = csv.DictReader(StringIO(csv_text))
    
    success_count = 0
    error_count = 0
    errors = []
    
    # Get broker ID (the broker who approved this sub-broker)
    partner = await db.Mfd_Ria_Partner.find_one({"id": current_user['id']}, {"_id": 0, "created_by": 1})
    broker_id = partner.get("created_by") if partner else None
    
    for row_num, row in enumerate(reader, start=2):  # Start from 2 (1 is header)
        try:
            # Validate required fields
            name = row.get('name', '').strip()
            email = row.get('email', '').strip()
            pan = row.get('pan', '').strip().upper()
            mobile = row.get('mobile', '').strip()
            
            if not name:
                errors.append({"row": row_num, "message": "Name is required"})
                error_count += 1
                continue
            
            if not email:
                errors.append({"row": row_num, "message": "Email is required"})
                error_count += 1
                continue
            
            if not pan or len(pan) != 10:
                errors.append({"row": row_num, "message": "Valid 10-digit PAN is required"})
                error_count += 1
                continue
            
            # Check for duplicate PAN
            existing_user = await db.users.find_one({"pan": pan})
            if existing_user:
                errors.append({"row": row_num, "message": f"PAN {pan} already exists"})
                error_count += 1
                continue
            
            existing_client = await db.Private_Investor.find_one({"pan": pan})
            if existing_client:
                errors.append({"row": row_num, "message": f"Client with PAN {pan} already exists"})
                error_count += 1
                continue
            
            # Generate default credentials (stored for later use after approval)
            default_password = ''.join(random.choices(string.ascii_letters + string.digits, k=10))
            default_pin = ''.join(random.choices(string.digits, k=4))
            
            # Create client record with pending_approval status
            client_id = str(uuid.uuid4())
            client_data = {
                "id": client_id,
                "name": name,
                "email": email,
                "pan": pan,
                "pan_number": pan,
                "mobile": mobile,
                "phone": mobile,
                "passport_type": "indian",
                "residency_status": "indian",
                "linked_subbroker_id": current_user['id'],
                "broker_id": broker_id,
                "created_by_subbroker": True,
                "approval_status": "pending_approval",
                "password_hash": get_password_hash(default_password),
                "pin_hash": get_password_hash(default_pin),
                "default_password": default_password,  # Store for email after approval
                "default_pin": default_pin,
                "is_active": False,
                "onboarding_step": 1,
                "created_at": datetime.now(timezone.utc).isoformat()
            }
            
            # Add optional fields
            for field in ['date_of_birth', 'father_husband_name', 'occupation', 'city', 'state', 'pincode']:
                if row.get(field):
                    client_data[field] = row.get(field).strip()
            
            await db.Private_Investor_Indian_Passport.insert_one(client_data)
            success_count += 1
            
        except Exception as e:
            logger.error(f"Error processing row {row_num}: {str(e)}")
            errors.append({"row": row_num, "message": str(e)})
            error_count += 1
    
    logger.info(f"Sub-broker {current_user['id']} bulk uploaded {success_count} clients for approval, {error_count} errors")
    
    return {
        "success_count": success_count,
        "error_count": error_count,
        "errors": errors[:20]  # Return first 20 errors
    }


@api_router.post("/mfd-ria/private-investors")
async def create_client_by_subbroker(
    client_data: dict,
    current_user: dict = Depends(get_current_user)
):
    """Create a new client (requires broker approval)"""
    if current_user['role'] != 'sub_broker':
        raise HTTPException(status_code=403, detail="Only sub-brokers can use this endpoint")
    
    # Get the broker associated with this sub-broker
    partner = await db.Mfd_Ria_Partner.find_one({"id": current_user['id']}, {"_id": 0})
    if not partner:
        raise HTTPException(status_code=404, detail="Partner not found")
    
    broker_id = partner.get('created_by') or partner.get('broker_id')
    
    # Determine PAN - could be pan_number or pan
    pan = client_data.get('pan_number', client_data.get('pan', '')).upper()
    passport_type = client_data.get('passport_type', 'indian')
    original_pan = pan
    is_role_overlap = False
    login_id = pan
    
    # Check if PAN/Passport already exists
    if passport_type == 'indian' and pan:
        existing = await db.Private_Investor.find_one({"$or": [{"pan": pan}, {"pan_number": pan}]})
        if existing:
            raise HTTPException(status_code=400, detail="Client with this PAN already exists")
        
        # ROLE OVERLAP HANDLING: Check if PAN exists as sub-broker OR broker
        existing_user = await db.users.find_one({"pan": pan})
        if existing_user:
            if existing_user.get('role') in ['sub_broker', 'broker']:
                # Create client login with PAN + "1" suffix for role overlap
                login_id = f"{pan}1"
                is_role_overlap = True
                
                # Verify the modified login_id doesn't exist
                existing_modified = await db.users.find_one({"pan": login_id})
                if existing_modified:
                    raise HTTPException(
                        status_code=400,
                        detail=f"Client login for {existing_user.get('role')} PAN {pan} already exists (Login: {login_id})"
                    )
            else:
                raise HTTPException(status_code=400, detail="User with this PAN already exists")
    elif passport_type == 'foreign':
        passport_number = client_data.get('passport_number', '').upper()
        if passport_number:
            existing = await db.Private_Investor.find_one({"passport_number": passport_number})
            if existing:
                raise HTTPException(status_code=400, detail="Client with this passport number already exists")
            login_id = passport_number
    
    # Generate client ID
    client_id = str(uuid.uuid4())
    
    # Generate temporary password and PIN
    temp_password = ''.join(random.choices(string.ascii_letters + string.digits, k=8))
    temp_pin = ''.join(random.choices(string.digits, k=4))
    
    # Create client with pending approval status - include ALL fields from broker modal
    new_client = {
        "id": client_id,
        "pan": login_id,  # Login ID (PAN or PAN+1 for role overlap)
        "pan_number": pan,  # Original PAN stored separately
        "original_pan": original_pan,
        "is_role_overlap": is_role_overlap,
        "name": client_data.get('name', ''),
        "email": client_data.get('email', ''),
        "phone": client_data.get('mobile', client_data.get('phone', '')),
        "mobile": client_data.get('mobile', client_data.get('phone', '')),
        "password_hash": get_password_hash(temp_password),
        "pin_hash": get_password_hash(temp_pin),
        "default_password": temp_password,
        "default_pin": temp_pin,
        "role": "client",
        "broker_id": broker_id,
        "linked_subbroker_id": current_user['id'],
        "created_by_subbroker": True,
        "approval_status": "pending_approval",
        "created_at": datetime.now(timezone.utc).isoformat(),
        "updated_at": datetime.now(timezone.utc).isoformat(),
        "is_active": False,
        
        # Passport & Residency
        "passport_type": passport_type,
        "country_of_residency": client_data.get('country_of_residency', ''),
        "passport_number": client_data.get('passport_number', ''),
        "emirates_id": client_data.get('emirates_id', ''),
        "emirates_id_expiry": client_data.get('emirates_id_expiry', ''),
        "passport_valid_from": client_data.get('passport_valid_from', ''),
        "passport_valid_until": client_data.get('passport_valid_until', ''),
        "passport_country_of_issue": client_data.get('passport_country_of_issue', ''),
        
        # Opportunities
        "opportunities": client_data.get('opportunities', []),
        
        # Indian Bank Details (for bonds)
        "demat_account_no": client_data.get('demat_account_no', ''),
        "bank_name": client_data.get('bank_name', ''),
        "account_number": client_data.get('account_number', ''),
        "branch": client_data.get('branch', ''),
        "ifsc_code": client_data.get('ifsc_code', ''),
        "account_type": client_data.get('account_type', ''),
        
        # International Bank Details (for NRIs)
        "intl_bank_name": client_data.get('intl_bank_name', ''),
        "intl_account_number": client_data.get('intl_account_number', ''),
        "intl_iban": client_data.get('intl_iban', ''),
        "intl_swift_code": client_data.get('intl_swift_code', ''),
        
        # Additional Details
        "occupation": client_data.get('occupation', ''),
        "date_of_birth": client_data.get('date_of_birth', ''),
        "father_husband_name": client_data.get('father_husband_name', ''),
        
        # Address
        "address_line1": client_data.get('address_line1', ''),
        "address_line2": client_data.get('address_line2', ''),
        "city": client_data.get('city', ''),
        "state": client_data.get('state', ''),
        "country": client_data.get('country', ''),
        "pincode": client_data.get('pincode', ''),
        
        # Nominee Details
        "nominee_name": client_data.get('nominee_name', ''),
        "nominee_dob": client_data.get('nominee_dob', ''),
        "nominee_mobile": client_data.get('nominee_mobile', ''),
        "nominee_relationship": client_data.get('nominee_relationship', ''),
        
        # UCCs
        "ucc_list": client_data.get('ucc_list', []),
        "bond_allocations": [],
        "notes": client_data.get('notes', '')
    }
    
    await db.Private_Investor.insert_one(new_client)
    
    # Clean response
    response_client = {k: v for k, v in new_client.items() if k != '_id'}
    
    return {
        "message": "Client created successfully. Pending broker approval.",
        "client": response_client,
        "default_password": temp_password,
        "default_pin": temp_pin,
        "requires_approval": True
    }


