@api_router.post("/broker/approve-client/{client_id}")
async def approve_client(
    client_id: str,
    action: str = Query(..., description="approve or reject"),
    current_user: dict = Depends(get_current_user)
):
    """Approve or reject a client created by sub-broker"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can approve clients")
    
    client = await db.Private_Investor.find_one({"id": client_id}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    
    if client.get('broker_id') != current_user['id']:
        raise HTTPException(status_code=403, detail="Not authorized to approve this client")
    
    if action == "approve":
        await db.Private_Investor.update_one(
            {"id": client_id},
            {
                "$set": {
                    "approval_status": "approved",
                    "is_active": True,
                    "approved_at": datetime.now(timezone.utc).isoformat(),
                    "approved_by": current_user['id']
                }
            }
        )
        
        # Welcome email intentionally suppressed here. Brokers can trigger
        # credential distribution manually from the Private Investors tab
        # via the "Resend Credentials" / "Reset Password" actions.
        if False and client.get('email'):
            from email_service import send_welcome_email_client
            broker = await db.users.find_one({"id": current_user['id']}, {"_id": 0})
            
            # Get sub-broker name if client is linked to one
            subbroker_name = None
            if client.get('linked_subbroker_id'):
                subbroker = await db.Mfd_Ria_Partner.find_one({"id": client.get('linked_subbroker_id')}, {"_id": 0})
                if not subbroker:
                    subbroker = await db.sub_brokers.find_one({"id": client.get('linked_subbroker_id')}, {"_id": 0})
                if subbroker:
                    subbroker_name = subbroker.get('name')
            
            send_welcome_email_client(
                client_name=client.get('name', ''),
                client_email=client.get('email'),
                pan=client.get('pan', ''),
                password=client.get('default_password', '') or client.get('temp_password', ''),
                pin=client.get('default_pin', '') or client.get('temp_pin', ''),
                broker_name=broker.get('name', 'Your Broker') if broker else 'Your Broker',
                subbroker_name=subbroker_name
            )
        
        return {"message": "Client approved successfully", "status": "approved"}
    
    elif action == "reject":
        await db.Private_Investor.update_one(
            {"id": client_id},
            {
                "$set": {
                    "approval_status": "rejected",
                    "rejected_at": datetime.now(timezone.utc).isoformat(),
                    "rejected_by": current_user['id']
                }
            }
        )
        return {"message": "Client rejected", "status": "rejected"}
    
    else:
        raise HTTPException(status_code=400, detail="Invalid action. Use 'approve' or 'reject'")


