class ApprovalLogEntry(BaseModel):
    """Model for creating approval log entries"""
    entity_type: str  # 'client' or 'reinvestment'
    entity_id: str
    action: str  # 'submitted', 'broker_approved', 'broker_rejected', 'client_approved', 'client_rejected', 'api_submitted'
    notes: Optional[str] = None


async def create_approval_log(
    entity_type: str,
    entity_id: str,
    action: str,
    actor_id: str,
    actor_role: str,
    actor_name: str,
    details: dict = None,
    notes: str = None
):
    """Helper to create approval log entries"""
    log_entry = {
        "id": str(uuid.uuid4()),
        "entity_type": entity_type,
        "entity_id": entity_id,
        "action": action,
        "actor_id": actor_id,
        "actor_role": actor_role,
        "actor_name": actor_name,
        "details": details or {},
        "notes": notes,
        "created_at": datetime.now(timezone.utc).isoformat()
    }
    await db.approval_logs.insert_one(log_entry)
    return log_entry


@api_router.get("/approval-logs")
async def get_approval_logs(
    entity_type: Optional[str] = None,
    entity_id: Optional[str] = None,
    limit: int = 100,
    current_user: dict = Depends(get_current_user)
):
    """Get approval logs based on user role"""
    query = {}
    
    if current_user['role'] == 'broker':
        # Broker sees all logs for their entities
        broker_id = current_user['id']
        # Get all clients and sub-brokers under this broker
        client_ids = await db.Private_Investor.distinct("id", {"broker_id": broker_id})
        partner_ids = await db.Mfd_Ria_Partner.distinct("id", {"created_by": broker_id})
        query["$or"] = [
            {"actor_id": broker_id},
            {"entity_id": {"$in": client_ids + partner_ids}},
            {"details.broker_id": broker_id}
        ]
    elif current_user['role'] == 'sub_broker':
        # Sub-broker sees logs for their submissions
        query["$or"] = [
            {"actor_id": current_user['id']},
            {"details.sub_broker_id": current_user['id']}
        ]
    elif current_user['role'] == 'client':
        # Client sees logs for their approvals
        client = await db.Private_Investor.find_one({"user_id": current_user['id']})
        if client:
            query["entity_id"] = client['id']
    
    if entity_type:
        query["entity_type"] = entity_type
    if entity_id:
        query["entity_id"] = entity_id
    
    logs = await db.approval_logs.find(query, {"_id": 0}).sort("created_at", -1).limit(limit).to_list(limit)
    return logs


@api_router.get("/approval-workflow/pending")
async def get_pending_approvals_workflow(current_user: dict = Depends(get_current_user)):
    """Get all pending approvals for the approval workflow page"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can view pending approvals")

    async def _resolve_client(client_id: str) -> dict:
        """Look up a private investor across all three collections.
        Indian / foreign passport investors live in their own collections,
        and a plain `Private_Investor.find_one` misses them — the row gets
        labelled "Unknown" on the approvals page. Iterate until a match is
        found so the broker always sees the actual client name + PAN."""
        if not client_id:
            return {}
        for coll in (
            "Private_Investor",
            "Private_Investor_Indian_Passport",
            "Private_Investor_Foreign_Passport",
        ):
            inv = await db[coll].find_one(
                {"id": client_id},
                {"_id": 0, "name": 1, "pan_number": 1, "passport_type": 1}
            )
            if inv:
                return inv
        return {}

    # Get pending clients from sub-brokers
    pending_clients = await db.Private_Investor.find(
        {
            "broker_id": current_user['id'],
            "approval_status": "pending_approval"
        },
        {"_id": 0}
    ).to_list(100)
    
    # Enrich with sub-broker info
    for client in pending_clients:
        if client.get('linked_subbroker_id'):
            sub_broker = await db.Mfd_Ria_Partner.find_one(
                {"id": client['linked_subbroker_id']},
                {"_id": 0, "name": 1, "partner_code": 1}
            )
            client['sub_broker_name'] = sub_broker.get('name') if sub_broker else 'Unknown'
            client['sub_broker_code'] = sub_broker.get('partner_code') if sub_broker else ''
    
    # Get pending reinvestments from sub-brokers (from reinvestment_submissions)
    pending_reinvestments_submissions = await db.reinvestment_submissions.find(
        {
            "broker_id": current_user['id'],
            "broker_approval_status": "pending"
        },
        {"_id": 0}
    ).to_list(100)
    
    # Also get pending reinvestments from reinvestment_logs with pending_broker_approval status
    # Get all sub-brokers under this broker (check both broker_id and created_by fields)
    sub_brokers = await db.Mfd_Ria_Partner.find({
        "$or": [
            {"broker_id": current_user['id']},
            {"created_by": current_user['id']}
        ]
    }, {"_id": 0, "id": 1}).to_list(1000)
    sub_broker_ids = [sb['id'] for sb in sub_brokers]
    
    pending_reinvestments_logs = []
    if sub_broker_ids:
        # First get the main investment entries (with UCC and real portfolio)
        main_logs = await db.reinvestment_logs.find(
            {
                "tagged_by": {"$in": sub_broker_ids},
                "approval_status": "pending_broker_approval",
                # Only include entries with UCC and portfolio tagged
                "$or": [
                    {"ucc": {"$exists": True, "$ne": None, "$ne": ""}},
                    {"target_ucc": {"$exists": True, "$ne": None, "$ne": ""}}
                ],
                "portfolio": {"$exists": True, "$ne": None, "$ne": "", "$ne": "none"}
            },
            {"_id": 0}
        ).to_list(100)
        
        # Get unique cashflow_ids from main logs
        main_cashflow_ids = list(set(log.get('cashflow_id') for log in main_logs if log.get('cashflow_id')))
        
        # Now get ALL allocations for these cashflows (including 'none' portfolio for bifurcation)
        # IMPORTANT: Don't filter by approval_status here - we need ALL allocations for the cashflow
        # to display the full bifurcation/grouping correctly
        if main_cashflow_ids:
            all_logs = await db.reinvestment_logs.find(
                {
                    "cashflow_id": {"$in": main_cashflow_ids}
                },
                {"_id": 0}
            ).sort([("cashflow_id", 1), ("allocation_index", 1)]).to_list(500)
            pending_reinvestments_logs = all_logs
        else:
            pending_reinvestments_logs = main_logs
    
    # Also check holding_cashflows directly for pending_broker_approval
    # Only include properly tagged entries (with UCC and portfolio)
    pending_cashflows = []
    if sub_broker_ids:
        pending_cashflows = await db.holding_cashflows.find(
            {
                "tagged_by": {"$in": sub_broker_ids},
                "approval_status": "pending_broker_approval",
                # Only include entries with UCC/target_ucc and portfolio_category
                "$or": [
                    {"target_ucc": {"$exists": True, "$ne": None, "$ne": ""}},
                ],
                "portfolio_category": {"$exists": True, "$ne": None, "$ne": ""}
            },
            {"_id": 0}
        ).to_list(100)
        
        # Enrich cashflows with client and bond info
        for cf in pending_cashflows:
            client = await _resolve_client(cf.get('client_id'))
            cf['client_name'] = client.get('name') if client else 'Unknown'
            cf['client_pan'] = client.get('pan_number') if client else ''
            
            # Get sub-broker info
            if cf.get('tagged_by'):
                sub_broker = await db.Mfd_Ria_Partner.find_one({"id": cf['tagged_by']}, {"_id": 0, "name": 1, "partner_code": 1})
                cf['sub_broker_name'] = sub_broker.get('name') if sub_broker else 'Unknown'
                cf['sub_broker_code'] = sub_broker.get('partner_code') if sub_broker else ''
    
    # Combine all reinvestment sources, but deduplicate
    # First, collect cashflow IDs from logs to avoid duplicates
    log_cashflow_ids = {log.get('cashflow_id') for log in pending_reinvestments_logs if log.get('cashflow_id')}
    
    # Filter out cashflows that already have logs
    unique_cashflows = [cf for cf in pending_cashflows if cf.get('id') not in log_cashflow_ids]
    
    # Combine all sources
    pending_reinvestments = pending_reinvestments_submissions + pending_reinvestments_logs + unique_cashflows
    
    # Filter to only include entries with proper UCC and portfolio
    pending_reinvestments = [
        r for r in pending_reinvestments 
        if (r.get('ucc') or r.get('target_ucc')) and (r.get('portfolio') or r.get('portfolio_category'))
        and r.get('ucc') != '' and r.get('portfolio') not in ['none', '']
    ]
    
    # Enrich reinvestments with client and sub-broker info
    for reinv in pending_reinvestments:
        if not reinv.get('client_name') and reinv.get('client_id'):
            client = await _resolve_client(reinv['client_id'])
            reinv['client_name'] = client.get('name') if client else 'Unknown'
            reinv['client_pan'] = client.get('pan_number') if client else ''
        if not reinv.get('sub_broker_name') and reinv.get('sub_broker_id'):
            sub_broker = await db.Mfd_Ria_Partner.find_one(
                {"id": reinv['sub_broker_id']},
                {"_id": 0, "name": 1, "partner_code": 1}
            )
            reinv['sub_broker_name'] = sub_broker.get('name') if sub_broker else 'Unknown'
            reinv['sub_broker_code'] = sub_broker.get('partner_code') if sub_broker else ''
    
    # Get pending trades (blocked units) from sub-brokers
    pending_trades = await db.Ncd_Investment_Details.find(
        {
            "broker_id": current_user['id'],
            "status": "pending"
        },
        {"_id": 0}
    ).sort("created_at", -1).to_list(100)
    
    # Enrich trades with client and sub-broker info
    for trade in pending_trades:
        if trade.get('client_id'):
            client = await _resolve_client(trade['client_id'])
            trade['client_name'] = client.get('name') if client else 'Unknown'
            trade['client_pan'] = client.get('pan_number') if client else ''
        if trade.get('created_by'):
            sub_broker = await db.Mfd_Ria_Partner.find_one(
                {"id": trade['created_by']},
                {"_id": 0, "name": 1, "partner_code": 1}
            )
            if sub_broker:
                trade['sub_broker_name'] = sub_broker.get('name', 'Unknown')
                trade['sub_broker_code'] = sub_broker.get('partner_code', '')
            else:
                # Check if it's the broker themselves
                user = await db.users.find_one({"id": trade['created_by']}, {"_id": 0, "name": 1})
                trade['sub_broker_name'] = user.get('name', 'Broker') if user else 'Unknown'
                trade['sub_broker_code'] = ''
    
    return {
        "pending_clients": pending_clients,
        "pending_reinvestments": pending_reinvestments,
        "pending_trades": pending_trades,
        "total_pending": len(pending_clients) + len(pending_reinvestments) + len(pending_trades)
    }


class ClientApprovalRequest(BaseModel):
    action: str  # 'approve' or 'reject'
    notes: Optional[str] = None
    send_client_email: bool = True  # Whether to send approval email to client


@api_router.post("/approval-workflow/client/{client_id}")
async def process_client_approval(
    client_id: str,
    request: ClientApprovalRequest,
    background_tasks: BackgroundTasks,
    current_user: dict = Depends(get_current_user)
):
    """Process client approval/rejection by broker and optionally send client email"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can approve clients")
    
    client = await db.Private_Investor.find_one({"id": client_id}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    
    if client.get('broker_id') != current_user['id']:
        raise HTTPException(status_code=403, detail="Not authorized to approve this client")
    
    if request.action == "approve":
        # Generate approval token for client email
        approval_token = create_access_token(
            data={
                "type": "client_approval",
                "client_id": client_id,
                "broker_id": current_user['id']
            },
            expires_delta=timedelta(days=7)  # Token valid for 7 days
        )
        
        # Update client status to broker_approved
        await db.Private_Investor.update_one(
            {"id": client_id},
            {
                "$set": {
                    "broker_approval_status": "approved",
                    "broker_approved_at": datetime.now(timezone.utc).isoformat(),
                    "broker_approved_by": current_user['id'],
                    "client_approval_status": "pending" if request.send_client_email else "not_required",
                    "approval_token": approval_token
                }
            }
        )
        
        # Create log entry
        await create_approval_log(
            entity_type="client",
            entity_id=client_id,
            action="broker_approved",
            actor_id=current_user['id'],
            actor_role="broker",
            actor_name=current_user.get('name', 'Broker'),
            details={
                "client_name": client.get('name'),
                "sub_broker_id": client.get('linked_subbroker_id'),
                "broker_id": current_user['id']
            },
            notes=request.notes
        )
        
        # Send client approval email if requested
        if request.send_client_email and client.get('email'):
            from email_service import send_client_approval_request_email
            background_tasks.add_task(
                send_client_approval_request_email,
                client_name=client.get('name', ''),
                client_email=client.get('email'),
                approval_token=approval_token,
                broker_name=current_user.get('name', 'Your Broker')
            )
            
        return {
            "message": "Client approved by broker" + (" - approval email sent to client" if request.send_client_email else ""),
            "status": "broker_approved",
            "client_approval_pending": request.send_client_email
        }
    
    elif request.action == "reject":
        await db.Private_Investor.update_one(
            {"id": client_id},
            {
                "$set": {
                    "approval_status": "rejected",
                    "broker_approval_status": "rejected",
                    "rejected_at": datetime.now(timezone.utc).isoformat(),
                    "rejected_by": current_user['id'],
                    "rejection_notes": request.notes
                }
            }
        )
        
        # Create log entry
        await create_approval_log(
            entity_type="client",
            entity_id=client_id,
            action="broker_rejected",
            actor_id=current_user['id'],
            actor_role="broker",
            actor_name=current_user.get('name', 'Broker'),
            details={
                "client_name": client.get('name'),
                "sub_broker_id": client.get('linked_subbroker_id'),
                "broker_id": current_user['id']
            },
            notes=request.notes
        )
        
        return {"message": "Client rejected", "status": "rejected"}
    
    else:
        raise HTTPException(status_code=400, detail="Invalid action. Use 'approve' or 'reject'")


@api_router.get("/approval-workflow/client-approve")
async def client_approve_via_link(token: str, action: str = "approve"):
    """Public endpoint for client to approve via email link - NO AUTH REQUIRED"""
    try:
        payload = verify_token(token)
        if not payload or payload.get("type") != "client_approval":
            return {"success": False, "message": "Invalid or expired approval link"}
        
        client_id = payload.get("client_id")
        
        client = await db.Private_Investor.find_one({"id": client_id}, {"_id": 0})
        if not client:
            return {"success": False, "message": "Client not found"}
        
        approved = action.lower() == "approve"
        
        if approved:
            # Final approval - activate client account
            temp_password = generate_password()
            temp_pin = generate_pin()
            
            # Create user account for client
            user_id = str(uuid.uuid4())
            await db.users.insert_one({
                "id": user_id,
                "pan": client.get('pan_number', '').upper(),
                "name": client.get('name', ''),
                "email": client.get('email', ''),
                "phone": client.get('mobile', ''),
                "password_hash": get_password_hash(temp_password),
                "pin_hash": get_password_hash(temp_pin),
                "role": "client",
                "client_id": client_id,
                "is_active": True,
                "created_at": datetime.now(timezone.utc).isoformat()
            })
            
            # Update client record
            await db.Private_Investor.update_one(
                {"id": client_id},
                {
                    "$set": {
                        "approval_status": "approved",
                        "client_approval_status": "approved",
                        "client_approved_at": datetime.now(timezone.utc).isoformat(),
                        "is_active": True,
                        "user_id": user_id,
                        "temp_password": temp_password,
                        "temp_pin": temp_pin
                    }
                }
            )
            
            # Create log entry
            await create_approval_log(
                entity_type="client",
                entity_id=client_id,
                action="client_approved",
                actor_id=client_id,
                actor_role="client",
                actor_name=client.get('name', 'Client'),
                details={"broker_id": client.get('broker_id')}
            )
            
            # Send welcome email with credentials
            if client.get('email'):
                broker = await db.users.find_one({"id": client.get('broker_id')}, {"_id": 0})
                
                # Get sub-broker name if client is linked to one
                subbroker_name = None
                if client.get('linked_subbroker_id'):
                    subbroker = await db.Mfd_Ria_Partner.find_one({"id": client.get('linked_subbroker_id')}, {"_id": 0})
                    if not subbroker:
                        subbroker = await db.sub_brokers.find_one({"id": client.get('linked_subbroker_id')}, {"_id": 0})
                    if subbroker:
                        subbroker_name = subbroker.get('name')
                
                from email_service import send_welcome_email_client
                send_welcome_email_client(
                    client_name=client.get('name', ''),
                    client_email=client.get('email'),
                    pan=client.get('pan_number', ''),
                    password=temp_password,
                    pin=temp_pin,
                    broker_name=broker.get('name', 'Your Broker') if broker else 'Your Broker',
                    subbroker_name=subbroker_name
                )
            
            return {
                "success": True,
                "message": "Your account has been approved! Check your email for login credentials.",
                "action": "approved"
            }
        else:
            await db.Private_Investor.update_one(
                {"id": client_id},
                {
                    "$set": {
                        "client_approval_status": "rejected",
                        "client_rejected_at": datetime.now(timezone.utc).isoformat()
                    }
                }
            )
            
            # Create log entry
            await create_approval_log(
                entity_type="client",
                entity_id=client_id,
                action="client_rejected",
                actor_id=client_id,
                actor_role="client",
                actor_name=client.get('name', 'Client'),
                details={"broker_id": client.get('broker_id')}
            )
            
            return {
                "success": True,
                "message": "You have declined the account creation.",
                "action": "rejected"
            }
            
    except Exception as e:
        logger.error(f"Error in client approval link: {e}")
        return {"success": False, "message": "Invalid or expired approval link"}


class ReinvestmentSubmissionRequest(BaseModel):
    """Request to submit reinvestment for approval"""
    client_id: str
    cashflow_ids: List[str]
    portfolio_category: str
    target_ucc: Optional[str] = None
    notes: Optional[str] = None


@api_router.post("/approval-workflow/submit-reinvestment")
async def submit_reinvestment_for_approval(
    request: ReinvestmentSubmissionRequest,
    current_user: dict = Depends(get_current_user)
):
    """Sub-broker submits reinvestment tagging for broker approval"""
    if current_user['role'] != 'sub_broker':
        raise HTTPException(status_code=403, detail="Only sub-brokers can submit reinvestments for approval")
    
    # Verify client is linked to this sub-broker
    client = await db.Private_Investor.find_one(
        {"id": request.client_id, "linked_subbroker_id": current_user['id']},
        {"_id": 0}
    )
    if not client:
        raise HTTPException(status_code=404, detail="Client not found or not linked to you")
    
    # Get cashflows
    cashflows = await db.holding_cashflows.find(
        {"id": {"$in": request.cashflow_ids}}
    ).to_list(100)
    
    if not cashflows:
        raise HTTPException(status_code=404, detail="No cashflows found")
    
    # Calculate total amount
    total_amount = sum(cf.get('net_amount', 0) for cf in cashflows)
    
    # Create submission record
    submission_id = str(uuid.uuid4())
    submission = {
        "id": submission_id,
        "sub_broker_id": current_user['id'],
        "broker_id": client.get('broker_id'),
        "client_id": request.client_id,
        "cashflow_ids": request.cashflow_ids,
        "portfolio_category": request.portfolio_category,
        "target_ucc": request.target_ucc,
        "total_amount": total_amount,
        "cashflows_count": len(cashflows),
        "broker_approval_status": "pending",
        "client_approval_status": "not_started",
        "kinntegra_status": "not_submitted",
        "notes": request.notes,
        "created_at": datetime.now(timezone.utc).isoformat()
    }
    await db.reinvestment_submissions.insert_one(submission)
    
    # Update cashflows with submission reference
    await db.holding_cashflows.update_many(
        {"id": {"$in": request.cashflow_ids}},
        {"$set": {
            "submission_id": submission_id,
            "approval_status": "pending_broker"
        }}
    )
    
    # Create log entry
    await create_approval_log(
        entity_type="reinvestment",
        entity_id=submission_id,
        action="submitted",
        actor_id=current_user['id'],
        actor_role="sub_broker",
        actor_name=current_user.get('name', 'Sub-Broker'),
        details={
            "client_id": request.client_id,
            "client_name": client.get('name'),
            "total_amount": total_amount,
            "cashflows_count": len(cashflows),
            "broker_id": client.get('broker_id'),
            "sub_broker_id": current_user['id']
        },
        notes=request.notes
    )
    
    return {
        "message": "Reinvestment submitted for broker approval",
        "submission_id": submission_id,
        "total_amount": total_amount,
        "cashflows_count": len(cashflows)
    }


class ReinvestmentApprovalRequest(BaseModel):
    action: str  # 'approve' or 'reject'
    notes: Optional[str] = None
    send_client_email: bool = True


@api_router.post("/approval-workflow/reinvestment/{submission_id}")
async def process_reinvestment_approval(
    submission_id: str,
    request: ReinvestmentApprovalRequest,
    background_tasks: BackgroundTasks,
    current_user: dict = Depends(get_current_user)
):
    """Broker approves/rejects reinvestment submission"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can approve reinvestments")
    
    submission = await db.reinvestment_submissions.find_one(
        {"id": submission_id, "broker_id": current_user['id']},
        {"_id": 0}
    )
    if not submission:
        raise HTTPException(status_code=404, detail="Submission not found")
    
    client = await db.Private_Investor.find_one({"id": submission['client_id']}, {"_id": 0})
    
    if request.action == "approve":
        # Generate approval token for client
        approval_token = create_access_token(
            data={
                "type": "reinvestment_approval",
                "submission_id": submission_id,
                "client_id": submission['client_id'],
                "cashflow_ids": submission['cashflow_ids']
            },
            expires_delta=timedelta(days=7)
        )
        
        await db.reinvestment_submissions.update_one(
            {"id": submission_id},
            {
                "$set": {
                    "broker_approval_status": "approved",
                    "broker_approved_at": datetime.now(timezone.utc).isoformat(),
                    "broker_approved_by": current_user['id'],
                    "client_approval_status": "pending" if request.send_client_email else "not_required",
                    "approval_token": approval_token
                }
            }
        )
        
        # Update cashflows
        await db.holding_cashflows.update_many(
            {"id": {"$in": submission['cashflow_ids']}},
            {"$set": {"approval_status": "broker_approved"}}
        )
        
        # Create log entry
        await create_approval_log(
            entity_type="reinvestment",
            entity_id=submission_id,
            action="broker_approved",
            actor_id=current_user['id'],
            actor_role="broker",
            actor_name=current_user.get('name', 'Broker'),
            details={
                "client_id": submission['client_id'],
                "total_amount": submission['total_amount'],
                "sub_broker_id": submission['sub_broker_id'],
                "broker_id": current_user['id']
            },
            notes=request.notes
        )
        
        # Send client approval email
        if request.send_client_email and client and client.get('email'):
            from email_service import send_reinvestment_client_approval_email
            
            # Get the representative name (prefer sub-broker if available from submission)
            representative_name = 'Your Broker'
            if submission.get('sub_broker_id'):
                subbroker = await db.Mfd_Ria_Partner.find_one({"id": submission['sub_broker_id']}, {"_id": 0, "name": 1})
                if not subbroker:
                    subbroker = await db.sub_brokers.find_one({"id": submission['sub_broker_id']}, {"_id": 0, "name": 1})
                if subbroker:
                    representative_name = subbroker.get('name', 'Your Broker')
            else:
                representative_name = current_user.get('name', 'Your Broker')
            
            background_tasks.add_task(
                send_reinvestment_client_approval_email,
                client_name=client.get('name', ''),
                client_email=client.get('email'),
                total_amount=submission['total_amount'],
                cashflows_count=submission['cashflows_count'],
                approval_token=approval_token,
                broker_name=representative_name
            )
        
        return {
            "message": "Reinvestment approved" + (" - approval email sent to client" if request.send_client_email else ""),
            "status": "broker_approved"
        }
    
    elif request.action == "reject":
        await db.reinvestment_submissions.update_one(
            {"id": submission_id},
            {
                "$set": {
                    "broker_approval_status": "rejected",
                    "broker_rejected_at": datetime.now(timezone.utc).isoformat(),
                    "rejection_notes": request.notes
                }
            }
        )
        
        # Update cashflows
        await db.holding_cashflows.update_many(
            {"id": {"$in": submission['cashflow_ids']}},
            {"$set": {"approval_status": "broker_rejected"}}
        )
        
        # Create log entry
        await create_approval_log(
            entity_type="reinvestment",
            entity_id=submission_id,
            action="broker_rejected",
            actor_id=current_user['id'],
            actor_role="broker",
            actor_name=current_user.get('name', 'Broker'),
            details={
                "client_id": submission['client_id'],
                "sub_broker_id": submission['sub_broker_id'],
                "broker_id": current_user['id']
            },
            notes=request.notes
        )
        
        return {"message": "Reinvestment rejected", "status": "rejected"}
    
    raise HTTPException(status_code=400, detail="Invalid action")


@api_router.post("/approval-workflow/reinvestment-tag/{cashflow_id}/{action}")
async def broker_approve_reinvestment_tag(
    cashflow_id: str,
    action: str,
    background_tasks: BackgroundTasks,
    current_user: dict = Depends(get_current_user),
    notes: Optional[str] = None
):
    """Broker approves/rejects a reinvestment tag from sub-broker"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can approve reinvestment tags")
    
    if action not in ['approve', 'reject']:
        raise HTTPException(status_code=400, detail="Action must be 'approve' or 'reject'")
    
    # Find the cashflow
    cashflow = await db.holding_cashflows.find_one({"id": cashflow_id}, {"_id": 0})
    if not cashflow:
        raise HTTPException(status_code=404, detail="Cashflow not found")
    
    # Check approval status - first check holding_cashflows, then check reinvestment_logs for split allocations
    cashflow_status = cashflow.get('approval_status')
    
    # If cashflow doesn't have pending_broker_approval, check reinvestment_logs for split allocations
    if cashflow_status != 'pending_broker_approval':
        # Check if there are reinvestment_logs with pending_broker_approval for this cashflow
        pending_logs = await db.reinvestment_logs.find(
            {
                "cashflow_id": cashflow_id,
                "approval_status": "pending_broker_approval"
            },
            {"_id": 0}
        ).to_list(100)
        
        if not pending_logs:
            raise HTTPException(status_code=400, detail="This tag is not pending broker approval")
    
    # Get client info
    client = await db.Private_Investor.find_one({"id": cashflow.get('client_id')}, {"_id": 0})
    
    if action == 'approve':
        # Update cashflow to pending (client approval)
        await db.holding_cashflows.update_one(
            {"id": cashflow_id},
            {"$set": {
                "approval_status": "pending",
                "broker_approved": True,
                "broker_approved_at": datetime.now(timezone.utc).isoformat(),
                "broker_approved_by": current_user['id']
            }}
        )
        
        # Update ALL reinvestment_logs for this cashflow (important for split allocations)
        update_result = await db.reinvestment_logs.update_many(
            {"cashflow_id": cashflow_id},
            {"$set": {
                "approval_status": "pending",
                "broker_approved": True,
                "broker_approved_at": datetime.now(timezone.utc).isoformat(),
                "broker_approved_by": current_user['id']
            }}
        )
        logs_updated = update_result.modified_count
        
        # Send approval email to client
        if client and client.get('email'):
            try:
                from email_service import send_reinvestment_client_approval_email
                
                # Generate approval token
                approval_token = create_access_token(
                    data={
                        "type": "reinvestment_approval",
                        "cashflow_id": cashflow_id,
                        "client_id": client['id']
                    },
                    expires_delta=timedelta(days=7)
                )
                
                # Get the representative name (prefer sub-broker if client is linked)
                representative_name = 'Your Broker'
                if client.get('linked_subbroker_id'):
                    subbroker = await db.Mfd_Ria_Partner.find_one({"id": client['linked_subbroker_id']}, {"_id": 0, "name": 1})
                    if not subbroker:
                        subbroker = await db.sub_brokers.find_one({"id": client['linked_subbroker_id']}, {"_id": 0, "name": 1})
                    if subbroker:
                        representative_name = subbroker.get('name', 'Your Broker')
                else:
                    broker = await db.users.find_one({"id": current_user['id']}, {"_id": 0, "name": 1})
                    representative_name = broker.get('name', 'Your Broker') if broker else 'Your Broker'
                
                # Get the net amount for email - sum all allocations if split
                if logs_updated > 1:
                    # Multiple allocations - get total from reinvestment_logs
                    logs = await db.reinvestment_logs.find(
                        {"cashflow_id": cashflow_id},
                        {"_id": 0, "amount": 1}
                    ).to_list(100)
                    net_amount = sum(log.get('amount', 0) for log in logs)
                else:
                    net_amount = cashflow.get('net_amount', cashflow.get('amount', 0))
                
                # Send email asynchronously
                background_tasks.add_task(
                    send_reinvestment_client_approval_email,
                    client_name=client.get('name', ''),
                    client_email=client.get('email'),
                    total_amount=net_amount,
                    cashflows_count=logs_updated or 1,
                    approval_token=approval_token,
                    broker_name=representative_name
                )
                
                logger.info(f"Broker approved reinvestment tag for {cashflow.get('bond_name')}, approval email sent to {client.get('email')}, {logs_updated} allocations updated")
            except Exception as e:
                logger.error(f"Error sending client approval email: {e}")
        
        return {
            "message": "Reinvestment tag approved, pending client approval",
            "status": "pending",
            "client_name": client.get('name') if client else 'Unknown',
            "allocations_updated": logs_updated
        }
    
    else:  # reject
        # Update cashflow - reset to not_tagged
        await db.holding_cashflows.update_one(
            {"id": cashflow_id},
            {"$set": {
                "reinvestment_tag": "not_tagged",
                "approval_status": "broker_rejected",
                "broker_approved": False,
                "broker_rejected_at": datetime.now(timezone.utc).isoformat(),
                "broker_rejected_by": current_user['id'],
                "broker_rejection_notes": notes,
                "portfolio_category": None,
                "target_ucc": None
            }}
        )
        
        # Update ALL reinvestment_logs for this cashflow (important for split allocations)
        await db.reinvestment_logs.update_many(
            {"cashflow_id": cashflow_id},
            {"$set": {
                "approval_status": "broker_rejected",
                "broker_approved": False,
                "broker_rejected_at": datetime.now(timezone.utc).isoformat(),
                "broker_rejection_notes": notes
            }}
        )
        
        return {
            "message": "Reinvestment tag rejected",
            "status": "broker_rejected"
        }


@api_router.post("/reinvestment/resend-approval/{cashflow_id}")
async def resend_reinvestment_approval_email(
    cashflow_id: str,
    background_tasks: BackgroundTasks,
    current_user: dict = Depends(get_current_user),
):
    """Resend the client-approval email for a reinvestment tag that's still
    pending client approval. Useful for stale entries the client hasn't acted
    on. Re-uses the same approval-token + email helper as broker approve."""
    if current_user.get('role') not in ('broker', 'sub_broker'):
        raise HTTPException(status_code=403, detail="Not authorised")

    cashflow = await db.holding_cashflows.find_one({"id": cashflow_id}, {"_id": 0})
    if not cashflow:
        raise HTTPException(status_code=404, detail="Cashflow not found")

    # Must be in pending-client state (broker has approved, client hasn't)
    cashflow_status = (cashflow.get('approval_status') or '').lower()
    if cashflow_status != 'pending':
        # Allow resend even if status is missing on cashflow but reinvestment_logs row exists
        log = await db.reinvestment_logs.find_one(
            {"cashflow_id": cashflow_id, "approval_status": "pending"},
            {"_id": 0}
        )
        if not log:
            raise HTTPException(
                status_code=400,
                detail="This entry isn't pending client approval — nothing to resend."
            )

    # Sub-broker scope: only resend for their own clients
    client = await db.Private_Investor.find_one({"id": cashflow.get('client_id')}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    if current_user.get('role') == 'sub_broker':
        if client.get('linked_subbroker_id') != current_user['id']:
            raise HTTPException(status_code=403, detail="Not your client")

    if not client.get('email'):
        raise HTTPException(status_code=400, detail="Client has no email on file")

    try:
        from email_service import send_reinvestment_client_approval_email

        approval_token = create_access_token(
            data={
                "type": "reinvestment_approval",
                "cashflow_id": cashflow_id,
                "client_id": client['id'],
            },
            expires_delta=timedelta(days=7),
        )

        # Representative name — prefer linked sub-broker
        representative_name = 'Your Broker'
        if client.get('linked_subbroker_id'):
            subbroker = await db.Mfd_Ria_Partner.find_one(
                {"id": client['linked_subbroker_id']}, {"_id": 0, "name": 1}
            ) or await db.sub_brokers.find_one(
                {"id": client['linked_subbroker_id']}, {"_id": 0, "name": 1}
            )
            if subbroker:
                representative_name = subbroker.get('name') or representative_name
        else:
            broker = await db.users.find_one(
                {"id": current_user['id']}, {"_id": 0, "name": 1}
            )
            representative_name = (broker or {}).get('name') or representative_name

        # Net amount — sum allocations if split
        logs = await db.reinvestment_logs.find(
            {"cashflow_id": cashflow_id}, {"_id": 0, "amount": 1}
        ).to_list(100)
        if logs:
            net_amount = sum(l.get('amount', 0) or 0 for l in logs)
            cashflows_count = len(logs)
        else:
            net_amount = cashflow.get('net_amount') or cashflow.get('amount') or 0
            cashflows_count = 1

        # Track resend audit
        now_iso = datetime.now(timezone.utc).isoformat()
        await db.holding_cashflows.update_one(
            {"id": cashflow_id},
            {
                "$set": {
                    "client_approval_email_last_sent_at": now_iso,
                    "client_approval_email_last_sent_by": current_user['id'],
                },
                "$inc": {"client_approval_email_resend_count": 1},
            },
        )

        background_tasks.add_task(
            send_reinvestment_client_approval_email,
            client_name=client.get('name', ''),
            client_email=client.get('email'),
            total_amount=net_amount,
            cashflows_count=cashflows_count,
            approval_token=approval_token,
            broker_name=representative_name,
        )

        return {
            "message": "Approval link resent",
            "client_email": client.get('email'),
            "client_name": client.get('name'),
            "amount": net_amount,
            "cashflows_count": cashflows_count,
            "sent_at": now_iso,
        }
    except HTTPException:
        raise
    except Exception as exc:
        logger.error(f"[resend-approval] failed for {cashflow_id}: {exc}")
        raise HTTPException(status_code=500, detail="Failed to resend approval email")


@api_router.get("/approval-workflow/reinvestment-approve")
async def reinvestment_approve_via_link(token: str, action: str = "approve"):
    """Public endpoint for client to approve reinvestment via email link - NO AUTH REQUIRED"""
    try:
        payload = verify_token(token)
        if not payload or payload.get("type") != "reinvestment_approval":
            return {"success": False, "message": "Invalid or expired approval link"}
        
        submission_id = payload.get("submission_id")
        client_id = payload.get("client_id")
        cashflow_ids = payload.get("cashflow_ids", [])
        
        submission = await db.reinvestment_submissions.find_one({"id": submission_id}, {"_id": 0})
        if not submission:
            return {"success": False, "message": "Submission not found"}
        
        client = await db.Private_Investor.find_one({"id": client_id}, {"_id": 0})
        
        approved = action.lower() == "approve"
        
        if approved:
            # Update submission
            await db.reinvestment_submissions.update_one(
                {"id": submission_id},
                {
                    "$set": {
                        "client_approval_status": "approved",
                        "client_approved_at": datetime.now(timezone.utc).isoformat(),
                        "kinntegra_status": "ready_to_submit"
                    }
                }
            )
            
            # Update cashflows
            await db.holding_cashflows.update_many(
                {"id": {"$in": cashflow_ids}},
                {"$set": {
                    "client_approved": True,
                    "approval_status": "client_approved"
                }}
            )
            
            # Create log entry
            await create_approval_log(
                entity_type="reinvestment",
                entity_id=submission_id,
                action="client_approved",
                actor_id=client_id,
                actor_role="client",
                actor_name=client.get('name', 'Client') if client else 'Client',
                details={
                    "broker_id": submission.get('broker_id'),
                    "sub_broker_id": submission.get('sub_broker_id')
                }
            )
            
            # Trigger Kinntegra API submission
            kinntegra_result = await submit_to_kinntegra_internal(submission_id)
            
            return {
                "success": True,
                "message": "Reinvestment approved! Your investment will be processed shortly.",
                "action": "approved",
                "kinntegra_status": kinntegra_result.get('status', 'pending')
            }
        else:
            await db.reinvestment_submissions.update_one(
                {"id": submission_id},
                {
                    "$set": {
                        "client_approval_status": "rejected",
                        "client_rejected_at": datetime.now(timezone.utc).isoformat()
                    }
                }
            )
            
            await db.holding_cashflows.update_many(
                {"id": {"$in": cashflow_ids}},
                {"$set": {"approval_status": "client_rejected"}}
            )
            
            # Create log entry
            await create_approval_log(
                entity_type="reinvestment",
                entity_id=submission_id,
                action="client_rejected",
                actor_id=client_id,
                actor_role="client",
                actor_name=client.get('name', 'Client') if client else 'Client',
                details={
                    "broker_id": submission.get('broker_id'),
                    "sub_broker_id": submission.get('sub_broker_id')
                }
            )
            
            return {
                "success": True,
                "message": "You have declined this reinvestment.",
                "action": "rejected"
            }
            
    except Exception as e:
        logger.error(f"Error in reinvestment approval link: {e}")
        return {"success": False, "message": "Invalid or expired approval link"}


@api_router.post("/approval-workflow/trade/{trade_id}")
async def broker_approve_trade(
    trade_id: str,
    action: str,  # "approve" or "reject"
    notes: Optional[str] = None,
    current_user: dict = Depends(get_current_user)
):
    """Broker approves or rejects a pending trade (blocked units) from sub-broker"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can approve trades")
    
    trade = await db.Ncd_Investment_Details.find_one({"id": trade_id}, {"_id": 0})
    if not trade:
        raise HTTPException(status_code=404, detail="Trade not found")
    
    if trade.get('broker_id') != current_user['id']:
        raise HTTPException(status_code=403, detail="You can only approve trades under your brokerage")
    
    if trade.get('status') != 'pending':
        raise HTTPException(status_code=400, detail=f"Trade is already {trade.get('status')}")
    
    if action.lower() == "approve":
        # Update trade status to approved
        update_data = {
            "status": "approved",
            "broker_approved": True,
            "broker_approved_at": datetime.now(timezone.utc).isoformat(),
            "broker_notes": notes,
        }
        await db.Ncd_Investment_Details.update_one(
            {"id": trade_id},
            {"$set": update_data}
        )
        
        # Update bond's units_sold count
        bond = await db.Ncd_Master.find_one({"id": trade.get('bond_id')}, {"_id": 0})
        if bond:
            current_units_sold = bond.get('units_sold', 0) or 0
            new_units_sold = current_units_sold + trade.get('units', 0)
            
            await db.Ncd_Master.update_one(
                {"id": trade.get('bond_id')},
                {"$set": {"units_sold": new_units_sold}}
            )
            
            logger.info(f"Updated bond {bond.get('name')} units_sold from {current_units_sold} to {new_units_sold}")

        # Generate `holding_cashflows` for this trade and refresh
        # `Ncd_Expected_Repayments` so the client's Holdings → NCD and the
        # Reinv Tag page see the new investment immediately.
        # (Mirrors the same generate_client_cashflows + rebuild pattern used
        # by /api/trades/{id}/tag-and-allocate.)
        cashflows_generated = 0
        if bond:
            try:
                trade_with_updates = {**trade, **update_data}
                cashflows = generate_client_cashflows(trade_with_updates, bond)
                if cashflows:
                    for cf in cashflows:
                        cf['client_id'] = trade.get('client_id')
                        cf['bond_id'] = trade.get('bond_id')
                        cf.setdefault('trade_id', trade_id)
                        cf.setdefault('type', 'projected')
                    await db.holding_cashflows.insert_many(cashflows)
                    cashflows_generated = len(cashflows)
                    logger.info(
                        f"Generated {cashflows_generated} holding_cashflows for approved trade {trade_id}"
                    )
            except Exception as exc:
                logger.error(f"[approval] holding_cashflows generation failed for {trade_id}: {exc}")

            try:
                await _rebuild_ncd_expected_repayments()
            except Exception as exc:
                logger.error(f"[approval] expected_repayments rebuild failed for {trade_id}: {exc}")
        
        return {
            "message": "Trade approved successfully",
            "trade_id": trade_id,
            "status": "approved",
            "units": trade.get('units'),
            "bond_name": trade.get('bond_name'),
            "cashflows_generated": cashflows_generated,
        }
    
    elif action.lower() == "reject":
        # Update trade status to rejected
        await db.Ncd_Investment_Details.update_one(
            {"id": trade_id},
            {
                "$set": {
                    "status": "rejected",
                    "broker_rejected": True,
                    "broker_rejected_at": datetime.now(timezone.utc).isoformat(),
                    "broker_rejection_notes": notes
                }
            }
        )
        
        return {
            "message": "Trade rejected",
            "trade_id": trade_id,
            "status": "rejected"
        }
    
    raise HTTPException(status_code=400, detail="Invalid action. Use 'approve' or 'reject'")


# Kinntegra MF Buy Scheduler API Configuration
KINNTEGRA_API_BASE_URL = "https://api.kinntegra.co.in/api/transaction"
KINNTEGRA_API_KEY = "397071386F563639685674495956545432704E4F6E673D3D"

# Portfolio name mapping for Kinntegra API (internal lowercase -> API Title Case)
PORTFOLIO_NAME_MAP = {
    'wealth': 'Wealth',
    'tax': 'Tax',
    'short_term': 'Short Term',
    'commodities': 'Commodities',
    'bonds': 'Bonds',
    'real_estate': 'Real Estate',
    'none': 'None'
}

def format_portfolio_name(portfolio: str) -> str:
    """Convert internal portfolio name to Kinntegra API format (Title Case)"""
    if not portfolio:
        return 'Wealth'
    return PORTFOLIO_NAME_MAP.get(portfolio.lower(), portfolio.title().replace('_', ' '))


def _resolve_bank_account_number(client: dict) -> str:
    """Return the client's bank account number for the Kinntegra MF buy
    scheduler API. Prefers the domestic `account_number`; falls back to the
    international one for foreign-passport investors. Returns '' if nothing
    is available — the caller should still send the field (Kinntegra now
    requires `BankAccountNumber` on add/revise payloads)."""
    if not client:
        return ''
    return (
        client.get('account_number')
        or client.get('bank_account_number')
        or client.get('intl_account_number')
        or ''
    )


async def call_kinntegra_mf_buy_scheduler(cashflow: dict, client: dict, is_revision: bool = False) -> dict:
    """
    Call Kinntegra MF Buy Scheduler API when client approves reinvestment tag.
    
    Args:
        cashflow: The holding_cashflows document with reinvestment tag
        client: The client document
        is_revision: If True, calls revisebuyschedule endpoint instead of addbuyschedule
    
    Returns:
        dict with API response or error details
    """
    import httpx
    
    try:
        # Determine the investment amount based on reinvestment tag
        tag = cashflow.get('reinvestment_tag', 'not_tagged')
        
        # Handle split allocations - if present, process each allocation separately
        if cashflow.get('has_split_allocations') and cashflow.get('ucc_allocations'):
            allocations = cashflow.get('ucc_allocations', [])
            results = []
            
            for alloc in allocations:
                alloc_result = await _call_kinntegra_for_allocation(
                    cashflow, client, alloc, is_revision
                )
                results.append(alloc_result)
            
            # Return combined result
            success_count = sum(1 for r in results if r.get('status') == 'success')
            return {
                "status": "success" if success_count > 0 else "error",
                "message": f"Submitted {success_count}/{len(results)} allocations to Kinntegra",
                "allocation_results": results
            }
        
        # Standard single allocation processing
        if tag == 'other' or tag == 'custom':
            amount = cashflow.get('custom_amount', 0)
        elif tag == 'principal':
            amount = cashflow.get('principal_component', 0)
        elif tag == 'interest':
            amount = cashflow.get('interest_component', 0) - cashflow.get('tds_amount', 0)
        elif tag == 'both' or tag == 'net_amount':
            # 'both' means principal + interest (net amount)
            amount = cashflow.get('net_amount', 0)
        elif tag == 'none' or tag == 'not_tagged' or tag == 'not_invest':
            return {"status": "skipped", "message": f"Reinvestment tag '{tag}' - no API call needed"}
        else:
            return {"status": "skipped", "message": f"Unknown reinvestment tag: {tag}"}
        
        if amount <= 0:
            return {"status": "skipped", "message": "Investment amount is zero or negative"}
        
        # Get bond details for DealId
        bond = await db.Ncd_Master.find_one({"id": cashflow.get('bond_id')}, {"_id": 0})
        deal_id = bond.get('bond_code', '') if bond else cashflow.get('bond_id', '')
        
        # Get UCC - use target_ucc from cashflow if available, otherwise client's UCC
        ucc = cashflow.get('target_ucc') or client.get('ucc') or client.get('pan_number', '')
        
        # Get MF investment date - use broker-selected date from cashflow, fallback to T+1 from cashflow date
        mf_investment_date = cashflow.get('mf_investment_date')
        if not mf_investment_date:
            # Fallback to T+1 from cashflow date
            if cashflow.get('date'):
                try:
                    cf_date = datetime.strptime(cashflow['date'][:10], '%Y-%m-%d')
                    mf_investment_date = (cf_date + timedelta(days=1)).strftime('%Y-%m-%d')
                except:
                    mf_investment_date = datetime.now(timezone.utc).strftime('%Y-%m-%d')
            else:
                mf_investment_date = datetime.now(timezone.utc).strftime('%Y-%m-%d')
        
        # Prepare investment data
        investment_item = {
            "UCC": ucc,
            "DealId": deal_id,
            "BondInvestmentDate": cashflow.get('date', datetime.now(timezone.utc).strftime('%Y-%m-%d')),
            "InvestmentAmount": amount,
            "PortfolioName": format_portfolio_name(cashflow.get('portfolio_category', 'wealth')),
            "MFInvestmentDate": mf_investment_date,  # Use broker-selected date, not approval date
            "BankAccountNumber": _resolve_bank_account_number(client),
        }
        
        # Add revision fields if this is a revision
        if is_revision:
            investment_item["RevisedAmount"] = amount
            investment_item["RevisedDate"] = datetime.now(timezone.utc).strftime('%Y-%m-%d')
        
        api_payload = {"InvestmentData": [investment_item]}
        
        # Determine endpoint
        endpoint = f"{KINNTEGRA_API_BASE_URL}/{'revisebuyschedule' if is_revision else 'addbuyschedule'}"
        
        headers = {
            "Content-Type": "application/json",
            "x-api-key": KINNTEGRA_API_KEY
        }
        
        # Log the API request
        api_log = {
            "id": str(uuid.uuid4()),
            "cashflow_id": cashflow.get('id'),
            "client_id": client.get('id'),
            "client_name": client.get('name'),
            "endpoint": endpoint,
            "payload": api_payload,
            "status": "pending",
            "created_at": datetime.now(timezone.utc).isoformat()
        }
        await db.kinntegra_api_logs.insert_one(api_log)
        
        # Make the API call
        async with httpx.AsyncClient(timeout=30.0) as http_client:
            response = await http_client.post(endpoint, json=api_payload, headers=headers)
            
            response_data = response.json() if response.headers.get('content-type', '').startswith('application/json') else {"raw": response.text}
            
            # Update log with response
            await db.kinntegra_api_logs.update_one(
                {"id": api_log['id']},
                {"$set": {
                    "status": "success" if response.status_code == 200 else "error",
                    "response_status_code": response.status_code,
                    "response_body": response_data,
                    "completed_at": datetime.now(timezone.utc).isoformat()
                }}
            )
            
            # Update cashflow with API submission status
            await db.holding_cashflows.update_one(
                {"id": cashflow.get('id')},
                {"$set": {
                    "kinntegra_api_submitted": True,
                    "kinntegra_api_status": "success" if response.status_code == 200 else "error",
                    "kinntegra_api_response": response_data,
                    "kinntegra_submitted_at": datetime.now(timezone.utc).isoformat()
                }}
            )
            
            if response.status_code == 200:
                logger.info(f"Successfully submitted to Kinntegra API for cashflow {cashflow.get('id')}")
                return {
                    "status": "success",
                    "message": "Successfully submitted to Kinntegra MF Buy Scheduler",
                    "api_response": response_data
                }
            else:
                logger.error(f"Kinntegra API error: {response.status_code} - {response_data}")
                return {
                    "status": "error",
                    "message": f"API returned status {response.status_code}",
                    "api_response": response_data
                }
                
    except httpx.TimeoutException:
        logger.error("Kinntegra API timeout")
        return {"status": "error", "message": "API request timed out"}
    except Exception as e:
        logger.error(f"Error calling Kinntegra API: {e}")
        return {"status": "error", "message": str(e)}


async def _call_kinntegra_for_allocation(cashflow: dict, client: dict, allocation: dict, is_revision: bool = False) -> dict:
    """
    Helper function to call Kinntegra API for a single allocation within a split.
    """
    import httpx
    
    try:
        amount = allocation.get('amount', 0)
        if amount <= 0:
            return {"status": "skipped", "message": "Allocation amount is zero or negative", "allocation": allocation}
        
        # Skip 'none' portfolio allocations
        if allocation.get('portfolio') == 'none':
            return {"status": "skipped", "message": "Portfolio is 'none' - no API call needed", "allocation": allocation}
        
        # Get bond details for DealId
        bond = await db.Ncd_Master.find_one({"id": cashflow.get('bond_id')}, {"_id": 0})
        deal_id = bond.get('bond_code', '') if bond else cashflow.get('bond_id', '')
        
        # Get UCC from allocation
        ucc = allocation.get('ucc') or client.get('ucc') or client.get('pan_number', '')
        
        # Get MF investment date - use broker-selected date, fallback to T+1 from cashflow date
        mf_investment_date = allocation.get('investment_date')
        if not mf_investment_date:
            # Fallback to T+1 from cashflow date
            if cashflow.get('date'):
                try:
                    cf_date = datetime.strptime(cashflow['date'][:10], '%Y-%m-%d')
                    mf_investment_date = (cf_date + timedelta(days=1)).strftime('%Y-%m-%d')
                except:
                    mf_investment_date = datetime.now(timezone.utc).strftime('%Y-%m-%d')
            else:
                mf_investment_date = datetime.now(timezone.utc).strftime('%Y-%m-%d')
        
        # Prepare investment data
        investment_item = {
            "UCC": ucc,
            "DealId": deal_id,
            "BondInvestmentDate": cashflow.get('date', datetime.now(timezone.utc).strftime('%Y-%m-%d')),
            "InvestmentAmount": amount,
            "PortfolioName": format_portfolio_name(allocation.get('portfolio', 'wealth')),
            "MFInvestmentDate": mf_investment_date,  # Use broker-selected date
            "BankAccountNumber": _resolve_bank_account_number(client),
        }
        
        if is_revision:
            investment_item["RevisedAmount"] = amount
            investment_item["RevisedDate"] = datetime.now(timezone.utc).strftime('%Y-%m-%d')
        
        api_payload = {"InvestmentData": [investment_item]}
        endpoint = f"{KINNTEGRA_API_BASE_URL}/{'revisebuyschedule' if is_revision else 'addbuyschedule'}"
        
        headers = {
            "Content-Type": "application/json",
            "x-api-key": KINNTEGRA_API_KEY
        }
        
        # Log the API request
        api_log = {
            "id": str(uuid.uuid4()),
            "cashflow_id": cashflow.get('id'),
            "allocation_ucc": ucc,
            "allocation_amount": amount,
            "allocation_portfolio": allocation.get('portfolio'),
            "client_id": client.get('id'),
            "client_name": client.get('name'),
            "endpoint": endpoint,
            "payload": api_payload,
            "status": "pending",
            "is_split_allocation": True,
            "created_at": datetime.now(timezone.utc).isoformat()
        }
        await db.kinntegra_api_logs.insert_one(api_log)
        
        # Make the API call
        async with httpx.AsyncClient(timeout=30.0) as http_client:
            response = await http_client.post(endpoint, json=api_payload, headers=headers)
            
            response_data = response.json() if response.headers.get('content-type', '').startswith('application/json') else {"raw": response.text}
            
            # Update log with response
            await db.kinntegra_api_logs.update_one(
                {"id": api_log['id']},
                {"$set": {
                    "status": "success" if response.status_code == 200 else "error",
                    "response_status_code": response.status_code,
                    "response_body": response_data,
                    "completed_at": datetime.now(timezone.utc).isoformat()
                }}
            )
            
            if response.status_code == 200:
                logger.info(f"Successfully submitted split allocation to Kinntegra: UCC={ucc}, Amount={amount}")
                return {
                    "status": "success",
                    "allocation": allocation,
                    "api_response": response_data
                }
            else:
                logger.error(f"Kinntegra API error for allocation: {response.status_code} - {response_data}")
                return {
                    "status": "error",
                    "allocation": allocation,
                    "message": f"API returned status {response.status_code}",
                    "api_response": response_data
                }
                
    except Exception as e:
        logger.error(f"Error calling Kinntegra API for allocation: {e}")
        return {"status": "error", "allocation": allocation, "message": str(e)}


async def submit_to_kinntegra_internal(submission_id: str) -> dict:
    """Internal function to submit approved reinvestment to Kinntegra API"""
    try:
        submission = await db.reinvestment_submissions.find_one({"id": submission_id}, {"_id": 0})
        if not submission:
            return {"status": "error", "message": "Submission not found"}
        
        # Get cashflows
        cashflows = await db.holding_cashflows.find(
            {"id": {"$in": submission['cashflow_ids']}}
        ).to_list(100)
        
        # Get client
        client = await db.Private_Investor.find_one({"id": submission['client_id']}, {"_id": 0})
        
        # Prepare Kinntegra API payload
        investment_data = []
        for cf in cashflows:
            investment_data.append({
                "UCC": submission.get('target_ucc', client.get('ucc', '')),
                "DealId": cf.get('bond_id', ''),
                "BondInvestmentDate": cf.get('date', ''),
                "InvestmentAmount": cf.get('net_amount', 0),
                "PortfolioName": format_portfolio_name(submission.get('portfolio_category', 'wealth')),
                "MFInvestmentDate": datetime.now(timezone.utc).strftime('%Y-%m-%d')
            })
        
        api_payload = {"InvestmentData": investment_data}
        
        # Store the API request (will make actual call when Kinntegra auth is available)
        kinntegra_request = {
            "id": str(uuid.uuid4()),
            "submission_id": submission_id,
            "client_id": submission['client_id'],
            "api_endpoint": "https://api.kinntegra.co.in/api/transaction/addbuyschedule",
            "payload": api_payload,
            "status": "pending_api_credentials",  # Change to 'submitted' when we have API credentials
            "created_at": datetime.now(timezone.utc).isoformat()
        }
        await db.kinntegra_api_requests.insert_one(kinntegra_request)
        
        # Update submission status
        await db.reinvestment_submissions.update_one(
            {"id": submission_id},
            {
                "$set": {
                    "kinntegra_status": "pending_api_credentials",
                    "kinntegra_request_id": kinntegra_request['id'],
                    "kinntegra_payload": api_payload
                }
            }
        )
        
        # Create log entry
        await create_approval_log(
            entity_type="reinvestment",
            entity_id=submission_id,
            action="kinntegra_prepared",
            actor_id="system",
            actor_role="system",
            actor_name="System",
            details={
                "kinntegra_request_id": kinntegra_request['id'],
                "status": "pending_api_credentials"
            },
            notes="Kinntegra API payload prepared. Awaiting API credentials for submission."
        )
        
        logger.info(f"Kinntegra submission prepared for submission {submission_id}")
        return {"status": "pending_api_credentials", "request_id": kinntegra_request['id']}
        
    except Exception as e:
        logger.error(f"Error preparing Kinntegra submission: {e}")
        return {"status": "error", "message": str(e)}


@api_router.get("/approval-workflow/my-submissions")
async def get_my_submissions(current_user: dict = Depends(get_current_user)):
    """Sub-broker gets their own submissions status"""
    if current_user['role'] != 'sub_broker':
        raise HTTPException(status_code=403, detail="Only sub-brokers can view their submissions")
    
    submissions = await db.reinvestment_submissions.find(
        {"sub_broker_id": current_user['id']},
        {"_id": 0}
    ).sort("created_at", -1).to_list(100)
    
    # Enrich with client info
    for sub in submissions:
        client = await db.Private_Investor.find_one(
            {"id": sub['client_id']},
            {"_id": 0, "name": 1}
        )
        sub['client_name'] = client.get('name') if client else 'Unknown'
    
    return submissions


