@api_router.post("/bulk/mfd-ria")
async def bulk_upload_subbrokers(
    file: UploadFile = File(...),
    background_tasks: BackgroundTasks = None,
    current_user: dict = Depends(get_current_user)
):
    """Bulk upload sub-brokers from Excel file"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can bulk upload sub-brokers")
    
    if not file.filename.endswith(('.xlsx', '.xls')):
        raise HTTPException(status_code=400, detail="Please upload an Excel file (.xlsx or .xls)")
    
    import pandas as pd
    
    content = await file.read()
    df = pd.read_excel(io.BytesIO(content), sheet_name=0)
    
    # Clean column names
    df.columns = [col.replace('*', '').strip().lower().replace(' ', '_') for col in df.columns]
    
    results = {"success": 0, "failed": 0, "errors": [], "created_subbrokers": []}
    
    for idx, row in df.iterrows():
        try:
            # Validate required fields
            if pd.isna(row.get('name')) or pd.isna(row.get('pan')):
                results['errors'].append(f"Row {idx+2}: Missing required fields (Name or PAN)")
                results['failed'] += 1
                continue
            
            pan = str(row['pan']).upper().strip()
            name = str(row['name']).strip()
            email = str(row.get('email', '')).strip() if not pd.isna(row.get('email')) else ''
            
            # Get partner type
            partner_type_raw = str(row.get('partner_type_(mfd/ria/both)', '')).strip().lower() if not pd.isna(row.get('partner_type_(mfd/ria/both)')) else ''
            partner_type = partner_type_raw if partner_type_raw in ['mfd', 'ria', 'both'] else 'mfd'
            
            # Validate conditional required fields based on partner type
            is_mfd = partner_type in ['mfd', 'both']
            is_ria = partner_type in ['ria', 'both']
            
            arn_number = str(row.get('arn_number', '')).strip() if not pd.isna(row.get('arn_number')) else ''
            sebi_reg_no = str(row.get('sebi_registration_no', '')).strip() if not pd.isna(row.get('sebi_registration_no')) else ''
            
            if is_mfd and not arn_number:
                results['errors'].append(f"Row {idx+2}: ARN Number is required for MFD partner type")
                results['failed'] += 1
                continue
            
            if is_ria and not sebi_reg_no:
                results['errors'].append(f"Row {idx+2}: SEBI Registration Number is required for RIA partner type")
                results['failed'] += 1
                continue
            
            # Check for duplicates
            existing_pan = await db.users.find_one({"pan": pan})
            if existing_pan:
                results['errors'].append(f"Row {idx+2}: PAN {pan} already exists")
                results['failed'] += 1
                continue
            
            # Generate partner code if not provided
            partner_code = str(row.get('partner_code', '')).strip() if not pd.isna(row.get('partner_code')) else ''
            if not partner_code:
                partner_code = f"{partner_type.upper()}{str(uuid.uuid4())[:6].upper()}"
            
            existing_code = await db.Mfd_Ria_Partner.find_one({"partner_code": partner_code})
            if existing_code:
                results['errors'].append(f"Row {idx+2}: Partner code {partner_code} already exists")
                results['failed'] += 1
                continue
            
            # Generate temporary password and PIN (partner will set their own via email reset)
            temp_password = generate_password()
            temp_pin = generate_pin()
            
            # Create user with pending_verification status
            user_id = str(uuid.uuid4())
            user = {
                "id": user_id,
                "pan": pan,
                "name": name,
                "email": email,
                "phone": str(row.get('mobile', '')).strip() if not pd.isna(row.get('mobile')) else '',
                "password_hash": get_password_hash(temp_password),
                "pin_hash": get_password_hash(temp_pin),
                "role": "sub_broker",
                "is_active": False,  # Inactive until broker verifies
                "status": "pending_verification",  # Pending broker verification
                "needs_password_reset": True,  # Partner needs to set their own password
                "created_at": datetime.now(timezone.utc).isoformat(),
                "source": "bulk_upload"
            }
            await db.users.insert_one(user)
            
            # Extract additional fields
            euin = str(row.get('euin', '')).strip() if not pd.isna(row.get('euin')) else ''
            registration_type = str(row.get('registration_type_(individual/corporate)', '')).strip().lower() if not pd.isna(row.get('registration_type_(individual/corporate)')) else ''
            years_of_experience = str(row.get('years_of_experience', '')).strip() if not pd.isna(row.get('years_of_experience')) else ''
            current_aum = str(row.get('current_aum', '')).strip() if not pd.isna(row.get('current_aum')) else ''
            city = str(row.get('city', '')).strip() if not pd.isna(row.get('city')) else ''
            state = str(row.get('state', '')).strip() if not pd.isna(row.get('state')) else ''
            pincode = str(row.get('pincode', '')).strip() if not pd.isna(row.get('pincode')) else ''
            # Accept either "Address" (new canonical) or "Full Address" (legacy)
            address_val = row.get('address', row.get('full_address', ''))
            full_address = str(address_val).strip() if not pd.isna(address_val) else ''
            country = str(row.get('country', 'India')).strip() if not pd.isna(row.get('country')) else 'India'
            if not country:
                country = 'India'
            about = str(row.get('about', '')).strip() if not pd.isna(row.get('about')) else ''
            mobile = str(row.get('mobile', '')).strip() if not pd.isna(row.get('mobile')) else ''
            
            # Create partner record in CANONICAL field order
            # (aligned with Add MFD/RIA form, Bulk Upload template, and Downloads export)
            partner = {
                "id": user_id,
                "name": name,
                "pan": pan,
                "email": email,
                "mobile": mobile,
                "partner_code": partner_code,
                "partner_type": partner_type,
                "arn": arn_number,
                "euin": euin,
                "sebi_registration_number": sebi_reg_no,
                "registration_type": registration_type,
                "years_of_experience": years_of_experience,
                "current_aum": current_aum,
                "address": full_address,
                "city": city,
                "state": state,
                "pincode": pincode,
                "country": country,
                "about": about,
                # System / internal
                "color": "#C9A227",  # Etihad gold
                "created_by": current_user['id'],
                "is_active": False,  # Inactive until broker verifies
                "status": "pending_verification",
                "needs_password_reset": True,
                "created_at": datetime.now(timezone.utc).isoformat(),
                "source": "bulk_upload"
            }
            await db.Mfd_Ria_Partner.insert_one(partner)
            
            results['success'] += 1
            results['created_subbrokers'].append({
                "name": name,
                "pan": pan,
                "partner_code": partner_code,
                "email": email,
                "status": "pending_verification"
            })
            
            # Note: Password reset email will be sent AFTER broker verifies the upload
            # The broker will trigger the verification which activates the account and sends the email
            
        except Exception as e:
            results['errors'].append(f"Row {idx+2}: {str(e)}")
            results['failed'] += 1
    
    return results


