@api_router.post("/bulk/benchmark-data")
async def bulk_upload_benchmark_data(
    file: UploadFile = File(...),
    current_user: dict = Depends(get_current_user)
):
    """
    Bulk upload benchmark data (scheme mappings and benchmark values).
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can bulk upload benchmark data")
    
    if not file.filename.endswith(('.xlsx', '.xls')):
        raise HTTPException(status_code=400, detail="Please upload an Excel file (.xlsx or .xls)")
    
    import pandas as pd
    
    content = await file.read()
    
    results = {
        "success": 0,
        "failed": 0,
        "errors": [],
        "scheme_mappings_added": 0,
        "scheme_mappings_updated": 0,
        "benchmark_values_added": 0,
        "benchmark_values_updated": 0
    }
    
    try:
        # Read Scheme to BM Mapping sheet
        try:
            df_mapping = pd.read_excel(io.BytesIO(content), sheet_name="Scheme BM Mapping")
        except Exception:
            try:
                df_mapping = pd.read_excel(io.BytesIO(content), sheet_name="Sheet1")
            except Exception:
                df_mapping = pd.read_excel(io.BytesIO(content), sheet_name=0)
        
        # Normalize column names
        df_mapping.columns = [str(col).replace('*', '').strip().lower().replace(' ', '_') for col in df_mapping.columns]
        
        # Process scheme mappings
        if 'scheme_code' in df_mapping.columns and 'bm_code' in df_mapping.columns:
            for idx, row in df_mapping.iterrows():
                row_num = idx + 2
                try:
                    if pd.isna(row.get('scheme_code')) or pd.isna(row.get('bm_code')):
                        continue
                    
                    scheme_code = str(int(row['scheme_code'])) if isinstance(row['scheme_code'], float) else str(row['scheme_code'])
                    bm_code = str(row['bm_code']).strip()
                    
                    # Upsert scheme-benchmark mapping
                    result = await db.scheme_benchmark_mapping.update_one(
                        {"scheme_code": scheme_code},
                        {"$set": {
                            "scheme_code": scheme_code,
                            "bm_code": bm_code,
                            "updated_at": datetime.now(timezone.utc).isoformat(),
                            "updated_by": current_user['id']
                        }},
                        upsert=True
                    )
                    
                    if result.upserted_id:
                        results['scheme_mappings_added'] += 1
                    else:
                        results['scheme_mappings_updated'] += 1
                    results['success'] += 1
                    
                except Exception as e:
                    results['errors'].append(f"Mapping Row {row_num}: {str(e)}")
                    results['failed'] += 1
        
        # Read BM Values sheet
        try:
            df_values = pd.read_excel(io.BytesIO(content), sheet_name="BM Values")
        except Exception:
            df_values = None
        
        if df_values is not None and len(df_values) > 0:
            df_values.columns = [str(col).replace('*', '').strip().lower().replace(' ', '_') for col in df_values.columns]
            
            for idx, row in df_values.iterrows():
                row_num = idx + 2
                try:
                    if pd.isna(row.get('benchmark_code')) or pd.isna(row.get('benchmark_value')):
                        continue
                    
                    benchmark_code = str(row['benchmark_code']).strip()
                    benchmark_value = float(row['benchmark_value'])
                    as_on_date = row.get('as_on_date')
                    
                    # Parse date
                    if isinstance(as_on_date, str):
                        as_on_date_str = as_on_date[:10]
                    else:
                        as_on_date_str = as_on_date.strftime('%Y-%m-%d') if hasattr(as_on_date, 'strftime') else str(as_on_date)[:10]
                    
                    bm_record = {
                        "benchmark": str(row.get('benchmark', '')).strip() if pd.notna(row.get('benchmark')) else '',
                        "benchmark_code": benchmark_code,
                        "benchmark_value": benchmark_value,
                        "as_on_date": as_on_date_str,
                        "alt_benchmark": str(row.get('alt_benchmark', '')).strip() if pd.notna(row.get('alt_benchmark')) else None,
                        "alt_benchmark_code": str(row.get('alt_benchmark_code', '')).strip() if pd.notna(row.get('alt_benchmark_code')) else None,
                        "final_benchmark": str(row.get('final_benchmark', benchmark_code)).strip() if pd.notna(row.get('final_benchmark')) else benchmark_code,
                        "updated_at": datetime.now(timezone.utc).isoformat()
                    }
                    
                    # Upsert benchmark value
                    result = await db.benchmark_values.update_one(
                        {"benchmark_code": benchmark_code, "as_on_date": as_on_date_str},
                        {"$set": bm_record},
                        upsert=True
                    )
                    
                    if result.upserted_id:
                        results['benchmark_values_added'] += 1
                    else:
                        results['benchmark_values_updated'] += 1
                    results['success'] += 1
                    
                except Exception as e:
                    results['errors'].append(f"BM Values Row {row_num}: {str(e)}")
                    results['failed'] += 1
    
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error processing benchmark data upload: {str(e)}")
        results['errors'].append(f"Processing error: {str(e)}")
    
    return results


@api_router.get("/benchmark-data/status")
async def get_benchmark_data_status(current_user: dict = Depends(get_current_user)):
    """Get status of benchmark data in the database"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Access denied")
    
    values_count = await db.benchmark_values.count_documents({})
    
    # Get unique benchmark codes
    unique_benchmarks = await db.benchmark_values.distinct("benchmark_code")
    
    # Get date range
    latest = await db.benchmark_values.find_one(sort=[("as_on_date", -1)])
    earliest = await db.benchmark_values.find_one(sort=[("as_on_date", 1)])
    
    # Get last 3 upload dates
    upload_history = await db.upload_history.find(
        {"upload_type": "benchmark_nav_data"},
        {"_id": 0, "uploaded_at": 1, "filename": 1, "records_processed": 1}
    ).sort("uploaded_at", -1).limit(3).to_list(3)
    
    # Get sample benchmark names
    sample_benchmarks = await db.benchmark_values.aggregate([
        {"$group": {"_id": "$benchmark"}},
        {"$limit": 5}
    ]).to_list(5)
    sample_names = [b["_id"] for b in sample_benchmarks if b["_id"]]
    
    return {
        "benchmark_values_count": values_count,
        "unique_benchmarks": len(unique_benchmarks),
        "sample_benchmarks": sample_names,
        "date_range": {
            "earliest": earliest.get('as_on_date') if earliest else None,
            "latest": latest.get('as_on_date') if latest else None
        },
        "upload_history": upload_history
    }


@api_router.post("/bulk/benchmark-nav-data")
async def bulk_upload_benchmark_nav_data(
    file: UploadFile = File(...),
    current_user: dict = Depends(get_current_user)
):
    """
    Upload historical benchmark NAV data (benchmark values over time).
    Used for comparing fund performance against benchmark.
    Uses background processing for large files.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can upload benchmark data")
    
    if not file.filename.endswith(('.xlsx', '.xls', '.csv')):
        raise HTTPException(status_code=400, detail="Please upload an Excel or CSV file (.xlsx, .xls, .csv)")
    
    content = await file.read()
    file_size = len(content)
    
    # For files > 500KB, use background processing
    if file_size > 500_000:
        job_id = str(uuid.uuid4())
        
        # Store initial job status
        await db.upload_jobs.insert_one({
            "job_id": job_id,
            "type": "benchmark_nav_data",
            "status": "processing",
            "total_rows": 0,
            "processed_rows": 0,
            "success": 0,
            "failed": 0,
            "values_added": 0,
            "errors": [],
            "started_at": datetime.now(timezone.utc).isoformat(),
            "user_id": current_user['id'],
            "filename": file.filename,
            "file_size_mb": round(file_size / 1_000_000, 2),
            "progress_pct": 0
        })
        
        # Start background task
        import asyncio
        asyncio.create_task(process_benchmark_nav_upload_background(job_id, content, file.filename, current_user['id']))
        
        return {
            "status": "processing",
            "job_id": job_id,
            "message": f"Large file detected ({round(file_size/1_000_000, 2)} MB). Processing in background.",
            "file_size_mb": round(file_size / 1_000_000, 2)
        }
    
    # For smaller files, process immediately
    return await process_benchmark_nav_upload_sync(content, file.filename, current_user['id'])


async def process_benchmark_nav_upload_sync(content: bytes, filename: str, user_id: str):
    """Process benchmark NAV data upload synchronously for smaller files"""
    import pandas as pd
    
    results = {
        "success": 0,
        "failed": 0,
        "errors": [],
        "values_added": 0,
        "values_updated": 0,
        "unique_benchmarks": 0,
        "date_range": {"earliest": None, "latest": None}
    }
    
    try:
        # Read file based on extension
        if filename.endswith('.csv'):
            df = pd.read_csv(io.BytesIO(content))
        else:
            df = pd.read_excel(io.BytesIO(content), sheet_name=0)
        
        df.columns = [str(col).strip().lower().replace(' ', '_') for col in df.columns]
        
        benchmark_codes_seen = set()
        dates_seen = set()
        
        for idx, row in df.iterrows():
            row_num = idx + 2
            try:
                # Get benchmark code
                benchmark_code = str(row.get('benchmark_code', '')).strip() if pd.notna(row.get('benchmark_code')) else ''
                if not benchmark_code:
                    continue
                
                # Get benchmark value
                benchmark_value = row.get('benchmark_value')
                if pd.isna(benchmark_value):
                    continue
                benchmark_value = float(benchmark_value)
                
                # Get date
                as_on_date = row.get('as_on_date')
                if pd.isna(as_on_date):
                    continue
                if isinstance(as_on_date, str):
                    as_on_date_str = as_on_date[:10]
                else:
                    as_on_date_str = as_on_date.strftime('%Y-%m-%d') if hasattr(as_on_date, 'strftime') else str(as_on_date)[:10]
                
                benchmark_codes_seen.add(benchmark_code)
                dates_seen.add(as_on_date_str)
                
                bm_record = {
                    "benchmark": str(row.get('benchmark', '')).strip() if pd.notna(row.get('benchmark')) else '',
                    "benchmark_code": benchmark_code,
                    "benchmark_value": benchmark_value,
                    "as_on_date": as_on_date_str,
                    "alt_benchmark": str(row.get('alt_benchmark', '')).strip() if pd.notna(row.get('alt_benchmark')) else None,
                    "alt_benchmark_code": str(row.get('alt_benchmark_code', '')).strip() if pd.notna(row.get('alt_benchmark_code')) else None,
                    "final_benchmark": str(row.get('final_benchmark', benchmark_code)).strip() if pd.notna(row.get('final_benchmark')) else benchmark_code,
                    "updated_at": datetime.now(timezone.utc).isoformat(),
                    "updated_by": user_id
                }
                
                result = await db.benchmark_values.update_one(
                    {"benchmark_code": benchmark_code, "as_on_date": as_on_date_str},
                    {"$set": bm_record},
                    upsert=True
                )
                
                if result.upserted_id:
                    results['values_added'] += 1
                else:
                    results['values_updated'] += 1
                results['success'] += 1
                
            except Exception as e:
                results['errors'].append(f"Row {row_num}: {str(e)}")
                results['failed'] += 1
                if len(results['errors']) > 10:
                    results['errors'] = results['errors'][:10]
        
        results['unique_benchmarks'] = len(benchmark_codes_seen)
        if dates_seen:
            results['date_range'] = {
                "earliest": min(dates_seen),
                "latest": max(dates_seen)
            }
        
        # Save upload history
        await db.upload_history.insert_one({
            "upload_type": "benchmark_nav_data",
            "filename": filename,
            "uploaded_at": datetime.now(timezone.utc).isoformat(),
            "uploaded_by": user_id,
            "records_processed": results['success'],
            "unique_benchmarks": results['unique_benchmarks'],
            "date_range": results['date_range']
        })
        
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error processing benchmark NAV data: {str(e)}")
        results['errors'].append(f"Processing error: {str(e)}")
    
    return results


async def process_benchmark_nav_upload_background(job_id: str, content: bytes, filename: str, user_id: str):
    """Process large benchmark NAV data upload in background with progress tracking"""
    import pandas as pd
    from pymongo import UpdateOne
    
    try:
        logger.info(f"Starting background benchmark NAV upload job: {job_id}")
        
        # Read file based on extension
        if filename.endswith('.csv'):
            df = pd.read_csv(io.BytesIO(content))
        else:
            df = pd.read_excel(io.BytesIO(content), sheet_name=0)
        
        total_rows = len(df)
        
        # Update job with total rows
        await db.upload_jobs.update_one(
            {"job_id": job_id},
            {"$set": {"total_rows": total_rows, "status": "reading_complete"}}
        )
        
        logger.info(f"Job {job_id}: Loaded {total_rows} rows")
        
        df.columns = [str(col).strip().lower().replace(' ', '_') for col in df.columns]
        
        benchmark_codes_seen = set()
        dates_seen = set()
        batch_size = 5000  # Increased batch size for bulk operations
        
        success = 0
        failed = 0
        values_added = 0
        values_updated = 0
        errors = []
        
        # Process in batches using bulk_write for much faster performance
        bulk_operations = []
        
        for idx, row in df.iterrows():
            try:
                benchmark_code = str(row.get('benchmark_code', '')).strip() if pd.notna(row.get('benchmark_code')) else ''
                if not benchmark_code:
                    continue
                
                benchmark_value = row.get('benchmark_value')
                if pd.isna(benchmark_value):
                    continue
                benchmark_value = float(benchmark_value)
                
                as_on_date = row.get('as_on_date')
                if pd.isna(as_on_date):
                    continue
                if isinstance(as_on_date, str):
                    as_on_date_str = as_on_date[:10]
                else:
                    as_on_date_str = as_on_date.strftime('%Y-%m-%d') if hasattr(as_on_date, 'strftime') else str(as_on_date)[:10]
                
                benchmark_codes_seen.add(benchmark_code)
                dates_seen.add(as_on_date_str)
                
                bm_record = {
                    "benchmark": str(row.get('benchmark', '')).strip() if pd.notna(row.get('benchmark')) else '',
                    "benchmark_code": benchmark_code,
                    "benchmark_value": benchmark_value,
                    "as_on_date": as_on_date_str,
                    "alt_benchmark": str(row.get('alt_benchmark', '')).strip() if pd.notna(row.get('alt_benchmark')) else None,
                    "alt_benchmark_code": str(row.get('alt_benchmark_code', '')).strip() if pd.notna(row.get('alt_benchmark_code')) else None,
                    "final_benchmark": str(row.get('final_benchmark', benchmark_code)).strip() if pd.notna(row.get('final_benchmark')) else benchmark_code,
                    "updated_at": datetime.now(timezone.utc).isoformat(),
                    "updated_by": user_id
                }
                
                # Add to bulk operations list
                bulk_operations.append(
                    UpdateOne(
                        {"benchmark_code": benchmark_code, "as_on_date": as_on_date_str},
                        {"$set": bm_record},
                        upsert=True
                    )
                )
                success += 1
                
                # Execute bulk write when batch is full
                if len(bulk_operations) >= batch_size:
                    # Check if job was cancelled
                    job_check = await db.upload_jobs.find_one({"job_id": job_id}, {"status": 1})
                    if job_check and job_check.get('status') == 'cancelled':
                        logger.info(f"Job {job_id} was cancelled, stopping processing")
                        return
                    
                    try:
                        result = await db.benchmark_values.bulk_write(bulk_operations, ordered=False)
                        values_added += result.upserted_count
                        values_updated += result.modified_count
                    except Exception as bulk_err:
                        logger.warning(f"Bulk write partial error: {bulk_err}")
                    
                    bulk_operations = []
                    
                    # Update progress
                    await db.upload_jobs.update_one(
                        {"job_id": job_id},
                        {"$set": {
                            "processed_rows": idx + 1,
                            "success": success,
                            "failed": failed,
                            "values_added": values_added,
                            "values_updated": values_updated,
                            "progress_pct": round((idx + 1) / total_rows * 100, 1)
                        }}
                    )
                
            except Exception as e:
                failed += 1
                if len(errors) < 10:
                    errors.append(f"Row {idx + 2}: {str(e)}")
        
        # Process remaining operations
        if bulk_operations:
            try:
                result = await db.benchmark_values.bulk_write(bulk_operations, ordered=False)
                values_added += result.upserted_count
                values_updated += result.modified_count
            except Exception as bulk_err:
                logger.warning(f"Final bulk write error: {bulk_err}")
        
        # Save upload history
        date_range = {}
        if dates_seen:
            date_range = {"earliest": min(dates_seen), "latest": max(dates_seen)}
        
        await db.upload_history.insert_one({
            "upload_type": "benchmark_nav_data",
            "filename": filename,
            "uploaded_at": datetime.now(timezone.utc).isoformat(),
            "uploaded_by": user_id,
            "records_processed": success,
            "unique_benchmarks": len(benchmark_codes_seen),
            "date_range": date_range
        })
        
        # Update final status
        await db.upload_jobs.update_one(
            {"job_id": job_id},
            {"$set": {
                "status": "completed",
                "processed_rows": total_rows,
                "success": success,
                "failed": failed,
                "values_added": values_added,
                "values_updated": values_updated,
                "unique_benchmarks": len(benchmark_codes_seen),
                "date_range": date_range,
                "errors": errors,
                "progress_pct": 100,
                "completed_at": datetime.now(timezone.utc).isoformat()
            }}
        )
        
        logger.info(f"Job {job_id}: Completed - {success} values from {len(benchmark_codes_seen)} benchmarks")
        
    except Exception as e:
        logger.error(f"Background benchmark NAV upload failed: {str(e)}")
        await db.upload_jobs.update_one(
            {"job_id": job_id},
            {"$set": {
                "status": "failed",
                "error": str(e),
                "completed_at": datetime.now(timezone.utc).isoformat()
            }}
        )


@api_router.get("/bulk/benchmark-nav-data/job/{job_id}")
async def get_benchmark_nav_upload_job_status(
    job_id: str,
    current_user: dict = Depends(get_current_user)
):
    """Get status of a background benchmark NAV data upload job"""
    job = await db.upload_jobs.find_one({"job_id": job_id}, {"_id": 0})
    
    if not job:
        raise HTTPException(status_code=404, detail="Job not found")
    
    return job


@api_router.delete("/bulk/benchmark-nav-data/job/{job_id}")
async def cancel_benchmark_nav_upload_job(
    job_id: str,
    current_user: dict = Depends(get_current_user)
):
    """Cancel/stop a background benchmark NAV data upload job"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can cancel upload jobs")
    
    job = await db.upload_jobs.find_one({"job_id": job_id})
    
    if not job:
        raise HTTPException(status_code=404, detail="Job not found")
    
    if job.get('status') == 'completed':
        raise HTTPException(status_code=400, detail="Job already completed, cannot cancel")
    
    # Mark job as cancelled
    await db.upload_jobs.update_one(
        {"job_id": job_id},
        {"$set": {
            "status": "cancelled",
            "cancelled_at": datetime.now(timezone.utc).isoformat(),
            "cancelled_by": current_user['id']
        }}
    )
    
    return {
        "message": "Job cancelled successfully",
        "job_id": job_id,
        "processed_rows": job.get('processed_rows', 0),
        "values_added": job.get('values_added', 0)
    }


@api_router.get("/bulk/upload-jobs")
async def list_upload_jobs(
    status: str = None,
    limit: int = 10,
    current_user: dict = Depends(get_current_user)
):
    """List all upload jobs with optional status filter"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can view upload jobs")
    
    query = {}
    if status:
        query["status"] = status
    
    jobs = await db.upload_jobs.find(
        query,
        {"_id": 0}
    ).sort("started_at", -1).limit(limit).to_list(limit)
    
    return {"jobs": jobs, "count": len(jobs)}


# ==================== AMFI SCHEME DATA UPLOAD ====================

@api_router.post("/bulk/amfi-scheme-data")
async def bulk_upload_amfi_scheme_data(
    file: UploadFile = File(...),
    current_user: dict = Depends(get_current_user)
):
    """
    Upload AMFI scheme data CSV. 
    Each scheme code can have two ISINs - one for dividend payout/growth and one for dividend reinvestment.
    Creates separate records for each ISIN with the same AMFI code.
    Uses background processing for large files.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can upload AMFI scheme data")
    
    if not file.filename.endswith(('.csv', '.xlsx', '.xls')):
        raise HTTPException(status_code=400, detail="Please upload a CSV or Excel file")
    
    content = await file.read()
    file_size = len(content)
    
    # For files > 500KB, use background processing
    if file_size > 500_000:
        job_id = str(uuid.uuid4())
        
        # Store initial job status
        await db.upload_jobs.insert_one({
            "job_id": job_id,
            "type": "amfi_scheme_data",
            "status": "processing",
            "total_rows": 0,
            "processed_rows": 0,
            "success": 0,
            "failed": 0,
            "isin_records_created": 0,
            "errors": [],
            "started_at": datetime.now(timezone.utc).isoformat(),
            "user_id": current_user['id'],
            "filename": file.filename,
            "file_size_mb": round(file_size / 1_000_000, 2),
            "progress_pct": 0
        })
        
        # Start background task
        import asyncio
        asyncio.create_task(process_amfi_scheme_upload_background(job_id, content, file.filename, current_user['id']))
        
        return {
            "status": "processing",
            "job_id": job_id,
            "message": f"Large file detected ({round(file_size/1_000_000, 2)} MB). Processing in background.",
            "file_size_mb": round(file_size / 1_000_000, 2)
        }
    
    # For smaller files, process immediately
    return await process_amfi_scheme_upload_sync(content, file.filename, current_user['id'])


async def process_amfi_scheme_upload_sync(content: bytes, filename: str, user_id: str):
    """Process AMFI scheme data upload synchronously for smaller files"""
    import pandas as pd
    import re
    
    results = {
        "success": 0,
        "failed": 0,
        "errors": [],
        "schemes_added": 0,
        "schemes_updated": 0,
        "total_isin_records": 0
    }
    
    try:
        # Read file
        if filename.endswith('.csv'):
            df = pd.read_csv(io.BytesIO(content))
        else:
            df = pd.read_excel(io.BytesIO(content), sheet_name=0)
        
        # Normalize column names
        df.columns = [str(col).strip().lower().replace(' ', '_') for col in df.columns]
        
        # Find the ISIN column (may have different names)
        isin_col = None
        for col in df.columns:
            if 'isin' in col.lower():
                isin_col = col
                break
        
        if not isin_col:
            raise HTTPException(status_code=400, detail="No ISIN column found in file")
        
        # Find code column
        code_col = None
        for col in df.columns:
            if col.lower() in ['code', 'scheme_code', 'amfi_code']:
                code_col = col
                break
        
        if not code_col:
            raise HTTPException(status_code=400, detail="No scheme code column found")
        
        current_time = datetime.now(timezone.utc).isoformat()
        operations = []
        
        for idx, row in df.iterrows():
            try:
                scheme_code = str(row.get(code_col, '')).strip()
                if pd.isna(scheme_code) or not scheme_code:
                    continue
                
                scheme_name = str(row.get('scheme_name', '')).strip() if pd.notna(row.get('scheme_name')) else ''
                scheme_nav_name = str(row.get('scheme_nav_name', '')).strip() if pd.notna(row.get('scheme_nav_name')) else ''
                amc = str(row.get('amc', '')).strip() if pd.notna(row.get('amc')) else ''
                scheme_type = str(row.get('scheme_type', '')).strip() if pd.notna(row.get('scheme_type')) else ''
                scheme_category = str(row.get('scheme_category', '')).strip() if pd.notna(row.get('scheme_category')) else ''
                
                # Parse ISINs - they may be concatenated like "INF209K01157INF209K01CE5"
                isin_raw = str(row.get(isin_col, '')).strip() if pd.notna(row.get(isin_col)) else ''
                
                # Extract all ISINs (format: INFxxxxxxxxx - 12 chars)
                isins = re.findall(r'INF[A-Z0-9]{9}', isin_raw)
                
                if not isins:
                    # Try single ISIN without INF prefix match
                    if isin_raw and len(isin_raw) >= 12:
                        isins = [isin_raw[:12]]
                
                if not isins:
                    continue
                
                # Create a record for each ISIN
                for i, isin in enumerate(isins):
                    isin_type = 'dividend_payout' if i == 0 else 'dividend_reinvestment'
                    if len(isins) == 1:
                        isin_type = 'growth'  # Single ISIN usually means growth option
                    
                    record = {
                        "scheme_code": scheme_code,
                        "isin": isin,
                        "isin_type": isin_type,
                        "scheme_name": scheme_name,
                        "scheme_nav_name": scheme_nav_name,
                        "amc": amc,
                        "scheme_type": scheme_type,
                        "scheme_category": scheme_category,
                        "updated_at": current_time,
                        "updated_by": user_id
                    }
                    
                    operations.append({
                        "filter": {"isin": isin},
                        "update": {"$set": record},
                        "upsert": True
                    })
                    
                    results['total_isin_records'] += 1
                
                results['success'] += 1
                
                # Batch execute every 1000 operations
                if len(operations) >= 1000:
                    for op in operations:
                        await db.amfi_scheme_data.update_one(
                            op['filter'], op['update'], upsert=op['upsert']
                        )
                    operations = []
                    
            except Exception as e:
                results['errors'].append(f"Row {idx + 2}: {str(e)}")
                results['failed'] += 1
                if len(results['errors']) > 10:
                    results['errors'] = results['errors'][:10]
        
        # Execute remaining operations
        for op in operations:
            result = await db.amfi_scheme_data.update_one(
                op['filter'], op['update'], upsert=op['upsert']
            )
            if result.upserted_id:
                results['schemes_added'] += 1
            else:
                results['schemes_updated'] += 1
        
        # Save upload history
        await db.upload_history.insert_one({
            "upload_type": "amfi_scheme_data",
            "filename": filename,
            "uploaded_at": datetime.now(timezone.utc).isoformat(),
            "uploaded_by": user_id,
            "records_processed": results['success'],
            "isin_records_created": results['total_isin_records']
        })
    
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error processing AMFI scheme data: {str(e)}")
        results['errors'].append(f"Processing error: {str(e)}")
    
    return results


async def process_amfi_scheme_upload_background(job_id: str, content: bytes, filename: str, user_id: str):
    """Process large AMFI scheme data upload in background with progress tracking"""
    import pandas as pd
    import re
    
    try:
        logger.info(f"Starting background AMFI scheme upload job: {job_id}")
        
        # Read file
        if filename.endswith('.csv'):
            df = pd.read_csv(io.BytesIO(content))
        else:
            df = pd.read_excel(io.BytesIO(content), sheet_name=0)
        
        total_rows = len(df)
        
        # Update job with total rows
        await db.upload_jobs.update_one(
            {"job_id": job_id},
            {"$set": {"total_rows": total_rows, "status": "reading_complete"}}
        )
        
        logger.info(f"Job {job_id}: Loaded {total_rows} rows")
        
        # Normalize column names
        df.columns = [str(col).strip().lower().replace(' ', '_') for col in df.columns]
        
        # Find the ISIN column
        isin_col = None
        for col in df.columns:
            if 'isin' in col.lower():
                isin_col = col
                break
        
        # Find code column
        code_col = None
        for col in df.columns:
            if col.lower() in ['code', 'scheme_code', 'amfi_code']:
                code_col = col
                break
        
        if not isin_col or not code_col:
            await db.upload_jobs.update_one(
                {"job_id": job_id},
                {"$set": {"status": "failed", "error": "Missing required columns (ISIN or Code)"}}
            )
            return
        
        current_time = datetime.now(timezone.utc).isoformat()
        batch_size = 1000
        operations = []
        
        success = 0
        failed = 0
        isin_records_created = 0
        errors = []
        
        for idx, row in df.iterrows():
            try:
                scheme_code = str(row.get(code_col, '')).strip()
                if pd.isna(scheme_code) or not scheme_code:
                    continue
                
                scheme_name = str(row.get('scheme_name', '')).strip() if pd.notna(row.get('scheme_name')) else ''
                scheme_nav_name = str(row.get('scheme_nav_name', '')).strip() if pd.notna(row.get('scheme_nav_name')) else ''
                amc = str(row.get('amc', '')).strip() if pd.notna(row.get('amc')) else ''
                scheme_type = str(row.get('scheme_type', '')).strip() if pd.notna(row.get('scheme_type')) else ''
                scheme_category = str(row.get('scheme_category', '')).strip() if pd.notna(row.get('scheme_category')) else ''
                
                # Parse ISINs
                isin_raw = str(row.get(isin_col, '')).strip() if pd.notna(row.get(isin_col)) else ''
                isins = re.findall(r'INF[A-Z0-9]{9}', isin_raw)
                
                if not isins and isin_raw and len(isin_raw) >= 12:
                    isins = [isin_raw[:12]]
                
                if not isins:
                    continue
                
                for i, isin in enumerate(isins):
                    isin_type = 'dividend_payout' if i == 0 else 'dividend_reinvestment'
                    if len(isins) == 1:
                        isin_type = 'growth'
                    
                    record = {
                        "scheme_code": scheme_code,
                        "isin": isin,
                        "isin_type": isin_type,
                        "scheme_name": scheme_name,
                        "scheme_nav_name": scheme_nav_name,
                        "amc": amc,
                        "scheme_type": scheme_type,
                        "scheme_category": scheme_category,
                        "updated_at": current_time,
                        "updated_by": user_id
                    }
                    
                    await db.amfi_scheme_data.update_one(
                        {"isin": isin},
                        {"$set": record},
                        upsert=True
                    )
                    isin_records_created += 1
                
                success += 1
                
                # Update progress every batch
                if success % batch_size == 0:
                    await db.upload_jobs.update_one(
                        {"job_id": job_id},
                        {"$set": {
                            "processed_rows": idx + 1,
                            "success": success,
                            "failed": failed,
                            "isin_records_created": isin_records_created,
                            "progress_pct": round((idx + 1) / total_rows * 100, 1)
                        }}
                    )
                    
            except Exception as e:
                failed += 1
                if len(errors) < 10:
                    errors.append(f"Row {idx + 2}: {str(e)}")
        
        # Save upload history
        await db.upload_history.insert_one({
            "upload_type": "amfi_scheme_data",
            "filename": filename,
            "uploaded_at": datetime.now(timezone.utc).isoformat(),
            "uploaded_by": user_id,
            "records_processed": success,
            "isin_records_created": isin_records_created
        })
        
        # Update final status
        await db.upload_jobs.update_one(
            {"job_id": job_id},
            {"$set": {
                "status": "completed",
                "processed_rows": total_rows,
                "success": success,
                "failed": failed,
                "isin_records_created": isin_records_created,
                "errors": errors,
                "progress_pct": 100,
                "completed_at": datetime.now(timezone.utc).isoformat()
            }}
        )
        
        logger.info(f"Job {job_id}: Completed - {success} schemes, {isin_records_created} ISIN records")
        
    except Exception as e:
        logger.error(f"Background AMFI scheme upload failed: {str(e)}")
        await db.upload_jobs.update_one(
            {"job_id": job_id},
            {"$set": {
                "status": "failed",
                "error": str(e),
                "completed_at": datetime.now(timezone.utc).isoformat()
            }}
        )


@api_router.get("/bulk/amfi-scheme-data/job/{job_id}")
async def get_amfi_scheme_upload_job_status(
    job_id: str,
    current_user: dict = Depends(get_current_user)
):
    """Get status of a background AMFI scheme data upload job"""
    job = await db.upload_jobs.find_one({"job_id": job_id}, {"_id": 0})
    
    if not job:
        raise HTTPException(status_code=404, detail="Job not found")
    
    return job


@api_router.delete("/bulk/amfi-scheme-data/job/{job_id}")
async def cancel_amfi_scheme_upload_job(
    job_id: str,
    current_user: dict = Depends(get_current_user)
):
    """Cancel/stop a background AMFI scheme data upload job"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can cancel upload jobs")
    
    job = await db.upload_jobs.find_one({"job_id": job_id})
    
    if not job:
        raise HTTPException(status_code=404, detail="Job not found")
    
    if job.get('status') == 'completed':
        raise HTTPException(status_code=400, detail="Job already completed, cannot cancel")
    
    # Mark job as cancelled
    await db.upload_jobs.update_one(
        {"job_id": job_id},
        {"$set": {
            "status": "cancelled",
            "cancelled_at": datetime.now(timezone.utc).isoformat(),
            "cancelled_by": current_user['id']
        }}
    )
    
    return {
        "message": "Job cancelled successfully",
        "job_id": job_id,
        "processed_rows": job.get('processed_rows', 0)
    }


@api_router.get("/amfi-scheme-data/status")
async def get_amfi_scheme_data_status(current_user: dict = Depends(get_current_user)):
    """Get status of AMFI scheme data in the database"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Access denied")
    
    total_records = await db.amfi_scheme_data.count_documents({})
    unique_schemes = len(await db.amfi_scheme_data.distinct("scheme_code"))
    unique_isins = len(await db.amfi_scheme_data.distinct("isin"))
    
    # Get count by ISIN type
    growth_count = await db.amfi_scheme_data.count_documents({"isin_type": "growth"})
    div_payout = await db.amfi_scheme_data.count_documents({"isin_type": "dividend_payout"})
    div_reinvest = await db.amfi_scheme_data.count_documents({"isin_type": "dividend_reinvestment"})
    
    # Get last 3 unique upload dates from upload_history collection
    upload_history = await db.upload_history.find(
        {"upload_type": "amfi_scheme_data"},
        {"_id": 0, "uploaded_at": 1, "filename": 1, "records_processed": 1}
    ).sort("uploaded_at", -1).limit(3).to_list(3)
    
    latest = await db.amfi_scheme_data.find_one(sort=[("updated_at", -1)])
    
    return {
        "total_records": total_records,
        "unique_schemes": unique_schemes,
        "unique_isins": unique_isins,
        "by_isin_type": {
            "growth": growth_count,
            "dividend_payout": div_payout,
            "dividend_reinvestment": div_reinvest
        },
        "last_updated": latest.get('updated_at') if latest else None,
        "upload_history": upload_history
    }


