@api_router.post("/bulk/stockwise-holding")
async def bulk_upload_stockwise_holding(
    file: UploadFile = File(...),
    background_tasks: BackgroundTasks = None,
    current_user: dict = Depends(get_current_user)
):
    """
    Bulk upload stockwise holding/portfolio data for mutual fund schemes.
    For large files, starts a background job and returns job_id for progress tracking.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can bulk upload portfolio data")
    
    if not file.filename.endswith(('.xlsx', '.xls')):
        raise HTTPException(status_code=400, detail="Please upload an Excel file (.xlsx or .xls)")
    
    content = await file.read()
    file_size = len(content)
    
    # For files > 1MB, use background processing (don't read Excel upfront)
    if file_size > 1_000_000:  # 1MB threshold
        job_id = str(uuid.uuid4())
        
        # Store initial job status
        await db.upload_jobs.insert_one({
            "job_id": job_id,
            "type": "stockwise_holding",
            "status": "processing",
            "total_rows": 0,  # Will be updated when processing starts
            "processed_rows": 0,
            "success": 0,
            "failed": 0,
            "holdings_added": 0,
            "holdings_updated": 0,
            "errors": [],
            "started_at": datetime.now(timezone.utc).isoformat(),
            "user_id": current_user['id'],
            "filename": file.filename,
            "file_size_mb": round(file_size / 1_000_000, 2),
            "progress_pct": 0
        })
        
        # Start background task
        import asyncio
        asyncio.create_task(process_stockwise_upload_background(job_id, content, current_user['id'], file.filename))
        
        return {
            "status": "processing",
            "job_id": job_id,
            "message": f"Large file detected ({round(file_size/1_000_000, 2)} MB). Processing in background.",
            "file_size_mb": round(file_size / 1_000_000, 2)
        }
    
    # For smaller files, process immediately
    import pandas as pd
    df = pd.read_excel(io.BytesIO(content), sheet_name=0)
    return await process_stockwise_upload_sync(df, current_user['id'])


async def process_stockwise_upload_sync(df, user_id: str):
    """Process stockwise upload synchronously for smaller files.
    REPLACES all existing stockwise data (deletes first, then inserts new)."""
    import pandas as pd
    from pymongo import InsertOne
    
    results = {
        "success": 0,
        "failed": 0,
        "errors": [],
        "holdings_added": 0,
        "holdings_deleted": 0,
        "schemes_processed": set(),
        "month_end": None
    }
    
    try:
        # DELETE all existing stockwise holdings data first
        delete_result = await db.stockwise_holdings.delete_many({})
        results['holdings_deleted'] = delete_result.deleted_count
        logger.info(f"Stockwise sync upload: Deleted {delete_result.deleted_count} existing records")
        
        # Normalize column names
        df.columns = [str(col).replace('*', '').replace('\n', ' ').strip().lower().replace(' ', '_').replace('(rs._cr.)', '_cr').replace('(rs.cr.)', '_cr') for col in df.columns]
        
        # Required columns
        required_cols = ['scheme_name', 'amfi_code', 'name_of_the_instrument']
        missing_cols = [col for col in required_cols if col not in df.columns]
        if missing_cols:
            alt_mapping = {
                'scheme_name': ['scheme_name1'],
                'amfi_code': ['amfi_code'],
                'name_of_the_instrument': ['name_of_the_instrument', 'instrument_name', 'stock_name']
            }
            for req, alts in alt_mapping.items():
                if req in missing_cols:
                    for alt in alts:
                        if alt in df.columns:
                            df = df.rename(columns={alt: req})
                            missing_cols.remove(req)
                            break
        
        if missing_cols:
            raise HTTPException(status_code=400, detail=f"Missing required columns: {', '.join(missing_cols)}")
        
        batch_size = 1000
        operations = []
        current_time = datetime.now(timezone.utc).isoformat()
        
        for idx, row in df.iterrows():
            try:
                scheme_name = str(row.get('scheme_name') or row.get('scheme_name1', '')).strip()
                if pd.isna(scheme_name) or not scheme_name:
                    continue
                
                amfi_code = str(int(row['amfi_code'])) if pd.notna(row['amfi_code']) else ''
                instrument_name = str(row.get('name_of_the_instrument', '')).strip()
                
                if not instrument_name:
                    continue
                
                month_end = str(row.get('month_end', '')).strip() if pd.notna(row.get('month_end')) else ''
                if month_end and not results['month_end']:
                    results['month_end'] = month_end
                
                market_value = 0
                for col_name in ['market/fair_value__cr', 'market/fair_value_cr', 'market_value_cr', 'market_fair_value_cr']:
                    if col_name in df.columns and pd.notna(row.get(col_name)):
                        market_value = float(row.get(col_name, 0))
                        break
                
                instrument_isin = str(row.get('isin', '')).strip() if pd.notna(row.get('isin')) else ''
                
                holding_record = {
                    "scheme_name": scheme_name,
                    "amc_code": str(row.get('amc_code', '')).strip() if pd.notna(row.get('amc_code')) else '',
                    "amfi_code": amfi_code,
                    "scheme_isin": str(row.get('scheme_isin', '')).strip() if pd.notna(row.get('scheme_isin')) else '',
                    "month_end": month_end,
                    "instrument_name": instrument_name,
                    "instrument_isin": instrument_isin,
                    "instrument_type": str(row.get('instrument', '')).strip() if pd.notna(row.get('instrument')) else '',
                    "instrument_type1": str(row.get('instrument1', '')).strip() if pd.notna(row.get('instrument1')) else '',
                    "sector": str(row.get('sector', '')).strip() if pd.notna(row.get('sector')) else '',
                    "rating": str(row.get('rating', '')).strip() if pd.notna(row.get('rating')) else '',
                    "equiv_rating": str(row.get('equiv_rating', '')).strip() if pd.notna(row.get('equiv_rating')) else '',
                    "agency": str(row.get('agency', '')).strip() if pd.notna(row.get('agency')) else '',
                    "quantity": float(row.get('quantity', 0)) if pd.notna(row.get('quantity')) else 0,
                    "market_value_cr": market_value,
                    "pct_to_net_assets": float(row.get('%_to_net_assets', 0)) if pd.notna(row.get('%_to_net_assets')) else 0,
                    "amfi_code_direct": str(int(row.get('amfi_code_direct', 0))) if pd.notna(row.get('amfi_code_direct')) else '',
                    "market_cap_cr": float(row.get('market_cap_cr', 0)) if pd.notna(row.get('market_cap_cr')) else 0,
                    "market_cap_category": str(row.get('market_cap_category', '')).strip() if pd.notna(row.get('market_cap_category')) else '',
                    "updated_at": current_time,
                    "updated_by": user_id
                }
                
                operations.append(InsertOne(holding_record))
                
                results['schemes_processed'].add(amfi_code)
                results['success'] += 1
                
                if len(operations) >= batch_size:
                    bulk_result = await db.stockwise_holdings.bulk_write(operations, ordered=False)
                    results['holdings_added'] += len(operations)
                    operations = []
                
            except Exception as e:
                results['errors'].append(f"Row {idx + 2}: {str(e)}")
                results['failed'] += 1
                if len(results['errors']) > 10:
                    results['errors'] = results['errors'][:10] + [f"... and {results['failed'] - 10} more errors"]
        
        if operations:
            bulk_result = await db.stockwise_holdings.bulk_write(operations, ordered=False)
            results['holdings_added'] += len(operations)
        
        # Save upload history
        await db.upload_history.insert_one({
            "upload_type": "stockwise_holding",
            "filename": "Sync upload",
            "uploaded_at": datetime.now(timezone.utc).isoformat(),
            "uploaded_by": user_id,
            "records_processed": results['success'],
            "holdings_added": results['holdings_added']
        })
    
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error processing stockwise holding upload: {str(e)}")
        results['errors'].append(f"Processing error: {str(e)}")
    
    results['unique_schemes'] = len(results['schemes_processed'])
    del results['schemes_processed']
    
    return results


async def process_stockwise_upload_background(job_id: str, content: bytes, user_id: str, filename: str = "Unknown"):
    """Process large stockwise upload in background with progress tracking.
    REPLACES all existing stockwise data (deletes first, then inserts new)."""
    import pandas as pd
    from pymongo import InsertOne
    
    try:
        logger.info(f"Starting background stockwise upload job: {job_id}")
        
        df = pd.read_excel(io.BytesIO(content), sheet_name=0)
        total_rows = len(df)
        
        # DELETE all existing stockwise holdings data first
        logger.info(f"Job {job_id}: Deleting existing stockwise_holdings data...")
        delete_result = await db.stockwise_holdings.delete_many({})
        logger.info(f"Job {job_id}: Deleted {delete_result.deleted_count} existing records")
        
        # Update job with total rows
        await db.upload_jobs.update_one(
            {"job_id": job_id},
            {"$set": {"total_rows": total_rows, "status": "reading_complete", "previous_deleted": delete_result.deleted_count}}
        )
        
        logger.info(f"Job {job_id}: Loaded {total_rows} rows")
        
        # Normalize column names
        df.columns = [str(col).replace('*', '').replace('\n', ' ').strip().lower().replace(' ', '_').replace('(rs._cr.)', '_cr').replace('(rs.cr.)', '_cr') for col in df.columns]
        
        batch_size = 1000
        operations = []
        current_time = datetime.now(timezone.utc).isoformat()
        
        success = 0
        failed = 0
        holdings_added = 0
        holdings_updated = 0
        errors = []
        schemes_processed = set()
        month_end = None
        
        for idx, row in df.iterrows():
            try:
                scheme_name = str(row.get('scheme_name') or row.get('scheme_name1', '')).strip()
                if pd.isna(scheme_name) or not scheme_name:
                    continue
                
                amfi_code = str(int(row['amfi_code'])) if pd.notna(row['amfi_code']) else ''
                instrument_name = str(row.get('name_of_the_instrument', '')).strip()
                
                if not instrument_name:
                    continue
                
                row_month_end = str(row.get('month_end', '')).strip() if pd.notna(row.get('month_end')) else ''
                if row_month_end and not month_end:
                    month_end = row_month_end
                
                market_value = 0
                for col_name in ['market/fair_value__cr', 'market/fair_value_cr', 'market_value_cr', 'market_fair_value_cr']:
                    if col_name in df.columns and pd.notna(row.get(col_name)):
                        market_value = float(row.get(col_name, 0))
                        break
                
                instrument_isin = str(row.get('isin', '')).strip() if pd.notna(row.get('isin')) else ''
                
                holding_record = {
                    "scheme_name": scheme_name,
                    "amc_code": str(row.get('amc_code', '')).strip() if pd.notna(row.get('amc_code')) else '',
                    "amfi_code": amfi_code,
                    "scheme_isin": str(row.get('scheme_isin', '')).strip() if pd.notna(row.get('scheme_isin')) else '',
                    "month_end": row_month_end,
                    "instrument_name": instrument_name,
                    "instrument_isin": instrument_isin,
                    "instrument_type": str(row.get('instrument', '')).strip() if pd.notna(row.get('instrument')) else '',
                    "instrument_type1": str(row.get('instrument1', '')).strip() if pd.notna(row.get('instrument1')) else '',
                    "sector": str(row.get('sector', '')).strip() if pd.notna(row.get('sector')) else '',
                    "rating": str(row.get('rating', '')).strip() if pd.notna(row.get('rating')) else '',
                    "equiv_rating": str(row.get('equiv_rating', '')).strip() if pd.notna(row.get('equiv_rating')) else '',
                    "agency": str(row.get('agency', '')).strip() if pd.notna(row.get('agency')) else '',
                    "quantity": float(row.get('quantity', 0)) if pd.notna(row.get('quantity')) else 0,
                    "market_value_cr": market_value,
                    "pct_to_net_assets": float(row.get('%_to_net_assets', 0)) if pd.notna(row.get('%_to_net_assets')) else 0,
                    "amfi_code_direct": str(int(row.get('amfi_code_direct', 0))) if pd.notna(row.get('amfi_code_direct')) else '',
                    "market_cap_cr": float(row.get('market_cap_cr', 0)) if pd.notna(row.get('market_cap_cr')) else 0,
                    "market_cap_category": str(row.get('market_cap_category', '')).strip() if pd.notna(row.get('market_cap_category')) else '',
                    "updated_at": current_time,
                    "updated_by": user_id
                }
                
                filter_key = instrument_isin if instrument_isin else instrument_name
                operations.append(InsertOne(holding_record))
                
                schemes_processed.add(amfi_code)
                success += 1
                
                if len(operations) >= batch_size:
                    bulk_result = await db.stockwise_holdings.bulk_write(operations, ordered=False)
                    holdings_added += len(operations)  # All are inserts now
                    operations = []
                    
                    # Update progress every batch
                    await db.upload_jobs.update_one(
                        {"job_id": job_id},
                        {"$set": {
                            "processed_rows": idx + 1,
                            "success": success,
                            "failed": failed,
                            "holdings_added": holdings_added,
                            "holdings_updated": holdings_updated,
                            "progress_pct": round((idx + 1) / total_rows * 100, 1)
                        }}
                    )
                
            except Exception as e:
                failed += 1
                if len(errors) < 10:
                    errors.append(f"Row {idx + 2}: {str(e)}")
        
        # Process remaining operations
        if operations:
            bulk_result = await db.stockwise_holdings.bulk_write(operations, ordered=False)
            holdings_added += len(operations)  # All are inserts
        
        # Save upload history
        await db.upload_history.insert_one({
            "upload_type": "stockwise_holding",
            "filename": filename,
            "uploaded_at": datetime.now(timezone.utc).isoformat(),
            "uploaded_by": user_id,
            "records_processed": success,
            "holdings_added": holdings_added
        })
        
        # Update final status
        await db.upload_jobs.update_one(
            {"job_id": job_id},
            {"$set": {
                "status": "completed",
                "processed_rows": total_rows,
                "success": success,
                "failed": failed,
                "holdings_added": holdings_added,
                "holdings_updated": 0,  # No updates, all fresh inserts
                "unique_schemes": len(schemes_processed),
                "month_end": month_end,
                "errors": errors,
                "progress_pct": 100,
                "completed_at": datetime.now(timezone.utc).isoformat()
            }}
        )
        
    except Exception as e:
        logger.error(f"Background stockwise upload failed: {str(e)}")
        await db.upload_jobs.update_one(
            {"job_id": job_id},
            {"$set": {
                "status": "failed",
                "error": str(e),
                "completed_at": datetime.now(timezone.utc).isoformat()
            }}
        )


