@api_router.get("/bulk/template/scheme-benchmark-mapping")
async def download_scheme_benchmark_mapping_template(current_user: dict = Depends(get_current_user)):
    """Download Excel template for scheme to benchmark mapping upload"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can download templates")
    
    wb = Workbook()
    ws = wb.active
    ws.title = "Scheme-Benchmark Mapping"
    
    # Headers
    headers = ["SCHEME CODE", "ISINDIVIDEND", "ISINREINVEST", "BENCHMARK", "FINAL BENCHMARK CODE"]
    for col, header in enumerate(headers, 1):
        cell = ws.cell(row=1, column=col, value=header)
        cell.font = Font(bold=True)
        cell.fill = PatternFill(start_color="1E3A5F", end_color="1E3A5F", fill_type="solid")
        cell.font = Font(bold=True, color="FFFFFF")
    
    # Sample data
    ws.cell(row=2, column=1, value="152073")
    ws.cell(row=2, column=2, value="INF579M01AZ6")
    ws.cell(row=2, column=3, value="INF579M01BA7")
    ws.cell(row=2, column=4, value="NIFTY 50 Hybrid Composite Debt 50:50 Index")
    ws.cell(row=2, column=5, value="AB124")
    
    # Adjust column widths
    ws.column_dimensions['A'].width = 15
    ws.column_dimensions['B'].width = 18
    ws.column_dimensions['C'].width = 18
    ws.column_dimensions['D'].width = 45
    ws.column_dimensions['E'].width = 22
    
    # Save to bytes
    output = io.BytesIO()
    wb.save(output)
    output.seek(0)
    
    return Response(
        content=output.getvalue(),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": "attachment; filename=scheme_benchmark_mapping_template.xlsx"}
    )


@api_router.post("/bulk/scheme-benchmark-mapping")
async def bulk_upload_scheme_benchmark_mapping(
    file: UploadFile = File(...),
    current_user: dict = Depends(get_current_user)
):
    """
    Bulk upload scheme to benchmark code mapping.
    This links scheme codes and ISINs to their benchmark codes for comparison.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can bulk upload mapping data")
    
    if not file.filename.endswith(('.xlsx', '.xls')):
        raise HTTPException(status_code=400, detail="Please upload an Excel file (.xlsx or .xls)")
    
    import pandas as pd
    from pymongo import UpdateOne
    
    content = await file.read()
    
    results = {
        "success": 0,
        "failed": 0,
        "errors": [],
        "mappings_added": 0,
        "mappings_updated": 0
    }
    
    try:
        df = pd.read_excel(io.BytesIO(content), sheet_name=0)
        
        # Normalize column names
        df.columns = [str(col).strip().lower().replace(' ', '_') for col in df.columns]
        
        # Check for required columns
        required_cols = ['scheme_code', 'final_benchmark_code']
        missing_cols = [col for col in required_cols if col not in df.columns]
        if missing_cols:
            raise HTTPException(status_code=400, detail=f"Missing required columns: {', '.join(missing_cols)}")
        
        operations = []
        current_time = datetime.now(timezone.utc).isoformat()
        
        # Helper to detect if a value is an ISIN (starts with INF and is 12 chars)
        def is_isin(value: str) -> bool:
            return value and len(value) == 12 and value.startswith('INF')
        
        # Pre-load ISIN to AMFI code mapping from amfi_scheme_data for lookup
        isin_to_amfi_code = {}
        async for record in db.amfi_scheme_data.find({}, {"_id": 0, "isin": 1, "scheme_code": 1}):
            isin = record.get('isin', '').strip()
            amfi_code = record.get('scheme_code')
            if isin and amfi_code:
                isin_to_amfi_code[isin] = str(amfi_code)
        
        logger.info(f"Loaded {len(isin_to_amfi_code)} ISIN->AMFI code mappings for benchmark upload")
        
        for idx, row in df.iterrows():
            try:
                scheme_code_raw = str(row.get('scheme_code', '')).strip()
                if pd.isna(scheme_code_raw) or not scheme_code_raw:
                    continue
                
                benchmark_code = str(row.get('final_benchmark_code', '')).strip()
                if pd.isna(benchmark_code) or not benchmark_code:
                    continue
                
                # Get ISINs from dedicated columns
                isin_dividend = str(row.get('isindividend', '')).strip() if pd.notna(row.get('isindividend')) else ''
                isin_reinvest = str(row.get('isinreinvest', '')).strip() if pd.notna(row.get('isinreinvest')) else ''
                benchmark_name = str(row.get('benchmark', '')).strip() if pd.notna(row.get('benchmark')) else ''
                
                # Check if scheme_code column actually contains an ISIN
                # This handles files where ISIN is in the scheme_code column
                if is_isin(scheme_code_raw):
                    # Look up the actual AMFI scheme code from amfi_scheme_data
                    amfi_code = isin_to_amfi_code.get(scheme_code_raw, '')
                    
                    # Store mapping with both ISIN and AMFI code
                    mapping_record = {
                        "isin": scheme_code_raw,  # Store the ISIN directly for direct lookup
                        "scheme_code": amfi_code or scheme_code_raw,  # Use AMFI code if found, else ISIN
                        "amfi_code": amfi_code,  # Store AMFI code separately
                        "isin_dividend": isin_dividend or scheme_code_raw,  # Use the ISIN if no separate column
                        "isin_reinvest": isin_reinvest,
                        "benchmark_name": benchmark_name,
                        "benchmark_code": benchmark_code,
                        "updated_at": current_time,
                        "updated_by": current_user['id']
                    }
                    
                    # Upsert by ISIN for direct lookup
                    operations.append(
                        UpdateOne(
                            {"isin": scheme_code_raw},
                            {"$set": mapping_record},
                            upsert=True
                        )
                    )
                    
                    # Also create a mapping by AMFI code if we found one
                    if amfi_code:
                        amfi_mapping_record = {
                            "scheme_code": amfi_code,
                            "isin_dividend": scheme_code_raw,
                            "isin_reinvest": isin_reinvest,
                            "benchmark_name": benchmark_name,
                            "benchmark_code": benchmark_code,
                            "updated_at": current_time,
                            "updated_by": current_user['id']
                        }
                        operations.append(
                            UpdateOne(
                                {"scheme_code": amfi_code},
                                {"$set": amfi_mapping_record},
                                upsert=True
                            )
                        )
                else:
                    # Regular scheme_code based mapping
                    mapping_record = {
                        "scheme_code": scheme_code_raw,
                        "isin_dividend": isin_dividend,
                        "isin_reinvest": isin_reinvest,
                        "benchmark_name": benchmark_name,
                        "benchmark_code": benchmark_code,
                        "updated_at": current_time,
                        "updated_by": current_user['id']
                    }
                    
                    # Upsert by scheme_code
                    operations.append(
                        UpdateOne(
                            {"scheme_code": scheme_code_raw},
                            {"$set": mapping_record},
                            upsert=True
                        )
                    )
                
                results['success'] += 1
                
                # Batch execute every 1000 operations
                if len(operations) >= 1000:
                    bulk_result = await db.scheme_benchmark_mapping.bulk_write(operations, ordered=False)
                    results['mappings_added'] += bulk_result.upserted_count
                    results['mappings_updated'] += bulk_result.modified_count
                    operations = []
                    
            except Exception as e:
                results['errors'].append(f"Row {idx + 2}: {str(e)}")
                results['failed'] += 1
                if len(results['errors']) > 10:
                    results['errors'] = results['errors'][:10] + [f"... and {results['failed'] - 10} more errors"]
        
        # Execute remaining operations
        if operations:
            bulk_result = await db.scheme_benchmark_mapping.bulk_write(operations, ordered=False)
            results['mappings_added'] += bulk_result.upserted_count
            results['mappings_updated'] += bulk_result.modified_count
        
        # Save upload history
        await db.upload_history.insert_one({
            "upload_type": "scheme_benchmark_mapping",
            "filename": file.filename,
            "uploaded_at": datetime.now(timezone.utc).isoformat(),
            "uploaded_by": current_user['id'],
            "records_processed": results['success'],
            "mappings_added": results['mappings_added'],
            "mappings_updated": results['mappings_updated']
        })
    
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error processing scheme-benchmark mapping upload: {str(e)}")
        results['errors'].append(f"Processing error: {str(e)}")
    
    return results


