def _build_client_query(current_user: dict) -> dict:
    """Helper to build the investor lookup query based on role."""
    if current_user['role'] == 'broker':
        return {"created_by": current_user['id']}
    return {"linked_subbroker_id": current_user['id']}


async def _fetch_investors_by_passport(current_user: dict, passport_collection: str, passport_type: str):
    """Fetch investors from the passport-specific collection UNIONED with PRIVATE_INVESTOR
    docs of the same passport_type. Dedupe by id (passport-specific collection wins)."""
    base_query = _build_client_query(current_user)

    specific = await db[passport_collection].find(base_query, {"_id": 0}).to_list(1000)

    legacy_query = {**base_query, "passport_type": passport_type}
    legacy = await db.Private_Investor.find(legacy_query, {"_id": 0}).to_list(1000)

    seen_ids = {inv.get('id') for inv in specific if inv.get('id')}
    combined = list(specific)
    for inv in legacy:
        if inv.get('id') not in seen_ids:
            combined.append(inv)
    return combined


@api_router.get("/clients/indian-passport")
async def get_clients_indian_passport(current_user: dict = Depends(get_current_user)):
    """Get Indian-passport investors — union of PRIVATE_INVESTOR_INDIAN_PASSPORT
    (bulk uploads) and PRIVATE_INVESTOR docs with passport_type='indian' (form creates)."""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Access denied")
    return await _fetch_investors_by_passport(
        current_user, "Private_Investor_Indian_Passport", "indian"
    )


@api_router.get("/clients/foreign-passport")
async def get_clients_foreign_passport(current_user: dict = Depends(get_current_user)):
    """Get Foreign-passport investors — union of PRIVATE_INVESTOR_FOREIGN_PASSPORT
    (bulk uploads) and PRIVATE_INVESTOR docs with passport_type='foreign' (form creates)."""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Access denied")
    return await _fetch_investors_by_passport(
        current_user, "Private_Investor_Foreign_Passport", "foreign"
    )




@api_router.get("/private-investors/dashboard/expiring-documents")
async def get_expiring_documents(current_user: dict = Depends(get_current_user)):
    """Get clients with documents expiring within 3 months (for dashboard notifications)"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Access denied")
    
    from datetime import timedelta
    
    # Calculate date 3 months from now
    three_months_from_now = datetime.now(timezone.utc) + timedelta(days=90)
    today = datetime.now(timezone.utc)
    
    # Build query based on role
    if current_user['role'] == 'broker':
        base_query = {"created_by": current_user['id']}
    else:
        base_query = {"linked_subbroker_id": current_user['id']}
    
    # Find clients with passport expiring within 3 months
    clients = await db.Private_Investor.find(base_query, {"_id": 0}).to_list(1000)
    
    expiring_documents = []
    for client in clients:
        passport_expiry = client.get('passport_valid_until')
        if passport_expiry:
            try:
                expiry_date = datetime.fromisoformat(passport_expiry.replace('Z', '+00:00')) if isinstance(passport_expiry, str) else passport_expiry
                if today <= expiry_date <= three_months_from_now:
                    days_until_expiry = (expiry_date - today).days
                    expiring_documents.append({
                        "client_id": client.get('id'),
                        "client_name": client.get('name'),
                        "document_type": "passport",
                        "expiry_date": passport_expiry,
                        "days_until_expiry": days_until_expiry,
                        "photo_id": client.get('photo_id') or client.get('pan_number')
                    })
            except (ValueError, TypeError):
                pass
    
    # Sort by days until expiry (most urgent first)
    expiring_documents.sort(key=lambda x: x['days_until_expiry'])
    
    return {"expiring_documents": expiring_documents, "count": len(expiring_documents)}


@api_router.get("/private-investors/dashboard/invalid-pan")
async def get_invalid_pan_clients(current_user: dict = Depends(get_current_user)):
    """Get clients with invalid PAN format (for dashboard alerts)"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Access denied")
    
    # Build query based on role
    if current_user['role'] == 'broker':
        base_query = {"created_by": current_user['id']}
    else:
        base_query = {"linked_subbroker_id": current_user['id']}
    
    # Only check Indian passport holders
    base_query['passport_type'] = 'indian'
    
    clients = await db.Private_Investor.find(base_query, {"_id": 0}).to_list(1000)
    
    invalid_pan_clients = []
    for client in clients:
        pan = client.get('pan_number') or client.get('photo_id')
        if pan and not is_valid_pan_format(pan):
            invalid_pan_clients.append({
                "client_id": client.get('id'),
                "client_name": client.get('name'),
                "pan_number": pan,
                "email": client.get('email'),
                "mobile": client.get('mobile')
            })
    
    return {"invalid_pan_clients": invalid_pan_clients, "count": len(invalid_pan_clients)}


@api_router.get("/private-investors/{client_id}")
async def get_client(client_id: str, current_user: dict = Depends(get_current_user)):
    """Get a specific client - accessible by broker (creator), sub-broker (linked), or the client themselves"""
    # Look across legacy + Indian/Foreign passport collections so 3-way login
    # clients (Private Investor Indian Passport) resolve.
    client = None
    for coll in ("Private_Investor", "Private_Investor_Indian_Passport", "Private_Investor_Foreign_Passport"):
        client = await db[coll].find_one({"id": client_id}, {"_id": 0})
        if client:
            break
    
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    
    # Check access based on role
    if current_user['role'] == 'broker':
        # Broker can access clients they created
        if client.get('created_by') != current_user['id']:
            raise HTTPException(status_code=403, detail="Access denied")
    elif current_user['role'] == 'client':
        # Client can access their own profile data (legacy + 3-way login).
        if client.get('user_id') != current_user['id'] and client.get('id') != current_user['id']:
            raise HTTPException(status_code=403, detail="Access denied")
    else:
        # Sub-broker can access linked clients
        if client.get('linked_subbroker_id') != current_user['id']:
            raise HTTPException(status_code=403, detail="Access denied")
    
    return client


@api_router.put("/private-investors/{client_id}")
async def update_client(client_id: str, client_update: ClientUpdate, current_user: dict = Depends(get_current_user)):
    """Update a client (brokers and sub-brokers)"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers and sub-brokers can update clients")
    
    # Brokers can update any client they created, sub-brokers can update linked clients
    if current_user['role'] == 'broker':
        client = await db.Private_Investor.find_one({"id": client_id, "created_by": current_user['id']})
    else:  # sub_broker
        client = await db.Private_Investor.find_one({"id": client_id, "linked_subbroker_id": current_user['id']})
    
    if not client:
        raise HTTPException(status_code=404, detail="Client not found or access denied")
    
    update_data = {k: v for k, v in client_update.model_dump().items() if v is not None}
    
    if not update_data:
        raise HTTPException(status_code=400, detail="No fields to update")
    
    # Validate UCC list if provided
    if 'ucc_list' in update_data:
        ucc_list = update_data['ucc_list']
        
        if not ucc_list or len(ucc_list) == 0:
            raise HTTPException(status_code=400, detail="At least one UCC is required")
        
        if len(ucc_list) > 5:
            raise HTTPException(status_code=400, detail="Maximum 5 UCCs allowed per client")
        
        # Clean and uppercase UCCs
        ucc_list = [ucc.strip().upper() for ucc in ucc_list if ucc.strip()]
        
        if len(ucc_list) == 0:
            raise HTTPException(status_code=400, detail="At least one valid UCC is required")
        
        # Check for duplicate UCCs in the submitted list
        if len(ucc_list) != len(set(ucc_list)):
            raise HTTPException(status_code=400, detail="Duplicate UCCs are not allowed")
        
        # Check if any UCC already exists in the system (excluding current client)
        for ucc in ucc_list:
            existing_ucc = await db.Private_Investor.find_one({"ucc_list": ucc, "id": {"$ne": client_id}})
            if existing_ucc:
                raise HTTPException(status_code=400, detail=f"UCC '{ucc}' is already assigned to another client")
        
        update_data['ucc_list'] = ucc_list
    
    update_data['updated_at'] = datetime.now(timezone.utc).isoformat()
    
    await db.Private_Investor.update_one({"id": client_id}, {"$set": update_data})
    
    updated_client = await db.Private_Investor.find_one({"id": client_id}, {"_id": 0})
    return updated_client


@api_router.delete("/private-investors/{client_id}")
async def delete_client(client_id: str, current_user: dict = Depends(get_current_user)):
    """Hard delete a client (brokers only) - removes from both clients and users collections"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can delete clients")
    
    client = await db.Private_Investor.find_one({"id": client_id, "created_by": current_user['id']})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    
    # Check if client has any confirmed trades
    trades = await db.Ncd_Investment_Details.find({"client_id": client_id, "status": "approved"}).to_list(1)
    
    if trades:
        # Cannot hard delete - client has trades
        raise HTTPException(
            status_code=400, 
            detail="Cannot delete client with confirmed trades. Use 'Deactivate' instead to disable the account."
        )
    
    # Hard delete - remove from both collections to allow PAN reuse
    pan_number = client.get('pan_number')
    
    # Delete from clients collection
    await db.Private_Investor.delete_one({"id": client_id})
    
    # Also delete from users collection to allow recreation with same PAN - support both pan and pan_number fields
    if pan_number:
        user_query = {"$or": [{"pan": pan_number}, {"pan_number": pan_number}, {"id": client_id}]}
        await db.users.delete_one(user_query)
    
    return {"message": "Client deleted successfully. PAN can now be reused.", "soft_delete": False}


