@api_router.post("/private-investors/{client_id}/reactivate")
async def reactivate_client(client_id: str, current_user: dict = Depends(get_current_user)):
    """Reactivate an inactive client (brokers only)"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can reactivate clients")
    
    client = await db.Private_Investor.find_one({"id": client_id, "created_by": current_user['id']})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    
    # Update clients collection
    await db.Private_Investor.update_one(
        {"id": client_id},
        {"$set": {"is_active": True}, "$unset": {"deactivated_at": ""}}
    )
    
    # ALSO update users collection (this is where login check happens) - support both pan and pan_number fields
    user_query = {"$or": [{"pan": client['pan_number']}, {"pan_number": client['pan_number']}, {"id": client_id}]}
    await db.users.update_one(
        user_query,
        {"$set": {"is_active": True}, "$unset": {"deactivated_at": ""}}
    )
    
    return {"message": "Client reactivated successfully"}


@api_router.post("/private-investors/{client_id}/sync-activation")
async def sync_client_activation(client_id: str, current_user: dict = Depends(get_current_user)):
    """Sync the activation status between clients and users collections"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can sync client activation")
    
    client = await db.Private_Investor.find_one({"id": client_id, "created_by": current_user['id']})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    
    # Get client's is_active status
    client_active = client.get('is_active', True) and not client.get('deactivated_at')
    
    # Update users collection to match - support both pan and pan_number fields
    user_query = {"$or": [{"pan": client['pan_number']}, {"pan_number": client['pan_number']}, {"id": client_id}]}
    result = await db.users.update_one(
        user_query,
        {"$set": {"is_active": client_active}}
    )
    
    if result.matched_count == 0:
        return {"message": "No user account found for this client", "synced": False}
    
    return {
        "message": "Activation synced successfully",
        "synced": True,
        "is_active": client_active
    }


@api_router.post("/private-investors/{client_id}/resend-credentials")
async def resend_client_credentials(client_id: str, background_tasks: BackgroundTasks, current_user: dict = Depends(get_current_user)):
    """Resend login credentials to client via email (brokers and sub-brokers)"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers and sub-brokers can resend credentials")
    
    # Find client based on role
    if current_user['role'] == 'broker':
        client = await db.Private_Investor.find_one({"id": client_id})
    else:
        # Sub-broker can only resend for their linked clients
        client = await db.Private_Investor.find_one({"id": client_id, "linked_subbroker_id": current_user['id']})
    
    if not client:
        raise HTTPException(status_code=404, detail="Client not found or not authorized")
    
    # Check if client has email
    if not client.get('email'):
        raise HTTPException(status_code=400, detail="Client does not have an email address. Please update client profile first.")
    
    # Generate new password and PIN
    new_password = client['pan_number'][-4:] + str(uuid.uuid4().hex[:4])
    new_pin = str(uuid.uuid4().int)[:4]
    
    # Update user credentials - support both pan and pan_number fields
    user_query = {"$or": [{"pan": client['pan_number']}, {"pan_number": client['pan_number']}, {"id": client_id}]}
    await db.users.update_one(
        user_query,
        {"$set": {
            "password_hash": get_password_hash(new_password),
            "pin_hash": get_password_hash(new_pin)
        }}
    )
    
    # Update stored credentials in client record (for admin reference only, not shown to broker)
    await db.Private_Investor.update_one(
        {"id": client_id},
        {"$set": {
            "credentials_updated_at": datetime.now(timezone.utc).isoformat(),
            "credentials_updated_by": current_user['id']
        }}
    )
    
    # Send email to client with credentials
    try:
        background_tasks.add_task(
            send_credentials_email,
            email=client['email'],
            name=client['name'],
            pan=client['pan_number'],
            password=new_password,
            pin=new_pin
        )
        return {
            "message": f"Credentials have been sent to {client['email']}",
            "email_sent": True,
            "client_email": client['email']
        }
    except Exception as e:
        logger.error(f"Failed to send credentials email: {e}")
        raise HTTPException(status_code=500, detail="Failed to send credentials email. Please try again.")


