# ==================== BULK REPAYMENT UPLOAD ====================

@api_router.get("/holdings/repayment-template")
async def get_repayment_template(current_user: dict = Depends(get_current_user)):
    """Generate Excel template for bulk repayment updates"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers and sub-brokers can download repayment template")
    
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    from io import BytesIO
    
    wb = Workbook()
    ws = wb.active
    ws.title = "Repayment Updates"
    
    # Header style
    header_font = Font(bold=True, color="FFFFFF")
    header_fill = PatternFill(start_color="4472C4", end_color="4472C4", fill_type="solid")
    thin_border = Border(
        left=Side(style='thin'),
        right=Side(style='thin'),
        top=Side(style='thin'),
        bottom=Side(style='thin')
    )
    
    # Headers
    headers = [
        "Client PAN*", "Bond Name*", "Scheduled Date*", "Type*",
        "Expected Amount", "Actual Paid Date*", "Actual Amount Received*", "Notes"
    ]
    
    for col, header in enumerate(headers, 1):
        cell = ws.cell(row=1, column=col, value=header)
        cell.font = header_font
        cell.fill = header_fill
        cell.alignment = Alignment(horizontal='center')
        cell.border = thin_border
    
    # Set column widths
    ws.column_dimensions['A'].width = 15
    ws.column_dimensions['B'].width = 35
    ws.column_dimensions['C'].width = 15
    ws.column_dimensions['D'].width = 12
    ws.column_dimensions['E'].width = 18
    ws.column_dimensions['F'].width = 18
    ws.column_dimensions['G'].width = 22
    ws.column_dimensions['H'].width = 30
    
    # Add instructions sheet
    ws_inst = wb.create_sheet("Instructions")
    instructions = [
        "BULK REPAYMENT UPDATE - INSTRUCTIONS",
        "",
        "Required Fields (marked with *):",
        "1. Client PAN - The PAN number of the client (e.g., ABCDE1234F)",
        "2. Bond Name - Exact name of the bond as registered in the system",
        "3. Scheduled Date - Original scheduled payment date (DD-MM-YYYY format)",
        "4. Type - Either 'interest' or 'principal'",
        "5. Actual Paid Date - Date when payment was actually received (DD-MM-YYYY)",
        "6. Actual Amount Received - Amount received (numbers only, no commas)",
        "",
        "Optional Fields:",
        "7. Expected Amount - The originally expected amount (for reference)",
        "8. Notes - Any notes about this repayment",
        "",
        "IMPORTANT:",
        "- If Actual Paid Date is before Scheduled Date, it will be marked as PREPAID",
        "- Date format: DD-MM-YYYY (e.g., 15-01-2026)",
        "- Amount format: Plain numbers (e.g., 50000.00)",
        "- The system will match entries based on Client PAN + Bond Name + Scheduled Date + Type"
    ]
    
    for row, text in enumerate(instructions, 1):
        ws_inst.cell(row=row, column=1, value=text)
    ws_inst.column_dimensions['A'].width = 80
    
    # Save to buffer
    buffer = BytesIO()
    wb.save(buffer)
    buffer.seek(0)
    
    return StreamingResponse(
        buffer,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": "attachment; filename=repayment_update_template.xlsx"}
    )


@api_router.post("/holdings/bulk-repayment-upload")
async def bulk_repayment_upload(
    file: UploadFile = File(...),
    current_user: dict = Depends(get_current_user)
):
    """Process bulk repayment updates from Excel file"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers and sub-brokers can upload repayments")
    
    from openpyxl import load_workbook
    from io import BytesIO
    
    try:
        content = await file.read()
        wb = load_workbook(BytesIO(content))
        ws = wb.active
        
        results = {
            "success": 0,
            "failed": 0,
            "prepaid": 0,
            "errors": []
        }
        
        # Skip header row
        for row_num, row in enumerate(ws.iter_rows(min_row=2, values_only=True), start=2):
            if not row[0]:  # Skip empty rows
                continue
            
            try:
                client_pan = str(row[0]).strip().upper()
                bond_name = str(row[1]).strip() if row[1] else None
                scheduled_date_raw = row[2]
                cf_type = str(row[3]).strip().lower() if row[3] else None
                actual_paid_date_raw = row[5]
                actual_amount = float(row[6]) if row[6] else None
                notes = str(row[7]).strip() if row[7] else None
                
                # Validate required fields
                if not all([client_pan, bond_name, scheduled_date_raw, cf_type, actual_paid_date_raw, actual_amount]):
                    results["errors"].append(f"Row {row_num}: Missing required fields")
                    results["failed"] += 1
                    continue
                
                if cf_type not in ['interest', 'principal']:
                    results["errors"].append(f"Row {row_num}: Type must be 'interest' or 'principal'")
                    results["failed"] += 1
                    continue
                
                # Parse dates
                if isinstance(scheduled_date_raw, datetime):
                    scheduled_date = scheduled_date_raw
                else:
                    try:
                        scheduled_date = datetime.strptime(str(scheduled_date_raw), "%d-%m-%Y")
                    except:
                        try:
                            scheduled_date = datetime.strptime(str(scheduled_date_raw), "%Y-%m-%d")
                        except:
                            results["errors"].append(f"Row {row_num}: Invalid scheduled date format")
                            results["failed"] += 1
                            continue
                
                if isinstance(actual_paid_date_raw, datetime):
                    actual_paid_date = actual_paid_date_raw
                else:
                    try:
                        actual_paid_date = datetime.strptime(str(actual_paid_date_raw), "%d-%m-%Y")
                    except:
                        try:
                            actual_paid_date = datetime.strptime(str(actual_paid_date_raw), "%Y-%m-%d")
                        except:
                            results["errors"].append(f"Row {row_num}: Invalid actual paid date format")
                            results["failed"] += 1
                            continue
                
                # Find client
                client = await db.Private_Investor.find_one({"pan_number": client_pan})
                if not client:
                    results["errors"].append(f"Row {row_num}: Client with PAN {client_pan} not found")
                    results["failed"] += 1
                    continue
                
                # Verify access
                if current_user['role'] == 'broker':
                    if client.get('created_by') != current_user['id']:
                        results["errors"].append(f"Row {row_num}: Access denied for client {client_pan}")
                        results["failed"] += 1
                        continue
                else:
                    if client.get('linked_subbroker_id') != current_user['id']:
                        results["errors"].append(f"Row {row_num}: Access denied for client {client_pan}")
                        results["failed"] += 1
                        continue
                
                # Find matching cashflow - use date range for matching (same day)
                scheduled_date_str = scheduled_date.strftime("%Y-%m-%d")
                
                cashflow = await db.holding_cashflows.find_one({
                    "client_id": client['id'],
                    "bond_name": {"$regex": f"^{bond_name}$", "$options": "i"},
                    "date": {"$regex": f"^{scheduled_date_str}"},
                    "type": cf_type
                })
                
                if not cashflow:
                    results["errors"].append(f"Row {row_num}: No matching cashflow found for {client_pan}, {bond_name}, {scheduled_date_str}, {cf_type}")
                    results["failed"] += 1
                    continue
                
                # Detect prepayment
                is_prepaid = actual_paid_date.date() < scheduled_date.date()
                days_early = (scheduled_date.date() - actual_paid_date.date()).days if is_prepaid else 0
                
                # Update cashflow
                update_data = {
                    "is_repaid": True,
                    "repaid_date": actual_paid_date.isoformat(),
                    "repaid_actual_amount": actual_amount,
                    "is_prepaid": is_prepaid,
                    "days_early": days_early,
                    "notes": notes,
                    "marked_by": current_user['id'],
                    "marked_at": datetime.now(timezone.utc).isoformat(),
                    "bulk_uploaded": True
                }
                
                await db.holding_cashflows.update_one(
                    {"id": cashflow['id']},
                    {"$set": update_data}
                )
                
                results["success"] += 1
                if is_prepaid:
                    results["prepaid"] += 1
                
            except Exception as e:
                results["errors"].append(f"Row {row_num}: {str(e)}")
                results["failed"] += 1
        
        return {
            "message": f"Processed {results['success'] + results['failed']} entries",
            "success_count": results["success"],
            "failed_count": results["failed"],
            "prepaid_count": results["prepaid"],
            "errors": results["errors"][:20]  # Limit errors to first 20
        }
        
    except Exception as e:
        logger.error(f"Error processing bulk repayment upload: {e}")
        raise HTTPException(status_code=400, detail=f"Error processing file: {str(e)}")


@api_router.post("/holdings/client/{client_id}/send-report-email")
async def send_holdings_report_email_endpoint(
    client_id: str,
    current_user: dict = Depends(get_current_user)
):
    """
    Send holdings report email to client with sub-broker CC and BCC to donotreply@kinntegraa.club.
    Includes Excel attachment with full holdings data (same as download).
    Broker or sub-broker can trigger this for their clients.
    """
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers and sub-brokers can send reports")
    
    # Verify client access
    client = await db.Private_Investor.find_one({"id": client_id}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    
    if current_user['role'] == 'broker':
        if client.get('created_by') != current_user['id']:
            raise HTTPException(status_code=403, detail="Access denied")
    elif current_user['role'] == 'sub_broker':
        if client.get('linked_subbroker_id') != current_user['id']:
            raise HTTPException(status_code=403, detail="Access denied")
    
    # Get client email
    client_email = client.get('email')
    if not client_email:
        raise HTTPException(status_code=400, detail="Client has no email address")
    
    # Get sub-broker email for CC (only sub-broker, not broker)
    cc_emails = []
    if client.get('linked_subbroker_id'):
        # Try partners collection first (primary), then sub_brokers
        sub_broker = await db.Mfd_Ria_Partner.find_one({"id": client.get('linked_subbroker_id')}, {"_id": 0})
        if not sub_broker:
            sub_broker = await db.sub_brokers.find_one({"id": client.get('linked_subbroker_id')}, {"_id": 0})
        if sub_broker and sub_broker.get('email'):
            cc_emails.append(sub_broker.get('email'))
    
    # BCC to donotreply@kinntegraa.club
    bcc_emails = ["donotreply@kinntegraa.club"]
    
    # Get full holdings data using the same function as download
    try:
        holdings_data = await get_client_holdings(client_id, current_user)
    except HTTPException:
        raise HTTPException(status_code=404, detail="No holdings found for this client")
    
    if not holdings_data.get('holdings'):
        raise HTTPException(status_code=404, detail="No holdings found for this client")
    
    # Generate Excel file bytes using THE SAME LOGIC as download endpoint
    from io import BytesIO
    
    wb = Workbook()
    
    # Styles (same as download)
    header_font = Font(bold=True, size=11, color="FFFFFF")
    header_fill = PatternFill(start_color="5B373C", end_color="5B373C", fill_type="solid")
    expected_fill = PatternFill(start_color="059669", end_color="059669", fill_type="solid")
    actual_fill = PatternFill(start_color="7c3aed", end_color="7c3aed", fill_type="solid")
    summary_fill = PatternFill(start_color="f5f5f5", end_color="f5f5f5", fill_type="solid")
    title_font = Font(bold=True, size=14)
    subtitle_font = Font(bold=True, size=12)
    money_font = Font(name="Consolas", size=10)
    border = Border(
        left=Side(style='thin'),
        right=Side(style='thin'),
        top=Side(style='thin'),
        bottom=Side(style='thin')
    )
    
    # ========== SUMMARY SHEET ==========
    ws_summary = wb.active
    ws_summary.title = "Summary"
    
    ws_summary['A1'] = f"Holdings Report - {holdings_data['client']['name']}"
    ws_summary['A1'].font = title_font
    ws_summary.merge_cells('A1:K1')
    
    ws_summary['A2'] = f"PAN: {holdings_data['client']['pan_number']}"
    ws_summary['A3'] = f"Generated: {datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S')} UTC"
    
    start_row = 5
    ws_summary[f'A{start_row}'] = "HOLDINGS BY BOND"
    ws_summary[f'A{start_row}'].font = Font(bold=True, size=12)
    
    summary_row = _render_summary_header(ws_summary, header_font, header_fill, border, start_row=start_row + 1)
    
    ws_summary.column_dimensions['A'].width = 32   # NCD Name
    ws_summary.column_dimensions['B'].width = 16   # Investment
    ws_summary.column_dimensions['C'].width = 14   # Gross Expected — Principal
    ws_summary.column_dimensions['D'].width = 14   # Gross Expected — Interest
    ws_summary.column_dimensions['E'].width = 14   # Gross Repaid — Principal
    ws_summary.column_dimensions['F'].width = 14   # Gross Repaid — Interest
    ws_summary.column_dimensions['G'].width = 12   # Gross Repaid — TDS
    ws_summary.column_dimensions['H'].width = 14   # Profit
    ws_summary.column_dimensions['I'].width = 14   # Expected XIRR
    ws_summary.column_dimensions['J'].width = 14   # Actual XIRR
    ws_summary.column_dimensions['K'].width = 11   # Status
    
    # ========== CREATE SEPARATE SHEET FOR EACH HOLDING ==========
    sheet_index = 0
    
    for holding in holdings_data['holdings']:
        trades = holding.get('trades', [holding])
        
        for trade in trades:
            sheet_index += 1
            bond_name = holding.get('bond_name', 'Bond')
            investment_date = trade.get('investment_date', trade.get('date', ''))
            
            short_bond_name = bond_name[:15].replace('/', '-').replace('\\', '-').replace('*', '-').replace('?', '-').replace('[', '').replace(']', '')
            inv_date_short = investment_date[:10] if investment_date else ''
            sheet_name = f"{sheet_index}_{short_bond_name}_{inv_date_short}"[:31]
            
            ws = wb.create_sheet(title=sheet_name)
            
            ws['A1'] = bond_name
            ws['A1'].font = title_font
            ws.merge_cells('A1:J1')

            # "← Back to Summary" hyperlink
            ws['K1'] = '← Back to Summary'
            ws['K1'].hyperlink = "#'Summary'!A1"
            ws['K1'].font = Font(bold=True, color="0563C1", underline="single", size=11)
            ws['K1'].alignment = Alignment(horizontal='right', vertical='center')

            ws['A3'] = "Investment Date"
            ws['B3'] = investment_date[:10] if investment_date else '-'
            ws['C3'] = "Units"
            ws['D3'] = trade.get('units', holding.get('units', holding.get('total_units', '-')))
            ws['E3'] = "Investment"
            ws['F3'] = trade.get('invested_amount', holding.get('invested_amount', 0))
            ws['F3'].font = money_font
            ws['F3'].number_format = '₹ #,##0.00'
            
            ws['A4'] = "Expected XIRR"
            ws['B4'] = f"{holding.get('xirr', 0):.2f}%" if holding.get('xirr') else '-'
            ws['C4'] = "Actual XIRR"
            ws['D4'] = f"{holding.get('actual_xirr', 0):.2f}%" if holding.get('actual_xirr') else '-'
            
            for cell in ['A3', 'C3', 'E3', 'A4', 'C4']:
                ws[cell].font = Font(bold=True)
            
            # ===== EXPECTED + ACTUAL CASHFLOW SECTIONS (side-by-side) =====
            # Mirrors the on-screen Repayment Details modal — Expected on the
            # left (cols A-E) and Actual on the right (cols G-K), both using
            # the same Date | Principal | Interest | TDS | Total layout.
            _today_str_em = datetime.now(timezone.utc).strftime('%Y-%m-%d')
            _maturity_str_em = (holding.get('maturity_date') or trade.get('maturity_date') or '')[:10]
            _is_matured_em = bool(_maturity_str_em) and _maturity_str_em <= _today_str_em

            expected_cfs = trade.get('expected_cashflows', holding.get('expected_cashflows', []))

            # Rebuild Actual cashflows from `holding.repaid_rows` (now per-trade
            # principal-matched on the backend) so the email Excel mirrors the
            # download Excel exactly. Falls back to legacy `actual_cashflows`
            # if `repaid_rows` is unavailable for a non-NCD holding.
            _repaid_rows = holding.get('repaid_rows') or []
            if _repaid_rows:
                _inv_amt_em = float(trade.get('invested_amount', holding.get('invested_amount', 0)) or 0)
                _inv_dt_em = (trade.get('investment_date') or holding.get('investment_date') or '')
                actual_cfs = [{
                    'date': _inv_dt_em,
                    'type': 'investment',
                    'gross_amount': -_inv_amt_em,
                    'net_amount': -_inv_amt_em,
                }] + [{
                    'date': r.get('date'),
                    'principal_component': r.get('principal') or 0,
                    'interest_component': r.get('interest') or 0,
                    'tds_amount': r.get('tds') or 0,
                    'gross_amount': r.get('gross') or 0,
                    'is_repaid': True,
                } for r in _repaid_rows]
            else:
                actual_cfs = list(trade.get('actual_cashflows', holding.get('actual_cashflows', [])) or [])

            # Append still-due future scheduled rows so the Actual table
            # extends through maturity (matches the UI's "Actuals + future
            # scheduled" section).
            if not _is_matured_em:
                _act_dates_em = {((cf.get('date') or '')[:10]) for cf in actual_cfs}
                _future_em = [
                    cf for cf in expected_cfs
                    if cf.get('type') != 'investment'
                    and ((cf.get('date') or '')[:10]) > _today_str_em
                    and ((cf.get('date') or '')[:10]) not in _act_dates_em
                ]
                actual_cfs = actual_cfs + _future_em

            _exp_end_row_em = _render_cashflow_side(
                ws, start_row=6, start_col=1,
                title="Expected Cashflow", fill_color="2563EB",
                cfs=expected_cfs, today_str=_today_str_em,
            )
            _act_end_row_em = _render_cashflow_side(
                ws, start_row=6, start_col=7,
                title="Actual Cashflow", fill_color="16A34A",
                cfs=actual_cfs, today_str=_today_str_em,
            )

            row = max(_exp_end_row_em, _act_end_row_em) + 1

            ws.cell(row=row, column=1, value="Note: Future-scheduled rows in the Actual table are shown in amber italic. Investment outflows are shown in red. Negative Total denotes an outflow.")
            ws.cell(row=row, column=1).font = Font(italic=True, size=9, color="666666")
            ws.merge_cells(start_row=row, start_column=1, end_row=row, end_column=11)

            # Adjust column widths — Expected (A-E) | gap (F) | Actual (G-K)
            for letter in ['A', 'G']:
                ws.column_dimensions[letter].width = 12
            for letter in ['B', 'C', 'D', 'E', 'H', 'I', 'J', 'K']:
                ws.column_dimensions[letter].width = 14
            ws.column_dimensions['F'].width = 2  # narrow gap between sides
            
            # Add to summary — same column structure as the download endpoint
            _row = _compute_summary_row_values(holding, trade)

            name_cell = ws_summary.cell(row=summary_row, column=1, value=_row['name'])
            name_cell.border = border
            name_cell.hyperlink = f"#'{sheet_name}'!A1"
            name_cell.font = Font(color="0563C1", underline="single")

            ws_summary.cell(row=summary_row, column=2, value=_row['investment']).border = border
            ws_summary.cell(row=summary_row, column=2).font = money_font
            ws_summary.cell(row=summary_row, column=2).number_format = '₹ #,##0.00'

            ws_summary.cell(row=summary_row, column=3, value=_row['gross_exp_p']).border = border
            ws_summary.cell(row=summary_row, column=3).font = money_font
            ws_summary.cell(row=summary_row, column=3).number_format = '₹ #,##0.00'

            ws_summary.cell(row=summary_row, column=4, value=_row['gross_exp_i']).border = border
            ws_summary.cell(row=summary_row, column=4).font = money_font
            ws_summary.cell(row=summary_row, column=4).number_format = '₹ #,##0.00'

            ws_summary.cell(row=summary_row, column=5, value=_row['repaid_p']).border = border
            ws_summary.cell(row=summary_row, column=5).font = money_font
            ws_summary.cell(row=summary_row, column=5).number_format = '₹ #,##0.00'

            ws_summary.cell(row=summary_row, column=6, value=_row['repaid_i']).border = border
            ws_summary.cell(row=summary_row, column=6).font = money_font
            ws_summary.cell(row=summary_row, column=6).number_format = '₹ #,##0.00'

            ws_summary.cell(row=summary_row, column=7, value=_row['repaid_tds']).border = border
            ws_summary.cell(row=summary_row, column=7).font = money_font
            ws_summary.cell(row=summary_row, column=7).number_format = '₹ #,##0.00'

            ws_summary.cell(row=summary_row, column=8, value=_row['profit']).border = border
            ws_summary.cell(row=summary_row, column=8).font = Font(bold=True, name="Consolas", color="047857" if _row['profit'] >= 0 else "DC2626")
            ws_summary.cell(row=summary_row, column=8).number_format = '₹ #,##0.00'

            ws_summary.cell(row=summary_row, column=9, value=f"{_row['exp_xirr']:.2f}%" if _row['exp_xirr'] is not None else '-').border = border
            ws_summary.cell(row=summary_row, column=9).alignment = Alignment(horizontal='right')
            ws_summary.cell(row=summary_row, column=10, value=f"{_row['act_xirr']:.2f}%" if _row['act_xirr'] is not None else '-').border = border
            ws_summary.cell(row=summary_row, column=10).alignment = Alignment(horizontal='right')

            status_cell = ws_summary.cell(row=summary_row, column=11, value=_row['status'])
            status_cell.border = border
            status_cell.alignment = Alignment(horizontal='center')
            status_cell.font = Font(bold=True, color="047857" if _row['status'] == 'Active' else "6B7280")

            summary_row += 1
    
    # Save to bytes
    excel_buffer = BytesIO()
    wb.save(excel_buffer)
    excel_bytes = excel_buffer.getvalue()
    excel_buffer.close()
    
    # Compute totals using the SAME logic as the Excel Summary tab so the
    # email cards match what the user sees in the attached spreadsheet.
    email_holdings_data = []
    total_invested = 0.0
    total_gross_expected = 0.0
    total_gross_repaid = 0.0
    total_profit = 0.0

    for h in holdings_data['holdings']:
        for t in (h.get('trades') or [h]):
            _r = _compute_summary_row_values(h, t)
            email_holdings_data.append({
                'bond_name': _r['name'],
                'invested_amount': _r['investment'],
                'gross_expected': _r['gross_expected'],
                'gross_repaid': _r['repaid_p'] + _r['repaid_i'] + _r['repaid_tds'],
                'profit': _r['profit'],
                'expected_xirr': round(_r['exp_xirr'], 2) if _r['exp_xirr'] is not None else '-',
                'actual_xirr':   round(_r['act_xirr'], 2) if _r['act_xirr'] is not None else '-',
            })
            total_invested      += _r['investment']
            total_gross_expected += _r['gross_expected']
            total_gross_repaid   += _r['repaid_p'] + _r['repaid_i'] + _r['repaid_tds']
            total_profit         += _r['profit']
    
    # Generate filename
    pan = holdings_data['client']['pan_number']
    filename = f"holdings_{pan}_{datetime.now(timezone.utc).strftime('%Y%m%d')}.xlsx"
    
    # Send email with attachment, CC to sub-broker, BCC to donotreply
    email_sent = send_holdings_report_email(
        client_name=client.get('name', 'Valued Investor'),
        client_email=client_email,
        holdings_data=email_holdings_data,
        total_invested=total_invested,
        total_expected=total_gross_expected,
        total_repaid=total_gross_repaid,
        total_profit=total_profit,
        cc_emails=cc_emails if cc_emails else None,
        excel_attachment=excel_bytes,
        attachment_filename=filename,
        bcc_emails=bcc_emails
    )
    
    if email_sent:
        return {
            "success": True,
            "message": f"Holdings report with Excel attachment sent to {client_email}" + (f" with CC to {', '.join(cc_emails)}" if cc_emails else "") + f" and BCC to {', '.join(bcc_emails)}",
            "recipient": client_email,
            "cc": cc_emails,
            "bcc": bcc_emails,
            "attachment": filename
        }
    else:
        raise HTTPException(status_code=500, detail="Failed to send email. Please check email configuration.")


@api_router.get("/holdings/export-cashflows/{client_id}")
async def export_client_cashflows(client_id: str, current_user: dict = Depends(get_current_user)):
    """Export all cashflows for a client to Excel (for updating repayments)"""
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    from io import BytesIO
    
    # Verify client access
    client = await db.Private_Investor.find_one({"id": client_id}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    
    if current_user['role'] == 'broker':
        if client.get('created_by') != current_user['id']:
            raise HTTPException(status_code=403, detail="Access denied")
    elif current_user['role'] == 'sub_broker':
        if client.get('linked_subbroker_id') != current_user['id']:
            raise HTTPException(status_code=403, detail="Access denied")
    
    # Get all cashflows for this client
    cashflows = await db.holding_cashflows.find(
        {"client_id": client_id},
        {"_id": 0}
    ).to_list(1000)
    
    if not cashflows:
        raise HTTPException(status_code=404, detail="No cashflows found for this client")
    
    wb = Workbook()
    ws = wb.active
    ws.title = "Cashflows"
    
    # Header style
    header_font = Font(bold=True, color="FFFFFF")
    header_fill = PatternFill(start_color="4472C4", end_color="4472C4", fill_type="solid")
    prepaid_fill = PatternFill(start_color="BDD7EE", end_color="BDD7EE", fill_type="solid")
    repaid_fill = PatternFill(start_color="C6EFCE", end_color="C6EFCE", fill_type="solid")
    
    # Headers
    headers = [
        "Client PAN", "Bond Name", "Scheduled Date", "Type",
        "Expected Amount", "Actual Paid Date", "Actual Amount Received", 
        "Status", "Prepaid", "Days Early", "Notes"
    ]
    
    for col, header in enumerate(headers, 1):
        cell = ws.cell(row=1, column=col, value=header)
        cell.font = header_font
        cell.fill = header_fill
        cell.alignment = Alignment(horizontal='center')
    
    # Data rows
    for row_num, cf in enumerate(cashflows, 2):
        ws.cell(row=row_num, column=1, value=client['pan_number'])
        ws.cell(row=row_num, column=2, value=cf.get('bond_name', ''))
        
        # Format scheduled date
        scheduled_date = cf.get('date', '')
        if scheduled_date:
            try:
                dt = datetime.fromisoformat(scheduled_date.replace('Z', '+00:00'))
                scheduled_date = dt.strftime("%d-%m-%Y")
            except:
                pass
        ws.cell(row=row_num, column=3, value=scheduled_date)
        
        ws.cell(row=row_num, column=4, value=cf.get('type', ''))
        ws.cell(row=row_num, column=5, value=cf.get('net_amount', 0))
        
        # Format actual paid date
        repaid_date = cf.get('repaid_date', '')
        if repaid_date:
            try:
                dt = datetime.fromisoformat(repaid_date.replace('Z', '+00:00'))
                repaid_date = dt.strftime("%d-%m-%Y")
            except:
                pass
        ws.cell(row=row_num, column=6, value=repaid_date or '')
        
        ws.cell(row=row_num, column=7, value=cf.get('repaid_actual_amount', '') or '')
        ws.cell(row=row_num, column=8, value='Repaid' if cf.get('is_repaid') else 'Pending')
        ws.cell(row=row_num, column=9, value='Yes' if cf.get('is_prepaid') else 'No')
        ws.cell(row=row_num, column=10, value=cf.get('days_early', 0) or 0)
        ws.cell(row=row_num, column=11, value=cf.get('notes', '') or '')
        
        # Highlight prepaid and repaid rows
        if cf.get('is_prepaid'):
            for col in range(1, 12):
                ws.cell(row=row_num, column=col).fill = prepaid_fill
        elif cf.get('is_repaid'):
            for col in range(1, 12):
                ws.cell(row=row_num, column=col).fill = repaid_fill
    
    # Set column widths
    ws.column_dimensions['A'].width = 15
    ws.column_dimensions['B'].width = 35
    ws.column_dimensions['C'].width = 15
    ws.column_dimensions['D'].width = 12
    ws.column_dimensions['E'].width = 18
    ws.column_dimensions['F'].width = 18
    ws.column_dimensions['G'].width = 22
    ws.column_dimensions['H'].width = 12
    ws.column_dimensions['I'].width = 10
    ws.column_dimensions['J'].width = 12
    ws.column_dimensions['K'].width = 30
    
    buffer = BytesIO()
    wb.save(buffer)
    buffer.seek(0)
    
    return StreamingResponse(
        buffer,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f"attachment; filename=cashflows_{client['pan_number']}.xlsx"}
    )


# ==================== REINVESTMENT TAGGING ====================

class UccAllocation(BaseModel):
    """Single UCC allocation within a split reinvestment"""
    ucc: Optional[str] = ''  # Optional for amounts < 1000 (tagged to 'none')
    amount: float
    portfolio: str
    tag: Optional[str] = None
    investment_date: Optional[str] = None  # MF investment date selected by broker/sub-broker


class ReinvestmentTagUpdate(BaseModel):
    reinvestment_tag: str
    custom_amount: Optional[float] = None  # "not_tagged", "principal", "interest", "net_amount", "not_invest"
    send_approval_email: bool = False  # Whether to send approval email to client
    portfolio_category: Optional[str] = None  # "wealth", "tax", "short_term", "commodities", "retirement", "children_education"
    target_ucc: Optional[str] = None  # Target UCC for reinvestment
    ucc_allocations: Optional[List[UccAllocation]] = None  # For split allocations across multiple UCCs/portfolios


class ReinvestmentApproval(BaseModel):
    approved: bool
    notes: Optional[str] = None


class SendReinvestmentApprovalRequest(BaseModel):
    client_id: str
    cashflow_ids: List[str]


@api_router.get("/reinvestment/upcoming")
async def get_upcoming_reinvestments(current_user: dict = Depends(get_current_user)):
    """
    Get upcoming repayments for reinvestment tagging.
    
    UPDATED LOGIC (as per user requirements - Feb 2026):
    - ONLY show entries that have ACTUAL repayments (from emails or manual entry)
    - DO NOT show expected/scheduled maturity values as these may be incorrect after prepayments
    - This ensures only confirmed repayment amounts are available for tagging
    
    SUB-BROKER FILTERING:
    - Sub-brokers only see their linked clients
    - Brokers see all clients
    """
    
    upcoming = []
    
    # For sub-brokers, get only their linked client IDs
    allowed_client_ids = None
    if current_user.get('role') == 'sub_broker':
        linked_clients = await db.Private_Investor.find(
            {"linked_subbroker_id": current_user['id']},
            {"id": 1, "_id": 0}
        ).to_list(10000)
        allowed_client_ids = set(c['id'] for c in linked_clients)
        
        # If sub-broker has no linked clients, return empty result
        if not allowed_client_ids:
            return {
                "months": [],
                "by_client": [],
                "total_upcoming": 0
            }
    
    # Get all approved trades with their bonds
    # For sub-brokers, filter by allowed client IDs
    trade_query = {"status": "approved"}
    if allowed_client_ids is not None:
        trade_query["client_id"] = {"$in": list(allowed_client_ids)}
    
    all_trades = await db.Ncd_Investment_Details.find(trade_query, {"_id": 0}).to_list(10000)
    
    # Build a map of bond_id -> bond for efficiency
    bond_ids = list(set(t.get('bond_id') for t in all_trades if t.get('bond_id')))
    bonds_list = await db.Ncd_Master.find({"id": {"$in": bond_ids}}, {"_id": 0}).to_list(len(bond_ids))
    bonds_map = {b['id']: b for b in bonds_list}
    
    # Get all clients for enrichment
    client_ids = list(set(t.get('client_id') for t in all_trades if t.get('client_id')))
    clients_list = await db.Private_Investor.find({"id": {"$in": client_ids}}, {"_id": 0}).to_list(len(client_ids))
    clients_map = {c['id']: c for c in clients_list}
    
    # =====================================================================
    # SOURCE OF EXPECTED ROWS (per user request, Apr 2026):
    # Pull untagged-able rows from `Ncd_Expected_Repayments` (the canonical
    # view that already powers the Expected Repayments tab + Cashflow Details
    # modal). Tagging state continues to live on `holding_cashflows`, so we
    # build a (client_id, bond_id, date) index of those rows to enrich each
    # expected entry with reinvestment_tag / approval_status / etc.
    # =====================================================================
    expected_query: dict = {}
    if allowed_client_ids is not None:
        expected_query["client_id"] = {"$in": list(allowed_client_ids)}
    expected_rows = await db.Ncd_Expected_Repayments.find(
        expected_query, {"_id": 0}
    ).to_list(50000)

    cf_state_index: dict = {}
    async for cf in db.holding_cashflows.find({}, {"_id": 0}):
        date_key = (cf.get("date") or "").split("T")[0].split(" ")[0]
        # Key by (trade_id, date) — a single client can hold multiple trades
        # on the same bond/date, and each trade has its own holding_cashflows
        # row. Keying on (client_id, bond_id, date) collapses them onto one
        # row, which causes duplicate `id`s in the API response and ties
        # together two checkboxes on the Reinv Tag page.
        if cf.get("trade_id") and date_key:
            cf_state_index[(cf["trade_id"], date_key)] = cf

    cashflows_by_trade: dict = {}
    for er in expected_rows:
        trade_id = er.get("trade_id")
        if not trade_id:
            continue
        date_key = (er.get("expected_date") or "").split("T")[0].split(" ")[0]
        cf_state = cf_state_index.get((trade_id, date_key), {})
        synthetic_cf = {
            # Preserve holding_cashflows.id when we have one — that's what
            # `reinvestment_logs.cashflow_id` references, so existing tag
            # writes / approvals continue to round-trip correctly.
            "id": cf_state.get("id") or er.get("id"),
            "trade_id": trade_id,
            "bond_id": er.get("bond_id"),
            "bond_code": er.get("bond_code"),
            "client_id": er.get("client_id"),
            "date": er.get("expected_date"),
            "principal_component": er.get("principal_component", 0) or 0,
            "interest_component": er.get("interest_component", 0) or 0,
            "type": cf_state.get("type") or er.get("type", "coupon"),
            "is_maturity": cf_state.get("is_maturity", False),
            "is_prepayment_adjusted": cf_state.get("is_prepayment_adjusted", False),
            # Tagging state stays sourced from holding_cashflows.
            "reinvestment_tag": cf_state.get("reinvestment_tag"),
            "approval_status": cf_state.get("approval_status"),
            "client_approved": cf_state.get("client_approved", False),
            "kinntegra_api_submitted": cf_state.get("kinntegra_api_submitted", False),
            # Split allocations (so the Reinv Tag "Tagged (Pending)" view
            # can render every row — including sub-₹1000 residuals that
            # were saved to `ucc_allocations` but don't live in the base
            # `target_ucc` / `portfolio_category` fields).
            "has_split_allocations": cf_state.get("has_split_allocations", False),
            "ucc_allocations": cf_state.get("ucc_allocations"),
            "target_ucc": cf_state.get("target_ucc"),
            "portfolio_category": cf_state.get("portfolio_category"),
        }
        cashflows_by_trade.setdefault(trade_id, []).append(synthetic_cf)

    # Historical rows from Ncd_Repayments — already-confirmed receipts. The
    # frontend renders these read-only with a muted colour so users can see
    # what's already been received against each trade.
    historical_query: dict = {}
    if allowed_client_ids is not None:
        historical_query["client_id"] = {"$in": list(allowed_client_ids)}
    historical_rows = await db.Ncd_Repayments.find(
        historical_query, {"_id": 0}
    ).to_list(50000)
    
    # Get all actual repayments for balance calculation
    all_actual_repayments = await db.actual_repayments.find({}, {"_id": 0}).to_list(50000)
    repayments_by_trade = {}
    for ar in all_actual_repayments:
        trade_id = ar.get('trade_id')
        if trade_id:
            if trade_id not in repayments_by_trade:
                repayments_by_trade[trade_id] = []
            repayments_by_trade[trade_id].append(ar)
    
    # Get all existing reinvestment logs for tag status
    all_reinv_logs = await db.reinvestment_logs.find(
        {"approval_status": {"$nin": ["cancelled", "auto_cancelled", "rejected"]}},
        {"_id": 0}
    ).to_list(50000)
    reinv_logs_by_cashflow = {}
    for log in all_reinv_logs:
        cf_id = log.get('cashflow_id')
        if cf_id:
            reinv_logs_by_cashflow[cf_id] = log
    
    for trade in all_trades:
        bond = bonds_map.get(trade.get('bond_id'))
        if not bond:
            continue
        
        client = clients_map.get(trade.get('client_id'))
        if not client:
            continue
        
        # Determine cashflows_per_unit count for this bond
        cashflows_per_unit = bond.get('cashflows_per_unit', [])
        cashflows_count = len(cashflows_per_unit) if cashflows_per_unit else 1
        
        # Get bond name from bonds collection
        bond_name = bond.get('name') or bond.get('issuer') or ''
        bond_code = bond.get('bond_code', '')
        
        # Get client details
        client_ucc_list = client.get('ucc_list', [])
        if not client_ucc_list and client.get('ucc'):
            client_ucc_list = [client.get('ucc')]
        
        trade_cashflows = cashflows_by_trade.get(trade['id'], [])
        trade_repayments = repayments_by_trade.get(trade['id'], [])
        
        # Calculate total repaid amount for this trade
        total_repaid = sum(
            r.get('net_amount', 0) or r.get('gross_amount', 0) or r.get('amount', 0) or r.get('principal', 0) 
            for r in trade_repayments
        )
        
        # Build list of expected cashflows with dates AND amounts for matching with actual repayments
        expected_cashflows_info = []
        for cf in trade_cashflows:
            cf_date_str = cf.get('date', '')
            if cf_date_str:
                try:
                    if 'T' in cf_date_str:
                        cf_date = datetime.fromisoformat(cf_date_str.split('T')[0]).date()
                    else:
                        cf_date = datetime.strptime(cf_date_str, "%Y-%m-%d").date()
                    
                    # Calculate expected net amount
                    principal = cf.get('principal_component', 0)
                    interest = cf.get('interest_component', 0)
                    tds = interest * 0.10 if interest else 0
                    net_amount = principal + interest - tds
                    
                    expected_cashflows_info.append({
                        'date': cf_date,
                        'net_amount': net_amount,
                        'principal': principal,
                        'interest_net': interest - tds
                    })
                except (ValueError, TypeError):
                    pass
        
        # Helper function to check if actual repayment matches an expected cashflow
        def matches_expected_cashflow(repay_date_str, repay_amount, tolerance_days=5, tolerance_percent=3):
            """
            Check if actual repayment matches any expected cashflow based on:
            - Date: within ±tolerance_days
            - Amount: within ±tolerance_percent (to handle gross vs net differences like TDS)
            
            This handles cases where:
            - Expected shows net amount (after TDS)
            - Actual repayment from email shows gross amount (before TDS)
            - TDS is typically ~10% of interest, so 3% overall tolerance covers this
            """
            if not repay_date_str:
                return False
            try:
                if 'T' in repay_date_str:
                    repay_date = datetime.fromisoformat(repay_date_str.split('T')[0]).date()
                else:
                    repay_date = datetime.strptime(repay_date_str, "%Y-%m-%d").date()
                
                for expected in expected_cashflows_info:
                    days_diff = abs((repay_date - expected['date']).days)
                    
                    # Calculate percentage difference for amount matching
                    expected_amount = expected['net_amount'] or 0
                    actual_amount = repay_amount or 0
                    
                    if expected_amount > 0:
                        amount_diff_percent = abs(actual_amount - expected_amount) / expected_amount * 100
                    elif actual_amount > 0:
                        amount_diff_percent = 100  # No expected amount but actual has amount
                    else:
                        amount_diff_percent = 0  # Both zero
                    
                    # Match if date is within tolerance AND amount is within percentage tolerance
                    if days_diff <= tolerance_days and amount_diff_percent <= tolerance_percent:
                        return True
            except (ValueError, TypeError):
                pass
            return False
        
        # UPDATED LOGIC: 
        # - Show expected cashflows (primary source)
        # - Only show actual repayments if they are TRUE prepayments (don't match any expected cashflow)
        
        # Add actual repayments ONLY if they are prepayments (not matching expected cashflows)
        for repay in trade_repayments:
            repay_date = repay.get('repayment_date', '') or repay.get('date', '')
            repay_net_amount = repay.get('net_amount', 0) or repay.get('gross_amount', 0) or repay.get('amount', 0)
            
            # Skip this actual repayment if it matches an expected cashflow (within ±5 days AND ±3%)
            # This prevents duplicates - the expected cashflow entry will be shown instead
            # 3% tolerance handles gross vs net (TDS) differences
            if matches_expected_cashflow(repay_date, repay_net_amount, tolerance_days=5, tolerance_percent=3):
                continue
            
            # This is a TRUE prepayment - add it with correct amounts from actual repayment
            #
            # Tag/approval state lives on `holding_cashflows` (keyed by
            # trade_id + date) and `reinvestment_logs.cashflow_id`. If a
            # holding_cashflows row already exists for this (trade, date),
            # use its id as the canonical cashflow_id so we pick up any
            # existing tag/approval status — otherwise the entry was being
            # mislabelled as "Not Tagged" even after the broker had
            # submitted/approved it (visible on Holdings → NCD → Reinv Tag).
            repay_date_key = (repay_date or '').split('T')[0].split(' ')[0]
            cf_state = cf_state_index.get((trade['id'], repay_date_key), {})
            cashflow_id = cf_state.get('id') or f"repay_{repay.get('id', '')}"
            reinv_log = reinv_logs_by_cashflow.get(cashflow_id, {})
            
            if not repay_net_amount:
                continue
            
            # Get actual amounts from repayment record
            # Principal amount from actual repayment
            actual_principal = repay.get('principal', 0) or repay.get('principal_amount', 0) or 0
            # Interest amount (gross) from actual repayment  
            actual_interest_gross = repay.get('interest', 0) or repay.get('interest_amount', 0) or 0
            # TDS amount from actual repayment
            actual_tds = repay.get('tds', 0) or repay.get('tds_amount', 0) or 0
            # Calculate net interest (interest - TDS)
            actual_interest_net = actual_interest_gross - actual_tds
            
            # If principal is 0 but we have net_amount, use net_amount as principal (for cases where breakdown not available)
            if actual_principal == 0 and repay_net_amount > 0:
                actual_principal = repay_net_amount
            
            # Mark as prepayment since it doesn't match any expected cashflow
            repay_type = "prepayment"

            # Resolve tagging state with the same fallback chain used for the
            # expected-cashflow branch (reinvestment_logs → holding_cashflows
            # → default). Without this, entries already submitted/approved on
            # Holdings appear as "Not Tagged" on the Reinv Tag page.
            reinvestment_tag = (
                reinv_log.get('reinvestment_tag')
                or cf_state.get('reinvestment_tag')
                or 'not_tagged'
            )
            approval_status = (
                reinv_log.get('approval_status')
                or cf_state.get('approval_status')
                or 'none'
            )
            client_approved = reinv_log.get(
                'client_approved', cf_state.get('client_approved', False)
            )
            kinntegra_submitted = cf_state.get('kinntegra_api_submitted', False)
            if kinntegra_submitted:
                approval_status = 'submitted'
                client_approved = True
            
            upcoming.append({
                "cashflow_id": cashflow_id,
                "client_id": trade['client_id'],
                "client_name": client.get('name', 'Unknown'),
                "client_pan": client.get('pan_number', ''),
                "client_email": client.get('email', ''),
                "client_ucc_list": client_ucc_list,
                "bond_id": bond['id'],
                "bond_name": bond_name,
                "bond_code": bond_code,
                "trade_id": trade['id'],
                "amount_invested": trade.get('total_amount', 0),
                "units": trade.get('units', 0),
                "expected_date": repay_date,
                "principal_net": actual_principal,
                "interest_net": actual_interest_net,
                "tds_amount": actual_tds,
                "net_amount": repay_net_amount,
                "type": repay_type,
                "reinvestment_tag": reinvestment_tag,
                "approval_status": approval_status,
                "client_approved": client_approved,
                "kinntegra_submitted": kinntegra_submitted,
                "auto_tagged": repay.get('auto_tagged', False),
                "source": "actual_repayment",
                "repayment_id": repay.get('id', ''),
                "target_ucc": cf_state.get('target_ucc'),
                "portfolio_category": cf_state.get('portfolio_category'),
                "has_split_allocations": cf_state.get('has_split_allocations', False),
                "allocations": _distribute_allocation_net_amounts(
                    cf_state.get('ucc_allocations') or [], repay_net_amount
                )
            })
        
        # ADDED BACK: Include expected cashflows for future dates
        # This shows scheduled payments from payment_schedule for future months
        # Actual prepayments (that don't match expected cashflows) come from actual_repayments (above)
        
        # Add expected cashflows - these are the PRIMARY source of reinvestment entries
        today = datetime.now(timezone.utc).date()
        
        # Check if this trade has any TRUE prepayments - if so, skip maturity expected cashflows
        # as the final maturity amounts will change due to prepayments
        # 
        # A TRUE prepayment is an actual repayment that doesn't match any expected cashflow
        # We already filtered those above using matches_expected_cashflow()
        actual_cashflow_count = len(trade_repayments)
        expected_cashflow_count = len(trade_cashflows)
        has_prepayments = actual_cashflow_count > expected_cashflow_count
        
        # Also check for explicit prepayment flags
        if not has_prepayments and len(trade_repayments) > 0:
            has_prepayments = any(
                r.get('is_prepayment') or 
                r.get('is_prepayment_adjusted') or
                r.get('payment_type') == 'prepayment' or 
                r.get('type') == 'prepayment'
                for r in trade_repayments
            )
        
        # Also check prepaid_count on the trade itself
        trade_prepaid_count = trade.get('prepaid_count', 0) or 0
        trade_prepaid_amount = trade.get('prepaid_amount', 0) or 0
        if trade_prepaid_count > 0 or trade_prepaid_amount > 0:
            has_prepayments = True
        
        for cf in trade_cashflows:
            cf_date_str = cf.get('date', '')
            if not cf_date_str:
                continue
            
            # Parse the date first
            try:
                if 'T' in cf_date_str:
                    cf_date = datetime.fromisoformat(cf_date_str.split('T')[0]).date()
                else:
                    cf_date = datetime.strptime(cf_date_str, "%Y-%m-%d").date()
            except (ValueError, TypeError):
                continue
            
            # Get cashflow amounts
            principal_component = cf.get('principal_component', 0)
            interest_component = cf.get('interest_component', 0)
            tds = interest_component * 0.10 if interest_component else 0
            interest_net = interest_component - tds
            net_amount = principal_component + interest_net
            
            if net_amount <= 0:
                continue
            
            cashflow_id = cf.get('id', '')
            reinv_log = reinv_logs_by_cashflow.get(cashflow_id, {})
            
            # Get tag from reinvestment_logs first, fallback to holding_cashflows
            # This handles cases where log might not exist but cashflow was tagged directly
            reinvestment_tag = reinv_log.get('reinvestment_tag') or cf.get('reinvestment_tag') or 'not_tagged'
            approval_status = reinv_log.get('approval_status') or cf.get('approval_status') or 'none'
            client_approved = reinv_log.get('client_approved', cf.get('client_approved', False))
            kinntegra_submitted = cf.get('kinntegra_api_submitted', False)
            
            # If submitted to Kinntegra, treat as fully approved
            if kinntegra_submitted:
                approval_status = "submitted"
                client_approved = True
            
            # Determine type
            cf_type = cf.get('type', 'coupon')
            is_maturity = cf.get('is_maturity') or cf_type == 'maturity'
            is_prepayment_adjusted = cf.get('is_prepayment_adjusted', False)
            if is_maturity:
                cf_type = 'maturity'
            
            # Skip maturity expected cashflows for trades with prepayments
            # The maturity amount will change due to prepayments, so showing original expected value is misleading
            # Also skip if this specific cashflow has been marked as prepayment-adjusted
            if is_maturity and (has_prepayments or is_prepayment_adjusted):
                continue
            
            upcoming.append({
                "cashflow_id": cashflow_id,
                "client_id": trade['client_id'],
                "client_name": client.get('name', 'Unknown'),
                "client_pan": client.get('pan_number', ''),
                "client_email": client.get('email', ''),
                "client_ucc_list": client_ucc_list,
                "bond_id": bond['id'],
                "bond_name": bond_name,
                "bond_code": bond_code,
                "trade_id": trade['id'],
                "amount_invested": trade.get('total_amount', 0),
                "units": trade.get('units', 0),
                "expected_date": cf_date_str,
                "principal_net": principal_component,
                "interest_net": round(interest_net, 2),
                "net_amount": round(net_amount, 2),
                "type": cf_type,
                "reinvestment_tag": reinvestment_tag,
                "approval_status": approval_status,
                "client_approved": client_approved,
                "kinntegra_submitted": kinntegra_submitted,
                "auto_tagged": cf.get('auto_tagged', False),
                "source": "expected_cashflow",
                "is_past_date": cf_date < today,
                "target_ucc": cf.get('target_ucc'),
                "portfolio_category": cf.get('portfolio_category'),
                # Expose saved split allocations so the Tagged (Pending)
                # table renders each UCC/portfolio row (including sub-₹1000
                # residuals auto-tagged to "None"). Each allocation's
                # `net_amount` is the rounded investment amount for
                # non-residual rows; decimal leftovers are parked on the
                # "None" residual row so the UI matches the client view.
                "has_split_allocations": cf.get('has_split_allocations', False),
                "allocations": _distribute_allocation_net_amounts(
                    cf.get('ucc_allocations') or [], net_amount
                )
            })
        
        # REMOVED: Expected cashflows section - only showing actual repayments now
        
        if False:  # Disabled - keeping code for reference but not executing
            # LOGIC 2: NCDs with =1 expected cashflow per unit (typically maturity only)
            # Show ALL actual repayments (they are all effectively prepayments before maturity)
            # Plus show maturity with remaining balance
            
            # Get maturity date for reference
            maturity_cf = None
            for cf in trade_cashflows:
                if cf.get('is_maturity') or cf.get('type') == 'maturity':
                    maturity_cf = cf
                    break
            
            if not maturity_cf and trade_cashflows:
                sorted_cfs = sorted(trade_cashflows, key=lambda x: x.get('date', ''))
                maturity_cf = sorted_cfs[-1] if sorted_cfs else None
            
            maturity_date_str = maturity_cf.get('date', '') if maturity_cf else ''
            
            # Add ALL actual repayments as prepayment entries (for single-cashflow NCDs, any payment before maturity is a prepayment)
            for repay in trade_repayments:
                prepay_id = f"prepay_{repay.get('id', '')}"
                reinv_log = reinv_logs_by_cashflow.get(prepay_id, {})
                
                # Get the repayment amount - check multiple possible field names
                repay_amount = repay.get('net_amount', 0) or repay.get('gross_amount', 0) or repay.get('amount', 0) or repay.get('principal', 0)
                repay_date = repay.get('repayment_date', '') or repay.get('date', '')
                
                # Skip if no amount
                if not repay_amount:
                    continue
                
                upcoming.append({
                    "cashflow_id": prepay_id,
                    "client_id": trade['client_id'],
                    "client_name": client.get('name', 'Unknown'),
                    "client_pan": client.get('pan_number', ''),
                    "client_email": client.get('email', ''),
                    "client_ucc_list": client_ucc_list,
                    "bond_id": bond['id'],
                    "bond_name": bond_name,
                    "bond_code": bond_code,
                    "trade_id": trade['id'],
                    "amount_invested": trade.get('total_amount', 0),
                    "units": trade.get('units', 0),
                    "expected_date": repay_date,
                    "principal_net": repay.get('principal', 0) or repay_amount,
                    "interest_net": (repay.get('interest', 0) or 0) - (repay.get('tds', 0) or 0),
                    "net_amount": repay_amount,
                    "type": "prepayment",
                    "reinvestment_tag": reinv_log.get('reinvestment_tag', 'not_tagged'),
                    "approval_status": reinv_log.get('approval_status', 'none'),
                    "client_approved": reinv_log.get('client_approved', False),
                    "auto_tagged": repay.get('auto_tagged', False),
                    "source": "actual_repayment",
                    "prepayment_id": repay.get('id', '')
                })
            
            # Add maturity entry with balance (original amount - repaid amount)
            if maturity_cf:
                # Calculate original principal based on units × face_value (or principal_per_unit)
                # NOT the trade's total_amount which is the purchase price
                units = trade.get('units', 0)
                face_value = bond.get('face_value', 100000)  # Default face value
                
                # Try to get principal_per_unit from cashflows_per_unit
                principal_per_unit = face_value
                if cashflows_per_unit and len(cashflows_per_unit) > 0:
                    # For single cashflow NCD, the principal_per_unit is the face value
                    principal_per_unit = cashflows_per_unit[0].get('principal_per_unit', face_value)
                
                # Original principal = units × principal_per_unit (face value)
                original_principal = units * principal_per_unit
                
                # If maturity_cf has principal_component that matches units × principal_per_unit, use it
                # Otherwise use our calculated value
                cf_principal = maturity_cf.get('principal_component', 0)
                if cf_principal and abs(cf_principal - original_principal) < 1000:  # Close enough
                    original_principal = cf_principal
                
                balance_principal = max(0, original_principal - total_repaid)
                
                # Only show if there's remaining balance
                if balance_principal > 0:
                    cashflow_id = maturity_cf.get('id', '')
                    reinv_log = reinv_logs_by_cashflow.get(cashflow_id, {})
                    
                    # Calculate interest based on remaining balance
                    # Interest per unit from bond definition
                    interest_per_unit = 0
                    if cashflows_per_unit and len(cashflows_per_unit) > 0:
                        interest_per_unit = cashflows_per_unit[0].get('interest_per_unit', 0)
                    
                    # Original interest = units × interest_per_unit
                    original_interest = units * interest_per_unit
                    
                    # Adjust interest proportionally to remaining principal
                    if original_principal > 0:
                        interest_ratio = balance_principal / original_principal
                        adjusted_interest = original_interest * interest_ratio
                    else:
                        adjusted_interest = maturity_cf.get('interest_component', 0)
                    
                    tds = adjusted_interest * 0.10  # 10% TDS
                    interest_net = adjusted_interest - tds
                    net_amount = balance_principal + interest_net
                    
                    upcoming.append({
                        "cashflow_id": cashflow_id,
                        "client_id": trade['client_id'],
                        "client_name": client.get('name', 'Unknown'),
                        "client_pan": client.get('pan_number', ''),
                        "client_email": client.get('email', ''),
                        "client_ucc_list": client_ucc_list,
                        "bond_id": bond['id'],
                        "bond_name": bond_name,
                        "bond_code": bond_code,
                        "trade_id": trade['id'],
                        "amount_invested": trade.get('total_amount', 0),
                        "units": trade.get('units', 0),
                        "expected_date": maturity_cf.get('date', ''),
                        "principal_net": balance_principal,
                        "interest_net": round(interest_net, 2),
                        "net_amount": round(net_amount, 2),
                        "type": "maturity",
                        "reinvestment_tag": reinv_log.get('reinvestment_tag', 'not_tagged'),
                        "approval_status": reinv_log.get('approval_status', 'none'),
                        "client_approved": reinv_log.get('client_approved', False),
                        "auto_tagged": maturity_cf.get('auto_tagged', False),
                        "source": "maturity_balance",
                        "original_principal": original_principal,
                        "total_repaid": total_repaid
                    })
    
    # Deduplicate by (client_id, bond_id, expected_date, net_amount)
    seen_entries = set()
    unique_upcoming = []
    for item in upcoming:
        dedup_key = (
            item.get('client_id', ''),
            item.get('bond_id', ''),
            item.get('expected_date', ''),
            round(item.get('net_amount', 0), 2)
        )
        if dedup_key in seen_entries:
            continue
        seen_entries.add(dedup_key)
        unique_upcoming.append(item)
    
    upcoming = unique_upcoming
    
    # Exclude entries that have already moved into Reinv Logs.
    #
    # The Reinv Logs view (Holdings → NCD → Reinv Logs and Logs → Reinv Logs)
    # treats a holding_cashflows row as a "log" once it has a non-empty
    # reinvestment_tag AND either kinntegra_api_submitted=True or
    # approval_status ∈ {approved, submitted, client_approved, broker_approved,
    # auto_approved}. Once an entry is on that view, the broker shouldn't see
    # it on the Reinv Tag page in either the Untagged or Tagged buckets — the
    # explicit lifecycle is Untagged → Tagged (pending_broker_approval) →
    # Reinv Logs.
    _SUBMITTED_STATUSES = {
        'pending',  # broker approved, now awaiting client → lives in Reinv Logs
        'approved', 'submitted', 'client_approved',
        'broker_approved', 'auto_approved',
    }
    def _is_in_reinv_logs(item: dict) -> bool:
        tag = (item.get('reinvestment_tag') or '').strip().lower()
        if not tag or tag in {'not_tagged', 'none'}:
            return False
        if item.get('kinntegra_submitted') or item.get('client_approved'):
            return True
        status = (item.get('approval_status') or '').strip().lower()
        return status in _SUBMITTED_STATUSES
    upcoming = [it for it in upcoming if not _is_in_reinv_logs(it)]
    
    # Sort by date
    def safe_date_sort(item):
        try:
            date_str = item.get('expected_date', '')
            if 'T' in date_str:
                return datetime.fromisoformat(date_str.split('T')[0]).date()
            return datetime.strptime(date_str, "%Y-%m-%d").date()
        except (ValueError, TypeError):
            return datetime.now(timezone.utc).date()
    
    upcoming.sort(key=safe_date_sort)
    
    # Group by month
    months = {}
    for item in upcoming:
        try:
            date_str = item.get('expected_date', '')
            if 'T' in date_str:
                date_obj = datetime.fromisoformat(date_str.split('T')[0]).date()
            else:
                date_obj = datetime.strptime(date_str, "%Y-%m-%d").date()
            month = date_obj.strftime("%B %Y")
        except (ValueError, TypeError):
            continue
        
        if month not in months:
            months[month] = []
        months[month].append(item)
    
    # Group by client
    by_client = {}
    for item in upcoming:
        client_id = item['client_id']
        if client_id not in by_client:
            by_client[client_id] = {
                "client_id": client_id,
                "client_name": item['client_name'],
                "client_pan": item['client_pan'],
                "client_email": item['client_email'],
                "entries": [],
                "total_amount": 0,
                "tagged_count": 0,
                "pending_approval": 0,
                "approved_count": 0
            }
        by_client[client_id]['entries'].append(item)
        by_client[client_id]['total_amount'] += item['net_amount']
        if item['reinvestment_tag'] != 'not_tagged':
            by_client[client_id]['tagged_count'] += 1
        if item['approval_status'] == 'pending':
            by_client[client_id]['pending_approval'] += 1
        if item['client_approved']:
            by_client[client_id]['approved_count'] += 1
    
    # Build month list
    today = datetime.now(timezone.utc).date()
    from calendar import month_name as cal_month_names
    
    def parse_month_key(month_str):
        parts = month_str.split(' ')
        month_idx = list(cal_month_names).index(parts[0])
        year = int(parts[1])
        return year * 12 + month_idx
    
    all_months_data = []
    for month_name, items in months.items():
        all_months_data.append({
            "name": month_name,
            "items": items,
            "count": len(items)
        })
    
    all_months_data.sort(key=lambda x: parse_month_key(x['name']))
    
    # Add next 6 months if empty
    current_date = today.replace(day=1)
    existing_month_names = {m['name'] for m in all_months_data}
    for i in range(6):
        month_name = current_date.strftime("%B %Y")
        if month_name not in existing_month_names:
            all_months_data.append({
                "name": month_name,
                "items": [],
                "count": 0
            })
        if current_date.month == 12:
            current_date = current_date.replace(year=current_date.year + 1, month=1)
        else:
            current_date = current_date.replace(month=current_date.month + 1)
    
    all_months_data.sort(key=lambda x: parse_month_key(x['name']))
    
    # Build a `historical` list — read-only rows already cited in
    # Ncd_Repayments, rendered with a muted colour by the frontend so users
    # can see what's already been received without disrupting the tagging
    # workflow above.
    #
    # Suppress historical rows that just mirror an already-tagged & submitted
    # holding_cashflows row — otherwise the broker sees the same maturity
    # as TWO rows (the original projected one + the actual receipt one) on
    # the Reinv Tag page even after they've completed the workflow.
    #
    # We index the suppression key two ways because legacy `Ncd_Repayments`
    # rows often have an empty `trade_id` (especially for IMAP-synced
    # actuals): primary key is (trade_id, date), fallback key is
    # (client_id, bond_id, date).
    submitted_cf_keys: set = set()
    submitted_cf_alt_keys: set = set()
    for (tid, dkey), cf in cf_state_index.items():
        tag = (cf.get('reinvestment_tag') or '').strip().lower()
        if not tag or tag in {'not_tagged', 'none'}:
            continue
        is_submitted = (
            cf.get('kinntegra_api_submitted')
            or cf.get('client_approved')
            or (cf.get('approval_status') or '').strip().lower() in _SUBMITTED_STATUSES
        )
        if is_submitted:
            submitted_cf_keys.add((tid, dkey))
            submitted_cf_alt_keys.add((cf.get('client_id'), cf.get('bond_id'), dkey))

    historical: list = []
    for hr in historical_rows:
        repay_date = hr.get("repayment_date") or hr.get("date") or ""
        repay_date_key = repay_date.split("T")[0].split(" ")[0]
        primary_key = (hr.get("trade_id"), repay_date_key)
        alt_key = (hr.get("client_id"), hr.get("bond_id"), repay_date_key)
        if primary_key in submitted_cf_keys or alt_key in submitted_cf_alt_keys:
            # Already represented by the tagged+submitted holding_cashflows
            # row, which is itself surfaced through Reinv Logs. Skip the
            # duplicate historical mirror.
            continue
        historical.append({
            "id": hr.get("id"),
            "client_id": hr.get("client_id"),
            "client_name": hr.get("client_name", ""),
            "client_pan": hr.get("client_pan", ""),
            "client_email": hr.get("client_email", ""),
            "bond_id": hr.get("bond_id", ""),
            "bond_name": hr.get("bond_name", ""),
            "bond_code": hr.get("bond_code", ""),
            "trade_id": hr.get("trade_id", ""),
            "expected_date": hr.get("repayment_date") or hr.get("date"),
            "principal_net": hr.get("principal_amount", 0) or hr.get("principal_component", 0) or 0,
            "interest_net": (hr.get("interest_amount", 0) or hr.get("interest_component", 0) or 0)
                            - (hr.get("tds_amount", 0) or 0),
            "tds_amount": hr.get("tds_amount", 0) or 0,
            "net_amount": hr.get("net_amount", 0) or 0,
            "type": hr.get("type", "historical"),
            "is_historical": True,
            "reinvestment_tag": "historical",
            "approval_status": "historical",
        })

    return {
        "months": all_months_data,
        "by_client": list(by_client.values()),
        "historical": historical,
        "total_upcoming": len(upcoming),
        "total_historical": len(historical),
    }


@api_router.delete("/reinvestment/clear-all-logs")
async def clear_all_reinvestment_logs(current_user: dict = Depends(get_current_user)):
    """Clear all reinvestment logs. Only brokers can perform this action."""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can clear reinvestment logs")
    
    # Delete all reinvestment logs
    result = await db.reinvestment_logs.delete_many({})
    
    # Also clear reinvestment tags from holding_cashflows
    await db.holding_cashflows.update_many(
        {},
        {"$set": {
            "reinvestment_tag": "not_tagged",
            "portfolio_category": None,
            "target_ucc": None,
            "custom_amount": None,
            "approval_status": "not_sent",
            "client_approved": False,
            "tagged_at": None,
            "tagged_by": None,
            "auto_tagged": False,
            "allocations": []
        }}
    )
    
    # Clear reinvestment tags from actual_repayments
    await db.actual_repayments.update_many(
        {},
        {"$set": {
            "reinvestment_tag": "not_tagged",
            "portfolio_category": None,
            "target_ucc": None,
            "custom_amount": None,
            "approval_status": "not_sent",
            "client_approved": False,
            "tagged_at": None,
            "tagged_by": None
        }}
    )
    
    return {
        "message": "All reinvestment logs cleared successfully",
        "logs_deleted": result.deleted_count
    }


@api_router.delete("/reinvestment/clear-by-date/{date_pattern}")
async def clear_reinvestment_logs_by_date(
    date_pattern: str,
    secret_key: str = None,
    current_user: dict = Depends(get_current_user_optional)
):
    """
    Delete reinvestment_logs entries where expected_date matches the given pattern.
    Use this to remove incorrect entries created from actual repayments instead of expected cashflows.
    
    Examples:
    - /reinvestment/clear-by-date/2026-02-27 - deletes all Feb 27, 2026 entries
    - /reinvestment/clear-by-date/2026-02 - deletes all Feb 2026 entries
    
    Authentication: Either broker login OR secret_key=kinntegra_admin_2024
    """
    # Allow access with secret key OR broker login
    ADMIN_SECRET = "kinntegra_admin_2024"
    
    if secret_key != ADMIN_SECRET:
        if not current_user or current_user.get('role') != 'broker':
            raise HTTPException(status_code=403, detail="Access denied. Use secret_key or broker login.")
    
    # Validate date pattern
    if not date_pattern or len(date_pattern) < 7:
        raise HTTPException(status_code=400, detail="Date pattern must be at least YYYY-MM format")
    
    # Find entries to delete
    entries_to_delete = await db.reinvestment_logs.find({
        "expected_date": {"$regex": f"^{date_pattern}"}
    }, {"_id": 0, "id": 1, "client_name": 1, "bond_name": 1, "expected_date": 1, "net_amount": 1}).to_list(1000)
    
    if not entries_to_delete:
        return {
            "success": True,
            "message": f"No reinvestment_logs found with expected_date matching '{date_pattern}'",
            "deleted_count": 0
        }
    
    # Delete the entries
    result = await db.reinvestment_logs.delete_many({
        "expected_date": {"$regex": f"^{date_pattern}"}
    })
    
    return {
        "success": True,
        "message": f"Deleted {result.deleted_count} reinvestment_logs with expected_date matching '{date_pattern}'",
        "deleted_count": result.deleted_count,
        "deleted_entries": [
            {
                "client": e.get('client_name', 'Unknown'),
                "bond": e.get('bond_name', ''),
                "date": e.get('expected_date', ''),
                "amount": e.get('net_amount', 0)
            }
            for e in entries_to_delete[:20]  # Show first 20
        ]
    }


@api_router.delete("/actual-repayments/clear-duplicates")
async def clear_duplicate_actual_repayments(
    secret_key: str = None,
    current_user: dict = Depends(get_current_user_optional)
):
    """
    Remove duplicate entries from actual_repayments collection.
    Duplicates are identified by same client_id + bond_id + repayment_date + similar amount (±1 Rs).
    
    Keeps entries with source='reprocess_email_logs' or 'email_auto_approval' (from email tracker).
    Removes entries with source='email_holding_cashflow' or other sources.
    
    Authentication: Either broker login OR secret_key=kinntegra_admin_2024
    """
    ADMIN_SECRET = "kinntegra_admin_2024"
    
    if secret_key != ADMIN_SECRET:
        if not current_user or current_user.get('role') != 'broker':
            raise HTTPException(status_code=403, detail="Access denied. Use secret_key or broker login.")
    
    # Get all actual_repayments
    all_repayments = await db.actual_repayments.find({}, {"_id": 0}).to_list(50000)
    
    if not all_repayments:
        return {
            "success": True,
            "message": "No actual_repayments found",
            "total_before": 0,
            "duplicates_removed": 0
        }
    
    # Group by client_id + bond_id + date
    groups = {}
    for ar in all_repayments:
        ar_date = (ar.get('repayment_date', '') or ar.get('date', ''))[:10]
        key = f"{ar.get('client_id')}|{ar.get('bond_id')}|{ar_date}"
        if key not in groups:
            groups[key] = []
        groups[key].append(ar)
    
    # Find duplicates
    duplicates_to_delete = []
    
    # Priority sources (keep these, delete others)
    priority_sources = ['reprocess_email_logs', 'email_auto_approval', 'email_manual_tag', 'historical', 'manual']
    
    for key, entries in groups.items():
        if len(entries) <= 1:
            continue
        
        # Sort by priority (keep priority sources)
        def source_priority(ar):
            source = ar.get('source', '')
            if source in priority_sources:
                return 0
            return 1
        
        sorted_entries = sorted(entries, key=source_priority)
        
        # Keep the first (highest priority), mark others as duplicates
        for ar in sorted_entries[1:]:
            # Check if amount is similar (within ±1 Rs)
            first_amount = sorted_entries[0].get('net_amount', 0) or sorted_entries[0].get('gross_amount', 0) or 0
            ar_amount = ar.get('net_amount', 0) or ar.get('gross_amount', 0) or 0
            
            if abs(first_amount - ar_amount) < 2:
                duplicates_to_delete.append(ar.get('id'))
    
    if not duplicates_to_delete:
        return {
            "success": True,
            "message": "No duplicate actual_repayments found",
            "total_before": len(all_repayments),
            "duplicates_removed": 0
        }
    
    # Delete duplicates
    result = await db.actual_repayments.delete_many({
        "id": {"$in": duplicates_to_delete}
    })
    
    return {
        "success": True,
        "message": f"Removed {result.deleted_count} duplicate actual_repayments",
        "total_before": len(all_repayments),
        "duplicates_removed": result.deleted_count,
        "total_after": len(all_repayments) - result.deleted_count
    }


@api_router.delete("/reinvestment/clear-duplicates")
async def clear_duplicate_reinvestment_entries(current_user: dict = Depends(get_current_user)):
    """
    Clear duplicate reinvestment entries where actual repayments match expected cashflows.
    
    Duplicates are identified as entries where:
    - cashflow_id starts with 'repay_' (actual repayment entry)
    - AND there exists a corresponding expected cashflow within ±5 days and ±1 Rs
    
    This keeps the expected cashflow entries and removes the duplicate actual repayment entries.
    Only brokers can perform this action.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can clear duplicate entries")
    
    # Get all reinvestment logs
    all_logs = await db.reinvestment_logs.find({}, {"_id": 0}).to_list(10000)
    
    # Separate into repay_ entries and regular entries
    repay_logs = [l for l in all_logs if l.get('cashflow_id', '').startswith('repay_')]
    
    if not repay_logs:
        return {
            "message": "No actual repayment entries found in reinvestment logs",
            "duplicates_deleted": 0,
            "total_logs": len(all_logs)
        }
    
    # Get all holding cashflows (expected cashflows)
    holding_cashflows = await db.holding_cashflows.find({}, {"_id": 0}).to_list(50000)
    
    # Build lookup of expected cashflows by trade_id
    expected_by_trade = {}
    for cf in holding_cashflows:
        trade_id = cf.get('trade_id')
        if trade_id:
            if trade_id not in expected_by_trade:
                expected_by_trade[trade_id] = []
            cf_date_str = cf.get('date', '')
            if cf_date_str:
                try:
                    if 'T' in cf_date_str:
                        cf_date = datetime.fromisoformat(cf_date_str.split('T')[0]).date()
                    else:
                        cf_date = datetime.strptime(cf_date_str, "%Y-%m-%d").date()
                    
                    # Calculate expected net amount
                    principal = cf.get('principal_component', 0) or 0
                    interest = cf.get('interest_component', 0) or 0
                    tds = interest * 0.10 if interest else 0
                    net_amount = principal + interest - tds
                    
                    expected_by_trade[trade_id].append({
                        'date': cf_date,
                        'net_amount': net_amount
                    })
                except (ValueError, TypeError):
                    pass
    
    # Get actual repayments to find their trade_ids and details
    actual_repayments = await db.actual_repayments.find({}, {"_id": 0}).to_list(50000)
    repay_details = {r.get('id'): r for r in actual_repayments}
    
    # Find duplicate repay_ entries that match expected cashflows
    duplicates_to_delete = []
    
    for log in repay_logs:
        cashflow_id = log.get('cashflow_id', '')
        repay_id = cashflow_id.replace('repay_', '')
        
        repay_record = repay_details.get(repay_id, {})
        trade_id = repay_record.get('trade_id')
        
        if not trade_id:
            # Can't determine trade, skip
            continue
        
        expected_cfs = expected_by_trade.get(trade_id, [])
        if not expected_cfs:
            # No expected cashflows for this trade, not a duplicate
            continue
        
        # Get repayment date and amount
        repay_date_str = repay_record.get('repayment_date', '') or repay_record.get('date', '')
        repay_amount = repay_record.get('net_amount', 0) or repay_record.get('gross_amount', 0) or repay_record.get('amount', 0) or 0
        
        if not repay_date_str:
            continue
        
        try:
            if 'T' in repay_date_str:
                repay_date = datetime.fromisoformat(repay_date_str.split('T')[0]).date()
            else:
                repay_date = datetime.strptime(repay_date_str, "%Y-%m-%d").date()
        except (ValueError, TypeError):
            continue
        
        # Check if this repayment matches any expected cashflow (within ±5 days AND ±3% amount)
        # Using percentage tolerance to handle gross vs net differences (TDS)
        is_duplicate = False
        for expected in expected_cfs:
            days_diff = abs((repay_date - expected['date']).days)
            expected_amount = expected['net_amount'] or 0
            
            # Calculate percentage difference
            if expected_amount > 0:
                amount_diff_percent = abs(repay_amount - expected_amount) / expected_amount * 100
            else:
                amount_diff_percent = 100 if repay_amount > 0 else 0
            
            # Match if date within 5 days AND amount within 3%
            if days_diff <= 5 and amount_diff_percent <= 3:
                is_duplicate = True
                break
        
        if is_duplicate:
            duplicates_to_delete.append(cashflow_id)
    
    deleted_count = 0
    if duplicates_to_delete:
        # Delete duplicate entries from reinvestment_logs
        result = await db.reinvestment_logs.delete_many({"cashflow_id": {"$in": duplicates_to_delete}})
        deleted_count = result.deleted_count
        
        # Also reset tags in actual_repayments for these duplicates
        repay_ids = [cid.replace('repay_', '') for cid in duplicates_to_delete]
        await db.actual_repayments.update_many(
            {"id": {"$in": repay_ids}},
            {"$set": {
                "reinvestment_tag": "not_tagged",
                "portfolio_category": None,
                "target_ucc": None,
                "custom_amount": None,
                "approval_status": "not_sent",
                "client_approved": False
            }}
        )
    
    return {
        "message": f"Cleared {deleted_count} duplicate reinvestment entries",
        "duplicates_deleted": deleted_count,
        "total_repay_entries_checked": len(repay_logs),
        "total_logs_before": len(all_logs)
    }


@api_router.post("/reinvestment/sync-approved-entries")
async def sync_approved_reinvestment_entries(current_user: dict = Depends(get_current_user)):
    """
    Sync approved reinvestment entries from holding_cashflows to reinvestment_logs.
    
    This fixes cases where:
    - Cashflows were tagged and approved directly in holding_cashflows
    - But corresponding reinvestment_logs entries are missing or have wrong status
    
    Only brokers can perform this action.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can sync entries")
    
    synced_count = 0
    created_count = 0
    updated_count = 0
    errors = []
    
    # Get all holding_cashflows that have been tagged
    tagged_cashflows = await db.holding_cashflows.find(
        {
            "reinvestment_tag": {"$nin": ["not_tagged", None, ""]},
            "$or": [
                {"client_approved": True},
                {"approval_status": {"$in": ["approved", "auto_approved", "client_approved", "broker_approved", "pending"]}}
            ]
        },
        {"_id": 0}
    ).to_list(50000)
    
    for cf in tagged_cashflows:
        cashflow_id = cf.get('id')
        if not cashflow_id:
            continue
        
        # Check if reinvestment_log exists for this cashflow
        existing_log = await db.reinvestment_logs.find_one({"cashflow_id": cashflow_id}, {"_id": 0})
        
        # Get client info
        client = await db.Private_Investor.find_one({"id": cf.get('client_id')}, {"_id": 0, "name": 1})
        client_name = client.get('name', '') if client else ''
        
        if existing_log:
            # Update existing log with correct values from cashflow
            update_needed = False
            update_data = {}
            
            # Check if tag matches
            if existing_log.get('reinvestment_tag') != cf.get('reinvestment_tag'):
                update_data['reinvestment_tag'] = cf.get('reinvestment_tag')
                update_needed = True
            
            # Check if approval status matches
            if existing_log.get('approval_status') != cf.get('approval_status'):
                update_data['approval_status'] = cf.get('approval_status')
                update_needed = True
            
            # Check if client_approved matches
            if existing_log.get('client_approved') != cf.get('client_approved'):
                update_data['client_approved'] = cf.get('client_approved')
                update_needed = True
            
            # Add other fields that might be missing
            if not existing_log.get('portfolio_category') and cf.get('portfolio_category'):
                update_data['portfolio_category'] = cf.get('portfolio_category')
                update_needed = True
            
            if not existing_log.get('target_ucc') and cf.get('target_ucc'):
                update_data['target_ucc'] = cf.get('target_ucc')
                update_needed = True
            
            if update_needed:
                try:
                    update_data['synced_at'] = datetime.now(timezone.utc).isoformat()
                    await db.reinvestment_logs.update_one(
                        {"cashflow_id": cashflow_id},
                        {"$set": update_data}
                    )
                    updated_count += 1
                except Exception as e:
                    errors.append({"cashflow_id": cashflow_id, "action": "update", "error": str(e)})
        else:
            # Create new log entry
            try:
                # Calculate amounts
                net_amount = cf.get('net_amount', 0) or 0
                round_down_amount = (net_amount // 100) * 100
                residual_amount = net_amount - round_down_amount
                
                log_entry = {
                    "id": str(uuid.uuid4()),
                    "type": "reinvestment_tag_sync",
                    "cashflow_id": cashflow_id,
                    "client_id": cf.get('client_id'),
                    "client_name": client_name,
                    "bond_id": cf.get('bond_id'),
                    "bond_name": cf.get('bond_name', ''),
                    "expected_date": cf.get('date'),
                    "net_amount": net_amount,
                    "amount": round_down_amount,
                    "residual_amount": round(residual_amount, 2),
                    "reinvestment_tag": cf.get('reinvestment_tag'),
                    "portfolio_category": cf.get('portfolio_category'),
                    "target_ucc": cf.get('target_ucc'),
                    "tagged_by": cf.get('tagged_by'),
                    "tagged_at": cf.get('tagged_at'),
                    "is_past_date": cf.get('is_past_date', False),
                    "approval_status": cf.get('approval_status', 'pending'),
                    "client_approved": cf.get('client_approved', False),
                    "approved_at": cf.get('approved_at'),
                    "auto_approved": cf.get('auto_approved', False),
                    "synced_from_cashflow": True,
                    "synced_at": datetime.now(timezone.utc).isoformat(),
                    "created_at": cf.get('tagged_at') or datetime.now(timezone.utc).isoformat()
                }
                await db.reinvestment_logs.insert_one(log_entry)
                created_count += 1
            except Exception as e:
                errors.append({"cashflow_id": cashflow_id, "action": "create", "error": str(e)})
        
        synced_count += 1
    
    return {
        "message": f"Synced {synced_count} entries ({created_count} created, {updated_count} updated)",
        "synced_count": synced_count,
        "created_count": created_count,
        "updated_count": updated_count,
        "total_tagged_cashflows": len(tagged_cashflows),
        "errors": errors if errors else None
    }


@api_router.get("/reinvestment/kinntegra-api-requests")
async def get_kinntegra_api_requests(current_user: dict = Depends(get_current_user)):
    """Get all kinntegra API requests/submissions to see what was sent to kinntegra.co.in"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can access this endpoint")
    
    # Get from kinntegra_api_requests
    api_requests = await db.kinntegra_api_requests.find({}, {"_id": 0}).sort("created_at", -1).to_list(500)
    
    # Get from kinntegra_api_logs  
    api_logs = await db.kinntegra_api_logs.find({}, {"_id": 0}).sort("created_at", -1).to_list(500)
    
    # Get from kinntegraa_submissions
    submissions = await db.kinntegraa_submissions.find({}, {"_id": 0}).sort("created_at", -1).to_list(500)
    
    # Get from reinvestment_approvals (client approvals)
    reinvestment_approvals = await db.reinvestment_approvals.find({}, {"_id": 0}).sort("created_at", -1).to_list(500)
    
    # Get from reinvestment_submissions (the main submission tracking collection)
    reinvestment_submissions = await db.reinvestment_submissions.find({}, {"_id": 0}).sort("created_at", -1).to_list(500)
    
    # Get from reinvestment_logs
    reinvestment_logs = await db.reinvestment_logs.find({}, {"_id": 0}).sort("created_at", -1).to_list(500)
    
    return {
        "kinntegra_api_requests": api_requests,
        "kinntegra_api_logs": api_logs,
        "kinntegraa_submissions": submissions,
        "reinvestment_approvals": reinvestment_approvals,
        "reinvestment_submissions": reinvestment_submissions,
        "reinvestment_logs": reinvestment_logs
    }


@api_router.post("/reinvestment/sync-from-approvals")
async def sync_from_reinvestment_approvals(current_user: dict = Depends(get_current_user)):
    """
    Sync entries from reinvestment_approvals collection back to holding_cashflows.
    
    This fixes cases where client approved reinvestments but the holding_cashflows
    wasn't updated with the approval status.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can sync entries")
    
    synced_count = 0
    errors = []
    
    # Get all approved entries from reinvestment_approvals
    approved_entries = await db.reinvestment_approvals.find(
        {
            "$or": [
                {"client_approval_status": "approved"},
                {"broker_approval_status": "approved"},
                {"status": "approved"},
                {"status": "submitted"}
            ]
        },
        {"_id": 0}
    ).to_list(10000)
    
    for entry in approved_entries:
        cashflow_id = entry.get('cashflow_id')
        if not cashflow_id:
            continue
        
        try:
            # Update holding_cashflows with approval info
            result = await db.holding_cashflows.update_one(
                {"id": cashflow_id},
                {"$set": {
                    "reinvestment_tag": entry.get('reinvestment_tag', entry.get('tag', 'both')),
                    "client_approved": True,
                    "approval_status": "submitted",
                    "kinntegra_api_submitted": True,
                    "target_ucc": entry.get('target_ucc'),
                    "portfolio_category": entry.get('portfolio_category'),
                    "approved_at": entry.get('client_approved_at') or entry.get('approved_at'),
                    "synced_from_approvals": True,
                    "synced_at": datetime.now(timezone.utc).isoformat()
                }}
            )
            
            if result.modified_count > 0:
                synced_count += 1
                
                # Also create reinvestment_log entry
                cf = await db.holding_cashflows.find_one({"id": cashflow_id}, {"_id": 0})
                if cf:
                    client = await db.Private_Investor.find_one({"id": cf.get('client_id')}, {"_id": 0, "name": 1})
                    client_name = client.get('name', '') if client else entry.get('client_name', '')
                    
                    net_amount = cf.get('net_amount', 0) or 0
                    round_down = int(net_amount // 100) * 100
                    
                    await db.reinvestment_logs.update_one(
                        {"cashflow_id": cashflow_id},
                        {"$set": {
                            "id": str(uuid.uuid4()),
                            "type": "synced_from_approvals",
                            "cashflow_id": cashflow_id,
                            "client_id": cf.get('client_id'),
                            "client_name": client_name,
                            "bond_id": cf.get('bond_id'),
                            "bond_name": cf.get('bond_name', ''),
                            "expected_date": cf.get('date'),
                            "net_amount": net_amount,
                            "amount": round_down,
                            "reinvestment_tag": entry.get('reinvestment_tag', entry.get('tag', 'both')),
                            "approval_status": "submitted",
                            "client_approved": True,
                            "kinntegra_submitted": True,
                            "created_at": datetime.now(timezone.utc).isoformat()
                        }},
                        upsert=True
                    )
        except Exception as e:
            errors.append({"cashflow_id": cashflow_id, "error": str(e)})
    
    return {
        "message": f"Synced {synced_count} entries from reinvestment_approvals",
        "synced_count": synced_count,
        "total_approved_entries": len(approved_entries),
        "errors": errors if errors else None
    }


@api_router.post("/reinvestment/sync-from-kinntegra-requests")
async def sync_from_kinntegra_requests(current_user: dict = Depends(get_current_user)):
    """
    SAFE sync from kinntegra_api_logs to holding_cashflows/reinvestment_logs.
    
    CRITICAL: Only updates entries that have an EXACT cashflow_id match.
    Never updates entries based on client name, date, or amount alone.
    
    The kinntegra_api_logs collection is the SOURCE OF TRUTH for what was submitted.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can sync entries")
    
    synced_count = 0
    skipped_no_cashflow_id = 0
    skipped_not_found = 0
    already_synced = 0
    errors = []
    synced_details = []
    
    # Get all successful kinntegra API logs - ONLY success status
    api_logs = await db.kinntegra_api_logs.find(
        {"status": "success"},
        {"_id": 0}
    ).to_list(10000)
    
    logger.info(f"SAFE SYNC: Found {len(api_logs)} successful API logs to process")
    
    for log in api_logs:
        # CRITICAL: Only process if we have an explicit cashflow_id
        cashflow_id = log.get('cashflow_id')
        
        if not cashflow_id:
            skipped_no_cashflow_id += 1
            logger.warning(f"SAFE SYNC: Skipping API log without cashflow_id: {log.get('id', 'unknown')}")
            continue
        
        try:
            # Find the exact cashflow by ID
            existing_cf = await db.holding_cashflows.find_one({"id": cashflow_id}, {"_id": 0})
            
            if not existing_cf:
                skipped_not_found += 1
                logger.warning(f"SAFE SYNC: Cashflow {cashflow_id} not found in holding_cashflows")
                continue
            
            # Check if already synced to avoid unnecessary updates
            if existing_cf.get('kinntegra_api_submitted') and existing_cf.get('approval_status') == 'submitted':
                already_synced += 1
                continue
            
            # Extract portfolio/UCC from the API payload if available
            payload = log.get('payload', {})
            investment_data = payload.get('InvestmentData', [])
            correct_portfolio = None
            correct_ucc = None
            
            if investment_data and isinstance(investment_data, list) and len(investment_data) > 0:
                inv = investment_data[0]
                correct_portfolio = inv.get('PortfolioName') or inv.get('portfolio')
                correct_ucc = inv.get('UCC') or inv.get('ucc')
            
            # Build update - only set what we know is true
            cf_update = {
                "kinntegra_api_submitted": True,
                "kinntegra_api_status": "success",
                "kinntegra_submitted_at": log.get('created_at'),
                "client_approved": True,
                "approval_status": "submitted",
                "synced_from_api_log": True,
                "synced_at": datetime.now(timezone.utc).isoformat()
            }
            
            if correct_portfolio:
                cf_update["portfolio_category"] = correct_portfolio
            if correct_ucc:
                cf_update["target_ucc"] = correct_ucc
            
            # Update holding_cashflows
            await db.holding_cashflows.update_one(
                {"id": cashflow_id},
                {"$set": cf_update}
            )
            
            # Also update corresponding reinvestment_logs
            log_update = {
                "kinntegra_api_submitted": True,
                "approval_status": "submitted",
                "client_approved": True,
                "synced_from_api_log": True
            }
            if correct_portfolio:
                log_update["portfolio"] = correct_portfolio
                log_update["portfolio_category"] = correct_portfolio
            if correct_ucc:
                log_update["ucc"] = correct_ucc
                log_update["target_ucc"] = correct_ucc
            
            await db.reinvestment_logs.update_many(
                {"cashflow_id": cashflow_id},
                {"$set": log_update}
            )
            
            synced_count += 1
            synced_details.append({
                "cashflow_id": cashflow_id,
                "client_id": existing_cf.get('client_id'),
                "bond_name": existing_cf.get('bond_name'),
                "portfolio": correct_portfolio,
                "ucc": correct_ucc
            })
            
        except Exception as e:
            errors.append({"cashflow_id": cashflow_id, "error": str(e)})
            logger.error(f"SAFE SYNC: Error processing cashflow {cashflow_id}: {e}")
    
    return {
        "message": f"SAFE SYNC completed: {synced_count} entries synced",
        "synced_count": synced_count,
        "skipped_no_cashflow_id": skipped_no_cashflow_id,
        "skipped_not_found": skipped_not_found,
        "already_synced": already_synced,
        "api_logs_checked": len(api_logs),
        "synced_details": synced_details[:20],
        "errors": errors if errors else None
    }


@api_router.post("/reinvestment/mark-as-submitted")
async def mark_entries_as_submitted(
    cashflow_ids: List[str] = Body(...),
    reinvestment_tag: str = Body("both"),
    current_user: dict = Depends(get_current_user)
):
    """
    Manually mark cashflow entries as submitted to Kinntegra.
    
    Use this to sync entries that were submitted to kinntegra.co.in externally
    but weren't tracked in kinntegraa.club.
    
    Only brokers can perform this action.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can mark entries as submitted")
    
    updated_count = 0
    errors = []
    
    for cf_id in cashflow_ids:
        try:
            # Update holding_cashflows
            result = await db.holding_cashflows.update_one(
                {"id": cf_id},
                {"$set": {
                    "reinvestment_tag": reinvestment_tag,
                    "kinntegra_api_submitted": True,
                    "kinntegra_api_status": "submitted",
                    "kinntegra_submitted_at": datetime.now(timezone.utc).isoformat(),
                    "client_approved": True,
                    "approval_status": "submitted",
                    "manually_marked_submitted": True,
                    "marked_by": current_user['id'],
                    "marked_at": datetime.now(timezone.utc).isoformat()
                }}
            )
            
            if result.modified_count > 0:
                updated_count += 1
                
                # Also create/update reinvestment_log
                cf = await db.holding_cashflows.find_one({"id": cf_id}, {"_id": 0})
                if cf:
                    client = await db.Private_Investor.find_one({"id": cf.get('client_id')}, {"_id": 0, "name": 1})
                    client_name = client.get('name', '') if client else ''
                    
                    net_amount = cf.get('net_amount', 0) or 0
                    round_down = int(net_amount // 100) * 100
                    
                    log_entry = {
                        "id": str(uuid.uuid4()),
                        "type": "manual_kinntegra_submission",
                        "cashflow_id": cf_id,
                        "client_id": cf.get('client_id'),
                        "client_name": client_name,
                        "bond_id": cf.get('bond_id'),
                        "bond_name": cf.get('bond_name', ''),
                        "expected_date": cf.get('date'),
                        "net_amount": net_amount,
                        "amount": round_down,
                        "reinvestment_tag": reinvestment_tag,
                        "approval_status": "submitted",
                        "client_approved": True,
                        "kinntegra_submitted": True,
                        "manually_marked": True,
                        "marked_by": current_user['id'],
                        "created_at": datetime.now(timezone.utc).isoformat()
                    }
                    
                    # Upsert log
                    await db.reinvestment_logs.update_one(
                        {"cashflow_id": cf_id},
                        {"$set": log_entry},
                        upsert=True
                    )
        except Exception as e:
            errors.append({"cashflow_id": cf_id, "error": str(e)})
    
    return {
        "message": f"Marked {updated_count} entries as submitted to Kinntegra",
        "updated_count": updated_count,
        "total_requested": len(cashflow_ids),
        "errors": errors if errors else None
    }


@api_router.post("/reinvestment/reset-kinntegra-flag")
async def reset_kinntegra_flag(
    cashflow_ids: List[str] = Body(...),
    current_user: dict = Depends(get_current_user)
):
    """
    Reset the kinntegra_api_submitted flag for cashflows that have inconsistent data.
    
    Use this when:
    - kinntegra_api_submitted=True but reinvestment_tag=not_tagged
    - Or when entry needs to be re-tagged
    
    Only brokers can perform this action.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can reset this flag")
    
    reset_count = 0
    errors = []
    
    for cf_id in cashflow_ids:
        try:
            result = await db.holding_cashflows.update_one(
                {"id": cf_id},
                {"$set": {
                    "kinntegra_api_submitted": False,
                    "kinntegra_api_status": None,
                    "repayment_processed": False,
                    "flag_reset_at": datetime.now(timezone.utc).isoformat(),
                    "flag_reset_by": current_user['id']
                }}
            )
            if result.modified_count > 0:
                reset_count += 1
        except Exception as e:
            errors.append({"cashflow_id": cf_id, "error": str(e)})
    
    return {
        "message": f"Reset kinntegra flag for {reset_count} cashflows",
        "reset_count": reset_count,
        "total_requested": len(cashflow_ids),
        "errors": errors if errors else None
    }


class RepairEntryRequest(BaseModel):
    cashflow_id: str
    portfolio_category: str
    approval_status: str
    reason: str

@api_router.get("/reinvestment/diagnose-client/{client_pan}")
async def diagnose_client_data(client_pan: str, current_user: dict = Depends(get_current_user)):
    """
    DIAGNOSTIC ENDPOINT (READ-ONLY): Shows the current data state for a client
    without making any changes. Use this to verify before applying fixes.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can diagnose")
    
    # Find client
    client = await db.Private_Investor.find_one({"pan_number": client_pan}, {"_id": 0})
    if not client:
        return {"error": f"Client with PAN {client_pan} not found"}
    
    client_id = client['id']
    
    # Get API logs (source of truth)
    api_logs = await db.kinntegra_api_logs.find({
        "client_id": client_id,
        "status": "success"
    }, {"_id": 0, "id": 1, "cashflow_id": 1, "created_at": 1}).to_list(100)
    
    api_log_cashflow_ids = set()
    for log in api_logs:
        if log.get('cashflow_id'):
            api_log_cashflow_ids.add(log.get('cashflow_id'))
    
    # Get holding_cashflows
    cashflows = await db.holding_cashflows.find({
        "client_id": client_id
    }, {"_id": 0}).to_list(500)
    
    # Categorize cashflows
    correctly_submitted = []
    incorrectly_submitted = []
    pending_items = []
    untagged_items = []
    
    for cf in cashflows:
        cf_summary = {
            "id": cf.get('id'),
            "bond_name": cf.get('bond_name'),
            "date": cf.get('date'),
            "net_amount": cf.get('net_amount'),
            "portfolio": cf.get('portfolio_category'),
            "ucc": cf.get('target_ucc'),
            "approval_status": cf.get('approval_status'),
            "kinntegra_api_submitted": cf.get('kinntegra_api_submitted'),
            "client_approved": cf.get('client_approved'),
            "reinvestment_tag": cf.get('reinvestment_tag'),
            "in_api_logs": cf.get('id') in api_log_cashflow_ids
        }
        
        if cf.get('reinvestment_tag') in [None, '', 'not_tagged']:
            untagged_items.append(cf_summary)
        elif cf.get('id') in api_log_cashflow_ids:
            correctly_submitted.append(cf_summary)
        elif cf.get('kinntegra_api_submitted') or cf.get('approval_status') == 'submitted':
            # Marked as submitted but NOT in API logs = INCORRECT
            incorrectly_submitted.append(cf_summary)
        else:
            pending_items.append(cf_summary)
    
    return {
        "client": {
            "id": client_id,
            "name": client.get('name'),
            "pan": client_pan
        },
        "api_logs_count": len(api_logs),
        "api_logs_with_cashflow_id": len(api_log_cashflow_ids),
        "summary": {
            "correctly_submitted": len(correctly_submitted),
            "INCORRECTLY_SUBMITTED": len(incorrectly_submitted),
            "pending": len(pending_items),
            "untagged": len(untagged_items)
        },
        "correctly_submitted": correctly_submitted,
        "INCORRECTLY_SUBMITTED_ENTRIES": incorrectly_submitted,
        "pending_entries": pending_items[:20],
        "untagged_entries": untagged_items[:20]
    }




@api_router.post("/reinvestment/manual-status-fix")
async def manual_status_fix(
    cashflow_id: str,
    new_status: str,
    portfolio: str = None,
    ucc: str = None,
    kinntegra_submitted: bool = None,
    current_user: dict = Depends(get_current_user)
):
    """
    Manually fix a specific entry's status, portfolio, UCC, and submission status.
    Query params: cashflow_id, new_status, portfolio (optional), ucc (optional), kinntegra_submitted (optional)
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can fix entries")
    
    # Validate status
    valid_statuses = ['pending', 'approved', 'rejected', 'submitted', 'approved_no_reinvest', 'completed']
    if new_status not in valid_statuses:
        raise HTTPException(status_code=400, detail=f"Invalid status. Must be one of: {valid_statuses}")
    
    # Find the cashflow
    cf = await db.holding_cashflows.find_one({"id": cashflow_id}, {"_id": 0})
    if not cf:
        raise HTTPException(status_code=404, detail="Cashflow not found")
    
    # Build update
    cf_update = {"approval_status": new_status}
    if portfolio is not None:
        cf_update["portfolio_category"] = portfolio
    if ucc is not None:
        cf_update["target_ucc"] = ucc
    if kinntegra_submitted is not None:
        cf_update["kinntegra_api_submitted"] = kinntegra_submitted
    
    cf_update["manual_fix_at"] = datetime.now(timezone.utc).isoformat()
    cf_update["manual_fix_by"] = current_user['id']
    
    # Update cashflow
    await db.holding_cashflows.update_one({"id": cashflow_id}, {"$set": cf_update})
    
    # Update corresponding reinvestment_log
    log_update = {"approval_status": new_status}
    if portfolio is not None:
        log_update["portfolio"] = portfolio
        log_update["portfolio_category"] = portfolio
    if ucc is not None:
        log_update["ucc"] = ucc
        log_update["target_ucc"] = ucc
    if kinntegra_submitted is not None:
        log_update["kinntegra_api_submitted"] = kinntegra_submitted
    
    log_result = await db.reinvestment_logs.update_many(
        {"cashflow_id": cashflow_id},
        {"$set": log_update}
    )
    
    return {
        "message": f"Fixed entry {cashflow_id}",
        "new_status": new_status,
        "portfolio": portfolio,
        "ucc": ucc,
        "kinntegra_submitted": kinntegra_submitted,
        "logs_updated": log_result.modified_count
    }





@api_router.get("/actual-repayments/diagnose-duplicates")
async def diagnose_duplicate_repayments(
    bond_id: str = None,
    client_id: str = None,
    current_user: dict = Depends(get_current_user)
):
    """
    Diagnose potential duplicate actual_repayments without deleting.
    Returns detailed info about duplicates found.
    Use bond_id and client_id to filter to specific records.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can diagnose duplicates")
    
    # Build query filter
    query = {}
    if bond_id:
        query['bond_id'] = bond_id
    if client_id:
        query['client_id'] = client_id
    
    # Fetch repayments
    all_repayments = await db.actual_repayments.find(query, {"_id": 0}).to_list(10000)
    
    def amounts_similar(amount1, amount2, tolerance_percent=5.0):
        if amount1 == 0 and amount2 == 0:
            return True
        if amount1 == 0 or amount2 == 0:
            return abs(amount1 - amount2) < 100
        diff_percent = abs(amount1 - amount2) / max(abs(amount1), abs(amount2)) * 100
        return diff_percent <= tolerance_percent
    
    # Group by (client_id, bond_id, date)
    from collections import defaultdict
    groups = defaultdict(list)
    
    for ar in all_repayments:
        ar_date = (ar.get('repayment_date', '') or ar.get('date', ''))[:10]
        key = (ar.get('client_id', ''), ar.get('bond_id', ''), ar_date)
        groups[key].append(ar)
    
    # Find duplicates
    duplicates_info = []
    
    for (cid, bid, date), repayments in groups.items():
        if len(repayments) <= 1:
            continue
        
        # Group by similar amounts
        amount_groups = []
        for r in repayments:
            amount = r.get('gross_amount', 0) or r.get('net_amount', 0) or 0
            found = False
            for group in amount_groups:
                if amounts_similar(amount, group[0]['amount']):
                    group.append({'amount': amount, 'entry': r})
                    found = True
                    break
            if not found:
                amount_groups.append([{'amount': amount, 'entry': r}])
        
        # Report groups with more than 1 entry (duplicates)
        for group in amount_groups:
            if len(group) > 1:
                duplicates_info.append({
                    'client_id': cid,
                    'bond_id': bid,
                    'date': date,
                    'duplicate_count': len(group),
                    'total_amount_if_summed': sum(g['amount'] for g in group),
                    'expected_amount': group[0]['amount'],
                    'entries': [
                        {
                            'id': g['entry'].get('id', 'N/A'),
                            'amount': g['amount'],
                            'source': g['entry'].get('source', 'N/A'),
                            'trade_id': g['entry'].get('trade_id', 'N/A'),
                            'investment_date': g['entry'].get('investment_date', 'N/A')
                        }
                        for g in group
                    ]
                })
    
    # Get bond names for better readability
    bond_ids = list(set(d['bond_id'] for d in duplicates_info))
    bonds = await db.Ncd_Master.find({"id": {"$in": bond_ids}}, {"_id": 0, "id": 1, "name": 1}).to_list(100)
    bond_names = {b['id']: b['name'] for b in bonds}
    
    for d in duplicates_info:
        d['bond_name'] = bond_names.get(d['bond_id'], 'Unknown')
    
    return {
        "total_repayments_checked": len(all_repayments),
        "duplicate_groups_found": len(duplicates_info),
        "duplicates": duplicates_info
    }


@api_router.put("/reinvestment/tag/{cashflow_id}")
async def update_reinvestment_tag(cashflow_id: str, update: ReinvestmentTagUpdate, current_user: dict = Depends(get_current_user)):
    """Update reinvestment tag for a cashflow. Supports split allocations across multiple UCCs/portfolios."""
    
    # Check if this is a prepayment entry (starts with 'prepay_')
    is_prepayment_entry = cashflow_id.startswith('prepay_')
    
    if is_prepayment_entry:
        # Handle prepayment tagging - update actual_repayments collection
        actual_repayment_id = cashflow_id.replace('prepay_', '')
        prepayment = await db.actual_repayments.find_one({"id": actual_repayment_id})
        if not prepayment:
            raise HTTPException(status_code=404, detail="Prepayment not found")
        
        # Get client for validation
        client = await db.Private_Investor.find_one({"id": prepayment['client_id']})
        if not client:
            raise HTTPException(status_code=404, detail="Client not found")
        
        # Verify access
        if current_user['role'] == 'client':
            if client.get('user_id') != current_user['id']:
                raise HTTPException(status_code=403, detail="Access denied")
        elif current_user['role'] != 'broker':
            if client.get('linked_subbroker_id') != current_user['id']:
                raise HTTPException(status_code=403, detail="Access denied")
        
        # Update prepayment with reinvestment tag data
        update_data = {
            "reinvestment_tag": update.reinvestment_tag,
            "portfolio_category": update.portfolio_category,
            "target_ucc": update.target_ucc,
            "custom_amount": update.custom_amount,
            "tagged_at": datetime.now(timezone.utc).isoformat(),
            "tagged_by": current_user.get('id')
        }
        
        # Check if past date - auto approve
        today = datetime.now(timezone.utc).date()
        rep_date = datetime.fromisoformat(prepayment.get('repayment_date', '').split('T')[0]).date()
        is_past_date = rep_date < today
        
        if is_past_date:
            update_data["approval_status"] = "auto_approved"
            update_data["client_approved"] = True
            update_data["auto_approved_at"] = datetime.now(timezone.utc).isoformat()
        else:
            update_data["approval_status"] = "pending"
        
        await db.actual_repayments.update_one(
            {"id": actual_repayment_id},
            {"$set": update_data}
        )
        
        return {
            "message": "Prepayment reinvestment tag updated",
            "cashflow_id": cashflow_id,
            "auto_approved": is_past_date
        }
    
    # Regular cashflow handling below
    # Find the cashflow
    cashflow = await db.holding_cashflows.find_one({"id": cashflow_id})
    if not cashflow:
        # Try to find by alternative fields
        cashflow = await db.holding_cashflows.find_one({"cashflow_id": cashflow_id})
        if not cashflow:
            # Check if this is an actual_repayment ID (format: actual_repay_{id})
            if cashflow_id.startswith('actual_repay_') or cashflow_id.startswith('prepay_'):
                # This is from actual_repayments - create a holding_cashflow entry
                base_id = cashflow_id.replace('actual_repay_', '').replace('prepay_', '')
                actual_repay = await db.actual_repayments.find_one({"id": base_id})
                if actual_repay:
                    # Create a holding_cashflow entry from actual_repayment
                    client_id = actual_repay.get('client_id')
                    if not client_id:
                        # Try to get from trade
                        trade = await db.Ncd_Investment_Details.find_one({"id": actual_repay.get('trade_id')}, {"_id": 0, "client_id": 1})
                        client_id = trade.get('client_id') if trade else None
                    
                    # Get bond_name - lookup if not present
                    bond_name = actual_repay.get('bond_name', '')
                    if not bond_name and actual_repay.get('bond_id'):
                        bond = await db.Ncd_Master.find_one({"id": actual_repay.get('bond_id')}, {"_id": 0, "name": 1, "issuer": 1})
                        if bond:
                            bond_name = bond.get('name') or bond.get('issuer') or ''
                    
                    # IMPORTANT: Try to find matching expected cashflow to use its date
                    # Only use actual repayment date if no expected cashflow found (prepayment)
                    actual_date = actual_repay.get('repayment_date') or actual_repay.get('date')
                    expected_date = actual_date  # Default to actual date
                    is_prepayment = actual_repay.get('is_prepayment', False)
                    
                    if actual_date and not is_prepayment:
                        # Try to find a matching expected cashflow within ±3 working days
                        try:
                            actual_dt = datetime.fromisoformat(actual_date.split('T')[0])
                            # Search for expected cashflow on same bond/client within date range
                            date_range_start = (actual_dt - timedelta(days=5)).strftime('%Y-%m-%d')
                            date_range_end = (actual_dt + timedelta(days=5)).strftime('%Y-%m-%d')
                            
                            matching_expected = await db.holding_cashflows.find_one({
                                "client_id": client_id,
                                "bond_id": actual_repay.get('bond_id'),
                                "date": {"$gte": date_range_start, "$lte": date_range_end},
                                "source": {"$ne": "actual_repayment"}  # Not created from actual repayment
                            }, {"_id": 0, "date": 1})
                            
                            if matching_expected:
                                expected_date = matching_expected.get('date', actual_date)
                                logger.info(f"Using expected date {expected_date} instead of actual date {actual_date}")
                        except Exception as e:
                            logger.warning(f"Error finding expected cashflow for actual_repayment: {e}")
                    
                    new_cashflow = {
                        "id": cashflow_id,
                        "trade_id": actual_repay.get('trade_id'),
                        "bond_id": actual_repay.get('bond_id'),
                        "bond_name": bond_name,
                        "client_id": client_id,
                        "date": expected_date,  # Use expected date, not actual repayment date
                        "actual_repayment_date": actual_date,  # Store actual date for reference
                        "principal": actual_repay.get('principal', 0),
                        "interest": actual_repay.get('interest', 0),
                        "tds": actual_repay.get('tds', 0),
                        "net_amount": actual_repay.get('net_amount', 0),
                        "type": "actual_repayment",
                        "source": "actual_repayment",
                        "actual_repayment_id": base_id,
                        "is_prepayment": is_prepayment,
                        "created_from_repayment": True,
                        "created_at": datetime.now(timezone.utc).isoformat()
                    }
                    await db.holding_cashflows.insert_one(new_cashflow)
                    cashflow = new_cashflow
                    logger.info(f"Created holding_cashflow from actual_repayment: {cashflow_id}")
            
            if not cashflow:
                # Final fallback: this id may belong to an
                # Ncd_Expected_Repayments row (broker-direct trades created
                # before holding_cashflows generation was wired up). Lazily
                # materialise a `holding_cashflows` row so the tag can land.
                expected = await db.Ncd_Expected_Repayments.find_one({"id": cashflow_id})
                if expected:
                    new_cashflow = {
                        "id": expected.get("id"),
                        "trade_id": expected.get("trade_id"),
                        "bond_id": expected.get("bond_id"),
                        "bond_name": expected.get("bond_name"),
                        "client_id": expected.get("client_id"),
                        "date": expected.get("expected_date"),
                        "principal": expected.get("principal_component", 0) or 0,
                        "interest": expected.get("interest_component", 0) or 0,
                        "principal_component": expected.get("principal_component", 0) or 0,
                        "interest_component": expected.get("interest_component", 0) or 0,
                        "tds_amount": expected.get("tds_amount", 0) or 0,
                        "gross_amount": expected.get("gross_amount", 0) or 0,
                        "net_amount": expected.get("net_amount", 0) or 0,
                        "type": expected.get("type", "interest"),
                        "is_repaid": expected.get("is_repaid", False),
                        "reinvestment_tag": "not_tagged",
                        "source": "expected_repayment_backfill",
                        "created_from_expected": True,
                        "created_at": datetime.now(timezone.utc).isoformat(),
                    }
                    await db.holding_cashflows.insert_one(new_cashflow)
                    cashflow = new_cashflow
                    logger.info(
                        f"[update_reinvestment_tag] backfilled holding_cashflow from expected_repayment {cashflow_id}"
                    )

            if not cashflow:
                logger.error(f"Cashflow not found: {cashflow_id}")
                raise HTTPException(status_code=404, detail=f"Cashflow not found: {cashflow_id}")
    
    # Verify access
    client = await db.Private_Investor.find_one({"id": cashflow['client_id']})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    
    # Check if repayment has already happened - cannot modify after repayment
    if cashflow.get('repayment_processed') or cashflow.get('kinntegra_api_submitted'):
        raise HTTPException(status_code=400, detail="Cannot modify tags after repayment has been processed or API submitted")
    
    # Track if this is a modification of an already-approved tag (needs re-approval)
    was_client_approved = cashflow.get('client_approved', False)
    needs_reapproval = was_client_approved and current_user['role'] in ['broker', 'sub_broker']
    
    if current_user['role'] == 'client':
        # Client can only modify their own cashflows
        if client.get('user_id') != current_user['id']:
            raise HTTPException(status_code=403, detail="Access denied")
    elif current_user['role'] != 'broker':
        if client.get('linked_subbroker_id') != current_user['id']:
            raise HTTPException(status_code=403, detail="Access denied")
    
    # Get client's valid UCCs for validation
    client_ucc_list = client.get('ucc_list', [])
    if not client_ucc_list and client.get('ucc'):
        client_ucc_list = [client.get('ucc')]
    client_ucc_list_upper = [u.upper() for u in client_ucc_list]
    
    # Check if this is a past date or future date
    today = datetime.now(timezone.utc).date()
    cf_date = datetime.fromisoformat(cashflow['date']).date()
    is_past_date = cf_date < today
    
    # =====================================================
    # HANDLE SPLIT ALLOCATIONS (ucc_allocations array)
    # =====================================================
    if update.ucc_allocations and len(update.ucc_allocations) > 0:
        # Validate all allocations
        total_allocated = 0
        validated_allocations = []
        
        for alloc in update.ucc_allocations:
            # Skip UCC validation for:
            # 1. Small amounts (< 1000) - these are remainders
            # 2. "None" portfolio - these won't be invested
            is_small_amount = alloc.amount < 1000
            is_none_portfolio = alloc.portfolio and alloc.portfolio.lower() == 'none'
            skip_ucc_validation = is_small_amount or is_none_portfolio
            
            if skip_ucc_validation:
                # Force portfolio to 'none' for small amounts
                if is_small_amount and alloc.portfolio and alloc.portfolio.lower() != 'none':
                    raise HTTPException(
                        status_code=400,
                        detail=f"Amount < ₹1,000 must use 'none' portfolio (got '{alloc.portfolio}')"
                    )
                # Set empty UCC for small amounts or none portfolio (not needed)
                alloc_ucc = alloc.ucc if alloc.ucc else ''
            else:
                # Validate UCC belongs to client for regular investment amounts
                if not alloc.ucc:
                    raise HTTPException(
                        status_code=400,
                        detail="UCC is required for investment allocations"
                    )
                if alloc.ucc.upper() not in client_ucc_list_upper:
                    raise HTTPException(
                        status_code=400, 
                        detail=f"UCC '{alloc.ucc}' does not belong to this client"
                    )
                alloc_ucc = alloc.ucc
            
            # Validate amount
            if alloc.amount <= 0:
                raise HTTPException(
                    status_code=400,
                    detail="All allocation amounts must be greater than 0"
                )
            
            # Validate portfolio - must not be empty
            if not alloc.portfolio:
                raise HTTPException(
                    status_code=400,
                    detail="Portfolio is required for all allocations"
                )
            
            # Validate portfolio based on amount rules (only for actual investments, not "none" portfolio)
            if not skip_ucc_validation:
                if alloc.portfolio == 'bonds' and alloc.amount < 1000000:
                    raise HTTPException(
                        status_code=400,
                        detail=f"Bonds portfolio requires amount >= ₹10,00,000 (got ₹{alloc.amount:,.0f})"
                    )
                if alloc.portfolio == 'real_estate' and alloc.amount < 2500000:
                    raise HTTPException(
                        status_code=400,
                        detail=f"Real Estate portfolio requires amount >= ₹25,00,000 (got ₹{alloc.amount:,.0f})"
                    )
            
            total_allocated += alloc.amount
            # Calculate default investment date as T+1 from cashflow date if not provided
            default_investment_date = None
            cf_date_obj = None
            if cashflow.get('date'):
                try:
                    cf_date_obj = datetime.strptime(cashflow['date'][:10], '%Y-%m-%d')
                    default_investment_date = (cf_date_obj + timedelta(days=1)).strftime('%Y-%m-%d')
                except:
                    default_investment_date = None
            
            # VALIDATION: Investment date cannot be before repayment date
            final_investment_date = alloc.investment_date or default_investment_date
            if final_investment_date and cf_date_obj:
                try:
                    inv_date_obj = datetime.strptime(final_investment_date[:10], '%Y-%m-%d')
                    if inv_date_obj.date() < cf_date_obj.date():
                        raise HTTPException(
                            status_code=400,
                            detail=f"Investment date ({final_investment_date}) cannot be before repayment date ({cashflow['date'][:10]}). Investment can only happen after receiving the repayment."
                        )
                except HTTPException:
                    raise
                except:
                    pass
            
            validated_allocations.append({
                "ucc": alloc_ucc.upper() if alloc_ucc else '',
                "amount": alloc.amount,
                "portfolio": alloc.portfolio if alloc.portfolio else 'none',
                "tag": alloc.tag or update.reinvestment_tag,
                "investment_date": final_investment_date  # Broker-selected MF investment date (validated)
            })
        
        # Store split allocations on the cashflow
        update_data = {
            "reinvestment_tag": update.reinvestment_tag,
            "tagged_by": current_user['id'],
            "tagged_at": datetime.now(timezone.utc).isoformat(),
            "has_split_allocations": True,
            "ucc_allocations": validated_allocations,
            "total_allocated_amount": total_allocated,
            # Store first allocation values for backward compatibility
            "target_ucc": validated_allocations[0]['ucc'],
            "portfolio_category": validated_allocations[0]['portfolio'],
        }
        
        # Set approval status based on date and whether this is a modification
        # SPECIAL CASE: Amounts < 1000 without UCC are auto-approved (no broker/client approval needed)
        all_small_amounts = all(alloc['amount'] < 1000 for alloc in validated_allocations)

        # NEW: Auto-approve should be driven by the MF investment date, NOT the
        # cashflow (repayment expected) date. If any allocation's investment
        # date is today or in the future, require client approval.
        all_investment_dates_past = True
        for _a in validated_allocations:
            _inv_str = _a.get('investment_date')
            if _inv_str:
                try:
                    _inv_d = datetime.fromisoformat(_inv_str[:10]).date()
                except Exception:
                    _inv_d = None
            else:
                # Fallback: default investment date = cashflow date + 1 day
                _inv_d = (cf_date + timedelta(days=1)) if cf_date else None
            if _inv_d is None or _inv_d >= today:
                all_investment_dates_past = False
                break

        if current_user['role'] in ['broker', 'sub_broker'] and update.reinvestment_tag not in ['not_tagged']:
            # PRIORITY: If the chosen investment date is already in the past
            # (or all amounts are < 1000), auto-approve. Future investment
            # dates always require client approval.
            if all_investment_dates_past or all_small_amounts:
                # Past investment date OR all amounts < 1000 - auto approve (no approval needed)
                update_data['client_approved'] = True
                update_data['approval_status'] = 'approved'
                update_data['approved_at'] = datetime.now(timezone.utc).isoformat()
                update_data['approved_by'] = current_user['id']
                update_data['auto_approved'] = True
                if all_investment_dates_past:
                    update_data['auto_approved_reason'] = 'Investment date is in the past'
                elif all_small_amounts:
                    update_data['auto_approved_reason'] = 'Amount < 1000'
            elif needs_reapproval:
                # Previously approved, now modified - needs re-approval from client (ONLY for future dates)
                update_data['client_approved'] = False
                update_data['approval_status'] = 'pending_reapproval'
                update_data['modified_after_approval'] = True
                update_data['previous_approval_at'] = cashflow.get('approved_at')
                update_data['modification_reason'] = 'Broker/sub-broker modified approved tag'
            elif current_user['role'] == 'sub_broker':
                # Sub-broker tagging future date - needs broker approval first
                update_data['client_approved'] = False
                update_data['broker_approved'] = False
                update_data['approval_status'] = 'pending_broker_approval'
                update_data['tagged_by_sub_broker'] = current_user['id']
                update_data['tagged_by_sub_broker_name'] = current_user.get('name', '')
                # Get the broker ID for this sub-broker
                sub_broker_info = await db.Mfd_Ria_Partner.find_one({"id": current_user['id']}, {"_id": 0, "broker_id": 1})
                if sub_broker_info:
                    update_data['broker_id'] = sub_broker_info.get('broker_id')
            else:
                update_data['client_approved'] = False
                update_data['broker_approved'] = True  # Broker tagging is auto broker-approved
                update_data['approval_status'] = 'pending'
        
        await db.holding_cashflows.update_one(
            {"id": cashflow_id},
            {"$set": update_data}
        )
        
        # Delete any existing log entries for this cashflow (to prevent duplicates)
        await db.reinvestment_logs.delete_many({"cashflow_id": cashflow_id})
        
        # Distribute the cashflow's true net_amount across allocations so that
        # non-residual rows carry their rounded investment amount as
        # `net_amount` and the decimal leftover is parked on the "None"
        # residual row. Keeps Logs → Reinv Logs, Holdings → Trades → Reinv
        # Logs, and the client's approval view perfectly aligned.
        distributed_allocs = _distribute_allocation_net_amounts(
            validated_allocations, cashflow.get('net_amount', 0)
        )
        
        # Create log entries for each allocation
        for idx, alloc in enumerate(distributed_allocs):
            alloc_net_amount = alloc.get('net_amount', alloc['amount'])
            alloc_residual = round(alloc_net_amount - alloc['amount'], 2)
            
            log_entry = {
                "id": str(uuid.uuid4()),
                "type": "reinvestment_tag_split",
                "cashflow_id": cashflow_id,
                "client_id": cashflow['client_id'],
                "client_name": client.get('name', ''),
                "bond_id": cashflow.get('bond_id'),
                "bond_name": cashflow.get('bond_name', ''),
                "expected_date": cashflow['date'],
                "mf_investment_date": (alloc.get('investment_date') or (datetime.strptime(cashflow['date'], '%Y-%m-%d') + timedelta(days=1)).strftime('%Y-%m-%d')) if cashflow.get('date') else None,
                "allocation_index": idx,
                "ucc": alloc['ucc'],
                "amount": alloc['amount'],  # Round-down investment amount
                "net_amount": round(alloc_net_amount, 2),  # Actual net amount (share of cashflow)
                "residual_amount": alloc_residual,  # Difference (net - round_down)
                "portfolio": alloc['portfolio'],
                "tag": alloc['tag'],
                "total_allocations": len(validated_allocations),
                "total_cashflow_net_amount": cashflow.get('net_amount', 0),  # Full cashflow net amount
                "tagged_by": current_user['id'],
                "tagged_by_name": current_user.get('name', ''),
                "is_past_date": is_past_date,
                "approval_status": update_data.get('approval_status', 'pending'),
                "created_at": datetime.now(timezone.utc).isoformat()
            }
            await db.reinvestment_logs.insert_one(log_entry)
        
        logger.info(f"Split allocation saved for cashflow {cashflow_id}: {len(validated_allocations)} allocations, total ₹{total_allocated:,.2f}")
        
        message = f"Split allocation saved: {len(validated_allocations)} allocations totaling ₹{total_allocated:,.2f}"
        if needs_reapproval:
            message += " - Client re-approval required"
        
        return {
            "success": True,
            "message": message,
            "cashflow_id": cashflow_id,
            "allocations": validated_allocations,
            "is_past_date": is_past_date,
            "approval_status": update_data.get('approval_status', 'pending'),
            "needs_reapproval": needs_reapproval
        }
    
    # =====================================================
    # HANDLE SINGLE ALLOCATION (original logic)
    # =====================================================
    
    # Update tag - reset approval status if broker/sub-broker modifies
    update_data = {
        "reinvestment_tag": update.reinvestment_tag,
        "tagged_by": current_user['id'],
        "tagged_at": datetime.now(timezone.utc).isoformat(),
        "has_split_allocations": False,
        "ucc_allocations": None,  # Clear any previous split allocations
    }
    
    # Handle custom amount for "other" tag
    if update.reinvestment_tag == 'other' and update.custom_amount is not None:
        update_data['custom_amount'] = update.custom_amount
    elif update.reinvestment_tag != 'other':
        # Clear custom amount if not "other"
        update_data['custom_amount'] = None
    
    # Handle portfolio category
    if update.portfolio_category:
        update_data['portfolio_category'] = update.portfolio_category
    elif update.reinvestment_tag in ['not_tagged', 'not_invest']:
        # Clear portfolio category if not investing
        update_data['portfolio_category'] = None
    
    # Handle target UCC for reinvestment
    if update.target_ucc:
        # Validate that the UCC belongs to the client
        if update.target_ucc.upper() not in client_ucc_list_upper:
            raise HTTPException(status_code=400, detail=f"UCC '{update.target_ucc}' does not belong to this client")
        update_data['target_ucc'] = update.target_ucc.upper()
    elif update.reinvestment_tag in ['not_tagged', 'not_invest']:
        # Clear target UCC if not investing
        update_data['target_ucc'] = None
    
    # Check if this is a small amount (< 1000) that should be auto-approved
    net_amount = cashflow.get('net_amount', 0)
    is_small_amount = net_amount < 1000

    # NEW: Auto-approve should be driven by the MF investment date (not the
    # cashflow/repayment date). Without a user-supplied investment date here,
    # the default MF investment date is cashflow date + 1 day. Only auto-
    # approve if that effective investment date is already in the past.
    _default_inv_date = (cf_date + timedelta(days=1)) if cf_date else None
    is_investment_date_past = bool(_default_inv_date and _default_inv_date < today)

    # If broker/sub-broker is tagging:
    # - Sub-broker tags: Set to pending_broker_approval (broker must approve first)
    # - Broker tags: Set to pending (goes directly to client)
    # - Investment date already in the past: Auto-approve (no client approval needed)
    # - Small amounts < 1000: Auto-approve (no approval needed)
    # - Previously approved: Set to pending re-approval
    if current_user['role'] in ['broker', 'sub_broker'] and update.reinvestment_tag not in ['not_tagged']:
        if needs_reapproval:
            # Previously approved, now modified - needs re-approval from client
            update_data['client_approved'] = False
            update_data['approval_status'] = 'pending_reapproval'
            update_data['modified_after_approval'] = True
            update_data['previous_approval_at'] = cashflow.get('approved_at')
            update_data['modification_reason'] = 'Broker/sub-broker modified approved tag'
        elif is_investment_date_past or is_small_amount:
            # Investment date in past OR small amount (< 1000) - auto approve, no client/broker approval needed
            update_data['client_approved'] = True
            update_data['approval_status'] = 'approved'
            update_data['approved_at'] = datetime.now(timezone.utc).isoformat()
            update_data['approved_by'] = current_user['id']
            update_data['auto_approved'] = True
            if is_small_amount:
                update_data['auto_approved_reason'] = 'Amount < 1000'
            elif is_investment_date_past:
                update_data['auto_approved_reason'] = 'Investment date is in the past'
        elif current_user['role'] == 'sub_broker':
            # Sub-broker tagging future date - needs broker approval first
            update_data['client_approved'] = False
            update_data['broker_approved'] = False
            update_data['approval_status'] = 'pending_broker_approval'
            update_data['tagged_by_sub_broker'] = current_user['id']
            update_data['tagged_by_sub_broker_name'] = current_user.get('name', '')
            # Get the broker ID for this sub-broker
            sub_broker = await db.Mfd_Ria_Partner.find_one({"id": current_user['id']}, {"_id": 0, "broker_id": 1})
            if sub_broker:
                update_data['broker_id'] = sub_broker.get('broker_id')
        else:
            # Broker tagging future date - requires client approval
            update_data['client_approved'] = False
            update_data['broker_approved'] = True  # Broker tagging is auto broker-approved
            update_data['approval_status'] = 'pending'
    
    await db.holding_cashflows.update_one(
        {"id": cashflow_id},
        {"$set": update_data}
    )
    
    # Calculate round-down investment amount and residual
    cashflow_net_amount = cashflow.get('net_amount', 0)
    round_down_amount = (cashflow_net_amount // 100) * 100  # Round down to nearest 100
    residual_amount = cashflow_net_amount - round_down_amount
    
    # Delete any existing log entries for this cashflow before creating new one
    # This prevents duplicate entries and ensures the latest tag is used
    await db.reinvestment_logs.delete_many({"cashflow_id": cashflow_id})
    
    # Create a log entry for Reinvestment Approvals tab
    log_entry = {
        "id": str(uuid.uuid4()),
        "type": "reinvestment_tag",
        "cashflow_id": cashflow_id,
        "client_id": cashflow['client_id'],
        "client_name": client.get('name', ''),
        "bond_id": cashflow.get('bond_id'),
        "bond_name": cashflow.get('bond_name', ''),
        "expected_date": cashflow['date'],
        "net_amount": cashflow_net_amount,  # Original cashflow net amount
        "amount": round_down_amount,  # Round-down investment amount
        "residual_amount": round(residual_amount, 2),  # Difference (net - round_down)
        "reinvestment_tag": update.reinvestment_tag,
        "portfolio": update.portfolio_category,  # Add portfolio field
        "portfolio_category": update.portfolio_category,
        "ucc": update.target_ucc,  # Add ucc field
        "target_ucc": update.target_ucc,
        "tagged_by": current_user['id'],
        "tagged_by_name": current_user.get('name', ''),
        "tagged_by_sub_broker": update_data.get('tagged_by_sub_broker'),
        "tagged_by_sub_broker_name": update_data.get('tagged_by_sub_broker_name'),
        "is_past_date": is_past_date,
        "auto_approved": update_data.get('auto_approved', False),
        "approval_status": update_data.get('approval_status', 'pending'),
        "client_approved": update_data.get('client_approved', False),
        "created_at": datetime.now(timezone.utc).isoformat()
    }
    await db.reinvestment_logs.insert_one(log_entry)
    
    # AUTO-SEND EMAIL: For future dates tagged for reinvestment, send approval email automatically
    # EXCEPT for bonds and real_estate portfolios - these just create notifications
    email_sent = False
    notification_created = False
    
    # For bonds and real_estate portfolios: Create notification instead of email
    if update.portfolio_category in ['bonds', 'real_estate']:
        # Don't send email, don't call Kinntegra API
        # Instead, create a maturity notification for broker/sub-broker
        notification = {
            "id": str(uuid.uuid4()),
            "type": "maturity_reinvestment",
            "title": f"Reinvestment Tagged - {cashflow.get('bond_name', 'Unknown')}",
            "message": f"Client {client.get('name')} has a {update.reinvestment_tag} reinvestment tagged for {update.portfolio_category.replace('_', ' ').title()} on {cashflow['date'][:10]}",
            "client_id": client['id'],
            "client_name": client.get('name', ''),
            "bond_id": cashflow.get('bond_id'),
            "bond_name": cashflow.get('bond_name', ''),
            "cashflow_id": cashflow_id,
            "expected_date": cashflow['date'],
            "amount": cashflow.get('net_amount', 0),
            "reinvestment_tag": update.reinvestment_tag,
            "portfolio_category": update.portfolio_category,
            "target_ucc": update.target_ucc,
            "created_by": current_user['id'],
            "created_by_name": current_user.get('name', ''),
            "notify_on_date": cashflow['date'][:10],  # Notify on maturity date
            "is_read": False,
            "created_at": datetime.now(timezone.utc).isoformat()
        }
        
        # Create notification for the broker
        broker_id = None
        if current_user['role'] == 'broker':
            broker_id = current_user['id']
        elif current_user['role'] == 'sub_broker':
            sub_broker = await db.sub_brokers.find_one({"id": current_user['id']}, {"_id": 0})
            broker_id = sub_broker.get('created_by') if sub_broker else None
        
        if broker_id:
            broker_notification = notification.copy()
            broker_notification['id'] = str(uuid.uuid4())
            broker_notification['user_id'] = broker_id
            broker_notification['user_role'] = 'broker'
            await db.notifications.insert_one(broker_notification)
        
        # Also notify sub-broker if tagged by sub-broker
        if current_user['role'] == 'sub_broker':
            sb_notification = notification.copy()
            sb_notification['id'] = str(uuid.uuid4())
            sb_notification['user_id'] = current_user['id']
            sb_notification['user_role'] = 'sub_broker'
            await db.notifications.insert_one(sb_notification)
        
        notification_created = True
        
        # Mark as auto-approved since no client approval needed for bonds/real_estate
        await db.holding_cashflows.update_one(
            {"id": cashflow_id},
            {"$set": {
                "client_approved": True,
                "approval_status": "approved",
                "approved_at": datetime.now(timezone.utc).isoformat(),
                "auto_approved": True,
                "auto_approved_reason": f"Portfolio: {update.portfolio_category} - No client approval required"
            }}
        )
        
        logger.info(f"Created maturity notification for {update.portfolio_category} reinvestment - no email/API needed")
    
    # NOTE: Individual auto-emails removed to prevent spam. 
    # Broker should use the "Send Approval Email" button to send ONE combined email 
    # after tagging all reinvestments for a client.
    # This prevents clients from receiving multiple individual emails + one clubbed email.
    
    # Build response message
    if notification_created:
        message = f"Tag updated successfully (Notification created for {update.portfolio_category.replace('_', ' ')} - no client approval needed)"
    elif is_past_date:
        message = "Tag updated successfully (auto-approved for past date)"
    else:
        message = "Tag updated successfully (pending client approval - use 'Send Approval Email' to notify client)"
    
    return {
        "message": message, 
        "reinvestment_tag": update.reinvestment_tag, 
        "custom_amount": update.custom_amount,
        "portfolio_category": update.portfolio_category,
        "target_ucc": update.target_ucc,
        "is_past_date": is_past_date,
        "approval_status": update_data.get('approval_status'),
        "email_sent": False,  # Individual auto-emails disabled to prevent spam
        "notification_created": notification_created
    }


@api_router.put("/reinvestment/approve/{cashflow_id}")
async def approve_reinvestment_tag(cashflow_id: str, approval: ReinvestmentApproval, current_user: dict = Depends(get_current_user)):
    """Client approves or rejects reinvestment tag"""
    
    if current_user['role'] != 'client':
        raise HTTPException(status_code=403, detail="Only clients can approve reinvestment tags")
    
    # Find the cashflow
    cashflow = await db.holding_cashflows.find_one({"id": cashflow_id})
    if not cashflow:
        raise HTTPException(status_code=404, detail="Cashflow not found")
    
    # Verify this is client's own cashflow
    client = await db.Private_Investor.find_one({"id": cashflow['client_id']})
    if not client or client.get('user_id') != current_user['id']:
        raise HTTPException(status_code=403, detail="Access denied")
    
    # Update approval status in holding_cashflows. On REJECTION we also clear
    # the tag back to `not_tagged` so the entry naturally returns to the
    # "Untagged" bucket on the Reinv Tag page (matching the broker-side
    # cancel-reinvestment-tag behaviour). Otherwise the entry sticks as
    # "tagged + rejected" — visible to neither broker nor client in any
    # actionable bucket.
    if approval.approved:
        cashflow_set = {
            "client_approved": True,
            "approval_status": "approved",
            "approval_notes": approval.notes,
            "approved_by": current_user['id'],
            "approved_at": datetime.now(timezone.utc).isoformat(),
        }
    else:
        cashflow_set = {
            "client_approved": False,
            "approval_status": "rejected",
            "reinvestment_tag": "not_tagged",
            "portfolio_category": None,
            "target_ucc": None,
            "ucc_allocations": None,
            "has_split_allocations": False,
            "approval_notes": approval.notes,
            "approved_by": current_user['id'],
            "approved_at": datetime.now(timezone.utc).isoformat(),
        }
    await db.holding_cashflows.update_one(
        {"id": cashflow_id},
        {"$set": cashflow_set}
    )
    
    # Mirror the same change on reinvestment_logs so the Reinv Logs view
    # also drops the now-untagged entry.
    log_set = {
        "approval_status": "approved" if approval.approved else "rejected",
        "client_approved": approval.approved,
        "approval_notes": approval.notes,
        "approved_by": current_user['id'],
        "approved_at": datetime.now(timezone.utc).isoformat(),
    }
    if not approval.approved:
        log_set["reinvestment_tag"] = "not_tagged"
    await db.reinvestment_logs.update_many(
        {"cashflow_id": cashflow_id},
        {"$set": log_set}
    )
    
    # Create notification for broker/sub-broker
    notification = {
        "id": str(uuid.uuid4()),
        "type": "reinvestment_approval",
        "client_id": client['id'],
        "client_name": client['name'],
        "cashflow_id": cashflow_id,
        "approved": approval.approved,
        "notes": approval.notes,
        "for_user_id": client.get('linked_subbroker_id') or client.get('created_by'),
        "created_at": datetime.now(timezone.utc).isoformat(),
        "read": False
    }
    await db.notifications.insert_one(notification)
    
    # If approved, call the Kinntegra MF Buy Scheduler API
    kinntegra_result = None
    if approval.approved:
        try:
            kinntegra_result = await call_kinntegra_mf_buy_scheduler(cashflow, client)
        except Exception as e:
            logger.error(f"Error calling Kinntegra API: {e}")
            kinntegra_result = {"status": "error", "message": str(e)}
    
    return {
        "message": f"Tag {'approved' if approval.approved else 'rejected'} successfully",
        "kinntegra_api_result": kinntegra_result
    }


# Client-specific endpoints for dashboard, approvals and logs
@api_router.get("/client/dashboard/summary")
async def get_client_dashboard_summary(current_user: dict = Depends(get_current_user)):
    """Get dashboard summary for client - opportunities, upcoming repayments, AUM"""
    if current_user['role'] != 'client':
        raise HTTPException(status_code=403, detail="Only clients can access this endpoint")
    
    # Find client record
    client = await db.Private_Investor.find_one({"user_id": current_user['id']}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    
    client_id = client.get('id')
    
    # Get available opportunities (not funded or closed)
    available_bonds = await db.Ncd_Master.count_documents({
        "status": {"$in": ["available", "open", "active", None]},
        "$or": [
            {"is_funded": {"$ne": True}},
            {"is_funded": {"$exists": False}}
        ]
    })
    available_re = await db.Real_Estate_Master.count_documents({
        "status": {"$in": ["available", "open", "active", None]}
    })
    
    # Get upcoming repayments for this client
    today = datetime.now().strftime("%Y-%m-%d")
    upcoming_repayments = await db.holding_cashflows.find({
        "client_id": client_id,
        "date": {"$gte": today},
        "is_repaid": {"$ne": True}
    }, {"_id": 0, "date": 1, "amount": 1, "type": 1, "bond_name": 1}).sort("date", 1).to_list(5)
    
    upcoming_repayments_count = await db.holding_cashflows.count_documents({
        "client_id": client_id,
        "date": {"$gte": today},
        "is_repaid": {"$ne": True}
    })
    
    # Calculate Bond AUM from client allocations
    bonds = await db.Ncd_Master.find({}, {"_id": 0, "id": 1, "face_value": 1, "name": 1}).to_list(1000)
    bond_dict = {b['id']: b for b in bonds}
    
    total_bond_invested = 0
    total_bond_repaid = 0
    
    # Get trades for actual invested amount
    trades = await db.Ncd_Investment_Details.find({
        "client_id": client_id,
        "status": {"$in": ["approved", "completed"]}
    }, {"_id": 0, "total_amount": 1}).to_list(100)
    
    for trade in trades:
        total_bond_invested += trade.get('total_amount', 0) or 0
    
    # Calculate from allocations if no trades
    allocations = client.get('bond_allocations', [])
    total_bond_deal_size = 0
    for alloc in allocations:
        bond = bond_dict.get(alloc.get('bond_id'))
        if bond:
            units_paid = alloc.get('units_paid', 0)
            total_bond_deal_size += units_paid * bond.get('face_value', 0)
            
            # Calculate repaid from cashflows
            cashflows = alloc.get('cashflows', [])
            for cf in cashflows:
                if cf.get('type') == 'principal_repayment':
                    total_bond_repaid += cf.get('amount', 0)
    
    if total_bond_invested == 0:
        total_bond_invested = total_bond_deal_size
    
    total_bond_pending = total_bond_deal_size - total_bond_repaid
    
    # Calculate Real Estate AUM
    real_estate_opps = await db.Real_Estate_Master.find(
        {"investors.client_id": client_id},
        {"_id": 0}
    ).to_list(100)
    
    total_re_deal_size = 0
    total_re_paid = 0
    
    for re in real_estate_opps:
        investors = re.get('investors', [])
        for inv in investors:
            if inv.get('client_id') == client_id:
                share_pct = inv.get('share_percentage', inv.get('percentage', 0))
                total_cost = re.get('total_cost', 0)
                total_re_deal_size += total_cost * share_pct / 100
                
                # Calculate paid amount
                payments = inv.get('payments', [])
                for payment in payments:
                    total_re_paid += payment.get('amount', 0)
    
    return {
        "opportunities": {
            "bonds": {"available": available_bonds},
            "real_estate": {"available": available_re}
        },
        "upcoming_repayments": {
            "count": upcoming_repayments_count,
            "items": upcoming_repayments
        },
        "bond_aum": {
            "total_deal_size": total_bond_deal_size,
            "total_invested": total_bond_invested,
            "total_repaid": total_bond_repaid,
            "total_pending": total_bond_pending
        },
        "real_estate_aum": {
            "total_deal_size": total_re_deal_size,
            "total_paid": total_re_paid
        }
    }

def _distribute_allocation_net_amounts(allocations: list, cf_net_amount: float) -> list:
    """Return a new list of allocation dicts with a `net_amount` field set so
    that the rounded investment amounts (`alloc.amount`) are preserved for
    non-residual rows, and any leftover decimals from the cashflow's true
    `net_amount` are parked on the residual row (portfolio == "none", or the
    last row if no residual exists).

    Example: cf_net_amount=21402.72, allocations=[{amount:21400,portfolio:wealth},
    {amount:2,portfolio:none}] → row1.net_amount=21400.00, row2.net_amount=2.72.
    """
    if not allocations:
        return []
    out = []
    for a in allocations:
        new_a = dict(a)
        new_a["net_amount"] = float(a.get("amount") or 0)
        out.append(new_a)
    sum_amounts = sum((a.get("amount") or 0) for a in allocations)
    remainder = round(float(cf_net_amount or 0) - float(sum_amounts), 2)
    if abs(remainder) < 0.005:
        return out
    # Prefer the last "none"-portfolio row to receive the decimal residual.
    residual_idx = None
    for i in range(len(out) - 1, -1, -1):
        p = (out[i].get("portfolio") or "").lower()
        if p == "none":
            residual_idx = i
            break
    if residual_idx is None:
        residual_idx = len(out) - 1
    out[residual_idx]["net_amount"] = round(out[residual_idx]["net_amount"] + remainder, 2)
    return out




async def _resolve_client_record(current_user: dict):
    """Resolve the client's Private_Investor* record across all three auth paths.
    
    Returns a dict with at least an `id` field that matches the `client_id` used
    in trades / holding_cashflows / reinvestment_logs, or None if not found.
    
    Three paths considered:
      1) 3-way login (Login_Credentials) → current_user['id'] IS the reference_id
         (i.e. Private_Investor_Indian_Passport.id or _Foreign_Passport.id).
      2) Legacy `users` flow → current_user['id'] is users.id; clients in
         Private_Investor.* collections carry a `user_id` field that matches.
      3) Legacy `users` flow with `client_id` on the users row (passed in JWT).
    """
    user_id = current_user.get('id')
    if not user_id:
        return None
    
    # Path 1: direct id match in Indian / Foreign passport collections
    # (Login_Credentials reference_id == collection row id).
    for coll in (
        "Private_Investor_Indian_Passport",
        "Private_Investor_Foreign_Passport",
    ):
        row = await db[coll].find_one({"id": user_id}, {"_id": 0})
        if row:
            return row
    
    # Path 2: legacy user_id -> Private_Investor (and passport collections
    # if a legacy row happens to link back via user_id).
    for coll in (
        "Private_Investor",
        "Private_Investor_Indian_Passport",
        "Private_Investor_Foreign_Passport",
    ):
        row = await db[coll].find_one({"user_id": user_id}, {"_id": 0})
        if row:
            return row
    
    # Path 3: JWT carried client_id explicitly
    client_id = current_user.get('client_id')
    if client_id:
        for coll in (
            "Private_Investor_Indian_Passport",
            "Private_Investor_Foreign_Passport",
            "Private_Investor",
        ):
            row = await db[coll].find_one({"id": client_id}, {"_id": 0})
            if row:
                return row
    
    return None



@api_router.get("/client/pending-approvals/count")
async def get_client_pending_approvals_count(current_user: dict = Depends(get_current_user)):
    """Get count of pending approvals for client"""
    if current_user['role'] != 'client':
        raise HTTPException(status_code=403, detail="Only clients can access this endpoint")
    
    # Resolve client across legacy + 3-way login flows
    client = await _resolve_client_record(current_user)
    if not client:
        return {"count": 0}
    
    pending_statuses = ["pending", "cancellation_pending", "edit_pending", "pending_reapproval"]
    
    # Count pending reinvestment logs for this client
    log_count = await db.reinvestment_logs.count_documents({
        "client_id": client['id'],
        "approval_status": {"$in": pending_statuses}
    })
    
    # Also count pending holding_cashflows that might not have logs
    cf_count = await db.holding_cashflows.count_documents({
        "client_id": client['id'],
        "approval_status": {"$in": pending_statuses},
        "reinvestment_tag": {"$nin": [None, "", "not_tagged"]}
    })
    
    # Use max since some entries might be in both
    count = max(log_count, cf_count)
    
    return {"count": count}


@api_router.get("/client/pending-approvals")
async def get_client_pending_approvals(current_user: dict = Depends(get_current_user)):
    """Get pending reinvestment approvals for client"""
    if current_user['role'] != 'client':
        raise HTTPException(status_code=403, detail="Only clients can access this endpoint")
    
    # Resolve client across legacy + 3-way login flows
    client = await _resolve_client_record(current_user)
    if not client:
        return []
    
    # Get pending reinvestment logs (including cancellation_pending, edit_pending, pending_reapproval)
    pending_statuses = ["pending", "cancellation_pending", "edit_pending", "pending_reapproval"]
    
    # First check reinvestment_logs for pending entries
    main_logs = await db.reinvestment_logs.find({
        "client_id": client['id'],
        "approval_status": {"$in": pending_statuses}
    }, {"_id": 0}).sort("created_at", -1).to_list(100)
    
    # ALSO check holding_cashflows for entries that might not have logs yet
    pending_cashflows = await db.holding_cashflows.find({
        "client_id": client['id'],
        "approval_status": {"$in": pending_statuses},
        "reinvestment_tag": {"$nin": [None, "", "not_tagged"]}
    }, {"_id": 0}).to_list(100)
    
    # Create log entries for pending cashflows that don't have reinvestment_logs
    existing_cf_ids = {log.get('cashflow_id') for log in main_logs}
    
    for cf in pending_cashflows:
        cf_id = cf.get('id')
        if cf_id and cf_id not in existing_cf_ids:
            cf_net_amount = cf.get('net_amount', 0) or 0
            # If the cashflow has split allocations, expand each allocation
            # into its own synthetic log entry so the client-side approval UI
            # renders every row (primary + sub-₹1000 residuals).
            if cf.get('has_split_allocations') and cf.get('ucc_allocations'):
                raw_allocations = cf.get('ucc_allocations') or []
                distributed = _distribute_allocation_net_amounts(raw_allocations, cf_net_amount)
                for idx, alloc in enumerate(distributed):
                    alloc_amount = alloc.get('amount') or 0
                    alloc_net_amount = alloc.get('net_amount', float(alloc_amount))
                    main_logs.append({
                        "id": f"cf_{cf_id}_{idx}",
                        "type": "reinvestment_tag_split",
                        "cashflow_id": cf_id,
                        "client_id": cf.get('client_id'),
                        "client_name": client.get('name', ''),
                        "bond_id": cf.get('bond_id'),
                        "bond_name": cf.get('bond_name', ''),
                        "expected_date": cf.get('date'),
                        "net_amount": alloc_net_amount,
                        "total_cashflow_net_amount": cf_net_amount,
                        "amount": alloc_amount,
                        "allocation_index": idx,
                        "total_allocations": len(distributed),
                        "reinvestment_tag": alloc.get('tag') or cf.get('reinvestment_tag'),
                        "portfolio": alloc.get('portfolio'),
                        "portfolio_category": alloc.get('portfolio'),
                        "ucc": alloc.get('ucc'),
                        "target_ucc": alloc.get('ucc'),
                        "mf_investment_date": alloc.get('investment_date') or cf.get('mf_investment_date'),
                        "approval_status": cf.get('approval_status', 'pending'),
                        "tagged_by": cf.get('tagged_by'),
                        "tagged_at": cf.get('tagged_at'),
                        "created_at": cf.get('tagged_at') or cf.get('created_at')
                    })
            else:
                # Create a log-like entry from the cashflow (single allocation)
                log_entry = {
                    "id": f"cf_{cf_id}",
                    "type": "reinvestment_tag",
                    "cashflow_id": cf_id,
                    "client_id": cf.get('client_id'),
                    "client_name": client.get('name', ''),
                    "bond_id": cf.get('bond_id'),
                    "bond_name": cf.get('bond_name', ''),
                    "expected_date": cf.get('date'),
                    "net_amount": cf_net_amount,
                    "amount": int((cf_net_amount or 0) // 100) * 100,
                    "reinvestment_tag": cf.get('reinvestment_tag'),
                    "portfolio": cf.get('portfolio_category'),
                    "portfolio_category": cf.get('portfolio_category'),
                    "ucc": cf.get('target_ucc'),
                    "target_ucc": cf.get('target_ucc'),
                    "mf_investment_date": cf.get('mf_investment_date'),
                    "approval_status": cf.get('approval_status', 'pending'),
                    "tagged_by": cf.get('tagged_by'),
                    "tagged_at": cf.get('tagged_at'),
                    "created_at": cf.get('tagged_at') or cf.get('created_at')
                }
                main_logs.append(log_entry)
            existing_cf_ids.add(cf_id)
    
    # Get unique cashflow_ids from main logs
    cashflow_ids = list(set(log.get('cashflow_id') for log in main_logs if log.get('cashflow_id')))
    
    # Now get allocations for these cashflows - but ONLY those still pending approval
    all_logs = await db.reinvestment_logs.find({
        "cashflow_id": {"$in": cashflow_ids},
        "approval_status": {"$in": pending_statuses}
    }, {"_id": 0}).sort([("cashflow_id", 1), ("allocation_index", 1)]).to_list(500)
    
    # Merge: use all_logs but add any main_logs that don't have corresponding allocation logs
    all_log_cf_ids = {log.get('cashflow_id') for log in all_logs}
    logs = list(all_logs)
    for log in main_logs:
        if log.get('cashflow_id') not in all_log_cf_ids:
            logs.append(log)
    
    # Enrich with bond and broker info
    for log in logs:
        bond = await db.Ncd_Master.find_one({"id": log.get('bond_id')}, {"_id": 0, "name": 1})
        if bond:
            log['bond_name'] = bond.get('name', log.get('bond_name', 'Unknown'))
        
        # Calculate investment date if not present (T+1 from expected_date)
        if not log.get('mf_investment_date') and log.get('expected_date'):
            try:
                expected = datetime.strptime(log['expected_date'], '%Y-%m-%d')
                log['mf_investment_date'] = (expected + timedelta(days=1)).strftime('%Y-%m-%d')
            except:
                pass
        
        # Get who tagged it
        if log.get('tagged_by'):
            tagger = await db.users.find_one({"id": log.get('tagged_by')}, {"_id": 0, "name": 1})
            if not tagger:
                # Check if it's a sub-broker
                tagger = await db.Mfd_Ria_Partner.find_one({"id": log.get('tagged_by')}, {"_id": 0, "name": 1})
            log['tagged_by_name'] = tagger.get('name', 'Broker') if tagger else 'Broker'
        else:
            log['tagged_by_name'] = 'Broker'
    
    return logs


@api_router.get("/client/reinvestment-logs")
async def get_client_reinvestment_logs(current_user: dict = Depends(get_current_user)):
    """Get all reinvestment logs for client (approved, rejected, pending)"""
    if current_user['role'] != 'client':
        raise HTTPException(status_code=403, detail="Only clients can access this endpoint")
    
    # Resolve client across legacy + 3-way login flows
    client = await _resolve_client_record(current_user)
    if not client:
        return []
    
    # Mirror the broker `/api/reinvestment/logs` filter so entries that the
    # broker / MFD-RIA has rolled back to "untagged" (or the client has
    # rejected) vanish from this page on the client login as well. We only
    # surface logs that are actively tagged AND in an actionable lifecycle
    # state (pending / approved / submitted / etc.).
    excluded_statuses = [
        "pending_broker_approval",
        "cancelled", "auto_cancelled",
        "rejected", "broker_rejected", "client_rejected",
    ]
    logs = await db.reinvestment_logs.find({
        "client_id": client['id'],
        "approval_status": {"$nin": excluded_statuses},
        "reinvestment_tag": {"$nin": ["not_tagged", None, ""]},
    }, {"_id": 0}).sort("created_at", -1).to_list(500)
    
    # Also get tagged holding_cashflows that might not have corresponding logs
    tagged_cashflows = await db.holding_cashflows.find({
        "client_id": client['id'],
        "reinvestment_tag": {"$nin": [None, "", "not_tagged"]},
        "approval_status": {"$nin": excluded_statuses},
    }, {"_id": 0}).to_list(500)
    
    # Track existing cashflow IDs from logs
    existing_cf_ids = {log.get('cashflow_id') for log in logs if log.get('cashflow_id')}
    
    # Add cashflows that don't have corresponding logs
    for cf in tagged_cashflows:
        cf_id = cf.get('id')
        if cf_id and cf_id not in existing_cf_ids:
            # Create a log-like entry from the cashflow
            net_amount = cf.get('net_amount', 0) or 0
            round_down = int(net_amount // 100) * 100
            
            log_entry = {
                "id": f"cf_{cf_id}",
                "type": "reinvestment_tag",
                "cashflow_id": cf_id,
                "client_id": cf.get('client_id'),
                "bond_id": cf.get('bond_id'),
                "bond_name": cf.get('bond_name', ''),
                "expected_date": cf.get('date'),
                "net_amount": net_amount,
                "amount": round_down,
                "residual_amount": round(net_amount - round_down, 2),
                "reinvestment_tag": cf.get('reinvestment_tag'),
                "portfolio": cf.get('portfolio_category'),
                "portfolio_category": cf.get('portfolio_category'),
                "ucc": cf.get('target_ucc'),
                "target_ucc": cf.get('target_ucc'),
                "mf_investment_date": cf.get('mf_investment_date'),
                "approval_status": cf.get('approval_status', 'pending'),
                "client_approved": cf.get('client_approved', False),
                "kinntegra_api_submitted": cf.get('kinntegra_api_submitted', False),
                "tagged_by": cf.get('tagged_by'),
                "tagged_at": cf.get('tagged_at'),
                "created_at": cf.get('tagged_at') or cf.get('created_at')
            }
            logs.append(log_entry)
            existing_cf_ids.add(cf_id)
    
    # Enrich with bond info
    for log in logs:
        bond = await db.Ncd_Master.find_one({"id": log.get('bond_id')}, {"_id": 0, "name": 1})
        if bond:
            log['bond_name'] = bond.get('name', log.get('bond_name', 'Unknown'))
        
        # Calculate investment date if not present (T+1 from expected_date)
        if not log.get('mf_investment_date') and log.get('expected_date'):
            try:
                expected = datetime.strptime(log['expected_date'][:10], '%Y-%m-%d')
                log['mf_investment_date'] = (expected + timedelta(days=1)).strftime('%Y-%m-%d')
            except:
                pass
        
        # Get who tagged it
        if log.get('tagged_by'):
            tagger = await db.users.find_one({"id": log.get('tagged_by')}, {"_id": 0, "name": 1})
            if not tagger:
                tagger = await db.Mfd_Ria_Partner.find_one({"id": log.get('tagged_by')}, {"_id": 0, "name": 1})
            log['tagged_by_name'] = tagger.get('name', 'Broker') if tagger else 'Broker'
        else:
            log['tagged_by_name'] = 'Broker'
    
    # Sort by expected_date descending (most recent first)
    logs.sort(key=lambda x: x.get('expected_date', '') or '', reverse=True)
    
    return logs


class ClientApprovalAction(BaseModel):
    action: str  # 'approve' or 'reject'
    notes: Optional[str] = None


@api_router.post("/client/approve-reinvestment/{log_id}")
async def client_approve_reinvestment(
    log_id: str,
    approval: ClientApprovalAction,
    current_user: dict = Depends(get_current_user)
):
    """Client approves or rejects a reinvestment request (including cancellation and edit requests)"""
    if current_user['role'] != 'client':
        raise HTTPException(status_code=403, detail="Only clients can access this endpoint")
    
    # Resolve client across legacy + 3-way login flows
    client = await _resolve_client_record(current_user)
    if not client:
        raise HTTPException(status_code=404, detail="Client record not found")
    
    # Find the log entry. The frontend may send a synthetic id (cf_<cashflow_id>
    # or cf_<cashflow_id>_<idx>) when the split allocation was saved directly on
    # holding_cashflows without matching reinvestment_logs rows. In that case
    # resolve the underlying cashflow, materialise reinvestment_logs rows for
    # every allocation, and approve them together.
    log_entry = await db.reinvestment_logs.find_one({
        "id": log_id,
        "client_id": client['id']
    })
    
    if not log_entry and log_id.startswith("cf_"):
        # Strip the optional trailing "_<idx>" split suffix
        body = log_id[3:]
        # Cashflow id is a UUID (36 chars with 4 dashes). If the body ends with
        # a numeric suffix after the UUID, strip it.
        parts = body.rsplit("_", 1)
        if len(parts) == 2 and parts[1].isdigit():
            cashflow_id = parts[0]
        else:
            cashflow_id = body
        cf = await db.holding_cashflows.find_one({"id": cashflow_id, "client_id": client['id']})
        if cf:
            allocations = cf.get('ucc_allocations') or []
            now_iso = datetime.now(timezone.utc).isoformat()
            if allocations:
                distributed = _distribute_allocation_net_amounts(allocations, cf.get('net_amount', 0))
                for idx, alloc in enumerate(distributed):
                    await db.reinvestment_logs.update_one(
                        {"cashflow_id": cashflow_id, "allocation_index": idx, "client_id": client['id']},
                        {"$setOnInsert": {
                            "id": str(uuid.uuid4()),
                            "type": "reinvestment_tag_split",
                            "cashflow_id": cashflow_id,
                            "client_id": client['id'],
                            "client_name": client.get('name', ''),
                            "bond_id": cf.get('bond_id'),
                            "bond_name": cf.get('bond_name', ''),
                            "expected_date": cf.get('date'),
                            "mf_investment_date": alloc.get('investment_date'),
                            "allocation_index": idx,
                            "ucc": alloc.get('ucc'),
                            "amount": alloc.get('amount'),
                            # `net_amount` preserves the decimal residual so
                            # the "None" row shows e.g. ₹2.72 (not ₹2) in
                            # Logs → Reinv Logs + Holdings → Trades → Reinv Logs.
                            "net_amount": alloc.get('net_amount', alloc.get('amount')),
                            "portfolio": alloc.get('portfolio'),
                            "portfolio_category": alloc.get('portfolio'),
                            "tag": alloc.get('tag'),
                            "reinvestment_tag": alloc.get('tag') or cf.get('reinvestment_tag'),
                            "total_allocations": len(allocations),
                            "total_cashflow_net_amount": cf.get('net_amount', 0),
                            "approval_status": cf.get('approval_status', 'pending'),
                            "tagged_by": cf.get('tagged_by'),
                            "tagged_at": cf.get('tagged_at'),
                            "created_at": cf.get('tagged_at') or now_iso,
                        }},
                        upsert=True,
                    )
            else:
                await db.reinvestment_logs.update_one(
                    {"cashflow_id": cashflow_id, "client_id": client['id']},
                    {"$setOnInsert": {
                        "id": str(uuid.uuid4()),
                        "type": "reinvestment_tag",
                        "cashflow_id": cashflow_id,
                        "client_id": client['id'],
                        "client_name": client.get('name', ''),
                        "bond_id": cf.get('bond_id'),
                        "bond_name": cf.get('bond_name', ''),
                        "expected_date": cf.get('date'),
                        "mf_investment_date": cf.get('mf_investment_date'),
                        "ucc": cf.get('target_ucc'),
                        "target_ucc": cf.get('target_ucc'),
                        "amount": int((cf.get('net_amount', 0) or 0) // 100) * 100,
                        "net_amount": cf.get('net_amount', 0),
                        "portfolio": cf.get('portfolio_category'),
                        "portfolio_category": cf.get('portfolio_category'),
                        "reinvestment_tag": cf.get('reinvestment_tag'),
                        "approval_status": cf.get('approval_status', 'pending'),
                        "tagged_by": cf.get('tagged_by'),
                        "tagged_at": cf.get('tagged_at'),
                        "created_at": cf.get('tagged_at') or now_iso,
                    }},
                    upsert=True,
                )
            # Re-fetch any materialised log entry so downstream logic has state.
            log_entry = await db.reinvestment_logs.find_one(
                {"cashflow_id": cashflow_id, "client_id": client['id']}
            )
    
    if not log_entry:
        raise HTTPException(status_code=404, detail="Reinvestment log not found")
    
    current_status = log_entry.get('approval_status')
    
    # Validate status is one we can process
    if current_status not in ['pending', 'pending_reapproval', 'cancellation_pending', 'edit_pending']:
        raise HTTPException(status_code=400, detail="This request has already been processed")
    
    is_approved = approval.action == 'approve'
    kinntegra_result = None
    
    # Handle different approval types
    if current_status == 'cancellation_pending':
        # Client is approving/rejecting a cancellation request
        if is_approved:
            new_status = 'cancelled'
            # Reset the cashflow to untagged
            if log_entry.get('cashflow_id'):
                await db.holding_cashflows.update_one(
                    {"id": log_entry['cashflow_id']},
                    {"$set": {
                        "reinvestment_tag": "not_tagged",
                        "portfolio_category": None,
                        "target_ucc": None,
                        "approval_status": None,
                        "client_approved": False
                    }}
                )
        else:
            # Client rejected cancellation - keep original approved status
            new_status = 'submitted'
        
        await db.reinvestment_logs.update_one(
            {"id": log_id},
            {"$set": {
                "approval_status": new_status,
                "cancellation_approved_by_client": is_approved,
                "cancellation_approved_at": datetime.now(timezone.utc).isoformat(),
                "cancellation_approval_notes": approval.notes
            }}
        )
        
    elif current_status == 'edit_pending':
        # Client is approving/rejecting an edit request
        if is_approved:
            new_status = 'submitted'
            # Apply the edited values to cashflow
            if log_entry.get('cashflow_id'):
                await db.holding_cashflows.update_one(
                    {"id": log_entry['cashflow_id']},
                    {"$set": {
                        "client_approved": True,
                        "reinvestment_tag": log_entry.get('reinvestment_tag'),
                        "portfolio_category": log_entry.get('portfolio_category'),
                        "target_ucc": log_entry.get('target_ucc'),
                        "approval_status": new_status
                    }}
                )
            # Call Kinntegra API for the edited reinvestment
            try:
                cashflow = await db.holding_cashflows.find_one({"id": log_entry.get('cashflow_id')})
                if cashflow:
                    kinntegra_result = await call_kinntegra_mf_buy_scheduler(cashflow, client)
            except Exception as e:
                logger.error(f"Error calling Kinntegra API for edit: {e}")
                kinntegra_result = {"status": "error", "message": str(e)}
        else:
            # Client rejected edit - restore original values if available
            original = log_entry.get('original_values', {})
            if original and log_entry.get('cashflow_id'):
                await db.holding_cashflows.update_one(
                    {"id": log_entry['cashflow_id']},
                    {"$set": {
                        "reinvestment_tag": original.get('reinvestment_tag'),
                        "portfolio_category": original.get('portfolio_category'),
                        "target_ucc": original.get('target_ucc')
                    }}
                )
            new_status = log_entry.get('previous_approval_status', 'submitted')
        
        await db.reinvestment_logs.update_one(
            {"id": log_id},
            {"$set": {
                "approval_status": new_status,
                "client_approved": is_approved,
                "edit_approved_by_client": is_approved,
                "edit_approved_at": datetime.now(timezone.utc).isoformat(),
                "edit_approval_notes": approval.notes
            }}
        )
        
    elif current_status in ['pending', 'pending_reapproval']:
        # Standard new or re-approval request
        new_status = 'approved' if is_approved else 'rejected'
        cashflow_id = log_entry.get('cashflow_id')
        
        # Update ALL log entries for the same cashflow (important for split allocations)
        # This ensures all allocations (multiple UCCs) are approved/rejected together
        if cashflow_id:
            update_result = await db.reinvestment_logs.update_many(
                {
                    "cashflow_id": cashflow_id,
                    "client_id": client['id'],
                    "approval_status": {"$in": ["pending", "pending_reapproval"]}
                },
                {"$set": {
                    "approval_status": new_status,
                    "client_approved": is_approved,
                    "approval_notes": approval.notes,
                    "approved_by": current_user['id'],
                    "approved_at": datetime.now(timezone.utc).isoformat()
                }}
            )
            logs_updated = update_result.modified_count
            logger.info(f"Client approval: Updated {logs_updated} log entries for cashflow {cashflow_id}")
        else:
            # Fallback: update just this log entry
            await db.reinvestment_logs.update_one(
                {"id": log_id},
                {"$set": {
                    "approval_status": new_status,
                    "client_approved": is_approved,
                    "approval_notes": approval.notes,
                    "approved_by": current_user['id'],
                    "approved_at": datetime.now(timezone.utc).isoformat()
                }}
            )
            logs_updated = 1
        
        # Also update the cashflow entry if it exists
        if cashflow_id:
            if is_approved:
                # Approved: copy log entry's tag/portfolio/ucc back onto the cashflow
                # Note: reinvestment_logs may use 'portfolio' or 'portfolio_category' field
                portfolio_value = log_entry.get('portfolio_category') or log_entry.get('portfolio')
                await db.holding_cashflows.update_one(
                    {"id": cashflow_id},
                    {"$set": {
                        "client_approved": True,
                        "approval_status": new_status,
                        "reinvestment_tag": log_entry.get('reinvestment_tag'),
                        "portfolio_category": portfolio_value,
                        "target_ucc": log_entry.get('target_ucc') or log_entry.get('ucc'),
                        "approval_notes": approval.notes,
                        "approved_by": current_user['id'],
                        "approved_at": datetime.now(timezone.utc).isoformat()
                    }}
                )
            else:
                # Rejected: clear the tag/portfolio/ucc so the entry returns to
                # "untagged" state instead of staying in limbo.
                await db.holding_cashflows.update_one(
                    {"id": cashflow_id},
                    {"$set": {
                        "client_approved": False,
                        "approval_status": new_status,
                        "reinvestment_tag": "not_tagged",
                        "portfolio_category": None,
                        "target_ucc": None,
                        "approval_notes": approval.notes,
                        "approved_by": current_user['id'],
                        "approved_at": datetime.now(timezone.utc).isoformat()
                    }}
                )
        
        # If approved, call the Kinntegra MF Buy Scheduler API
        if is_approved:
            try:
                # Get cashflow data for API call
                cashflow = await db.holding_cashflows.find_one({"id": cashflow_id})
                if cashflow:
                    # Check if portfolio is "none" - means no reinvestment
                    # Check both the log entry and cashflow (log_entry is source of truth)
                    log_portfolio = (log_entry.get('portfolio_category') or log_entry.get('portfolio') or '').lower()
                    cashflow_portfolio = (cashflow.get('portfolio_category') or '').lower()
                    portfolio = log_portfolio or cashflow_portfolio
                    
                    if portfolio == 'none':
                        # No reinvestment - skip Kinntegra API call
                        kinntegra_result = {
                            "status": "skipped",
                            "message": "No reinvestment requested (portfolio: None)"
                        }
                        
                        # Update logs with no-reinvestment status
                        await db.reinvestment_logs.update_many(
                            {"cashflow_id": cashflow_id, "client_id": client['id']},
                            {"$set": {
                                "api_submitted": False,
                                "api_result": kinntegra_result,
                                "approval_status": "approved_no_reinvest",
                                "no_reinvestment": True
                            }}
                        )
                        
                        # Update holding_cashflows
                        await db.holding_cashflows.update_one(
                            {"id": cashflow_id},
                            {"$set": {
                                "kinntegra_api_submitted": False,
                                "kinntegra_api_result": kinntegra_result,
                                "client_approved": True,
                                "approval_status": "approved_no_reinvest",
                                "no_reinvestment": True,
                                "approved_at": datetime.now(timezone.utc).isoformat()
                            }}
                        )
                    else:
                        # Normal reinvestment - call Kinntegra API
                        kinntegra_result = await call_kinntegra_mf_buy_scheduler(cashflow, client)
                        
                        # Update ALL logs for this cashflow with API submission status
                        await db.reinvestment_logs.update_many(
                            {"cashflow_id": cashflow_id, "client_id": client['id']},
                            {"$set": {
                                "api_submitted": True,
                                "api_result": kinntegra_result,
                                "approval_status": "submitted"
                            }}
                        )
                        
                        # ALSO update holding_cashflows with kinntegra submission status
                        await db.holding_cashflows.update_one(
                            {"id": cashflow_id},
                            {"$set": {
                                "kinntegra_api_submitted": True,
                                "kinntegra_api_result": kinntegra_result,
                                "kinntegra_submitted_at": datetime.now(timezone.utc).isoformat(),
                                "approval_status": "submitted"
                            }}
                        )
            except Exception as e:
                logger.error(f"Error calling Kinntegra API: {e}")
                kinntegra_result = {"status": "error", "message": str(e)}
    
    # Create notification for broker/sub-broker
    broker_id = client.get('linked_subbroker_id') or client.get('broker_id') or client.get('created_by')
    if broker_id:
        action_type = "cancellation" if current_status == 'cancellation_pending' else ("edit" if current_status == 'edit_pending' else "reinvestment")
        notification = {
            "id": str(uuid.uuid4()),
            "type": f"client_{action_type}_approval",
            "client_id": client['id'],
            "client_name": client['name'],
            "log_id": log_id,
            "approved": is_approved,
            "notes": approval.notes,
            "for_user_id": broker_id,
            "created_at": datetime.now(timezone.utc).isoformat(),
            "read": False,
            "message": f"Client {client['name']} {'approved' if is_approved else 'rejected'} {action_type} for {log_entry.get('bond_name', 'a bond')}"
        }
        await db.notifications.insert_one(notification)
    
    return {
        "message": f"Request {'approved' if is_approved else 'rejected'} successfully",
        "status": new_status,
        "approval_type": current_status,
        "kinntegra_api_result": kinntegra_result
    }


@api_router.get("/client/investment-api-logs")
async def get_client_investment_api_logs(current_user: dict = Depends(get_current_user)):
    """Get investment API call logs for client"""
    if current_user['role'] != 'client':
        raise HTTPException(status_code=403, detail="Only clients can access this endpoint")
    
    # Resolve client across legacy + 3-way login flows
    client = await _resolve_client_record(current_user)
    if not client:
        return []
    
    # Get investment API logs for this client
    logs = await db.investment_api_logs.find({
        "client_id": client['id']
    }, {"_id": 0}).sort("created_at", -1).to_list(500)
    
    return logs


# Broker cancel/edit reinvestment tag endpoints
class CancelReinvestmentRequest(BaseModel):
    reason: Optional[str] = None


@api_router.post("/reinvestment/cancel/{log_id}")
async def cancel_reinvestment_tag(
    log_id: str,
    request: CancelReinvestmentRequest,
    current_user: dict = Depends(get_current_user)
):
    """Broker/Sub-broker cancels a reinvestment tag"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers can cancel reinvestment tags")
    
    # Find the log entry
    log_entry = await db.reinvestment_logs.find_one({"id": log_id})
    if not log_entry:
        raise HTTPException(status_code=404, detail="Reinvestment log not found")
    
    current_status = log_entry.get('approval_status', 'pending')
    client_approved = log_entry.get('client_approved', False)
    
    # If client has already approved, need to create a cancellation request
    if client_approved and current_status == 'submitted':
        # Update status to "cancellation_pending"
        await db.reinvestment_logs.update_one(
            {"id": log_id},
            {"$set": {
                "approval_status": "cancellation_pending",
                "cancellation_requested_by": current_user['id'],
                "cancellation_requested_at": datetime.now(timezone.utc).isoformat(),
                "cancellation_reason": request.reason
            }}
        )
        
        # Notify client about cancellation request
        client = await db.Private_Investor.find_one({"id": log_entry['client_id']})
        if client and client.get('user_id'):
            notification = {
                "id": str(uuid.uuid4()),
                "type": "reinvestment_cancellation_request",
                "client_id": client['id'],
                "log_id": log_id,
                "for_user_id": client['user_id'],
                "created_at": datetime.now(timezone.utc).isoformat(),
                "read": False,
                "message": f"Your broker has requested cancellation of reinvestment for {log_entry.get('bond_name', 'a bond')}"
            }
            await db.notifications.insert_one(notification)
        
        return {
            "message": "Cancellation request sent to client for approval",
            "status": "cancellation_pending",
            "requires_client_approval": True
        }
    else:
        # Direct cancellation if not yet approved by client
        await db.reinvestment_logs.update_one(
            {"id": log_id},
            {"$set": {
                "approval_status": "cancelled",
                "cancelled_by": current_user['id'],
                "cancelled_at": datetime.now(timezone.utc).isoformat(),
                "cancellation_reason": request.reason
            }}
        )
        
        # Also update cashflow entry back to untagged
        if log_entry.get('cashflow_id'):
            await db.holding_cashflows.update_one(
                {"id": log_entry['cashflow_id']},
                {"$set": {
                    "reinvestment_tag": "not_tagged",
                    "portfolio_category": None,
                    "target_ucc": None,
                    "approval_status": None,
                    "client_approved": False
                }}
            )
        
        # Notify client if they exist
        client = await db.Private_Investor.find_one({"id": log_entry['client_id']})
        if client and client.get('user_id'):
            notification = {
                "id": str(uuid.uuid4()),
                "type": "reinvestment_cancelled",
                "client_id": client['id'],
                "log_id": log_id,
                "for_user_id": client['user_id'],
                "created_at": datetime.now(timezone.utc).isoformat(),
                "read": False,
                "message": f"Reinvestment tag cancelled by broker for {log_entry.get('bond_name', 'a bond')}"
            }
            await db.notifications.insert_one(notification)
        
        return {
            "message": "Reinvestment tag cancelled successfully",
            "status": "cancelled",
            "requires_client_approval": False
        }


class EditReinvestmentRequest(BaseModel):
    reinvestment_tag: Optional[str] = None
    portfolio_category: Optional[str] = None
    target_ucc: Optional[str] = None
    custom_amount: Optional[float] = None
    reason: Optional[str] = None


@api_router.put("/reinvestment/edit/{log_id}")
async def edit_reinvestment_tag(
    log_id: str,
    request: EditReinvestmentRequest,
    current_user: dict = Depends(get_current_user)
):
    """Broker/Sub-broker edits a reinvestment tag (before or after client approval)"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers can edit reinvestment tags")
    
    # Find the log entry
    log_entry = await db.reinvestment_logs.find_one({"id": log_id})
    if not log_entry:
        raise HTTPException(status_code=404, detail="Reinvestment log not found")
    
    current_status = log_entry.get('approval_status', 'pending')
    
    # Check if edit is allowed (1 day before transaction date for approved entries)
    if current_status == 'submitted':
        expected_date = log_entry.get('expected_date')
        if expected_date:
            from datetime import timedelta
            expected_dt = datetime.fromisoformat(expected_date.replace('Z', '+00:00')) if isinstance(expected_date, str) else expected_date
            if isinstance(expected_dt, datetime):
                cutoff = expected_dt - timedelta(days=1)
                if datetime.now(timezone.utc) > cutoff:
                    raise HTTPException(status_code=400, detail="Cannot edit within 1 day of transaction date")
    
    # Build update data
    update_data = {
        "last_edited_by": current_user['id'],
        "last_edited_at": datetime.now(timezone.utc).isoformat(),
        "edit_reason": request.reason
    }
    
    if request.reinvestment_tag:
        update_data["reinvestment_tag"] = request.reinvestment_tag
    if request.portfolio_category:
        update_data["portfolio_category"] = request.portfolio_category
    if request.target_ucc:
        update_data["target_ucc"] = request.target_ucc
    if request.custom_amount is not None:
        update_data["custom_amount"] = request.custom_amount
    
    # If already approved by client, need re-approval
    client_approved = log_entry.get('client_approved', False)
    if client_approved:
        update_data["approval_status"] = "edit_pending"
        update_data["client_approved"] = False
        update_data["previous_approval_status"] = current_status
        
        # Store original values for reference
        update_data["original_values"] = {
            "reinvestment_tag": log_entry.get('reinvestment_tag'),
            "portfolio_category": log_entry.get('portfolio_category'),
            "target_ucc": log_entry.get('target_ucc')
        }
        
        # Notify client about edit request
        client = await db.Private_Investor.find_one({"id": log_entry['client_id']})
        if client and client.get('user_id'):
            notification = {
                "id": str(uuid.uuid4()),
                "type": "reinvestment_edit_request",
                "client_id": client['id'],
                "log_id": log_id,
                "for_user_id": client['user_id'],
                "created_at": datetime.now(timezone.utc).isoformat(),
                "read": False,
                "message": f"Your broker has modified reinvestment details for {log_entry.get('bond_name', 'a bond')}. Approval required."
            }
            await db.notifications.insert_one(notification)
        
        requires_approval = True
    else:
        requires_approval = False
    
    await db.reinvestment_logs.update_one({"id": log_id}, {"$set": update_data})
    
    # Also update cashflow entry
    if log_entry.get('cashflow_id'):
        cashflow_update = {}
        if request.reinvestment_tag:
            cashflow_update["reinvestment_tag"] = request.reinvestment_tag
        if request.portfolio_category:
            cashflow_update["portfolio_category"] = request.portfolio_category
        if request.target_ucc:
            cashflow_update["target_ucc"] = request.target_ucc
        
        if client_approved:
            cashflow_update["client_approved"] = False
            cashflow_update["approval_status"] = "edit_pending"
        
        if cashflow_update:
            await db.holding_cashflows.update_one(
                {"id": log_entry['cashflow_id']},
                {"$set": cashflow_update}
            )
    
    return {
        "message": "Reinvestment tag updated" + (" - awaiting client re-approval" if requires_approval else ""),
        "requires_client_approval": requires_approval
    }



@api_router.get("/reinvestment/export-all-logs-csv")
async def export_all_reinvestment_logs_csv(current_user: dict = Depends(get_current_user)):
    """
    Export ALL reinvestment logs as CSV for Excel.
    Returns: Client Name, UCC, Portfolio Type, Amount, Bond Name, Date, Tagged By, Status
    """
    from fastapi.responses import Response
    
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers/sub-brokers can export")
    
    # Build query based on role
    query = {"reinvestment_tag": {"$nin": ["not_tagged", None, ""]}}
    
    if current_user['role'] == 'sub_broker':
        # Sub-broker sees only their clients
        clients = await db.Private_Investor.find({"linked_subbroker_id": current_user['id']}, {"_id": 0, "id": 1}).to_list(1000)
        client_ids = [c['id'] for c in clients]
        query["client_id"] = {"$in": client_ids}
    
    # Get all reinvestment logs
    logs = await db.reinvestment_logs.find(query, {"_id": 0}).sort("created_at", -1).to_list(50000)
    
    # CSV Header
    csv_lines = ["Client Name,Client PAN,UCC,Portfolio Type,Amount,Bond Name,Expected Date,Tagged By,Tagged Date,Status"]
    
    for log in logs:
        # Get client PAN if not in log
        client_pan = ""
        if log.get('client_id'):
            client = await db.Private_Investor.find_one({"id": log['client_id']}, {"_id": 0, "pan_number": 1})
            client_pan = client.get('pan_number', '') if client else ''
        
        row = [
            str(log.get('client_name', '')).replace(',', ' '),
            client_pan,
            str(log.get('ucc') or log.get('target_ucc') or ''),
            str(log.get('portfolio') or log.get('portfolio_category') or ''),
            str(log.get('amount') or log.get('net_amount') or 0),
            str(log.get('bond_name', '')).replace(',', ' '),
            str(log.get('expected_date', '')),
            str(log.get('tagged_by_name') or log.get('tagged_by_sub_broker_name') or ''),
            str(log.get('created_at', ''))[:10],
            str(log.get('approval_status', 'pending'))
        ]
        csv_lines.append(','.join(row))
    
    csv_content = '\n'.join(csv_lines)
    
    return Response(
        content=csv_content,
        media_type="text/csv",
        headers={"Content-Disposition": "attachment; filename=reinvestment_logs.csv"}
    )


@api_router.get("/reinvestment/export-subbroker-initiated")
async def export_subbroker_initiated_reinvestments(current_user: dict = Depends(get_current_user)):
    """
    Export all reinvestments initiated by sub-brokers for broker review.
    Returns CSV data with: Client Name, UCC, Portfolio Type, Amount, Sub-Broker Name, Date, Status
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can export this data")
    
    # Get all reinvestment logs tagged by sub-brokers (tagged_by_sub_broker field exists)
    # OR from reinvestment_submissions created by sub-brokers
    
    results = []
    
    # 1. From reinvestment_logs - entries tagged by sub-brokers
    logs = await db.reinvestment_logs.find({
        "$or": [
            {"tagged_by_sub_broker": {"$exists": True, "$ne": None}},
            {"tagged_by_sub_broker_name": {"$exists": True, "$ne": None, "$ne": ""}}
        ]
    }, {"_id": 0}).sort("created_at", -1).to_list(10000)
    
    for log in logs:
        client = await db.Private_Investor.find_one({"id": log.get('client_id')}, {"_id": 0, "name": 1, "pan_number": 1})
        sub_broker = await db.Mfd_Ria_Partner.find_one({"id": log.get('tagged_by_sub_broker') or log.get('tagged_by')}, {"_id": 0, "name": 1})
        
        results.append({
            "client_name": client.get('name', '') if client else log.get('client_name', 'Unknown'),
            "client_pan": client.get('pan_number', '') if client else '',
            "ucc": log.get('ucc') or log.get('target_ucc') or '-',
            "portfolio_type": log.get('portfolio') or log.get('portfolio_category') or '-',
            "amount": log.get('amount') or log.get('net_amount') or 0,
            "bond_name": log.get('bond_name', ''),
            "expected_date": log.get('expected_date', ''),
            "sub_broker_name": sub_broker.get('name', '') if sub_broker else log.get('tagged_by_sub_broker_name', 'Unknown'),
            "tagged_date": log.get('created_at', ''),
            "approval_status": log.get('approval_status', 'pending'),
            "source": "reinvestment_logs"
        })
    
    # 2. From reinvestment_submissions - sub-broker approval workflow
    submissions = await db.reinvestment_submissions.find({
        "sub_broker_id": {"$exists": True, "$ne": None}
    }, {"_id": 0}).sort("created_at", -1).to_list(10000)
    
    for sub in submissions:
        client = await db.Private_Investor.find_one({"id": sub.get('client_id')}, {"_id": 0, "name": 1, "pan_number": 1})
        sub_broker = await db.Mfd_Ria_Partner.find_one({"id": sub.get('sub_broker_id')}, {"_id": 0, "name": 1})
        
        results.append({
            "client_name": client.get('name', '') if client else 'Unknown',
            "client_pan": client.get('pan_number', '') if client else '',
            "ucc": sub.get('target_ucc') or '-',
            "portfolio_type": sub.get('portfolio_category') or '-',
            "amount": sub.get('total_amount') or 0,
            "bond_name": "Multiple" if sub.get('cashflows_count', 0) > 1 else '',
            "expected_date": '',
            "sub_broker_name": sub_broker.get('name', '') if sub_broker else 'Unknown',
            "tagged_date": sub.get('created_at', ''),
            "approval_status": sub.get('broker_approval_status', 'pending'),
            "source": "reinvestment_submissions"
        })
    
    # 3. From holding_cashflows - check tagged_by_sub_broker field
    cashflows = await db.holding_cashflows.find({
        "$or": [
            {"tagged_by_sub_broker": {"$exists": True, "$ne": None}},
            {"tagged_by_sub_broker_name": {"$exists": True, "$ne": None, "$ne": ""}}
        ],
        "reinvestment_tag": {"$nin": ["not_tagged", None, ""]}
    }, {"_id": 0}).sort("tagged_at", -1).to_list(10000)
    
    # Track already added to avoid duplicates
    added_ids = set(log.get('cashflow_id') for log in logs if log.get('cashflow_id'))
    
    for cf in cashflows:
        if cf.get('id') in added_ids:
            continue
        
        client = await db.Private_Investor.find_one({"id": cf.get('client_id')}, {"_id": 0, "name": 1, "pan_number": 1})
        sub_broker = await db.Mfd_Ria_Partner.find_one({"id": cf.get('tagged_by_sub_broker')}, {"_id": 0, "name": 1})
        
        results.append({
            "client_name": client.get('name', '') if client else 'Unknown',
            "client_pan": client.get('pan_number', '') if client else '',
            "ucc": cf.get('target_ucc') or '-',
            "portfolio_type": cf.get('portfolio_category') or '-',
            "amount": cf.get('net_amount') or 0,
            "bond_name": cf.get('bond_name', ''),
            "expected_date": cf.get('date', ''),
            "sub_broker_name": sub_broker.get('name', '') if sub_broker else cf.get('tagged_by_sub_broker_name', 'Unknown'),
            "tagged_date": cf.get('tagged_at', ''),
            "approval_status": cf.get('approval_status', 'tagged'),
            "source": "holding_cashflows"
        })
    
    # Sort by date descending
    results.sort(key=lambda x: x.get('tagged_date', ''), reverse=True)
    
    return {
        "total_records": len(results),
        "data": results
    }


@api_router.post("/reinvestment/sync-missing-logs")
async def sync_missing_reinvestment_logs(current_user: dict = Depends(get_current_user)):
    """
    Sync missing reinvestment_logs entries from holding_cashflows.
    This creates log entries for all tagged cashflows that don't have corresponding logs.
    Makes them visible in Logs page for broker, sub-broker, and clients.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can sync missing logs")
    
    created_count = 0
    skipped_count = 0
    errors = []
    created_entries = []
    
    # Find all holding_cashflows that are tagged (have reinvestment_tag set)
    tagged_cashflows = await db.holding_cashflows.find({
        "reinvestment_tag": {"$nin": ["not_tagged", None, ""]},
        "$or": [
            {"portfolio_category": {"$exists": True, "$ne": None, "$ne": ""}},
            {"target_ucc": {"$exists": True, "$ne": None, "$ne": ""}}
        ]
    }, {"_id": 0}).to_list(10000)
    
    logger.info(f"Found {len(tagged_cashflows)} tagged cashflows to check")
    
    for cf in tagged_cashflows:
        try:
            cf_id = cf.get('id')
            
            # Check if reinvestment_log already exists for this cashflow
            existing_log = await db.reinvestment_logs.find_one({"cashflow_id": cf_id})
            if existing_log:
                skipped_count += 1
                continue
            
            # Get client info
            client = await db.Private_Investor.find_one({"id": cf.get('client_id')}, {"_id": 0, "name": 1, "pan_number": 1, "linked_subbroker_id": 1})
            client_name = client.get('name', 'Unknown') if client else 'Unknown'
            
            # Determine who tagged it
            tagged_by = cf.get('tagged_by') or cf.get('tagged_by_sub_broker')
            tagged_by_name = cf.get('tagged_by_name') or cf.get('tagged_by_sub_broker_name', '')
            
            # If tagged_by_name is empty, try to look it up
            if tagged_by and not tagged_by_name:
                tagger = await db.users.find_one({"id": tagged_by}, {"_id": 0, "name": 1})
                if not tagger:
                    tagger = await db.Mfd_Ria_Partner.find_one({"id": tagged_by}, {"_id": 0, "name": 1})
                tagged_by_name = tagger.get('name', 'Broker') if tagger else 'Broker'
            
            # Calculate round-down amount
            net_amount = cf.get('net_amount', 0)
            round_down_amount = (net_amount // 100) * 100
            residual_amount = net_amount - round_down_amount
            
            # Determine approval status - if client_approved and kinntegra_api_submitted, it's submitted
            approval_status = cf.get('approval_status', 'pending')
            if cf.get('kinntegra_api_submitted'):
                approval_status = 'submitted'
            elif cf.get('client_approved'):
                approval_status = 'approved'
            elif cf.get('no_reinvestment'):
                approval_status = 'approved_no_reinvest'
            
            # Create the log entry
            log_entry = {
                "id": str(uuid.uuid4()),
                "type": "reinvestment_tag",
                "cashflow_id": cf_id,
                "client_id": cf.get('client_id'),
                "client_name": client_name,
                "bond_id": cf.get('bond_id'),
                "bond_name": cf.get('bond_name', ''),
                "expected_date": cf.get('date'),
                "net_amount": net_amount,
                "amount": round_down_amount,
                "residual_amount": round(residual_amount, 2),
                "reinvestment_tag": cf.get('reinvestment_tag'),
                "portfolio": cf.get('portfolio_category'),
                "portfolio_category": cf.get('portfolio_category'),
                "ucc": cf.get('target_ucc'),
                "target_ucc": cf.get('target_ucc'),
                "tagged_by": tagged_by,
                "tagged_by_name": tagged_by_name,
                "tagged_by_sub_broker": cf.get('tagged_by_sub_broker'),
                "tagged_by_sub_broker_name": cf.get('tagged_by_sub_broker_name'),
                "is_past_date": cf.get('is_past_date', False),
                "approval_status": approval_status,
                "client_approved": cf.get('client_approved', False),
                "kinntegra_api_submitted": cf.get('kinntegra_api_submitted', False),
                "no_reinvestment": cf.get('no_reinvestment', False),
                "created_at": cf.get('tagged_at') or cf.get('updated_at') or datetime.now(timezone.utc).isoformat(),
                "synced_from_cashflow": True,
                "synced_at": datetime.now(timezone.utc).isoformat()
            }
            
            await db.reinvestment_logs.insert_one(log_entry)
            created_count += 1
            
            created_entries.append({
                "client_name": client_name,
                "bond_name": cf.get('bond_name', ''),
                "amount": round_down_amount,
                "portfolio": cf.get('portfolio_category'),
                "ucc": cf.get('target_ucc'),
                "status": approval_status
            })
            
        except Exception as e:
            errors.append(f"Error processing {cf.get('id')}: {str(e)}")
            logger.error(f"Error syncing cashflow {cf.get('id')}: {e}")
    
    return {
        "message": f"Synced {created_count} missing log entries",
        "created_count": created_count,
        "skipped_count": skipped_count,
        "total_checked": len(tagged_cashflows),
        "errors": errors[:10] if errors else [],
        "created_entries": created_entries[:20]  # Show first 20 created
    }




@api_router.get("/reinvestment/logs")
async def get_reinvestment_logs(
    status: Optional[str] = None,
    client_id: Optional[str] = None,
    current_user: dict = Depends(get_current_user)
):
    """Get reinvestment tagging logs for the Logs > Reinv Logs tab.
    Lifecycle the UI represents:
      Untagged → Tagged (pending_broker_approval, in Reinv Tag page) →
      Reinv Logs (pending client approval / approved / submitted).
    So we exclude only:
      - untagged / cancelled / rejected variants
      - `pending_broker_approval` (still in the broker's approval queue —
        not yet visible to the client; lives on Reinv Tag page instead)
    """
    excluded_statuses = [
        "pending_broker_approval",
        "cancelled", "auto_cancelled",
        "rejected", "broker_rejected", "client_rejected",
    ]
    
    query = {
        "approval_status": {"$nin": excluded_statuses},
        # Only include logs that have a valid reinvestment tag (not untagged)
        "$or": [
            {"reinvestment_tag": {"$nin": ["not_tagged", None, ""]}},
            {"type": "reinvestment_tag"},
            {"type": "reinvestment_tag_split"}
        ]
    }
    
    if status:
        # Override the approval_status filter if specific status requested
        query["approval_status"] = status
    if client_id:
        query["client_id"] = client_id
    
    # Sub-brokers can only see their clients' logs
    if current_user['role'] == 'sub_broker':
        # Get sub-broker's client IDs
        clients = await db.Private_Investor.find(
            {"linked_subbroker_id": current_user['id']}, 
            {"_id": 0, "id": 1}
        ).to_list(1000)
        client_ids = [c['id'] for c in clients]
        query["client_id"] = {"$in": client_ids}
    
    logs = await db.reinvestment_logs.find(query, {"_id": 0}).sort("created_at", -1).to_list(1000)
    
    # ALSO check holding_cashflows for entries that might have been submitted to Kinntegra
    # but don't have corresponding reinvestment_logs entries
    cf_query = {
        "reinvestment_tag": {"$nin": ["not_tagged", None, ""]},
        "kinntegra_api_submitted": True
    }
    if client_id:
        cf_query["client_id"] = client_id
    if current_user['role'] == 'sub_broker':
        cf_query["client_id"] = {"$in": client_ids}
    
    submitted_cashflows = await db.holding_cashflows.find(cf_query, {"_id": 0}).to_list(5000)
    
    # Get existing log cashflow_ids
    existing_cf_ids = {log.get('cashflow_id') for log in logs}
    
    # Add missing submitted entries
    for cf in submitted_cashflows:
        cf_id = cf.get('id')
        if cf_id and cf_id not in existing_cf_ids:
            # Get client info
            client = await db.Private_Investor.find_one({"id": cf.get('client_id')}, {"_id": 0, "name": 1})
            client_name = client.get('name', '') if client else ''
            
            # Get bond name if not present
            bond_name = cf.get('bond_name', '')
            if not bond_name and cf.get('bond_id'):
                bond = await db.Ncd_Master.find_one({"id": cf.get('bond_id')}, {"_id": 0, "name": 1, "issuer": 1})
                if bond:
                    bond_name = bond.get('name') or bond.get('issuer') or ''
            
            # Create a log-like entry from cashflow
            log_entry = {
                "id": f"auto_{cf_id}",
                "type": "kinntegra_submitted",
                "cashflow_id": cf_id,
                "client_id": cf.get('client_id'),
                "client_name": client_name,
                "bond_id": cf.get('bond_id'),
                "bond_name": bond_name,
                "expected_date": cf.get('date'),
                "net_amount": cf.get('net_amount', 0),
                "amount": int(cf.get('net_amount', 0) // 100) * 100,
                "reinvestment_tag": cf.get('reinvestment_tag'),
                "portfolio": cf.get('portfolio_category'),
                "portfolio_category": cf.get('portfolio_category'),
                "ucc": cf.get('target_ucc'),
                "target_ucc": cf.get('target_ucc'),
                "mf_investment_date": cf.get('mf_investment_date'),
                "investment_date": cf.get('mf_investment_date'),
                "approval_status": "submitted",
                "client_approved": cf.get('client_approved', True),
                "kinntegra_submitted": True,
                "kinntegra_submitted_at": cf.get('kinntegra_submitted_at'),
                "created_at": cf.get('tagged_at') or cf.get('kinntegra_submitted_at')
            }
            logs.append(log_entry)
    
    # Filter out junk entries (no client name, zero amount, no data)
    filtered_logs = []
    for log in logs:
        client_name = log.get('client_name', '')
        amount = log.get('amount', 0) or log.get('net_amount', 0)
        
        # Skip junk entries
        if not client_name or client_name in ['N/A', 'Unknown', '', None]:
            continue
        if amount == 0 or amount is None:
            continue
        
        # Enrich bond_name if missing
        bond_name = log.get('bond_name', '')
        if not bond_name or bond_name in ['', None, 'N/A', 'Unknown']:
            if log.get('bond_id'):
                bond = await db.Ncd_Master.find_one({"id": log.get('bond_id')}, {"_id": 0, "name": 1, "issuer": 1})
                if bond:
                    log['bond_name'] = bond.get('name') or bond.get('issuer') or 'Unknown'
        
        filtered_logs.append(log)
    
    return filtered_logs






@api_router.post("/admin/sync-repayments-from-emails")
async def sync_repayments_from_emails(current_user: dict = Depends(get_current_user)):
    """
    Sync actual_repayments from email_read_logs (from Jan 1, 2026 onwards).
    Each tagged email creates/updates an actual_repayment with the exact gross amount from email.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can sync")
    
    synced_count = 0
    created_count = 0
    skipped_count = 0
    synced_entries = []
    
    # Get all Tagged emails from Jan 2026 onwards
    tagged_emails = await db.email_read_logs.find({
        "holding_updated": True,
        "repayment_date": {"$gte": "2026-01-01"},
        "ignored": {"$ne": True}
    }, {"_id": 0}).to_list(10000)
    
    logger.info(f"SYNC FROM EMAIL: Found {len(tagged_emails)} tagged emails from Jan 2026")
    
    for email in tagged_emails:
        email_id = email.get('id')
        email_gross = email.get('gross_amount', 0) or 0
        email_net = email.get('net_amount', 0) or email_gross
        email_principal = email.get('principal', 0) or 0
        email_interest = email.get('interest', 0) or 0
        email_tds = email.get('tds_amount', 0) or (email_gross - email_net if email_gross and email_net else 0)
        email_date = email.get('repayment_date', '')
        client_name = email.get('client_name', '')
        client_id = email.get('client_id', '')
        bond_code = email.get('bond_code', '')
        matched_trade_id = email.get('matched_trade_id')
        
        if not email_gross or not email_date:
            skipped_count += 1
            continue
        
        # Check if actual_repayment already exists for this email
        existing_ar = await db.actual_repayments.find_one({"email_log_id": email_id}, {"_id": 0})
        
        if existing_ar:
            # Update with correct amounts from email
            current_gross = existing_ar.get('gross_amount', 0)
            if abs(current_gross - email_gross) > 1:
                await db.actual_repayments.update_one(
                    {"id": existing_ar.get('id')},
                    {"$set": {
                        "gross_amount": email_gross,
                        "net_amount": email_net,
                        "principal": email_principal,
                        "interest": email_interest,
                        "tds": email_tds,
                        "synced_from_email": True,
                        "previous_gross": current_gross,
                        "synced_at": datetime.now(timezone.utc).isoformat()
                    }}
                )
                synced_count += 1
                synced_entries.append({
                    "action": "updated",
                    "client_name": client_name,
                    "repayment_date": email_date,
                    "old_gross": current_gross,
                    "new_gross": email_gross
                })
        else:
            # Create new actual_repayment from email
            new_ar = {
                "id": f"email_{email_id}",
                "email_log_id": email_id,
                "client_id": client_id,
                "client_name": client_name,
                "bond_code": bond_code,
                "trade_id": matched_trade_id,
                "repayment_date": email_date,
                "gross_amount": email_gross,
                "net_amount": email_net,
                "principal": email_principal,
                "interest": email_interest,
                "tds": email_tds,
                "type": "interest" if email_principal == 0 else "prepayment",
                "source": "email",
                "created_at": datetime.now(timezone.utc).isoformat()
            }
            await db.actual_repayments.insert_one(new_ar)
            created_count += 1
            synced_entries.append({
                "action": "created",
                "client_name": client_name,
                "repayment_date": email_date,
                "gross": email_gross
            })
    
    return {
        "message": f"Synced {synced_count} and created {created_count} actual_repayments from emails",
        "synced_count": synced_count,
        "created_count": created_count,
        "skipped_count": skipped_count,
        "total_tagged_emails": len(tagged_emails),
        "synced_entries": synced_entries[:30]
    }


@api_router.post("/admin/sync-prepayments-to-reinv-tag")
async def sync_prepayments_to_reinv_tag(current_user: dict = Depends(get_current_user)):
    """
    Sync PREPAYMENTS from Email Tracker to Reinv Tag (holding_cashflows).
    
    A Prepayment is identified when:
    - Principal > 0 AND Interest = 0 (or Interest is very small compared to Principal)
    
    These prepayments are NOT in expected cashflows (unknown at investment time),
    so they need to be added to holding_cashflows for reinvestment tagging.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can sync prepayments")
    
    created_count = 0
    skipped_existing = 0
    skipped_not_prepayment = 0
    created_entries = []
    
    # Get all Tagged emails from Jan 2026 onwards
    tagged_emails = await db.email_read_logs.find({
        "holding_updated": True,
        "repayment_date": {"$gte": "2026-01-01"},
        "ignored": {"$ne": True}
    }, {"_id": 0}).to_list(10000)
    
    logger.info(f"PREPAYMENT SYNC: Checking {len(tagged_emails)} tagged emails for prepayments")
    
    for email in tagged_emails:
        email_id = email.get('id')
        email_gross = email.get('gross_amount', 0) or 0
        email_principal = email.get('principal', 0) or 0
        email_interest = email.get('interest', 0) or 0
        email_date = email.get('repayment_date', '')
        client_name = email.get('client_name', '')
        client_id = email.get('client_id', '')
        bond_code = email.get('bond_code', '')
        matched_trade_id = email.get('matched_trade_id')
        
        # Check if this is a PREPAYMENT (Principal > 0 and Interest = 0 or very small)
        is_prepayment = email_principal > 0 and (email_interest == 0 or email_principal > email_interest * 10)
        
        if not is_prepayment:
            skipped_not_prepayment += 1
            continue
        
        if not email_gross or not email_date or not client_id:
            continue
        
        # Check if holding_cashflows entry already exists for this prepayment
        existing_cf = await db.holding_cashflows.find_one({
            "client_id": client_id,
            "date": {"$regex": email_date[:10]},
            "type": "prepayment",
            "source": "email_prepayment"
        }, {"_id": 0})
        
        if existing_cf:
            skipped_existing += 1
            continue
        
        # Get client info
        client = await db.Private_Investor.find_one({"id": client_id}, {"_id": 0, "name": 1, "pan_number": 1})
        
        # Get bond info from bond_code
        bond = await db.Ncd_Master.find_one({"code": bond_code}, {"_id": 0, "id": 1, "name": 1, "issuer": 1})
        bond_id = bond.get('id') if bond else None
        bond_name = bond.get('name') or bond.get('issuer') if bond else bond_code
        
        # Create holding_cashflows entry for this prepayment
        cf_id = f"prepay_{email_id}"
        new_cf = {
            "id": cf_id,
            "client_id": client_id,
            "client_name": client_name or (client.get('name') if client else ''),
            "bond_id": bond_id,
            "bond_name": bond_name,
            "bond_code": bond_code,
            "trade_id": matched_trade_id,
            "date": email_date,
            "principal": email_principal,
            "interest": email_interest,
            "tds": email.get('tds_amount', 0) or 0,
            "net_amount": email_gross,
            "gross_amount": email_gross,
            "type": "prepayment",
            "source": "email_prepayment",
            "email_log_id": email_id,
            "tag": "not_tagged",
            "reinvestment_tag": None,
            "approval_status": None,
            "is_prepayment": True,
            "created_at": datetime.now(timezone.utc).isoformat(),
            "created_from": "email_tracker_prepayment_sync"
        }
        
        await db.holding_cashflows.insert_one(new_cf)
        created_count += 1
        created_entries.append({
            "cf_id": cf_id,
            "client_name": client_name,
            "date": email_date,
            "principal": email_principal,
            "gross_amount": email_gross,
            "bond_name": bond_name
        })
    
    return {
        "message": f"Created {created_count} prepayment entries in Reinv Tag",
        "created_count": created_count,
        "skipped_existing": skipped_existing,
        "skipped_not_prepayment": skipped_not_prepayment,
        "total_emails_checked": len(tagged_emails),
        "created_entries": created_entries[:30],
        "note": "Prepayments (Principal > 0, Interest ~0) are now available for reinvestment tagging"
    }


async def cleanup_junk_entries(current_user: dict = Depends(get_current_user)):
    """
    Remove junk entries from reinvestment_logs that have:
    - No client name or client_name = 'N/A'
    - Zero amount
    - No portfolio or UCC
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can cleanup entries")
    
    # Find junk entries
    junk_query = {
        "$or": [
            {"client_name": {"$in": [None, "", "N/A", "Unknown"]}},
            {"client_id": {"$in": [None, ""]}},
            {"amount": {"$in": [0, None]}},
            {"$and": [
                {"net_amount": {"$in": [0, None]}},
                {"amount": {"$in": [0, None]}}
            ]}
        ]
    }
    
    # Count before deletion
    junk_count = await db.reinvestment_logs.count_documents(junk_query)
    
    # Get sample of what will be deleted
    junk_samples = await db.reinvestment_logs.find(junk_query, {"_id": 0, "id": 1, "client_name": 1, "amount": 1, "created_at": 1}).limit(10).to_list(10)
    
    # Delete junk entries
    result = await db.reinvestment_logs.delete_many(junk_query)
    
    return {
        "message": f"Deleted {result.deleted_count} junk entries",
        "count_found": junk_count,
        "deleted_count": result.deleted_count,
        "sample_deleted": junk_samples
    }


@api_router.get("/reinvestment/approved-logs")
async def get_approved_reinvestment_logs(
    current_user: dict = Depends(get_current_user)
):
    """Get client-approved reinvestment logs for the Investment Logs tab"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers can access this endpoint")
    
    # Include all approved statuses AND filter out junk entries at query level
    query = {
        "$or": [
            {"approval_status": {"$in": ["submitted", "approved", "auto_approved", "client_approved", "broker_approved"]}},
            {"client_approved": True}
        ],
        # Filter out junk entries
        "client_name": {"$nin": [None, "", "N/A", "Unknown"]},
        "client_id": {"$nin": [None, ""]},
        "$and": [
            {"$or": [
                {"amount": {"$gt": 0}},
                {"net_amount": {"$gt": 0}}
            ]}
        ]
    }
    
    # Sub-brokers can only see their clients' logs
    if current_user['role'] == 'sub_broker':
        clients = await db.Private_Investor.find(
            {"linked_subbroker_id": current_user['id']}, 
            {"_id": 0, "id": 1}
        ).to_list(1000)
        client_ids = [c['id'] for c in clients]
        query["client_id"] = {"$in": client_ids}
    
    logs = await db.reinvestment_logs.find(query, {"_id": 0}).sort("approved_at", -1).to_list(500)
    
    # Enrich with bond and client info, and double-check filtering
    filtered_logs = []
    for log in logs:
        # Skip junk entries that may have slipped through
        client_name = log.get('client_name', '')
        amount = log.get('amount', 0) or log.get('net_amount', 0)
        if not client_name or client_name in ['N/A', 'Unknown', '', None]:
            continue
        if amount == 0 or amount is None:
            continue
        
        bond = await db.Ncd_Master.find_one({"id": log.get('bond_id')}, {"_id": 0, "name": 1, "issuer_name": 1})
        if bond:
            log['bond_name'] = bond.get('name', log.get('bond_name', 'Unknown'))
        
        client = await db.Private_Investor.find_one({"id": log.get('client_id')}, {"_id": 0, "name": 1, "pan_number": 1})
        if client:
            log['client_name'] = client.get('name', log.get('client_name', 'Unknown'))
            log['client_pan'] = client.get('pan_number', '')
        
        filtered_logs.append(log)
    
    return filtered_logs


@api_router.post("/reinvestment/send-approval-email")
async def send_reinvestment_approval_email(
    request: SendReinvestmentApprovalRequest,
    background_tasks: BackgroundTasks,
    current_user: dict = Depends(get_current_user)
):
    """Send approval email to client for tagged reinvestments"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers can send approval emails")
    
    # Get client
    client = await db.Private_Investor.find_one({"id": request.client_id})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    
    # Get user email
    user = await db.users.find_one({"id": client.get('user_id')})
    client_email = user.get('email') if user else client.get('email')
    
    if not client_email:
        raise HTTPException(status_code=400, detail="Client does not have an email address")
    
    # Get cashflows
    cashflows = await db.holding_cashflows.find(
        {"id": {"$in": request.cashflow_ids}}
    ).to_list(1000)
    
    if not cashflows:
        raise HTTPException(status_code=404, detail="No cashflows found")
    
    # Get all allocation details from reinvestment_logs
    cashflow_ids = [cf.get('id') for cf in cashflows]
    all_logs = await db.reinvestment_logs.find(
        {"cashflow_id": {"$in": cashflow_ids}}
    ).to_list(1000)
    
    # Group logs by cashflow_id
    logs_by_cashflow = {}
    for log in all_logs:
        cf_id = log.get('cashflow_id')
        if cf_id not in logs_by_cashflow:
            logs_by_cashflow[cf_id] = []
        logs_by_cashflow[cf_id].append(log)
    
    # Build email content with rounded down amounts and UCC allocations
    entries_html = ""
    total_amount = 0
    valid_cashflows = []  # Track cashflows with valid amounts
    
    for cf in cashflows:
        tag = cf.get('reinvestment_tag', 'not_tagged')
        if tag == 'other':
            amount = cf.get('custom_amount', 0)
        elif tag == 'principal':
            amount = cf.get('principal_component', 0)
            # Skip if principal-only tag but principal is zero or missing
            if not amount or amount <= 0:
                logger.info(f"Skipping cashflow {cf.get('id')} - principal-only tag with zero principal")
                continue
        elif tag == 'interest':
            amount = cf.get('interest_component', 0) - cf.get('tds_amount', 0)
        elif tag == 'net_amount' or tag == 'both':
            amount = cf.get('net_amount', 0)
        else:
            amount = 0
        
        # Round down to nearest integer for display and API
        rounded_amount = int(amount)  # Math.floor equivalent
        
        if rounded_amount <= 0:
            logger.info(f"Skipping cashflow {cf.get('id')} - rounded amount is zero or negative")
            continue
        
        total_amount += rounded_amount
        valid_cashflows.append(cf['id'])
        
        # Get allocations for this cashflow
        allocations = logs_by_cashflow.get(cf['id'], [])
        
        # Build allocation details string
        alloc_details = ""
        if allocations:
            alloc_html_parts = []
            for alloc in allocations:
                ucc = alloc.get('target_ucc', alloc.get('ucc', ''))
                portfolio = alloc.get('portfolio', alloc.get('portfolio_category', ''))
                alloc_amount = alloc.get('rounded_amount', alloc.get('amount', 0))
                if ucc or portfolio:
                    portfolio_display = portfolio.replace('_', ' ').title() if portfolio else 'N/A'
                    if alloc_amount and alloc_amount >= 1000:
                        alloc_html_parts.append(f"<div style='font-size: 11px; color: #6366F1; margin-top: 4px;'>{ucc} • {portfolio_display} • ₹{int(alloc_amount):,}</div>")
                    elif alloc_amount and alloc_amount < 1000:
                        alloc_html_parts.append(f"<div style='font-size: 11px; color: #9CA3AF; margin-top: 4px;'>₹{int(alloc_amount):,} (None - below ₹1000)</div>")
            alloc_details = "".join(alloc_html_parts)
        
        entries_html += f"""
        <tr>
            <td style="padding: 8px; border: 1px solid #ddd;">{cf.get('bond_name', 'N/A')}{alloc_details}</td>
            <td style="padding: 8px; border: 1px solid #ddd;">{cf.get('date', 'N/A')}</td>
            <td style="padding: 8px; border: 1px solid #ddd;">{tag.replace('_', ' ').title()}</td>
            <td style="padding: 8px; border: 1px solid #ddd; text-align: right;">₹{rounded_amount:,}</td>
        </tr>
        """
    
    if not valid_cashflows:
        raise HTTPException(status_code=400, detail="No valid cashflows to process. Principal-only tags with zero principal are skipped.")
    
    # Generate approval token with only valid cashflows
    approval_token = create_access_token(
        data={"client_id": client['id'], "cashflow_ids": valid_cashflows, "type": "reinvestment_approval"},
        expires_delta=timedelta(days=7)
    )
    
    # Update only valid cashflows with pending status
    await db.holding_cashflows.update_many(
        {"id": {"$in": valid_cashflows}},
        {"$set": {
            "approval_status": "pending",
            "approval_email_sent": True,
            "approval_email_sent_at": datetime.now(timezone.utc).isoformat()
        }}
    )
    
    # Send email (using the configured SMTP) - Use the "New MF Purchase Order" email template
    # This directs clients to login and approve through the portal
    try:
        from email_service import send_reinvestment_client_approval_email
        
        # Get the representative name (prefer sub-broker if client is linked to one)
        representative_name = 'Your Broker'
        
        # Check if client has a linked sub-broker
        if client.get('linked_subbroker_id'):
            subbroker = await db.Mfd_Ria_Partner.find_one({"id": client['linked_subbroker_id']}, {"_id": 0, "name": 1})
            if not subbroker:
                subbroker = await db.sub_brokers.find_one({"id": client['linked_subbroker_id']}, {"_id": 0, "name": 1})
            if subbroker:
                representative_name = subbroker.get('name', 'Your Broker')
        else:
            # Fall back to broker name
            broker = await db.users.find_one({"id": current_user['id']}, {"_id": 0, "name": 1})
            representative_name = broker.get('name', 'Your Broker') if broker else 'Your Broker'
        
        background_tasks.add_task(
            send_reinvestment_client_approval_email,
            client_name=client['name'],
            client_email=client_email,
            total_amount=total_amount,
            cashflows_count=len(valid_cashflows),
            approval_token=approval_token,
            broker_name=representative_name
        )
    except Exception as e:
        logger.error(f"Error sending approval email: {e}")
        # Still return success as the status was updated
    
    return {
        "message": f"Approval email sent to {client_email}",
        "cashflows_count": len(valid_cashflows),
        "total_amount": total_amount,
        "skipped_count": len(cashflows) - len(valid_cashflows)
    }


@api_router.get("/reinvestment/approve-via-link")
async def approve_reinvestment_via_link(token: str, action: str = "approve"):
    """Handle approval/rejection via email link"""
    try:
        payload = verify_token(token)
        if not payload or payload.get("type") != "reinvestment_approval":
            raise HTTPException(status_code=400, detail="Invalid or expired approval link")
        
        client_id = payload.get("client_id")
        cashflow_ids = payload.get("cashflow_ids", [])
        
        approved = action.lower() == "approve"
        
        # Get client info for logging
        client = await db.Private_Investor.find_one({"id": client_id}, {"_id": 0})
        
        # Update all cashflows in holding_cashflows
        await db.holding_cashflows.update_many(
            {"id": {"$in": cashflow_ids}},
            {"$set": {
                "client_approved": approved,
                "approval_status": "approved" if approved else "rejected",
                "approved_at": datetime.now(timezone.utc).isoformat()
            }}
        )
        
        # Also update reinvestment_logs collection
        await db.reinvestment_logs.update_many(
            {"cashflow_id": {"$in": cashflow_ids}},
            {"$set": {
                "client_approved": approved,
                "approval_status": "approved" if approved else "rejected",
                "approved_at": datetime.now(timezone.utc).isoformat()
            }}
        )
        
        # Create approval log
        await create_approval_log(
            entity_type="reinvestment",
            entity_id=cashflow_ids[0] if cashflow_ids else "unknown",
            action="client_approved" if approved else "client_rejected",
            actor_id=client_id,
            actor_role="client",
            actor_name=client.get('name', 'Client') if client else 'Client',
            details={
                "cashflow_ids": cashflow_ids,
                "broker_id": client.get('created_by') if client else None,
                "linked_subbroker_id": client.get('linked_subbroker_id') if client else None
            }
        )
        
        # If approved, trigger Kinntegraa API
        kinntegra_results = []
        if approved:
            # Get approved cashflows for API submission
            cashflows = await db.holding_cashflows.find(
                {"id": {"$in": cashflow_ids}},
                {"_id": 0}
            ).to_list(1000)
            
            # Call Kinntegra API for each approved cashflow
            for cashflow in cashflows:
                try:
                    result = await call_kinntegra_mf_buy_scheduler(cashflow, client)
                    kinntegra_results.append({
                        "cashflow_id": cashflow.get('id'),
                        "status": result.get('status', 'error'),
                        "message": result.get('message', '')
                    })
                except Exception as e:
                    logger.error(f"Error calling Kinntegra API for cashflow {cashflow.get('id')}: {e}")
                    kinntegra_results.append({
                        "cashflow_id": cashflow.get('id'),
                        "status": "error",
                        "message": str(e)
                    })
        
        return {
            "message": f"Reinvestment {'approved' if approved else 'rejected'} successfully",
            "action": action,
            "cashflows_count": len(cashflow_ids),
            "kinntegra_results": kinntegra_results if approved else None
        }
    except Exception as e:
        logger.error(f"Error in approval link: {e}")
        raise HTTPException(status_code=400, detail="Invalid or expired approval link")


@api_router.post("/reinvestment/submit-to-kinntegraa")
async def submit_to_kinntegraa(
    submission_id: str = None,
    current_user: dict = Depends(get_current_user)
):
    """Submit approved reinvestments to Kinntegraa API"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can submit to Kinntegraa")
    
    # Get pending submissions
    query = {"status": "pending_submission"}
    if submission_id:
        query["id"] = submission_id
    
    submissions = await db.kinntegraa_submissions.find(query).to_list(100)
    
    if not submissions:
        raise HTTPException(status_code=404, detail="No pending submissions found")
    
    results = []
    for submission in submissions:
        try:
            # Get cashflows
            cashflows = await db.holding_cashflows.find(
                {"id": {"$in": submission['cashflow_ids']}}
            ).to_list(1000)
            
            # Get client
            client = await db.Private_Investor.find_one({"id": submission['client_id']})
            
            # Prepare API payload (structure to be confirmed with Kinntegraa)
            api_payload = {
                "client_pan": client.get('pan_number', '') if client else '',
                "client_name": client.get('name', '') if client else '',
                "client_email": client.get('email', '') if client else '',
                "reinvestments": []
            }
            
            skipped_count = 0
            for cf in cashflows:
                tag = cf.get('reinvestment_tag', 'not_tagged')
                if tag == 'other':
                    amount = cf.get('custom_amount', 0)
                elif tag == 'principal':
                    amount = cf.get('principal_component', 0)
                    # Skip if principal-only tag but principal is zero or missing
                    if not amount or amount <= 0:
                        logger.info(f"Skipping cashflow {cf.get('id')} in API submission - principal-only with zero principal")
                        skipped_count += 1
                        continue
                elif tag == 'interest':
                    amount = cf.get('interest_component', 0) - cf.get('tds_amount', 0)
                elif tag == 'net_amount' or tag == 'both':
                    amount = cf.get('net_amount', 0)
                else:
                    continue
                
                # Round down to nearest integer for API submission
                rounded_amount = int(amount)
                
                if rounded_amount <= 0:
                    logger.info(f"Skipping cashflow {cf.get('id')} in API submission - rounded amount is zero")
                    skipped_count += 1
                    continue
                
                api_payload["reinvestments"].append({
                    "bond_name": cf.get('bond_name', ''),
                    "expected_date": cf.get('date', ''),
                    "amount": rounded_amount,  # Rounded down amount
                    "tag_type": tag
                })
            
            # TODO: Make actual API call to Kinntegraa
            # response = await httpx.post("https://api.kinntegraa.com/reinvestments", json=api_payload)
            
            # For now, mark as submitted
            await db.kinntegraa_submissions.update_one(
                {"id": submission['id']},
                {"$set": {
                    "status": "submitted",
                    "submitted_at": datetime.now(timezone.utc).isoformat(),
                    "api_payload": api_payload
                }}
            )
            
            results.append({
                "submission_id": submission['id'],
                "status": "submitted",
                "cashflows_count": len(cashflows)
            })
            
        except Exception as e:
            logger.error(f"Error submitting to Kinntegraa: {e}")
            results.append({
                "submission_id": submission['id'],
                "status": "error",
                "error": str(e)
            })
    
    return {"results": results}


@api_router.get("/reinvestment-logs")
async def get_reinvestment_logs_v2(
    client_id: str = None,
    current_user: dict = Depends(get_current_user)
):
    """Get reinvestment logs, optionally filtered by client_id"""
    query = {
        # Exclude cancelled and auto-cancelled logs - these should not appear in trade logs
        "approval_status": {"$nin": ["cancelled", "auto_cancelled", "rejected"]},
        # Only include logs that have a valid reinvestment tag (not untagged)
        "reinvestment_tag": {"$nin": ["not_tagged", None, ""]}
    }
    
    if current_user['role'] == 'broker':
        # Broker can see all logs
        if client_id:
            query['client_id'] = client_id
    elif current_user['role'] == 'sub_broker':
        # Sub-broker can only see logs for their linked clients
        linked_clients = await db.Private_Investor.find(
            {"linked_subbroker_id": current_user['id']},
            {"_id": 0, "id": 1}
        ).to_list(1000)
        client_ids = [c['id'] for c in linked_clients]
        
        if client_id:
            # If specific client requested, verify they're linked
            if client_id in client_ids:
                query['client_id'] = client_id
            else:
                return []  # Not authorized to see this client's logs
        else:
            # Show all linked clients' logs
            if client_ids:
                query['client_id'] = {'$in': client_ids}
            else:
                return []
    elif current_user['role'] == 'client':
        # Client can only see their own logs (legacy + 3-way login).
        resolved = await _resolve_client_record(current_user)
        if resolved:
            query['client_id'] = resolved['id']
        else:
            return []
    
    logs = await db.reinvestment_logs.find(
        query,
        {"_id": 0}
    ).sort("created_at", -1).to_list(5000)
    
    # Synthesize entries from holding_cashflows that have been tagged/submitted
    # but don't yet have matching reinvestment_logs rows. Mirrors the
    # /api/reinvestment/logs endpoint used by Logs → Reinv Logs, so Holdings
    # → Trades → Reinv Logs shows the same history (including legacy
    # Kinntegra-submitted repayments from before the per-allocation log
    # schema was introduced).
    cf_query = {
        "reinvestment_tag": {"$nin": ["not_tagged", None, ""]},
        "$or": [
            {"kinntegra_api_submitted": True},
            {"approval_status": {"$in": ["approved", "submitted", "client_approved"]}},
        ],
    }
    if query.get('client_id'):
        cf_query['client_id'] = query['client_id']
    submitted_cashflows = await db.holding_cashflows.find(cf_query, {"_id": 0}).to_list(20000)
    existing_cf_ids = {log.get('cashflow_id') for log in logs}
    for cf in submitted_cashflows:
        cf_id = cf.get('id')
        if not cf_id or cf_id in existing_cf_ids:
            continue
        cf_net = cf.get('net_amount', 0) or 0
        raw_allocs = cf.get('ucc_allocations') or []
        if cf.get('has_split_allocations') and raw_allocs:
            distributed = _distribute_allocation_net_amounts(raw_allocs, cf_net)
            for idx, alloc in enumerate(distributed):
                logs.append({
                    "id": f"auto_{cf_id}_{idx}",
                    "type": "reinvestment_tag_split",
                    "cashflow_id": cf_id,
                    "client_id": cf.get('client_id'),
                    "client_name": cf.get('client_name', ''),
                    "bond_id": cf.get('bond_id'),
                    "bond_name": cf.get('bond_name', ''),
                    "expected_date": cf.get('date'),
                    "mf_investment_date": alloc.get('investment_date') or cf.get('mf_investment_date'),
                    "allocation_index": idx,
                    "ucc": alloc.get('ucc'),
                    "target_ucc": alloc.get('ucc'),
                    "amount": alloc.get('amount'),
                    "net_amount": alloc.get('net_amount', alloc.get('amount')),
                    "portfolio": alloc.get('portfolio'),
                    "portfolio_category": alloc.get('portfolio'),
                    "reinvestment_tag": alloc.get('tag') or cf.get('reinvestment_tag'),
                    "total_allocations": len(distributed),
                    "total_cashflow_net_amount": cf_net,
                    "approval_status": cf.get('approval_status', 'submitted'),
                    "client_approved": cf.get('client_approved', True),
                    "kinntegra_submitted": bool(cf.get('kinntegra_api_submitted')),
                    "tagged_by": cf.get('tagged_by'),
                    "tagged_by_name": cf.get('tagged_by_name'),
                    "tagged_at": cf.get('tagged_at'),
                    "created_at": cf.get('tagged_at') or cf.get('kinntegra_submitted_at') or cf.get('created_at'),
                })
        else:
            logs.append({
                "id": f"auto_{cf_id}",
                "type": "reinvestment_tag",
                "cashflow_id": cf_id,
                "client_id": cf.get('client_id'),
                "client_name": cf.get('client_name', ''),
                "bond_id": cf.get('bond_id'),
                "bond_name": cf.get('bond_name', ''),
                "expected_date": cf.get('date'),
                "mf_investment_date": cf.get('mf_investment_date'),
                "ucc": cf.get('target_ucc'),
                "target_ucc": cf.get('target_ucc'),
                "amount": int((cf_net or 0) // 100) * 100,
                "net_amount": cf_net,
                "portfolio": cf.get('portfolio_category'),
                "portfolio_category": cf.get('portfolio_category'),
                "reinvestment_tag": cf.get('reinvestment_tag'),
                "approval_status": cf.get('approval_status', 'submitted'),
                "client_approved": cf.get('client_approved', True),
                "kinntegra_submitted": bool(cf.get('kinntegra_api_submitted')),
                "tagged_by": cf.get('tagged_by'),
                "tagged_by_name": cf.get('tagged_by_name'),
                "tagged_at": cf.get('tagged_at'),
                "created_at": cf.get('tagged_at') or cf.get('kinntegra_submitted_at') or cf.get('created_at'),
            })
        existing_cf_ids.add(cf_id)
    
    # Enrich logs with bond_name from bonds collection
    bond_ids = list(set(log.get('bond_id') for log in logs if log.get('bond_id')))
    bonds = {}
    if bond_ids:
        bonds_list = await db.Ncd_Master.find(
            {"id": {"$in": bond_ids}},
            {"_id": 0, "id": 1, "name": 1, "bond_code": 1, "issuer": 1}
        ).to_list(len(bond_ids))
        bonds = {b['id']: b for b in bonds_list}
    
    # Deduplicate logs by (cashflow_id, allocation_index) to avoid duplicates
    seen_keys = set()
    unique_logs = []
    for log in logs:
        # Create a unique key for deduplication
        dedup_key = (
            log.get('cashflow_id', ''),
            log.get('allocation_index', 0),
            log.get('client_id', '')
        )
        if dedup_key in seen_keys:
            continue
        seen_keys.add(dedup_key)
        
        # Enrich with bond name
        bond = bonds.get(log.get('bond_id'))
        if bond:
            # Set bond_name to the actual bond name (not just bond_code)
            log['bond_name'] = bond.get('name') or bond.get('issuer') or log.get('bond_name', 'Unknown')
            # Also provide bond_code for reference
            if not log.get('bond_code'):
                log['bond_code'] = bond.get('bond_code', '')
        
        unique_logs.append(log)
    
    return unique_logs


