@api_router.get("/client/verify/{token}")
async def get_client_verification_details(token: str):
    """Get client details for verification (no auth required)"""
    
    client = await db.Private_Investor.find_one({"verification_token": token}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Invalid verification token")
    
    if client.get('verification_status') == 'verified':
        raise HTTPException(status_code=400, detail="Profile already verified")
    
    # Get broker details
    broker = await db.users.find_one({"id": client['created_by']}, {"_id": 0, "password_hash": 0, "pin_hash": 0})
    
    # Get sub-broker details if linked
    subbroker = None
    if client.get('linked_subbroker_id'):
        subbroker = await db.users.find_one({"id": client['linked_subbroker_id']}, {"_id": 0, "password_hash": 0, "pin_hash": 0})
    
    return {
        "client": client,
        "broker": broker,
        "subbroker": subbroker
    }


@api_router.post("/client/verify/{token}")
async def verify_client_profile(token: str, verify: ClientVerifyProfile):
    """Client verifies their profile details"""
    
    client = await db.Private_Investor.find_one({"verification_token": token})
    if not client:
        raise HTTPException(status_code=404, detail="Invalid verification token")
    
    if client.get('verification_status') == 'verified':
        raise HTTPException(status_code=400, detail="Profile already verified")
    
    if not verify.verified:
        # Client rejected - notify broker
        notification = {
            "id": str(uuid.uuid4()),
            "type": "client_verification_rejected",
            "client_id": client['id'],
            "client_name": client['name'],
            "for_user_id": client['created_by'],
            "created_at": datetime.now(timezone.utc).isoformat(),
            "read": False
        }
        await db.notifications.insert_one(notification)
        return {"message": "Verification rejected. Broker has been notified."}
    
    # Activate the user account
    await db.users.update_one(
        {"id": client['user_id']},
        {"$set": {"is_active": True}}
    )
    
    # Update client verification status
    await db.Private_Investor.update_one(
        {"id": client['id']},
        {"$set": {
            "verification_status": "verified",
            "verified_at": datetime.now(timezone.utc).isoformat()
        }}
    )
    
    # Get default credentials
    default_password = client['pan_number'][-4:] + "1234"
    
    return {
        "message": "Profile verified successfully",
        "credentials": {
            "pan": client['pan_number'],
            "default_password": default_password,
            "default_pin": "1234",
            "note": "Please change your password and PIN after first login"
        }
    }


@api_router.get("/client/profile")
async def get_client_profile(current_user: dict = Depends(get_current_user)):
    """Get client's own profile with broker/sub-broker details"""
    
    if current_user['role'] != 'client':
        raise HTTPException(status_code=403, detail="Only clients can access this endpoint")
    
    # Get client record - try both user_id and id (they share the same ID in private investor flow)
    client = await db.Private_Investor.find_one({"user_id": current_user['id']}, {"_id": 0})
    if not client:
        client = await db.Private_Investor.find_one({"id": current_user['id']}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Client record not found")
    
    # Get broker details
    broker = await db.users.find_one({"id": client['created_by']}, {"_id": 0, "password_hash": 0, "pin_hash": 0})
    
    # Get sub-broker details if linked
    subbroker = None
    if client.get('linked_subbroker_id'):
        subbroker = await db.users.find_one({"id": client['linked_subbroker_id']}, {"_id": 0, "password_hash": 0, "pin_hash": 0})
        # Also get partner record for more details
        partner = await db.Mfd_Ria_Partner.find_one({"id": client['linked_subbroker_id']}, {"_id": 0})
        if partner and subbroker:
            subbroker['partner_details'] = partner
    
    # Calculate KYC completion status
    # KYC is complete if: Step 5 completed (all required fields filled) and verified by broker
    # OR if bulk-uploaded user has all fields AND is verified
    kyc_required_fields = ['name', 'email', 'mobile', 'pan_number', 'passport_type', 'country_of_residency']
    kyc_fields_filled = all(client.get(field) for field in kyc_required_fields)
    
    # Check onboarding step (5 = all steps complete)
    onboarding_step = client.get('onboarding_step', 1)
    
    # KYC is verified if broker has approved/verified
    kyc_verified = client.get('approval_status') == 'approved' or client.get('kyc_verified', False)
    
    # KYC is complete if:
    # 1. Normal flow: onboarding step >= 5 AND fields filled AND verified
    # 2. Bulk upload flow: fields filled AND verified (onboarding_step may not be set)
    # For bulk-uploaded users, if all required fields are filled and broker verified, KYC is complete
    kyc_complete = (onboarding_step >= 5 and kyc_fields_filled and kyc_verified) or \
                   (kyc_fields_filled and kyc_verified)
    
    return {
        "client": client,
        "broker": broker,
        "subbroker": subbroker,
        "kyc_status": {
            "complete": kyc_complete,
            "current_step": onboarding_step,
            "total_steps": 5,
            "verified_by_broker": kyc_verified,
            "fields_complete": kyc_fields_filled
        }
    }


