@api_router.post("/client/submit-kyc")
async def submit_client_kyc(kyc_data: ClientKYCSubmission, current_user: dict = Depends(get_current_user)):
    """Client submits their KYC details (steps 3-5)"""
    
    if current_user['role'] != 'client':
        raise HTTPException(status_code=403, detail="Only clients can submit KYC")
    
    # Get client record - try both user_id and id
    client = await db.Private_Investor.find_one({"user_id": current_user['id']})
    if not client:
        client = await db.Private_Investor.find_one({"id": current_user['id']})
    if not client:
        raise HTTPException(status_code=404, detail="Client record not found")
    
    # Prepare update data
    update_data = {
        "kyc_submitted": True,
        "kyc_submitted_at": datetime.now(timezone.utc).isoformat(),
        "kyc_status": "pending_verification",
        "onboarding_step": 5,  # Mark as submitted (step 5)
    }
    
    # Add all non-None fields from kyc_data
    kyc_dict = kyc_data.dict(exclude_none=True)
    update_data.update(kyc_dict)
    
    # Update client record
    await db.Private_Investor.update_one(
        {"id": client['id']},
        {"$set": update_data}
    )
    
    # Create notification for broker to verify KYC
    notification = {
        "id": str(uuid.uuid4()),
        "type": "kyc_verification_pending",
        "recipient_id": client['created_by'],
        "recipient_role": "broker",
        "client_id": client['id'],
        "client_name": client.get('name', 'Unknown'),
        "message": f"KYC submitted by {client.get('name', 'Client')} and is pending verification.",
        "status": "unread",
        "created_at": datetime.now(timezone.utc).isoformat(),
        "action_required": True,
        "metadata": {
            "passport_type": client.get('passport_type'),
            "country_of_residency": client.get('country_of_residency'),
            "opportunities": kyc_data.opportunities
        }
    }
    
    await db.notifications.insert_one(notification)
    
    logger.info(f"KYC submitted by client {client['id']}, pending broker verification")
    
    return {"message": "KYC submitted successfully. Your broker will verify your details shortly."}


@api_router.post("/client/upload-kyc-document")
async def upload_kyc_document(
    file: UploadFile = File(...),
    document_type: str = Form(...),
    current_user: dict = Depends(get_current_user)
):
    """Upload KYC document (PDF only, max 5 documents)"""
    
    if current_user['role'] != 'client':
        raise HTTPException(status_code=403, detail="Only clients can upload KYC documents")
    
    # Validate file type
    if not file.filename.lower().endswith('.pdf'):
        raise HTTPException(status_code=400, detail="Only PDF files are allowed")
    
    # Get client record - try both user_id and id
    client = await db.Private_Investor.find_one({"user_id": current_user['id']})
    if not client:
        client = await db.Private_Investor.find_one({"id": current_user['id']})
    if not client:
        raise HTTPException(status_code=404, detail="Client record not found")
    
    # Check current document count
    existing_docs = client.get('kyc_documents', [])
    if len(existing_docs) >= 5:
        raise HTTPException(status_code=400, detail="Maximum 5 documents allowed. Please delete an existing document first.")
    
    # Read file content
    content = await file.read()
    
    # Check file size (max 5MB)
    if len(content) > 5 * 1024 * 1024:
        raise HTTPException(status_code=400, detail="File size must be less than 5MB")
    
    # Store document
    doc_id = str(uuid.uuid4())
    document = {
        "id": doc_id,
        "filename": file.filename,
        "document_type": document_type,
        "content_type": "application/pdf",
        "size": len(content),
        "data": base64.b64encode(content).decode('utf-8'),
        "uploaded_at": datetime.now(timezone.utc).isoformat()
    }
    
    # Update client with new document
    await db.Private_Investor.update_one(
        {"id": client['id']},
        {"$push": {"kyc_documents": document}}
    )
    
    logger.info(f"KYC document uploaded for client {client['id']}: {document_type}")
    
    return {
        "message": "Document uploaded successfully",
        "document_id": doc_id,
        "filename": file.filename,
        "document_type": document_type
    }


@api_router.delete("/client/kyc-document/{document_id}")
async def delete_kyc_document(document_id: str, current_user: dict = Depends(get_current_user)):
    """Delete a KYC document"""
    
    if current_user['role'] != 'client':
        raise HTTPException(status_code=403, detail="Only clients can delete their KYC documents")
    
    # Get client record - try both user_id and id
    client = await db.Private_Investor.find_one({"user_id": current_user['id']})
    if not client:
        client = await db.Private_Investor.find_one({"id": current_user['id']})
    if not client:
        raise HTTPException(status_code=404, detail="Client record not found")
    
    # Remove document
    result = await db.Private_Investor.update_one(
        {"id": client['id']},
        {"$pull": {"kyc_documents": {"id": document_id}}}
    )
    
    if result.modified_count == 0:
        raise HTTPException(status_code=404, detail="Document not found")
    
    return {"message": "Document deleted successfully"}


