@api_router.post("/private-investors/{client_id}/verify-kyc")
async def verify_client_kyc(client_id: str, current_user: dict = Depends(get_current_user)):
    """Broker verifies client's KYC and enables full access"""
    
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can verify KYC")
    
    # Get client record
    client = await db.Private_Investor.find_one({"id": client_id})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    
    # Verify broker owns this client
    if client.get('created_by') != current_user['id']:
        raise HTTPException(status_code=403, detail="Access denied")
    
    # Update client KYC status
    await db.Private_Investor.update_one(
        {"id": client_id},
        {"$set": {
            "kyc_status": "verified",
            "kyc_verified": True,
            "kyc_verified_at": datetime.now(timezone.utc).isoformat(),
            "kyc_verified_by": current_user['id'],
            "approval_status": "approved"
        }}
    )
    
    # Also update the users collection
    await db.users.update_one(
        {"id": client.get('user_id') or client_id},
        {"$set": {
            "kyc_verified": True,
            "is_active": True
        }}
    )
    
    logger.info(f"KYC verified for client {client_id} by broker {current_user['id']}")
    
    return {"message": "KYC verified successfully. Client now has full access."}


