@api_router.post("/admin/bulk-download-grandfathered-navs")
async def bulk_download_grandfathered_navs(
    secret_key: str = None,
    current_user: dict = Depends(get_current_user)
):
    """
    Bulk download all grandfathered NAVs (31-Jan-2018) from mfapi.in and store in database.
    This is a one-time operation to populate the cache for fast CAS processing.
    WARNING: This operation can take 30-60 minutes to complete.
    """
    if secret_key != RESET_SECRET_KEY:
        raise HTTPException(status_code=403, detail="Invalid secret key")
    
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can perform this operation")
    
    try:
        # Check if already populated
        existing_count = await db.grandfathered_navs.count_documents({})
        
        if existing_count > 10000:
            return {
                "success": True,
                "message": f"Database already has {existing_count} grandfathered NAVs. Use force=true to re-download.",
                "existing_count": existing_count
            }
        
        # Run the bulk download (this is a long operation)
        logger.info("Starting bulk download of grandfathered NAVs...")
        
        def progress_log(current, total, scheme_name):
            if current % 500 == 0:
                logger.info(f"Progress: {current}/{total} schemes processed ({scheme_name})")
        
        summary = NAVFetcher.bulk_download_grandfathered_navs(progress_callback=progress_log)
        
        return {
            "success": True,
            "message": "Bulk download completed",
            "summary": summary
        }
    except Exception as e:
        logger.error(f"Bulk download failed: {str(e)}")
        raise HTTPException(status_code=500, detail=f"Bulk download failed: {str(e)}")


