class DataGatheringResetRequest(BaseModel):
    family_ids: List[str] = []  # Empty list means reset all
    secret_key: str


@api_router.post("/admin/reset/data-gathering")
async def reset_data_gathering(
    request: DataGatheringResetRequest,
    current_user: dict = Depends(get_current_user)
):
    """Reset data gathering families - specific families or all"""
    if request.secret_key != RESET_SECRET_KEY:
        raise HTTPException(status_code=403, detail="Invalid secret key")
    
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Access denied")
    
    try:
        deleted_counts = {}
        
        # Build query based on role and family_ids
        base_query = {}
        if current_user['role'] == 'sub_broker':
            base_query['sub_broker_id'] = current_user['id']
        
        if request.family_ids and len(request.family_ids) > 0:
            # Delete specific families
            base_query['id'] = {"$in": request.family_ids}
        
        # Delete families
        result = await db.data_gathering_families.delete_many(base_query)
        deleted_counts['data_gathering_families'] = result.deleted_count
        
        # Also delete related family members if any exist in separate collection
        if request.family_ids and len(request.family_ids) > 0:
            members_result = await db.data_gathering_members.delete_many({
                "family_id": {"$in": request.family_ids}
            })
        else:
            # Delete all members if deleting all families
            if current_user['role'] == 'sub_broker':
                # Get all family IDs for this sub-broker first
                family_docs = await db.data_gathering_families.find(
                    {"sub_broker_id": current_user['id']},
                    {"_id": 0, "id": 1}
                ).to_list(1000)
                family_ids = [f['id'] for f in family_docs]
                members_result = await db.data_gathering_members.delete_many({
                    "family_id": {"$in": family_ids}
                })
            else:
                members_result = await db.data_gathering_members.delete_many({})
        
        deleted_counts['data_gathering_members'] = members_result.deleted_count if 'members_result' in dir() else 0
        
        return {
            "success": True,
            "message": f"Deleted {deleted_counts.get('data_gathering_families', 0)} families",
            "deleted_counts": deleted_counts
        }
    except Exception as e:
        logger.error(f"Data Gathering reset failed: {str(e)}")
        raise HTTPException(status_code=500, detail=f"Reset failed: {str(e)}")


