# Constants
MAX_FRACTIONAL_INVESTMENT_USD = 50000
USD_TO_AED_RATE = 3.67  # Approximate rate
MAX_FRACTIONAL_INVESTMENT_AED = MAX_FRACTIONAL_INVESTMENT_USD * USD_TO_AED_RATE  # ~183,500 AED


def calculate_payment_schedule(unit_price: float, payment_schedule: List[dict]) -> List[dict]:
    """Calculate actual payment amounts based on percentages"""
    calculated = []
    for payment in payment_schedule:
        amount = unit_price * (payment['percentage'] / 100)
        calculated.append({
            "date": payment['date'],
            "percentage": payment['percentage'],
            "description": payment.get('description', ''),
            "amount": round(amount, 2)
        })
    return calculated


def _re_deal_id_slug(building_name: str, unit_no: str) -> str:
    """Derive the default Deal ID prefix from building_name + unit_no.
    Example: "Hyde Residences Dubai Hills" + "1802" -> "HYDE-1802".
    Takes the first 4 alnum chars of the first word of the building name
    (upper-cased), hyphen, then the cleaned unit number."""
    import re as _re
    bn = (building_name or "").strip()
    un = str(unit_no or "").strip()
    # First word, alnum-only, upper, truncated to 4 chars
    first_word = (bn.split() or [""])[0]
    base = _re.sub(r"[^A-Za-z0-9]", "", first_word).upper()[:4] or "RE"
    unit_clean = _re.sub(r"[^A-Za-z0-9]", "", un).upper() or "NA"
    return f"{base}-{unit_clean}"


async def _generate_unique_re_deal_id(building_name: str, unit_no: str, override: Optional[str] = None) -> str:
    """Return a unique Deal ID for a new Real_Estate_Master row.
    If `override` is a non-empty string and unique, it is used verbatim (uppercased).
    Otherwise a slug from building/unit is generated; on collision, suffixes
    -2, -3, ... are appended until unique."""
    if override and str(override).strip():
        candidate = str(override).strip().upper()
        existing = await db.Real_Estate_Master.find_one({"deal_id": candidate}, {"_id": 1})
        if existing:
            raise HTTPException(status_code=409, detail=f"Deal ID '{candidate}' is already in use")
        return candidate
    base = _re_deal_id_slug(building_name, unit_no)
    candidate = base
    suffix = 2
    while await db.Real_Estate_Master.find_one({"deal_id": candidate}, {"_id": 1}):
        candidate = f"{base}-{suffix}"
        suffix += 1
    return candidate


@api_router.post("/real-estate-opportunities")
async def create_real_estate_opportunity(
    opportunity_data: RealEstateOpportunityCreate, 
    current_user: dict = Depends(get_current_user)
):
    """Create a new off-plan real estate opportunity (broker or permitted sub-broker)"""
    # Check permission
    is_broker = current_user['role'] == 'broker'
    is_sub_broker_with_permission = False
    sub_broker_info = None
    broker_id = None
    
    if current_user['role'] == 'sub_broker':
        # Check if sub-broker has permission
        partner = await db.Mfd_Ria_Partner.find_one({"id": current_user['id']}, {"_id": 0})
        if partner and partner.get('can_create_real_estate', False):
            is_sub_broker_with_permission = True
            sub_broker_info = {
                "id": current_user['id'],
                "name": partner.get('name', ''),
                "partner_code": partner.get('partner_code', '')
            }
            broker_id = partner.get('created_by')  # The main broker who created this sub-broker
    
    if not is_broker and not is_sub_broker_with_permission:
        raise HTTPException(status_code=403, detail="Only brokers or authorized sub-brokers can create real estate opportunities")
    
    # Validate unit selling fee percentage (0-2.5%)
    if opportunity_data.unit_selling_fee_percentage < 0 or opportunity_data.unit_selling_fee_percentage > 2.5:
        raise HTTPException(status_code=400, detail="Unit Selling Fee must be between 0% and 2.5%")
    
    # DLD Fee is percentage of unit price
    dld_fee = opportunity_data.unit_price * opportunity_data.dld_fee_percentage / 100
    
    # Admin fee is absolute amount
    admin_fee = opportunity_data.admin_fee
    
    # Upfront amount (DLD + Admin) - paid with booking
    upfront_amount = dld_fee + admin_fee
    
    broker_fee = opportunity_data.broker_fee
    other_fees = opportunity_data.other_fees
    
    # Total cost = Unit Price + all fees
    total_cost = opportunity_data.unit_price + dld_fee + admin_fee + broker_fee + other_fees
    
    # Calculate balcony to carpet ratio
    balcony_ratio = 0
    if opportunity_data.carpet_area > 0:
        balcony_ratio = opportunity_data.balcony_area / opportunity_data.carpet_area
    
    # Payment schedule - percentages based on unit price only
    # DLD + Admin are paid upfront with booking (not part of payment schedule percentages)
    payment_schedule = []
    if opportunity_data.payment_schedule:
        payment_schedule = calculate_payment_schedule(
            opportunity_data.unit_price,  # Based on unit price only
            [p.model_dump() for p in opportunity_data.payment_schedule]
        )
    
    # Validate payment schedule totals to 100%
    if payment_schedule:
        total_percentage = sum(p['percentage'] for p in payment_schedule)
        if abs(total_percentage - 100) > 0.01:
            raise HTTPException(
                status_code=400, 
                detail=f"Payment schedule must total 100%. Current total: {total_percentage}%"
            )
    
    opportunity_dict = {
        "id": str(uuid.uuid4()),
        "deal_id": await _generate_unique_re_deal_id(
            opportunity_data.building_name,
            opportunity_data.unit_no,
            opportunity_data.deal_id,
        ),
        "building_name": opportunity_data.building_name,
        "unit_no": opportunity_data.unit_no,
        "property_type": _re_normalize_property_type(opportunity_data.property_type),
        "unit_price": opportunity_data.unit_price,
        "dld_fee_percentage": opportunity_data.dld_fee_percentage,
        "dld_fee": round(dld_fee, 2),
        "admin_fee": round(admin_fee, 2),
        "upfront_amount": round(upfront_amount, 2),  # DLD + Admin (paid with booking)
        "broker_fee": broker_fee,
        "other_fees": other_fees,
        "developer_discount": opportunity_data.developer_discount,
        "developer_discount_percentage": opportunity_data.developer_discount_percentage,
        "unit_selling_fee_percentage": opportunity_data.unit_selling_fee_percentage,
        "total_cost": round(total_cost, 2),
        "total_area": opportunity_data.total_area,
        "carpet_area": opportunity_data.carpet_area,
        "balcony_area": opportunity_data.balcony_area,
        "balcony_ratio": round(balcony_ratio, 4),
        "unit_type": opportunity_data.unit_type,
        "floor": opportunity_data.floor,
        "parking_spaces": opportunity_data.parking_spaces,
        "payment_schedule": payment_schedule,
        "total_payment_percentage_completed": 0,
        "expected_sale_rate": opportunity_data.expected_sale_rate,
        "estimated_sell_date": opportunity_data.estimated_sell_date,
        "eligible_to_sell_after_percentage": opportunity_data.eligible_to_sell_after_percentage,
        "is_eligible_to_sell": False,
        "max_investors": 4,  # Off-plan: max 4 investors
        "current_investors": 0,
        "total_invested": 0,
        "invested_percentage": 0,
        "remaining_percentage": 100,
        "investors": [],
        "developer_name": opportunity_data.developer_name,
        "location": opportunity_data.location,
        "handover_date": opportunity_data.handover_date,
        "description": opportunity_data.description,
        "view_3d_url": opportunity_data.view_3d_url,
        "images": [],
        "status": "available",
        "created_by": current_user['id'],
        # Sub-broker visibility fields
        "created_by_sub_broker": sub_broker_info,  # Sub-broker info if created by sub-broker, None if broker
        "broker_id": broker_id if is_sub_broker_with_permission else current_user['id'],  # Main broker ID
        "visible_to_all_sub_brokers": False,  # Main broker can toggle this to make it visible to all sub-brokers
        "created_at": datetime.now(timezone.utc).isoformat(),
        "updated_at": datetime.now(timezone.utc).isoformat()
    }
    
    await db.Real_Estate_Master.insert_one(opportunity_dict)
    
    # Remove _id for response
    if '_id' in opportunity_dict:
        del opportunity_dict['_id']
    
    return opportunity_dict


@api_router.get("/real-estate-opportunities")
async def get_real_estate_opportunities(
    status: Optional[str] = None,
    property_type: Optional[str] = None,
    page: int = 1,
    limit: int = 50,
    current_user: dict = Depends(get_current_user)
):
    """Get all real estate opportunities with pagination and optimized fields"""
    query = {}
    
    # Role-based visibility filtering
    if current_user['role'] == 'broker':
        # Brokers see all opportunities they own (created by them or their sub-brokers)
        # Support both new broker_id field and legacy created_by field
        query["$or"] = [
            {"broker_id": current_user['id']},
            {"created_by": current_user['id'], "broker_id": {"$exists": False}}  # Legacy data without broker_id
        ]
    elif current_user['role'] == 're_broker':
        # RE Brokers see ONLY their own real estate opportunities
        # This ensures complete data isolation from main broker and other RE brokers
        query["$or"] = [
            {"re_broker_id": current_user['id']},
            {"created_by": current_user['id']}
        ]
    elif current_user['role'] == 'sub_broker':
        # Sub-brokers see:
        # 1. Opportunities they created themselves
        # 2. Opportunities visible to all sub-brokers (set by main broker)
        # 3. Broker-created opportunities (visible_to_all_sub_brokers True or broker-created without sub_broker field)
        partner = await db.Mfd_Ria_Partner.find_one({"id": current_user['id']}, {"_id": 0, "created_by": 1})
        broker_id = partner.get('created_by') if partner else None
        if broker_id:
            query["$or"] = [
                {"created_by": current_user['id']},  # Own opportunities
                {"broker_id": broker_id, "visible_to_all_sub_brokers": True},  # Broker shared with all
                {"broker_id": broker_id, "created_by_sub_broker": None},  # Broker-created (new format)
                {"created_by": broker_id, "broker_id": {"$exists": False}}  # Broker-created (legacy format)
            ]
        else:
            query["created_by"] = current_user['id']
    elif current_user['role'] == 'client':
        # Clients see:
        # 1. Broker-created opportunities
        # 2. Sub-broker created opportunities ONLY if tagged to that sub-broker
        client = await db.Private_Investor.find_one({"id": current_user['id']}, {"_id": 0, "linked_subbroker_id": 1, "broker_id": 1, "created_by": 1})
        if client:
            broker_id = client.get('broker_id') or client.get('created_by')
            linked_subbroker_id = client.get('linked_subbroker_id')
            conditions = []
            if broker_id:
                # Broker-created opportunities (both new and legacy format)
                conditions.append({"broker_id": broker_id, "created_by_sub_broker": None})
                conditions.append({"created_by": broker_id, "broker_id": {"$exists": False}})
            if linked_subbroker_id:
                # Sub-broker's opportunities if client is tagged to them
                conditions.append({"created_by": linked_subbroker_id})
            if conditions:
                query["$or"] = conditions
            else:
                # No access if no broker/subbroker link
                query["_id"] = None  # Returns nothing
    
    if status:
        query["status"] = status
    
    if property_type:
        query["property_type"] = property_type
    
    # Optimized projection - include all fields needed for list view and edit
    projection = {
        "_id": 0,
        "id": 1,
        "deal_id": 1,
        "building_name": 1,
        "project_name": 1,
        "developer_name": 1,
        "unit_no": 1,
        "unit_type": 1,
        "location": 1,
        "floor": 1,
        "parking_spaces": 1,
        "description": 1,
        "total_area": 1,
        "carpet_area": 1,
        "balcony_area": 1,
        "total_cost": 1,
        "unit_price": 1,
        "dld_fee": 1,
        "dld_fee_percentage": 1,
        "admin_fee": 1,
        "broker_fee": 1,
        "brokerage_fee": 1,
        "other_fees": 1,
        "developer_discount": 1,
        "developer_discount_percentage": 1,
        "unit_selling_fee_percentage": 1,
        "selling_fee_percentage": 1,
        "price_per_sqft": 1,
        "expected_xirr": 1,
        "expected_sale_rate": 1,
        "estimated_sell_date": 1,
        "eligible_to_sell_after_percentage": 1,
        "payment_schedule": 1,
        "status": 1,
        "invested_percentage": 1,
        "max_co_owners": 1,
        "handover_date": 1,
        "view_3d_url": 1,
        "images": 1,
        "presentations": 1,
        "created_at": 1,
        "investors": 1,
        "interested_count": 1,
        "current_investors": 1,
        "total_payment_percentage_completed": 1,
        # New visibility fields
        "created_by": 1,
        "created_by_sub_broker": 1,
        "broker_id": 1,
        "visible_to_all_sub_brokers": 1,
    }
    
    skip = (page - 1) * limit
    
    opportunities = await db.Real_Estate_Master.find(
        query, projection
    ).sort("created_at", -1).skip(skip).limit(limit).to_list(limit)
    
    # Building-level fallback: if a unit has no images/presentations of its
    # own, surface whatever is set on a sibling unit of the same building.
    for opp in opportunities:
        await _re_apply_media_fallback(opp)
    
    # Get total count for pagination info
    total = await db.Real_Estate_Master.count_documents(query)
    
    return {
        "data": opportunities,
        "pagination": {
            "page": page,
            "limit": limit,
            "total": total,
            "pages": (total + limit - 1) // limit
        }
    }


@api_router.get("/real-estate-opportunities/client/{client_id}")
async def get_client_real_estate_investments(
    client_id: str,
    current_user: dict = Depends(get_current_user)
):
    """List all real-estate holdings for a client. Driven by the flat
    `Real_Estate_Investor` collection (source of truth for investor-level
    data) and enriched with opportunity-level fields from `Real_Estate_Master`
    (payment schedule, sale details, images, etc.)."""
    if current_user['role'] not in ['broker', 'sub_broker', 'client']:
        raise HTTPException(status_code=403, detail="Access denied")
    # Clients may only view their own investments.
    if current_user['role'] == 'client' and client_id != current_user['id'] and client_id != current_user.get('client_id'):
        raise HTTPException(status_code=403, detail="Access denied")

    # 1) Pull every investor row for this client from the flat mirror
    investor_rows = await db.Real_Estate_Investor.find(
        {"client_id": client_id},
        {"_id": 0}
    ).to_list(1000)
    if not investor_rows:
        return []

    # 2) Fetch the parent opportunities in one query
    opp_ids = list({r.get("opportunity_id") for r in investor_rows if r.get("opportunity_id")})
    opps_cursor = db.Real_Estate_Master.find({"id": {"$in": opp_ids}}, {"_id": 0})
    opps_by_id = {o.get("id"): o for o in await opps_cursor.to_list(1000)}

    client_investments = []
    for inv in investor_rows:
        opp = opps_by_id.get(inv.get("opportunity_id")) or {}

        # Count verified payments for this investor (kept for the
        # payments_completed progress bar). Fall back to the opportunity's
        # `investor_payments` array so we don't regress older records.
        opp_payments = [
            p for p in (opp.get("investor_payments") or [])
            if p.get("investor_id") == client_id and p.get("status") == "verified"
        ]
        total_milestones = len(opp.get("payment_schedule") or [])
        payments_completed = len(opp_payments)

        client_investments.append({
            "id": opp.get("id"),
            "opportunity_id": opp.get("id"),
            "deal_id": opp.get("deal_id"),
            "building_name": opp.get("building_name") or inv.get("opportunity_building_name"),
            "project_name": opp.get("project_name"),
            "developer_name": opp.get("developer_name"),
            "unit_no": opp.get("unit_no") or inv.get("opportunity_unit_no"),
            "unit_number": opp.get("unit_no") or inv.get("opportunity_unit_no"),
            "floor": opp.get("floor"),
            "unit_type": opp.get("unit_type"),
            "unit_price": opp.get("unit_price") or inv.get("opportunity_unit_price"),
            # Fee components (full 100% values) — frontend pro-rates by share_percentage
            "dld_fee": opp.get("dld_fee", 0),
            "dld_fee_percentage": opp.get("dld_fee_percentage", 4),
            "admin_fee": opp.get("admin_fee", 0),
            "broker_fee": opp.get("broker_fee", 0),
            "other_fees": opp.get("other_fees", 0),
            "status": opp.get("status"),
            # investor-level fields (from the flat collection)
            "share_percentage": inv.get("share_percentage", 0),
            "investment_amount": inv.get("amount", 0),
            "invested_at": inv.get("invested_at"),
            "investor_id": inv.get("id"),
            "payments": inv.get("payments") or [],
            "passport_details": inv.get("passport_details"),
            "passport_document": inv.get("passport_document"),
            # opportunity-level fields (for UI cards)
            "payment_schedule": opp.get("payment_schedule") or [],
            "payments_completed": payments_completed,
            "payments_completed_percent": round(
                (payments_completed / total_milestones * 100) if total_milestones > 0 else 0, 1
            ),
            "total_area": opp.get("total_area", 0),
            "carpet_area": opp.get("carpet_area", 0),
            "balcony_area": opp.get("balcony_area", 0),
            "handover_date": opp.get("handover_date"),
            "expected_sale_rate": opp.get("expected_sale_rate", 0),
            "estimated_sell_date": opp.get("estimated_sell_date"),
            "expected_sale_date": opp.get("estimated_sell_date"),
            "expected_sale_value": opp.get("expected_sale_value")
                or (opp.get("total_area", 0) * opp.get("expected_sale_rate", 0)),
            "location": opp.get("location"),
            "images": opp.get("images", []),
            # total cost (from mirror for fast access, falls back to opp)
            "total_cost_incl_fees": opp.get("total_cost_incl_fees") or inv.get("opportunity_total_cost"),
            # Source provenance — confirms the Holdings view is now reading
            # from Real_Estate_Investor instead of the embedded array.
            "source_collection": "Real_Estate_Investor",
        })

    return client_investments


@api_router.get("/real-estate-opportunities/{opportunity_id}")
async def get_real_estate_opportunity(
    opportunity_id: str,
    current_user: dict = Depends(get_current_user)
):
    """Get a specific real estate opportunity"""
    opportunity = await db.Real_Estate_Master.find_one({"id": opportunity_id}, {"_id": 0})
    
    if not opportunity:
        raise HTTPException(status_code=404, detail="Real estate opportunity not found")
    
    # Building-level fallback: if this unit has no images/presentations of its
    # own, surface the building's shared set.
    await _re_apply_media_fallback(opportunity)
    
    return opportunity


@api_router.put("/real-estate-opportunities/{opportunity_id}")
async def update_real_estate_opportunity(
    opportunity_id: str,
    update_data: RealEstateOpportunityUpdate,
    current_user: dict = Depends(get_current_user)
):
    """Update a real estate opportunity (broker can update all, sub-broker can update own)"""
    if current_user['role'] == 'broker':
        # Broker can update their own opportunities AND sub-broker created opportunities
        # Support both new broker_id field and legacy created_by field
        opportunity = await db.Real_Estate_Master.find_one({
            "id": opportunity_id,
            "$or": [
                {"broker_id": current_user['id']},
                {"created_by": current_user['id'], "broker_id": {"$exists": False}},  # Legacy data
                {"created_by": current_user['id'], "broker_id": None}  # Null broker_id
            ]
        })
    elif current_user['role'] == 'sub_broker':
        # Sub-broker can only update their own opportunities
        opportunity = await db.Real_Estate_Master.find_one({
            "id": opportunity_id, 
            "created_by": current_user['id']
        })
    else:
        raise HTTPException(status_code=403, detail="Only brokers and sub-brokers can update real estate opportunities")
    
    if not opportunity:
        raise HTTPException(status_code=404, detail="Real estate opportunity not found")
    
    # Build update dict with only provided fields
    update_dict = {k: v for k, v in update_data.model_dump().items() if v is not None}
    
    # Handle field name aliases
    if 'unit_selling_fee_percentage' in update_dict:
        update_dict['selling_fee_percentage'] = update_dict.pop('unit_selling_fee_percentage')
    if 'brokerage_fee' in update_dict and 'broker_fee' not in update_dict:
        update_dict['broker_fee'] = update_dict.pop('brokerage_fee')
    
    if not update_dict:
        raise HTTPException(status_code=400, detail="No fields to update")
    
    # Recalculate totals if any pricing field changed
    if any(k in update_dict for k in ['unit_price', 'dld_fee', 'admin_fee', 'broker_fee', 'brokerage_fee', 'other_fees']):
        unit_price = update_dict.get('unit_price', opportunity.get('unit_price', 0))
        dld_fee = update_dict.get('dld_fee', opportunity.get('dld_fee', 0))
        admin_fee = update_dict.get('admin_fee', opportunity.get('admin_fee', 0))
        broker_fee = update_dict.get('broker_fee', opportunity.get('broker_fee', opportunity.get('brokerage_fee', 0)))
        other_fees = update_dict.get('other_fees', opportunity.get('other_fees', 0))
        
        total_cost = unit_price + dld_fee + admin_fee + broker_fee + other_fees
        update_dict['total_cost'] = total_cost
        
        # Recalculate units
        UNIT_VALUE_AED = 500
        total_units = int(total_cost // UNIT_VALUE_AED)
        if total_units == 0:
            total_units = 1
        update_dict['total_units'] = total_units
        update_dict['unit_value'] = UNIT_VALUE_AED
        units_sold = opportunity.get('units_sold', 0)
        update_dict['units_available'] = total_units - units_sold
    
    # Recalculate balcony ratio if area fields changed
    if any(k in update_dict for k in ['carpet_area', 'balcony_area']):
        carpet_area = update_dict.get('carpet_area', opportunity.get('carpet_area', 0))
        balcony_area = update_dict.get('balcony_area', opportunity.get('balcony_area', 0))
        if carpet_area and carpet_area > 0:
            update_dict['balcony_ratio'] = round(balcony_area / carpet_area, 4)
    
    update_dict['updated_at'] = datetime.now(timezone.utc).isoformat()
    
    await db.Real_Estate_Master.update_one(
        {"id": opportunity_id},
        {"$set": update_dict}
    )
    
    updated = await db.Real_Estate_Master.find_one({"id": opportunity_id}, {"_id": 0})
    return updated


@api_router.delete("/real-estate-opportunities/{opportunity_id}")
async def delete_real_estate_opportunity(
    opportunity_id: str,
    force: bool = False,
    current_user: dict = Depends(get_current_user)
):
    """Delete a real estate opportunity (broker can delete all, sub-broker can delete own)
    
    Args:
        opportunity_id: ID of the opportunity to delete
        force: If True, delete even if there are investors (use with caution)
    """
    if current_user['role'] == 'broker':
        # Broker can delete their own opportunities AND sub-broker created opportunities
        # Support both new broker_id field and legacy created_by field
        opportunity = await db.Real_Estate_Master.find_one({
            "id": opportunity_id,
            "$or": [
                {"broker_id": current_user['id']},
                {"created_by": current_user['id'], "broker_id": {"$exists": False}},  # Legacy data
                {"created_by": current_user['id'], "broker_id": None}  # Null broker_id
            ]
        })
    elif current_user['role'] == 'sub_broker':
        # Sub-broker can only delete their own opportunities
        opportunity = await db.Real_Estate_Master.find_one({
            "id": opportunity_id, 
            "created_by": current_user['id']
        })
    else:
        raise HTTPException(status_code=403, detail="Only brokers and sub-brokers can delete real estate opportunities")
    
    if not opportunity:
        raise HTTPException(status_code=404, detail="Real estate opportunity not found")
    
    investor_count = opportunity.get('current_investors', 0)
    if investor_count > 0 and not force:
        raise HTTPException(
            status_code=400, 
            detail=f"This property has {investor_count} investor(s). Add ?force=true to delete anyway."
        )
    
    await db.Real_Estate_Master.delete_one({"id": opportunity_id})
    
    return {"message": "Real estate opportunity deleted successfully"}


@api_router.put("/real-estate-opportunities/{opportunity_id}/visibility")
async def toggle_real_estate_visibility(
    opportunity_id: str,
    visible_to_all_sub_brokers: bool,
    current_user: dict = Depends(get_current_user)
):
    """Toggle visibility of a sub-broker created property to all sub-brokers (broker only)"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can change visibility settings")
    
    opportunity = await db.Real_Estate_Master.find_one({
        "id": opportunity_id, 
        "broker_id": current_user['id']
    })
    
    if not opportunity:
        raise HTTPException(status_code=404, detail="Real estate opportunity not found")
    
    await db.Real_Estate_Master.update_one(
        {"id": opportunity_id},
        {"$set": {
            "visible_to_all_sub_brokers": visible_to_all_sub_brokers,
            "updated_at": datetime.now(timezone.utc).isoformat()
        }}
    )
    
    return {
        "message": f"Visibility {'enabled' if visible_to_all_sub_brokers else 'disabled'} for all sub-brokers",
        "visible_to_all_sub_brokers": visible_to_all_sub_brokers
    }


def _re_slug(s: str) -> str:
    """Slugify a building / unit name for filesystem paths."""
    import re as _re_mod
    s = (s or "").strip().lower()
    s = _re_mod.sub(r'[^a-z0-9]+', '_', s)
    return s.strip('_') or 'unknown'


# Canonical property-type vocabulary. Accepts a few common spellings / labels
# and maps them back to one of the canonical slugs.
RE_PROPERTY_TYPE_CANON = {
    "off_plan", "ready", "secondary", "rental",
}
RE_PROPERTY_TYPE_ALIASES = {
    "off_plan": "off_plan",
    "off-plan": "off_plan",
    "offplan": "off_plan",
    "off plan": "off_plan",
    "ready": "ready",
    "ready to move": "ready",
    "ready-to-move": "ready",
    "secondary": "secondary",
    "resale": "secondary",
    "rental": "rental",
    "rent": "rental",
    "for rent": "rental",
}


def _re_normalize_property_type(value, default: str = "off_plan") -> str:
    """Map a free-text property type to one of the canonical slugs."""
    if value is None:
        return default
    raw = str(value).strip().lower()
    if not raw:
        return default
    if raw in RE_PROPERTY_TYPE_CANON:
        return raw
    return RE_PROPERTY_TYPE_ALIASES.get(raw, default)


def _re_media_dirs(opportunity: dict):
    """Return per-unit (images_dir, presentations_dir, images_rel, presentations_rel).

    Kept for backwards compat in case a caller needs the per-unit path. New
    writes should use _re_shared_media_dirs() instead so duplicates across
    units in the same building share a single physical file on disk.
    """
    building_slug = _re_slug(opportunity.get('building_name'))
    unit_slug = _re_slug(str(opportunity.get('unit_no', '')))
    base_rel = f"real_estate/{building_slug}/{unit_slug}"
    images_rel = f"{base_rel}/images"
    presentations_rel = f"{base_rel}/presentations"
    images_dir = f"/app/uploads/{images_rel}"
    presentations_dir = f"/app/uploads/{presentations_rel}"
    return images_dir, presentations_dir, images_rel, presentations_rel


def _re_shared_media_dirs(opportunity: dict):
    """Shared per-building pool — one physical copy reused across every unit.

    Returns (images_dir, presentations_dir, images_rel, presentations_rel).
    """
    building_slug = _re_slug(opportunity.get('building_name'))
    base_rel = f"real_estate/{building_slug}/_shared"
    images_rel = f"{base_rel}/images"
    presentations_rel = f"{base_rel}/presentations"
    images_dir = f"/app/uploads/{images_rel}"
    presentations_dir = f"/app/uploads/{presentations_rel}"
    return images_dir, presentations_dir, images_rel, presentations_rel


async def _re_shared_file_in_use(opportunity_id: str, building_name: str, field: str, saved_path: str) -> bool:
    """True if any OTHER opportunity in the same building still references saved_path.

    Used by delete endpoints so we only remove a physical file when no unit
    still references it.
    """
    if not saved_path:
        return False
    query = {
        "building_name": building_name,
        "id": {"$ne": opportunity_id},
        f"{field}.saved_path": saved_path,
    }
    return await db.Real_Estate_Master.count_documents(query, limit=1) > 0


# Cache for building-level fallback media, keyed by (building_name, field).
# Cleared whenever a unit uploads/deletes (handled inline in those endpoints).
_re_building_media_cache: dict = {}


async def _re_building_fallback_media(building_name: str, field: str) -> list:
    """Return a representative media list for a building, sourced from whichever
    sibling unit has the most entries. Used when a specific unit has no media
    of its own so the UI can still show building-level photos / brochures.
    """
    if not building_name:
        return []
    cache_key = (building_name, field)
    cached = _re_building_media_cache.get(cache_key)
    if cached is not None:
        return cached
    best: list = []
    async for doc in db.Real_Estate_Master.find(
        {"building_name": building_name, f"{field}.0": {"$exists": True}},
        {"_id": 0, f"{field}": 1}
    ):
        items = doc.get(field) or []
        if len(items) > len(best):
            best = items
    # Strip per-unit identifiers from the URL/id so the frontend fetches via
    # the representative unit that actually owns the DB entry.
    _re_building_media_cache[cache_key] = best
    return best


def _re_invalidate_building_cache(building_name: str):
    if not building_name:
        return
    for field in ('images', 'presentations'):
        _re_building_media_cache.pop((building_name, field), None)


async def _re_apply_media_fallback(doc: dict) -> dict:
    """If a unit has no images/presentations of its own, fill them in with
    whatever sibling unit of the same building has the largest set. This keeps
    the response stable for the frontend (same shape, same API URL pattern)
    without duplicating DB rows.
    """
    if not doc:
        return doc
    bname = doc.get('building_name') or ''
    for field in ('images', 'presentations'):
        if not (doc.get(field) or []):
            fallback = await _re_building_fallback_media(bname, field)
            if fallback:
                doc[field] = fallback
    return doc


@api_router.post("/real-estate-opportunities/{opportunity_id}/images")
async def upload_opportunity_images(
    opportunity_id: str,
    files: List[UploadFile] = File(...),
    current_user: dict = Depends(get_current_user)
):
    """Upload images for a real estate opportunity (max 20 images).

    Files are persisted to disk under /app/uploads/real_estate/<building_slug>/<unit_slug>/images/.
    Silently dedupes against existing images using (filename, size).
    """
    if current_user['role'] == 'broker':
        opportunity = await db.Real_Estate_Master.find_one({
            "id": opportunity_id,
            "$or": [
                {"broker_id": current_user['id']},
                {"created_by": current_user['id']}
            ]
        })
    elif current_user['role'] == 'sub_broker':
        opportunity = await db.Real_Estate_Master.find_one({
            "id": opportunity_id, 
            "created_by": current_user['id']
        })
    else:
        raise HTTPException(status_code=403, detail="Only brokers and sub-brokers can upload images")
    
    if not opportunity:
        raise HTTPException(status_code=404, detail="Real estate opportunity not found")
    
    current_images = opportunity.get('images', [])
    existing_keys = {(img.get('filename'), img.get('size')) for img in current_images}
    
    # Validate file types
    allowed_types = ['image/jpeg', 'image/png', 'image/webp', 'image/gif']
    new_images = []
    skipped_duplicates = []
    
    images_dir, _, images_rel, _ = _re_shared_media_dirs(opportunity)
    os.makedirs(images_dir, exist_ok=True)
    
    import hashlib
    
    for file in files:
        if file.content_type not in allowed_types:
            raise HTTPException(
                status_code=400, 
                detail=f"Invalid file type: {file.content_type}. Allowed: JPEG, PNG, WebP, GIF"
            )
        
        content = await file.read()
        key = (file.filename, len(content))
        if key in existing_keys:
            skipped_duplicates.append(file.filename)
            continue
        existing_keys.add(key)
        
        # Content-hash the file so duplicates across units in the same
        # building share one physical copy on disk.
        digest = hashlib.sha256(content).hexdigest()
        file_ext = (file.filename.rsplit('.', 1)[-1] if '.' in file.filename else 'jpg').lower()
        saved_filename = f"{digest}.{file_ext}"
        file_path = os.path.join(images_dir, saved_filename)
        if not os.path.exists(file_path):
            with open(file_path, 'wb') as f:
                f.write(content)
        
        image_id = str(uuid.uuid4())
        image_data = {
            "id": image_id,
            "filename": file.filename,
            "saved_filename": saved_filename,
            "saved_path": f"{images_rel}/{saved_filename}",  # shared pool, relative to /app/uploads/
            "content_type": file.content_type,
            "size": len(content),
            "url": f"/api/real-estate-opportunities/{opportunity_id}/images/{image_id}",
            "uploaded_at": datetime.now(timezone.utc).isoformat()
        }
        new_images.append(image_data)
    
    # Check total image limit AFTER dedupe so re-uploading the same set doesn't fail
    if len(current_images) + len(new_images) > 20:
        raise HTTPException(
            status_code=400,
            detail=f"Maximum 20 images allowed. Currently have {len(current_images)}, trying to add {len(new_images)} new"
        )
    
    # Update opportunity with new images
    updated_images = current_images + new_images
    
    await db.Real_Estate_Master.update_one(
        {"id": opportunity_id},
        {"$set": {"images": updated_images, "updated_at": datetime.now(timezone.utc).isoformat()}}
    )
    _re_invalidate_building_cache(opportunity.get('building_name', ''))
    
    return {
        "message": f"Successfully uploaded {len(new_images)} images" + (
            f" ({len(skipped_duplicates)} duplicate(s) skipped)" if skipped_duplicates else ""
        ),
        "uploaded": len(new_images),
        "skipped": len(skipped_duplicates),
        "skipped_files": skipped_duplicates,
        "total_images": len(updated_images),
        "image_ids": [img['id'] for img in new_images]
    }


@api_router.get("/real-estate-opportunities/{opportunity_id}/images/{image_id}")
async def download_opportunity_image(opportunity_id: str, image_id: str):
    """Serve a property image from disk (with graceful legacy base64 fallback).

    Also supports building-level fallback: when a unit has no images of its
    own, the list/get API surfaces sibling-unit images. Requests hitting those
    URLs carry this unit's id + the sibling's image_id — we look the image up
    across any unit in the same building if not found locally.
    """
    from fastapi.responses import FileResponse, Response
    
    opportunity = await db.Real_Estate_Master.find_one({"id": opportunity_id})
    if not opportunity:
        raise HTTPException(status_code=404, detail="Real estate opportunity not found")
    
    image = next((i for i in opportunity.get('images', []) if i.get('id') == image_id), None)
    if not image:
        # Building-level lookup — find the image on any sibling unit.
        sibling = await db.Real_Estate_Master.find_one(
            {
                "building_name": opportunity.get('building_name', ''),
                "images.id": image_id,
            },
            {"_id": 0, "images": 1}
        )
        if sibling:
            image = next((i for i in (sibling.get('images') or []) if i.get('id') == image_id), None)
    if not image:
        raise HTTPException(status_code=404, detail="Image not found")
    
    content_type = image.get('content_type', 'image/jpeg')
    # Preferred: served from disk
    saved_path = image.get('saved_path')
    if saved_path:
        abs_path = os.path.join('/app/uploads', saved_path)
        # Defence in depth: if the local file is missing (cold pod, background
        # restore still running), pull it back from durable Object Storage on
        # demand so the client sees the image immediately.
        if not os.path.exists(abs_path):
            try:
                from uploads_persist import ensure_on_disk as _uploads_ensure
                await _uploads_ensure(saved_path)
            except Exception:
                pass
        if os.path.exists(abs_path):
            return FileResponse(path=abs_path, media_type=content_type, filename=image.get('filename'))
    # Legacy: base64 inline in DB
    encoded = image.get('data')
    if encoded:
        import base64
        try:
            raw = base64.b64decode(encoded)
            return Response(content=raw, media_type=content_type)
        except Exception:
            pass
    raise HTTPException(status_code=404, detail="Image file not found on server")


@api_router.delete("/real-estate-opportunities/{opportunity_id}/images/{image_id}")
async def delete_opportunity_image(
    opportunity_id: str,
    image_id: str,
    current_user: dict = Depends(get_current_user)
):
    """Delete a specific image from a real estate opportunity (and its disk file)."""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can delete images")
    
    opportunity = await db.Real_Estate_Master.find_one({
        "id": opportunity_id,
        "$or": [
            {"broker_id": current_user['id']},
            {"created_by": current_user['id']}
        ]
    })
    
    if not opportunity:
        raise HTTPException(status_code=404, detail="Real estate opportunity not found")
    
    current_images = opportunity.get('images', [])
    target = next((img for img in current_images if img.get('id') == image_id), None)
    if not target:
        raise HTTPException(status_code=404, detail="Image not found")
    
    # Remove disk file only if no other unit in the same building still
    # references the same saved_path (shared pool semantics).
    saved_path = target.get('saved_path')
    if saved_path and not await _re_shared_file_in_use(
        opportunity_id, opportunity.get('building_name', ''), 'images', saved_path
    ):
        abs_path = os.path.join('/app/uploads', saved_path)
        try:
            if os.path.exists(abs_path):
                os.remove(abs_path)
        except Exception:
            pass
    
    updated_images = [img for img in current_images if img.get('id') != image_id]
    
    await db.Real_Estate_Master.update_one(
        {"id": opportunity_id},
        {"$set": {"images": updated_images, "updated_at": datetime.now(timezone.utc).isoformat()}}
    )
    _re_invalidate_building_cache(opportunity.get('building_name', ''))
    
    return {"message": "Image deleted successfully", "remaining_images": len(updated_images)}


@api_router.post("/real-estate-opportunities/{opportunity_id}/videos")
async def upload_opportunity_videos(
    opportunity_id: str,
    files: List[UploadFile] = File(...),
    current_user: dict = Depends(get_current_user)
):
    """Upload videos for a real estate opportunity (max 5 videos, max 100MB each)"""
    if current_user['role'] not in ['broker', 'sub_broker', 're_broker']:
        raise HTTPException(status_code=403, detail="Access denied")
    
    # Find opportunity based on role
    if current_user['role'] == 'broker':
        opportunity = await db.Real_Estate_Master.find_one({
            "id": opportunity_id, 
            "$or": [
                {"broker_id": current_user['id']},
                {"created_by": current_user['id']}
            ]
        })
    else:
        opportunity = await db.Real_Estate_Master.find_one({
            "id": opportunity_id, 
            "created_by": current_user['id']
        })
    
    if not opportunity:
        raise HTTPException(status_code=404, detail="Real estate opportunity not found")
    
    current_videos = opportunity.get('videos', [])
    
    # Check total video limit
    if len(current_videos) + len(files) > 5:
        raise HTTPException(
            status_code=400, 
            detail=f"Maximum 5 videos allowed. Currently have {len(current_videos)}, trying to add {len(files)}"
        )
    
    # Validate file types and size
    allowed_types = ['video/mp4', 'video/webm', 'video/quicktime', 'video/x-msvideo', 'video/mpeg']
    max_size = 100 * 1024 * 1024  # 100MB
    new_videos = []
    
    # Create uploads directory if it doesn't exist
    import os
    upload_dir = "/app/uploads/videos"
    os.makedirs(upload_dir, exist_ok=True)
    
    for file in files:
        if file.content_type not in allowed_types:
            raise HTTPException(
                status_code=400, 
                detail=f"Invalid file type: {file.content_type}. Allowed: MP4, WebM, MOV, AVI, MPEG"
            )
        
        # Read file content
        content = await file.read()
        
        if len(content) > max_size:
            raise HTTPException(
                status_code=400,
                detail=f"Video {file.filename} exceeds 100MB limit"
            )
        
        # Save video to disk (better for large files than base64 in DB)
        video_id = str(uuid.uuid4())
        file_ext = file.filename.split('.')[-1] if '.' in file.filename else 'mp4'
        saved_filename = f"{video_id}.{file_ext}"
        file_path = f"{upload_dir}/{saved_filename}"
        
        with open(file_path, 'wb') as f:
            f.write(content)
        
        video_data = {
            "id": video_id,
            "filename": file.filename,
            "saved_filename": saved_filename,
            "content_type": file.content_type,
            "size": len(content),
            "url": f"/api/uploads/videos/{saved_filename}",
            "uploaded_at": datetime.now(timezone.utc).isoformat(),
            "uploaded_by": current_user['id']
        }
        new_videos.append(video_data)
    
    # Update opportunity with new videos
    updated_videos = current_videos + new_videos
    
    await db.Real_Estate_Master.update_one(
        {"id": opportunity_id},
        {"$set": {"videos": updated_videos, "updated_at": datetime.now(timezone.utc).isoformat()}}
    )
    
    return {
        "message": f"Successfully uploaded {len(new_videos)} videos",
        "total_videos": len(updated_videos),
        "videos": [{"id": v['id'], "filename": v['filename'], "url": v['url']} for v in new_videos]
    }


