@api_router.delete("/login-credentials/{login_id}/{login_type}")
async def delete_login_credential(
    login_id: str,
    login_type: str,
    current_user: dict = Depends(get_current_user),
):
    """Broker-only — remove a specific (login_id, login_type) row from
    Login_Credentials. Use after `/login-credentials/duplicates` identifies
    a wrong row (e.g. the accidental broker entry for a Private Investor's
    PAN). Also detaches the orphaned reference doc so the user can't be
    silently re-elevated by re-running the seeder.
    """
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can delete credentials")
    res = await db.Login_Credentials.delete_one({
        "login_id": (login_id or "").strip().upper(),
        "login_type": login_type,
    })
    return {
        "deleted": res.deleted_count,
        "login_id": login_id,
        "login_type": login_type,
    }


@api_router.get("/login-credentials/duplicates")
async def list_login_credential_duplicates(
    current_user: dict = Depends(get_current_user),
):
    """Broker-only — find any `login_id` that has multiple Login_Credentials
    rows (i.e. registered under more than one login_type). These are the
    silent-elevation cases (e.g. a Private Investor PAN that was also
    accidentally seeded as a broker user) that produce wrong-sidebar bugs.
    """
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can audit credentials")
    pipeline = [
        {"$group": {
            "_id": "$login_id",
            "rows": {"$push": {
                "login_type": "$login_type",
                "reference_id": "$reference_id",
                "reference_collection": "$reference_collection",
                "name": "$name",
                "email": "$email",
                "updated_at": "$updated_at",
            }},
            "count": {"$sum": 1},
        }},
        {"$match": {"count": {"$gt": 1}}},
        {"$sort": {"count": -1, "_id": 1}},
    ]
    duplicates = await db.Login_Credentials.aggregate(pipeline).to_list(2000)
    return {
        "total_duplicate_login_ids": len(duplicates),
        "duplicates": [
            {"login_id": d["_id"], "count": d["count"], "rows": d["rows"]}
            for d in duplicates
        ],
    }


@api_router.post("/login-credentials/{login_id}/reset")
async def reset_login_credential(
    login_id: str,
    current_user: dict = Depends(get_current_user),
):
    """Broker-only — reset a user's password + PIN back to the defaults
    (`kinntegraa123` / `1234`). Does NOT auto-email the user — use the
    `/resend` endpoint for that."""
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can reset credentials")
    cred = await _lc_find_by_login(db, login_id)
    if not cred:
        raise HTTPException(status_code=404, detail="Login credential not found")
    await _lc_upsert(
        db,
        login_id=cred["login_id"],
        login_type=cred["login_type"],
        reference_id=cred.get("reference_id", ""),
        name=cred.get("name", ""),
        email=cred.get("email"),
        plain_password=_LC_DEFAULT_PASSWORD,
        plain_pin=_LC_DEFAULT_PIN,
        force_reset=True,
    )
    return {"status": "reset", "login_id": cred["login_id"], "password": _LC_DEFAULT_PASSWORD, "pin": _LC_DEFAULT_PIN}


@api_router.post("/login-credentials/{login_id}/resend")
async def resend_login_credential(
    login_id: str,
    current_user: dict = Depends(get_current_user),
):
    """Broker-only — email the current plaintext password + PIN to the
    credential's associated email address."""
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can resend credentials")
    cred = await _lc_find_by_login(db, login_id)
    if not cred:
        raise HTTPException(status_code=404, detail="Login credential not found")
    email = (cred.get("email") or "").strip()
    if not email:
        raise HTTPException(status_code=400, detail="No email on file for this user — update the profile first")
    try:
        send_credentials_email(
            recipient_email=email,
            recipient_name=cred.get("name") or cred["login_id"],
            login_id=cred["login_id"],
            password=cred.get("plain_password", _LC_DEFAULT_PASSWORD),
            pin=cred.get("plain_pin", _LC_DEFAULT_PIN),
        )
    except TypeError:
        # Older `send_credentials_email` signature — best-effort fallback.
        send_credentials_email(
            email,
            cred.get("name") or cred["login_id"],
            cred["login_id"],
            cred.get("plain_password", _LC_DEFAULT_PASSWORD),
            cred.get("plain_pin", _LC_DEFAULT_PIN),
        )
    return {"status": "sent", "email": email}


@api_router.get("/export/login-credentials")
async def export_login_credentials(current_user: dict = Depends(get_current_user)):
    """Broker-only — Excel export of every Login_Credentials row."""
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can export login credentials")

    rows = await db.Login_Credentials.find({}, {"_id": 0}).sort("login_type", 1).to_list(50000)

    wb = Workbook()
    ws = wb.active
    ws.title = "Login Credentials"
    headers = ["Login Type", "Login ID", "Password", "PIN", "Name", "Email", "Updated At"]
    ws.append(headers)
    header_font = Font(bold=True, color="FFFFFF")
    header_fill = PatternFill(start_color="0F766E", end_color="0F766E", fill_type="solid")
    for col in range(1, len(headers) + 1):
        cell = ws.cell(row=1, column=col)
        cell.font = header_font
        cell.fill = header_fill
        cell.alignment = Alignment(horizontal="center")

    type_label = {k: v.get("label", k) for k, v in _LC_META.items()}
    for r in rows:
        ws.append([
            type_label.get(r.get("login_type"), r.get("login_type", "")),
            r.get("login_id", ""),
            r.get("plain_password", ""),
            r.get("plain_pin", ""),
            r.get("name", ""),
            r.get("email", ""),
            r.get("updated_at", ""),
        ])
    for col_idx, _ in enumerate(headers, start=1):
        ws.column_dimensions[get_column_letter(col_idx)].width = 22

    from io import BytesIO
    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    fname = f"login_credentials_{datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%S')}.xlsx"
    return StreamingResponse(
        buf,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


@api_router.post("/admin/backfill-real-estate-investors")
async def backfill_real_estate_investors(current_user: dict = Depends(get_current_user)):
    """
    One-time migration: copy every embedded `investors[]` across all
    `Real_Estate_Master` docs into the new `Real_Estate_Investor`
    collection. Safe to re-run (idempotent per opportunity).
    """
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can run backfill")
    processed = 0
    total_investors = 0
    async for opp in db.Real_Estate_Master.find({}, {"id": 1, "investors": 1}):
        opportunity_id = opp.get("id")
        if not opportunity_id:
            continue
        await _sync_real_estate_investors_to_collection(opportunity_id)
        processed += 1
        total_investors += len(opp.get("investors", []) or [])
    return {
        "status": "ok",
        "opportunities_processed": processed,
        "investors_mirrored": total_investors,
    }


