@api_router.post("/email-reader/process")
async def process_emails_endpoint(
    days_back: int = 7,
    force_reprocess: bool = False,
    current_user: dict = Depends(get_current_user)
):
    """
    Manually trigger email processing to fetch and process repayment emails
    Updates cashflows with actual repayment data from emails
    Args:
        days_back: Number of days to look back for emails
        force_reprocess: If True, re-process emails even if already read
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can process emails")
    
    result = await process_repayment_emails(db, days_back, force_reprocess)
    return result


@api_router.post("/email-reader/reprocess-logs")
async def reprocess_email_logs_endpoint(
    days_back: int = 30,
    current_user: dict = Depends(get_current_user)
):
    """
    Re-process existing email_read_logs that are missing actual_repayments.
    This creates actual_repayment records for emails that were read but didn't
    have repayment records created properly.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can reprocess email logs")
    
    result = await reprocess_email_logs(db, days_back)
    return result


