@api_router.get("/email-reader/scheduler-status")
async def get_email_scheduler_status(current_user: dict = Depends(get_current_user)):
    """Get the status of the email reader scheduler"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can access this")
    
    global email_scheduler
    
    if not email_scheduler:
        return {
            "status": "not_running",
            "message": "Email scheduler is not initialized"
        }
    
    jobs = []
    for job in email_scheduler.get_jobs():
        jobs.append({
            "id": job.id,
            "name": job.name,
            "next_run_time": job.next_run_time.isoformat() if job.next_run_time else None,
            "trigger": str(job.trigger)
        })
    
    # Get recent scheduler logs
    recent_logs = await db.email_scheduler_logs.find(
        {}, {"_id": 0}
    ).sort("timestamp", -1).limit(10).to_list(10)
    
    return {
        "status": "running" if email_scheduler.running else "paused",
        "jobs": jobs,
        "recent_logs": recent_logs,
        "schedule_info": {
            "frequency": "Once daily",
            "time_ist": "12:00 PM",
            "time_utc": "6:30 AM",
            "timezone": "IST (UTC+5:30)"
        }
    }


@api_router.post("/email-reader/trigger-now")
async def trigger_email_processing_now(
    days_back: int = 2,
    current_user: dict = Depends(get_current_user)
):
    """Manually trigger email processing immediately"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can trigger email processing")
    
    try:
        logger.info(f"Manual email processing triggered by {current_user['name']}")
        result = await process_repayment_emails(db, days_back=days_back)
        
        # Log the manual trigger
        log_entry = {
            "id": str(uuid.uuid4()),
            "type": "manual_trigger",
            "triggered_by": current_user['name'],
            "triggered_by_id": current_user['id'],
            "days_back": days_back,
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "result": result,
            "status": "success" if result.get('status') == 'success' else "error"
        }
        await db.email_scheduler_logs.insert_one(log_entry)
        
        return {
            "status": "success",
            "message": "Email processing triggered successfully",
            "result": result
        }
    except Exception as e:
        logger.error(f"Manual email processing failed: {e}")
        raise HTTPException(status_code=500, detail=f"Email processing failed: {str(e)}")


class ProcessEmailsRequest(BaseModel):
    bond_codes: Optional[List[str]] = None  # Filter by specific deal IDs/bond codes

@api_router.get("/email-reader/available-deals")
async def get_available_deals_from_mailbox(
    days_back: int = 90,
    current_user: dict = Depends(get_current_user)
):
    """
    Fetch unique deal IDs (bond codes) from emails in the mailbox.
    Used to populate the filter dropdown in Process Emails modal.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can access email data")
    
    try:
        reader = RepaymentEmailReader()
        if not reader.connect():
            return {"deals": [], "error": "Failed to connect to email server"}
        
        emails = reader.fetch_repayment_emails(days_back=days_back)
        reader.disconnect()
        
        # Extract unique bond codes with counts
        deal_counts = {}
        for email_data in emails:
            bond_code = (email_data.get('opportunity_id') or '').strip().upper()
            if bond_code:
                if bond_code not in deal_counts:
                    deal_counts[bond_code] = {
                        'code': bond_code,
                        'count': 0,
                        'company_name': email_data.get('company_name', bond_code)
                    }
                deal_counts[bond_code]['count'] += 1
        
        # Sort by count descending
        deals = sorted(deal_counts.values(), key=lambda x: x['count'], reverse=True)
        
        return {
            "deals": deals,
            "total_emails": len(emails)
        }
    except Exception as e:
        logger.error(f"Error fetching available deals: {e}")
        return {"deals": [], "error": str(e)}

@api_router.post("/email-reader/process-emails")
async def process_emails_unified(
    days_back: int = 30,
    request: Optional[ProcessEmailsRequest] = None,
    current_user: dict = Depends(get_current_user)
):
    """
    Unified email processing endpoint.
    - Reads emails from mailbox
    - Creates log entries for NEW emails only
    - Skips duplicates (same bond + client + repayment_date + gross_amount)
    - Does NOT update existing entries
    - Optional: Filter by specific bond_codes/deal IDs
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can process emails")
    
    # Extract filter bond codes if provided
    filter_bond_codes = None
    if request and request.bond_codes:
        filter_bond_codes = [code.strip().upper() for code in request.bond_codes if code.strip()]
    
    try:
        logger.info(f"Unified email processing triggered by {current_user['name']} for {days_back} days" + 
                   (f", filtering by bond codes: {filter_bond_codes}" if filter_bond_codes else ""))
        
        # Use the existing email reader
        reader = RepaymentEmailReader()
        results = {
            'status': 'success',
            'new_entries': 0,
            'skipped_duplicates': 0,
            'skipped_filtered': 0,
            'errors': []
        }
        
        try:
            reader.connect()
            emails = reader.fetch_repayment_emails(days_back=days_back)
            
            for email_data in emails:
                try:
                    # Extract key fields for duplicate check
                    bond_code = (email_data.get('opportunity_id') or '').strip().upper()
                    client_name = (email_data.get('client_name') or '').strip()
                    repayment_date = email_data.get('repayment_date')
                    gross_amount = email_data.get('gross_amount', 0)
                    email_date_val = email_data.get('email_date', '')
                    
                    # Skip if filtering by bond codes and this email doesn't match
                    if filter_bond_codes and bond_code and bond_code not in filter_bond_codes:
                        results['skipped_filtered'] += 1
                        continue
                    
                    # Handle emails with missing critical fields - still capture them
                    if not bond_code or not repayment_date:
                        # Create a unique key for incomplete emails using email_date and client_name
                        incomplete_key = f"{client_name}_{gross_amount}_{email_date_val}"
                        existing_incomplete = await db.email_read_logs.find_one({
                            "is_incomplete": True,
                            "client_name": client_name,
                            "gross_amount": gross_amount,
                            "email_date": email_date_val
                        })
                        
                        if existing_incomplete:
                            results['skipped_duplicates'] += 1
                            continue
                        
                        # Create incomplete email log
                        incomplete_log = {
                            'id': str(uuid.uuid4()),
                            'email_from': 'altGraaf',
                            'email_subject': email_data.get('raw_subject', ''),
                            'email_date': email_date_val,
                            'email_received_at': email_date_val,
                            'email_read_at': datetime.now(timezone.utc).isoformat(),
                            'client_name': client_name,
                            'matched_client_id': None,
                            'matched_client_name': None,
                            'match_similarity': 0,
                            'bond_id': None,
                            'bond_name': bond_code or 'Unknown',
                            'bond_code': bond_code or None,
                            'repayment_date': repayment_date,
                            'gross_amount': gross_amount,
                            'principal': email_data.get('principal'),
                            'interest': email_data.get('interest'),
                            'net_amount': email_data.get('net_amount'),
                            'tds_amount': email_data.get('tds_amount'),
                            'is_incomplete': True,
                            'missing_fields': [f for f in ['bond_code', 'repayment_date'] if not (bond_code if f == 'bond_code' else repayment_date)],
                            'approved': False,
                            'created_at': datetime.now(timezone.utc).isoformat()
                        }
                        await db.email_read_logs.insert_one(incomplete_log)
                        results['new_entries'] += 1
                        if 'incomplete_emails' not in results:
                            results['incomplete_emails'] = 0
                        results['incomplete_emails'] += 1
                        continue
                    
                    # Find bond
                    bond = await db.Ncd_Master.find_one({
                        "$or": [
                            {"bond_code": {"$regex": f"^{bond_code}$", "$options": "i"}},
                            {"opportunity_id": {"$regex": f"^{bond_code}$", "$options": "i"}}
                        ]
                    }, {"_id": 0})
                    
                    # Handle unlisted NCDs - still create log entry but mark as unlisted
                    is_unlisted_ncd = not bond
                    bond_id = bond.get('id') if bond else None
                    
                    # Check for duplicate entry - include email_date to ensure different emails 
                    # received on different days are treated as unique even if other fields match
                    # Key: bond_code + client_name + repayment_date + gross_amount + email_date
                    email_date_for_dedup = email_data.get('email_date', '')
                    existing = await db.email_read_logs.find_one({
                        "bond_code": bond_code,
                        "client_name": client_name,
                        "repayment_date": repayment_date,
                        "gross_amount": gross_amount,
                        "email_date": email_date_for_dedup
                    })
                    
                    if existing:
                        results['skipped_duplicates'] += 1
                        continue
                    
                    # For unlisted NCDs, create minimal log entry and continue to next email
                    if is_unlisted_ncd:
                        unlisted_email_log = {
                            'id': str(uuid.uuid4()),
                            'email_from': 'altGraaf',
                            'email_subject': email_data.get('raw_subject', ''),
                            'email_date': email_data.get('email_date'),
                            'raw_email_date': email_data.get('raw_email_date'),  # Original date header
                            'email_received_at': email_data.get('email_date'),
                            'email_read_at': datetime.now(timezone.utc).isoformat(),
                            'client_name': client_name,
                            'matched_client_id': None,
                            'matched_client_name': None,
                            'match_similarity': 0,
                            'auto_linked': False,
                            'matched_trade_id': None,
                            'matched_trade_date': None,
                            'matched_trade_units': 0,
                            'bond_id': None,
                            'bond_name': bond_code,  # Use bond_code as name for unlisted
                            'bond_code': bond_code,
                            'repayment_date': repayment_date,
                            'gross_amount': gross_amount,
                            'principal': email_data.get('principal'),
                            'interest': email_data.get('interest'),
                            'net_amount': email_data.get('net_amount'),
                            'tds_amount': email_data.get('tds_amount'),
                            'is_unlisted_ncd': True,
                            'approved': False,
                            'auto_approved': False,
                            'created_at': datetime.now(timezone.utc).isoformat()
                        }
                        await db.email_read_logs.insert_one(unlisted_email_log)
                        results['new_entries'] += 1
                        if 'unlisted_ncds' not in results:
                            results['unlisted_ncds'] = 0
                        results['unlisted_ncds'] += 1
                        continue
                    
                    # Match client - FIRST check saved name mappings for auto-linking
                    matched_client_id = None
                    matched_client_name = None
                    match_similarity = 0
                    auto_linked = False
                    
                    if client_name:
                        # Check if we have a saved mapping for this email name
                        name_mapping = await db.client_name_mappings.find_one({
                            "email_name": {"$regex": f"^{client_name.strip()}$", "$options": "i"}
                        }, {"_id": 0})
                        
                        if name_mapping:
                            # Auto-link from saved mapping
                            matched_client_id = name_mapping.get('client_id')
                            matched_client_name = name_mapping.get('client_name')
                            match_similarity = 1.0
                            auto_linked = True
                            logger.info(f"Auto-linked '{client_name}' to '{matched_client_name}' from saved mapping")
                        else:
                            # Fall back to 95% similarity matching
                            all_clients = await db.Private_Investor.find({}, {'_id': 0, 'id': 1, 'name': 1}).to_list(1000)
                            best_match = None
                            best_sim = 0
                            
                            for c in all_clients:
                                sim = name_similarity(client_name, c.get('name', ''))
                                if sim > best_sim:
                                    best_sim = sim
                                    best_match = c
                            
                            if best_match and best_sim >= 0.95:
                                matched_client_id = best_match.get('id')
                                matched_client_name = best_match.get('name')
                                match_similarity = best_sim
                            elif best_match and best_sim > 0.5:
                                matched_client_name = best_match.get('name')
                                match_similarity = best_sim
                    
                    # Match trade by per-unit amount (prepayment / units = clean integer)
                    matched_trade_id = None
                    matched_trade_date = None
                    matched_trade_units = 0
                    per_unit_amount = 0
                    
                    # Determine if this is a prepayment (principal only, no interest)
                    principal = email_data.get('principal', 0)
                    interest = email_data.get('interest', 0)
                    is_prepayment = principal > 0 and (not interest or interest == 0)
                    
                    # IMPORTANT: Only search trades for the matched client
                    # If we have a client match (even partial), only look at their trades
                    # Only search ALL trades if client_name from email is empty
                    if matched_client_id:
                        # Client was matched by name - search only their trades
                        trades = await db.Ncd_Investment_Details.find({
                            "client_id": matched_client_id,
                            "bond_id": bond_id,
                            "status": {"$ne": "cancelled"}
                        }, {"_id": 0}).to_list(100)
                    elif not client_name:
                        # No client name in email - search ALL trades to identify client
                        trades = await db.Ncd_Investment_Details.find({
                            "bond_id": bond_id,
                            "status": {"$ne": "cancelled"}
                        }, {"_id": 0}).to_list(500)
                    else:
                        # Client name exists but no match found - don't auto-match trades
                        # User will need to manually select the client
                        trades = []
                    
                    if trades:
                        if len(trades) == 1:
                            # Only one trade - direct match
                            trade = trades[0]
                            matched_trade_id = trade.get('id')
                            matched_trade_date = str(trade.get('investment_date', ''))[:10]
                            matched_trade_units = trade.get('units', 0)
                            per_unit_amount = round(gross_amount / matched_trade_units, 2) if matched_trade_units > 0 else 0
                            
                            # If client was unknown, identify from trade
                            if not matched_client_id and trade.get('client_id'):
                                matched_client_id = trade.get('client_id')
                                client_obj = await db.Private_Investor.find_one({"id": matched_client_id}, {"_id": 0})
                                if client_obj:
                                    matched_client_name = client_obj.get('name')
                                    match_similarity = 1.0
                                    logger.info(f"Client identified from single trade: {matched_client_name}")
                        
                        elif len(trades) > 1:
                            # Multiple trades - match by per-unit calculation
                            # For prepayments: prepayment_amount / units = clean integer
                            for trade in trades:
                                trade_units = trade.get('units', 0)
                                if trade_units > 0 and gross_amount > 0:
                                    # Calculate per-unit for this trade
                                    trade_per_unit = gross_amount / trade_units
                                    
                                    # Check if per_unit is a clean integer (within 0.01 tolerance)
                                    is_clean_integer = abs(trade_per_unit - round(trade_per_unit)) < 0.01
                                    
                                    if is_clean_integer:
                                        matched_trade_id = trade.get('id')
                                        matched_trade_date = str(trade.get('investment_date', ''))[:10]
                                        matched_trade_units = trade_units
                                        per_unit_amount = round(trade_per_unit)
                                        
                                        # If client was unknown, identify from trade
                                        if not matched_client_id and trade.get('client_id'):
                                            matched_client_id = trade.get('client_id')
                                            client_obj = await db.Private_Investor.find_one({"id": matched_client_id}, {"_id": 0})
                                            if client_obj:
                                                matched_client_name = client_obj.get('name')
                                                match_similarity = 1.0
                                                logger.info(f"Client identified by prepayment match: {matched_client_name} ({gross_amount}/{trade_units}={per_unit_amount})")
                                        break
                            
                            # If still no match and client was known, fall back to first client trade
                            if not matched_trade_id and matched_client_id:
                                client_trades = [t for t in trades if t.get('client_id') == matched_client_id]
                                if client_trades:
                                    trade = client_trades[0]
                                    matched_trade_id = trade.get('id')
                                    matched_trade_date = str(trade.get('investment_date', ''))[:10]
                                    matched_trade_units = trade.get('units', 0)
                                    per_unit_amount = round(gross_amount / matched_trade_units, 2) if matched_trade_units > 0 else 0
                    
                    # Determine if this should be auto-approved
                    # Auto-approve if:
                    # 1. 100% client match
                    # 2. Trade info identified
                    # 3. For regular repayments: amount matches expected cashflow (within ₹1)
                    # 4. For prepayments: trade identified by per-unit calculation
                    should_auto_approve = False
                    matching_cashflow = None
                    
                    if match_similarity >= 1.0 and matched_client_id and matched_trade_id and matched_trade_units > 0:
                        if is_prepayment:
                            # Prepayments are auto-approved if trade is identified
                            # The per-unit calculation already validated the match
                            should_auto_approve = True
                            logger.info(f"Auto-approving prepayment: {gross_amount} for trade {matched_trade_id} ({matched_trade_units} units)")
                        else:
                            # Regular repayment - verify it matches an expected cashflow
                            repayment_month = repayment_date[:7] if repayment_date else None
                            
                            if repayment_month:
                                # Find expected cashflow for this trade in this month
                                expected_cashflows = await db.holding_cashflows.find({
                                    "trade_id": matched_trade_id,
                                    "date": {"$regex": f"^{repayment_month}"},
                                    "is_repaid": {"$ne": True}
                                }, {"_id": 0}).to_list(10)
                                
                                for cf in expected_cashflows:
                                    expected_gross = cf.get('gross_amount', 0)
                                    # Check if amounts match within ₹1 tolerance
                                    if abs(gross_amount - expected_gross) <= 1:
                                        should_auto_approve = True
                                        matching_cashflow = cf
                                        logger.info(f"Auto-approve validated: {gross_amount} matches expected {expected_gross}")
                                        break
                                
                                if not should_auto_approve:
                                    logger.info(f"Auto-approve skipped: {gross_amount} doesn't match any expected cashflow for trade {matched_trade_id} in {repayment_month}")
                    
                    # Create new email log entry
                    email_log = {
                        'id': str(uuid.uuid4()),
                        'email_from': 'altGraaf',
                        'email_subject': email_data.get('raw_subject', ''),
                        'email_date': email_data.get('email_date'),
                        'raw_email_date': email_data.get('raw_email_date'),  # Original date header
                        'email_received_at': email_data.get('email_date'),  # Date email was received
                        'email_read_at': datetime.now(timezone.utc).isoformat(),  # Date we processed it
                        'client_name': client_name,
                        'matched_client_id': matched_client_id,
                        'matched_client_name': matched_client_name,
                        'match_similarity': match_similarity,
                        'auto_linked': auto_linked,
                        'matched_trade_id': matched_trade_id,
                        'matched_trade_date': matched_trade_date,
                        'matched_trade_units': matched_trade_units,
                        'bond_id': bond_id,
                        'bond_name': bond.get('name'),
                        'bond_code': bond.get('bond_code') or bond_code,
                        'repayment_date': repayment_date,
                        'gross_amount': gross_amount,
                        'principal': email_data.get('principal'),
                        'interest': email_data.get('interest'),
                        'net_amount': email_data.get('net_amount'),
                        'tds_amount': email_data.get('tds_amount'),
                        'approved': should_auto_approve,
                        'auto_approved': should_auto_approve,
                        'approved_at': datetime.now(timezone.utc).isoformat() if should_auto_approve else None,
                        'approved_by': 'system' if should_auto_approve else None,
                        'created_at': datetime.now(timezone.utc).isoformat()
                    }
                    
                    await db.email_read_logs.insert_one(email_log)
                    results['new_entries'] += 1
                    
                    # If auto-approved, create the actual_repayment entry
                    if should_auto_approve:
                        try:
                            # DUPLICATE CHECK: Ensure we don't create duplicate repayments
                            # Check by client_id + bond_id + repayment_date + gross_amount
                            existing_repayment = await db.actual_repayments.find_one({
                                "client_id": matched_client_id,
                                "bond_id": bond_id,
                                "repayment_date": repayment_date,
                                "gross_amount": gross_amount
                            })
                            
                            if existing_repayment:
                                logger.info(f"Skipping duplicate repayment: client={matched_client_id}, bond={bond_id}, date={repayment_date}, amount={gross_amount}")
                                # Still mark email log as approved to prevent reprocessing
                                await db.email_read_logs.update_one(
                                    {"id": email_log['id']},
                                    {"$set": {
                                        "approved": True,
                                        "approved_at": datetime.now(timezone.utc).isoformat(),
                                        "approved_by": "system",
                                        "actual_repayment_id": existing_repayment.get('id'),
                                        "duplicate_skipped": True
                                    }}
                                )
                                results['skipped_duplicates'] = results.get('skipped_duplicates', 0) + 1
                                continue
                            
                            actual_repayment = {
                                'id': str(uuid.uuid4()),
                                'trade_id': matched_trade_id,
                                'client_id': matched_client_id,
                                'bond_id': bond_id,
                                'email_log_id': email_log['id'],
                                'cashflow_id': matching_cashflow.get('id') if matching_cashflow else None,
                                'repayment_date': repayment_date,
                                'investment_date': matched_trade_date,  # CRITICAL: Add investment_date for proper matching
                                'expected_date': matching_cashflow.get('date') if matching_cashflow else None,
                                'gross_amount': gross_amount,
                                'net_amount': email_data.get('net_amount'),
                                'principal': email_data.get('principal'),
                                'interest': email_data.get('interest'),
                                'tds_amount': email_data.get('tds_amount'),
                                'is_prepayment': is_prepayment,
                                'source': 'email_auto_approval',
                                'approved_by': 'system',
                                'approved_at': datetime.now(timezone.utc).isoformat(),
                                'created_at': datetime.now(timezone.utc).isoformat()
                            }
                            
                            await db.actual_repayments.insert_one(actual_repayment)
                            
                            # For regular repayments: mark the matching cashflow as repaid
                            if matching_cashflow and matching_cashflow.get('id'):
                                await db.holding_cashflows.update_one(
                                    {"id": matching_cashflow['id']},
                                    {"$set": {
                                        "is_repaid": True,
                                        "actual_amount": gross_amount,
                                        "actual_net_amount": email_data.get('net_amount'),
                                        "repaid_at": datetime.now(timezone.utc).isoformat(),
                                        "actual_repayment_id": actual_repayment['id']
                                    }}
                                )
                            
                            # For prepayments: recalculate final maturity amount
                            if is_prepayment:
                                prepayment_principal = email_data.get('principal', 0)
                                
                                # Get bond info for face_value
                                bond_info = await db.Ncd_Master.find_one({"id": bond_id}, {"_id": 0, "face_value": 1, "cashflows_per_unit": 1})
                                face_value = bond_info.get('face_value', 100000) if bond_info else 100000
                                
                                # Find the maturity cashflow for this trade (latest date, typically highest amount)
                                maturity_cashflow = await db.holding_cashflows.find_one({
                                    "trade_id": matched_trade_id,
                                    "is_repaid": {"$ne": True},
                                    "type": {"$ne": "prepayment"}
                                }, {"_id": 0}, sort=[("date", -1)])
                                
                                if maturity_cashflow:
                                    old_gross = maturity_cashflow.get('gross_amount', 0)
                                    
                                    # Calculate original principal and interest from trade units and bond structure
                                    trade = await db.Ncd_Investment_Details.find_one({"id": matched_trade_id}, {"_id": 0, "units": 1})
                                    trade_units = trade.get('units', 0) if trade else matched_trade_units
                                    
                                    # Get per-unit breakdown from bond
                                    cashflows_per_unit = bond_info.get('cashflows_per_unit', []) if bond_info else []
                                    maturity_cf_per_unit = next((cf for cf in cashflows_per_unit if 'principal_per_unit' in cf and cf.get('principal_per_unit', 0) > 0), None)
                                    
                                    if maturity_cf_per_unit:
                                        principal_per_unit = maturity_cf_per_unit.get('principal_per_unit', face_value)
                                        interest_per_unit = maturity_cf_per_unit.get('interest_per_unit', 0)
                                        
                                        old_principal = trade_units * principal_per_unit
                                        old_interest = trade_units * interest_per_unit
                                    else:
                                        # Fallback: assume principal = units × face_value, interest = gross - principal
                                        old_principal = trade_units * face_value
                                        old_interest = max(0, old_gross - old_principal)
                                    
                                    # Calculate new maturity amounts after prepayment
                                    # Reduce principal by prepayment amount
                                    new_principal = max(0, old_principal - prepayment_principal)
                                    
                                    # Recalculate interest proportionally
                                    if old_principal > 0:
                                        interest_ratio = new_principal / old_principal
                                        new_interest = round(old_interest * interest_ratio, 2)
                                    else:
                                        new_interest = 0
                                    
                                    new_gross = new_principal + new_interest
                                    new_tds = round(new_interest * 0.1, 2)  # 10% TDS on interest
                                    new_net = new_gross - new_tds
                                    
                                    # Update the maturity cashflow
                                    await db.holding_cashflows.update_one(
                                        {"id": maturity_cashflow['id']},
                                        {"$set": {
                                            "principal": new_principal,
                                            "interest": new_interest,
                                            "gross_amount": new_gross,
                                            "net_amount": new_net,
                                            "tds": new_tds,
                                            "prepayment_adjusted": True,
                                            "prepayment_amount": prepayment_principal,
                                            "original_principal": old_principal,
                                            "original_interest": old_interest,
                                            "original_gross": old_gross,
                                            "adjusted_at": datetime.now(timezone.utc).isoformat()
                                        }}
                                    )
                                    
                                    logger.info(f"Maturity recalculated for trade {matched_trade_id}: "
                                               f"Principal {old_principal} -> {new_principal}, "
                                               f"Interest {old_interest} -> {new_interest}, "
                                               f"Gross {old_gross} -> {new_gross}")
                                
                                # Also create a new cashflow entry for the prepayment itself
                                prepayment_cashflow = {
                                    'id': str(uuid.uuid4()),
                                    'trade_id': matched_trade_id,
                                    'client_id': matched_client_id,
                                    'bond_id': bond_id,
                                    'date': repayment_date,
                                    'type': 'prepayment',
                                    'principal': prepayment_principal,
                                    'interest': 0,
                                    'gross_amount': prepayment_principal,
                                    'net_amount': prepayment_principal,
                                    'tds': 0,
                                    'is_repaid': True,
                                    'actual_amount': prepayment_principal,
                                    'actual_repayment_id': actual_repayment['id'],
                                    'repaid_at': datetime.now(timezone.utc).isoformat(),
                                    'created_at': datetime.now(timezone.utc).isoformat()
                                }
                                await db.holding_cashflows.insert_one(prepayment_cashflow)
                            
                            # Update email log with actual_repayment_id
                            await db.email_read_logs.update_one(
                                {"id": email_log['id']},
                                {"$set": {"actual_repayment_id": actual_repayment['id']}}
                            )
                            
                            results['auto_approved'] = results.get('auto_approved', 0) + 1
                            logger.info(f"Auto-approved {'prepayment' if is_prepayment else 'repayment'} for {matched_client_name}: {gross_amount}")
                                
                        except Exception as auto_err:
                            logger.error(f"Error auto-approving: {auto_err}")
                    
                except Exception as e:
                    results['errors'].append(str(e))
            
        finally:
            reader.disconnect()
        
        logger.info(f"Email processing complete: {results['new_entries']} new, {results['skipped_duplicates']} skipped")
        
        # AUTO-TAG: Automatically tag all matched emails after processing
        # This removes the need for manual triggering
        try:
            auto_tag_result = await auto_tag_email_repayments_internal(db)
            results['auto_tagged'] = auto_tag_result.get('tagged_count', 0)
            results['auto_tag_duplicates'] = auto_tag_result.get('duplicate_count', 0)
            logger.info(f"Auto-tag complete: {results.get('auto_tagged', 0)} tagged, {results.get('auto_tag_duplicates', 0)} duplicates")
        except Exception as auto_tag_err:
            logger.error(f"Auto-tag failed: {auto_tag_err}")
            results['auto_tag_error'] = str(auto_tag_err)
        
        return results
        
    except Exception as e:
        logger.error(f"Email processing failed: {e}")
        raise HTTPException(status_code=500, detail=f"Email processing failed: {str(e)}")


@api_router.post("/email-reader/approve-log/{log_id}")
async def approve_email_log(
    log_id: str,
    current_user: dict = Depends(get_current_user)
):
    """
    Approve an email log to create actual_repayment record.
    This is the workflow: Email Read -> Show in Logs -> User Approves -> Creates Actual Repayment
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can approve email logs")
    
    try:
        # Get the email log
        log = await db.email_read_logs.find_one({"id": log_id}, {"_id": 0})
        if not log:
            raise HTTPException(status_code=404, detail="Email log not found")
        
        if log.get('approved'):
            raise HTTPException(status_code=400, detail="Email log already approved")
        
        # Get matched client and trade info
        matched_client_id = log.get('matched_client_id')
        matched_trade_id = log.get('matched_trade_id')
        bond_id = log.get('bond_id')
        
        if not matched_client_id:
            raise HTTPException(status_code=400, detail="No matched client. Please tag manually.")
        
        # Get the trade
        trade = None
        if matched_trade_id:
            trade = await db.Ncd_Investment_Details.find_one({"id": matched_trade_id}, {"_id": 0})
        
        if not trade:
            # Find trade by client_id and bond_id
            trade = await db.Ncd_Investment_Details.find_one({
                "client_id": matched_client_id,
                "bond_id": bond_id,
                "status": {"$ne": "cancelled"}
            }, {"_id": 0})
        
        if not trade:
            raise HTTPException(status_code=400, detail="No matching trade found for this client/bond")
        
        # Create actual_repayment record
        repayment_date = log.get('repayment_date')
        gross_amount = log.get('gross_amount', 0)
        principal = log.get('principal', 0)
        interest = log.get('interest', 0)
        net_amount = log.get('net_amount', gross_amount)
        tds = log.get('tds_amount', 0)
        
        # Check if already exists - check both by email_log_id and by content
        existing = await db.actual_repayments.find_one({
            "email_log_id": log_id
        })
        
        if existing:
            raise HTTPException(status_code=400, detail="Repayment record already exists for this email")
        
        # Also check for duplicate by content (same client, bond, date, amount)
        existing_by_content = await db.actual_repayments.find_one({
            "client_id": matched_client_id,
            "bond_id": bond_id,
            "repayment_date": repayment_date,
            "gross_amount": gross_amount
        })
        
        if existing_by_content:
            raise HTTPException(status_code=400, detail="A repayment with the same details already exists")
        
        trade_units = trade.get('units', 0)
        investment_date = str(trade.get('investment_date', ''))[:10]
        
        is_prepayment = (principal and principal > 0 and (not interest or interest == 0))
        
        repayment_record = {
            "id": str(uuid.uuid4()),
            "client_id": matched_client_id,
            "client_name": log.get('matched_client_name') or log.get('client_name'),
            "bond_id": bond_id,
            "bond_name": log.get('bond_name'),
            "bond_code": log.get('bond_code'),
            "repayment_date": repayment_date,
            "investment_date": investment_date,
            "gross_amount": gross_amount,
            "principal": principal,
            "interest": interest,
            "net_amount": net_amount,
            "tds": tds,
            "units": trade_units,
            "per_unit_amount": round(gross_amount / trade_units, 2) if trade_units > 0 else 0,
            "payment_type": "prepayment" if is_prepayment else "interest_payment",
            "is_prepayment": is_prepayment,
            "email_log_id": log_id,
            "trade_id": trade.get('id'),
            "approved_by": current_user['name'],
            "approved_by_id": current_user['id'],
            "approved_at": datetime.now(timezone.utc).isoformat(),
            "source": "email_approval",
            "created_at": datetime.now(timezone.utc).isoformat()
        }
        
        await db.actual_repayments.insert_one(repayment_record)
        
        # Update email log as approved
        await db.email_read_logs.update_one(
            {"id": log_id},
            {"$set": {
                "approved": True,
                "approved_at": datetime.now(timezone.utc).isoformat(),
                "approved_by": current_user['name'],
                "actual_repayment_id": repayment_record['id']
            }}
        )
        
        logger.info(f"Email log {log_id} approved by {current_user['name']}, created actual_repayment {repayment_record['id']}")
        
        return {
            "status": "success",
            "message": "Email log approved and actual repayment created",
            "repayment_id": repayment_record['id']
        }
        
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error approving email log: {e}")
        raise HTTPException(status_code=500, detail=f"Failed to approve: {str(e)}")


class ResetTrackerRequest(BaseModel):
    option: str  # "unapproved", "all", "from_date"
    from_date: Optional[str] = None


@api_router.post("/email-reader/reset-tracker")
async def reset_email_tracker(
    request: ResetTrackerRequest,
    current_user: dict = Depends(get_current_user)
):
    """
    Reset email tracker to allow re-reading emails from mailbox.
    Options:
    - unapproved: Delete only unapproved email logs
    - all: Delete all email logs (keeps approved actual_repayments)
    - from_date: Delete logs from a specific date onwards
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can reset email tracker")
    
    try:
        query = {}
        
        if request.option == "unapproved":
            # Only delete unapproved logs
            query = {"$or": [{"approved": False}, {"approved": {"$exists": False}}]}
        elif request.option == "all":
            # Delete all logs
            query = {}
        elif request.option == "from_date" and request.from_date:
            # Delete logs from specific date onwards
            query = {"email_read_at": {"$gte": request.from_date}}
        else:
            raise HTTPException(status_code=400, detail="Invalid reset option")
        
        # Count before delete
        count_before = await db.email_read_logs.count_documents(query)
        
        # Delete the logs
        result = await db.email_read_logs.delete_many(query)
        
        logger.info(f"Email tracker reset by {current_user['name']}: option={request.option}, deleted={result.deleted_count}")
        
        return {
            "status": "success",
            "message": f"Email tracker reset successfully",
            "deleted_count": result.deleted_count,
            "option": request.option
        }
        
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error resetting email tracker: {e}")
        raise HTTPException(status_code=500, detail=f"Failed to reset tracker: {str(e)}")




@api_router.get("/email-reader/bond-private-investors/{bond_id}")
async def get_bond_clients(
    bond_id: str,
    email_client_name: str = None,
    current_user: dict = Depends(get_current_user)
):
    """
    Get all clients who have trades in a specific bond.
    Used for manual client selection in email logs.
    If email_client_name is provided, returns similarity scores sorted by best match.
    """
    from difflib import SequenceMatcher
    
    try:
        # Get all trades for this bond
        trades = await db.Ncd_Investment_Details.find({
            "bond_id": bond_id,
            "status": {"$ne": "cancelled"}
        }, {"_id": 0, "client_id": 1, "client_name": 1, "units": 1, "investment_date": 1}).to_list(1000)
        
        # Aggregate by client
        clients_map = {}
        for trade in trades:
            client_id = trade.get('client_id')
            if client_id:
                if client_id not in clients_map:
                    clients_map[client_id] = {
                        "id": client_id,
                        "name": trade.get('client_name', 'Unknown'),
                        "units": 0,
                        "investment_dates": [],
                        "similarity": 0
                    }
                clients_map[client_id]["units"] += trade.get('units', 0)
                inv_date = str(trade.get('investment_date', ''))[:10]
                if inv_date and inv_date not in clients_map[client_id]["investment_dates"]:
                    clients_map[client_id]["investment_dates"].append(inv_date)
        
        clients = list(clients_map.values())
        
        # Calculate similarity scores if email_client_name is provided
        if email_client_name:
            email_name_lower = email_client_name.lower().strip()
            for client in clients:
                client_name_lower = client["name"].lower().strip()
                similarity = SequenceMatcher(None, email_name_lower, client_name_lower).ratio()
                client["similarity"] = round(similarity, 2)
            
            # Sort by similarity (highest first), then by name
            clients.sort(key=lambda x: (-x["similarity"], x["name"]))
        else:
            clients.sort(key=lambda x: x["name"])
        
        return {"clients": clients}
        
    except Exception as e:
        logger.error(f"Error fetching bond clients: {e}")
        raise HTTPException(status_code=500, detail=str(e))


class AssignClientRequest(BaseModel):
    log_id: str
    client_id: str


@api_router.post("/email-reader/assign-client")
async def assign_client_to_log(
    request: AssignClientRequest,
    current_user: dict = Depends(get_current_user)
):
    """
    Manually assign a client to an email log.
    Also saves the mapping for future auto-linking.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can assign clients")
    
    try:
        # Get the email log
        log = await db.email_read_logs.find_one({"id": request.log_id}, {"_id": 0})
        if not log:
            raise HTTPException(status_code=404, detail="Email log not found")
        
        # Get the client
        client = await db.Private_Investor.find_one({"id": request.client_id}, {"_id": 0, "id": 1, "name": 1})
        if not client:
            raise HTTPException(status_code=404, detail="Client not found")
        
        email_client_name = log.get('client_name', '').strip()
        bond_id = log.get('bond_id')
        
        # Find the best matching trade for this client + bond
        trade = await db.Ncd_Investment_Details.find_one({
            "client_id": request.client_id,
            "bond_id": bond_id,
            "status": {"$ne": "cancelled"}
        }, {"_id": 0})
        
        matched_trade_id = trade.get('id') if trade else None
        matched_trade_date = str(trade.get('investment_date', ''))[:10] if trade else None
        matched_trade_units = trade.get('units', 0) if trade else 0
        
        # Update the email log with matched client info
        await db.email_read_logs.update_one(
            {"id": request.log_id},
            {"$set": {
                "matched_client_id": request.client_id,
                "matched_client_name": client.get('name'),
                "match_similarity": 1.0,  # Manual = 100% match
                "matched_trade_id": matched_trade_id,
                "matched_trade_date": matched_trade_date,
                "matched_trade_units": matched_trade_units,
                "manually_assigned": True,
                "assigned_by": current_user['name'],
                "assigned_at": datetime.now(timezone.utc).isoformat()
            }}
        )
        
        # Save the name mapping for future auto-linking
        if email_client_name:
            existing_mapping = await db.client_name_mappings.find_one({
                "email_name": {"$regex": f"^{email_client_name}$", "$options": "i"}
            })
            
            if not existing_mapping:
                await db.client_name_mappings.insert_one({
                    "id": str(uuid.uuid4()),
                    "email_name": email_client_name,
                    "client_id": request.client_id,
                    "client_name": client.get('name'),
                    "created_by": current_user['name'],
                    "created_at": datetime.now(timezone.utc).isoformat()
                })
                logger.info(f"Created client name mapping: '{email_client_name}' -> '{client.get('name')}'")
        
        return {
            "status": "success",
            "message": f"Client '{client.get('name')}' assigned to email log",
            "mapping_saved": bool(email_client_name)
        }
        
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error assigning client: {e}")
        raise HTTPException(status_code=500, detail=str(e))


class ManualEmailTagRequest(BaseModel):
    email_log_id: str
    client_id: str
    bond_id: str
    repayment_date: str


@api_router.post("/email-engagement/manual-tag")
async def manual_tag_email_to_holding(
    request: ManualEmailTagRequest,
    current_user: dict = Depends(get_current_user)
):
    """Manually tag an email to a client and update their holding cashflow"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can manually tag emails")
    
    # Get the email log
    email_log = await db.email_read_logs.find_one({"id": request.email_log_id}, {"_id": 0})
    if not email_log:
        raise HTTPException(status_code=404, detail="Email log not found")
    
    # Get client details
    client = await db.Private_Investor.find_one({"id": request.client_id}, {"_id": 0, "id": 1, "name": 1, "pan_number": 1})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    
    # Get bond details
    bond = await db.Ncd_Master.find_one({"id": request.bond_id}, {"_id": 0, "id": 1, "name": 1, "bond_code": 1})
    if not bond:
        raise HTTPException(status_code=404, detail="Bond not found")
    
    # Update holding cashflows for this client, bond and date
    update_result = await db.holding_cashflows.update_many(
        {
            "client_id": request.client_id,
            "bond_id": request.bond_id,
            "date": {"$regex": f"^{request.repayment_date}"}
        },
        {
            "$set": {
                "is_repaid": True,
                "repaid_date": request.repayment_date,
                "repaid_actual_amount": email_log.get('gross_amount'),
                "repaid_net_amount": email_log.get('net_amount'),
                "repaid_tds": email_log.get('tds_amount'),
                "email_processed": True,
                "email_processed_at": datetime.now().isoformat(),
                "email_log_id": request.email_log_id,
                "manually_tagged": True,
                "manually_tagged_by": current_user['name'],
                "manually_tagged_at": datetime.now(timezone.utc).isoformat()
            }
        }
    )
    
    # Update the email log with client mapping
    await db.email_read_logs.update_one(
        {"id": request.email_log_id},
        {
            "$set": {
                "client_id": client['id'],
                "client_name": client['name'],
                "client_pan": client.get('pan_number'),
                "bond_id": bond['id'],
                "bond_name": bond['name'],
                "bond_code": bond.get('bond_code'),
                "repayment_date": request.repayment_date,
                "holding_updated": update_result.modified_count > 0,
                "holding_updated_at": datetime.now(timezone.utc).isoformat() if update_result.modified_count > 0 else None,
                "cashflows_updated_count": update_result.modified_count,
                "manually_tagged": True,
                "manually_tagged_by": current_user['name'],
                "manually_tagged_at": datetime.now(timezone.utc).isoformat(),
                "updated_at": datetime.now(timezone.utc).isoformat()
            }
        }
    )
    
    return {
        "status": "success",
        "message": f"Email tagged to {client['name']} for {bond['name']}",
        "cashflows_updated": update_result.modified_count
    }


