@api_router.get("/email-engagement/client-investments")
async def get_client_investment_dates(
    client_name: Optional[str] = None,
    bond_name: Optional[str] = None,
    bond_code: Optional[str] = None,
    current_user: dict = Depends(get_current_user)
):
    """Get client's actual investment dates and amounts for the dropdown - filtered by Deal ID and Client Name"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can access this data")
    
    investments = []
    
    # Build query to match both client name AND bond/deal
    query = {"status": {"$ne": "cancelled"}}
    
    # Must match client name
    if client_name:
        query["client_name"] = {"$regex": client_name, "$options": "i"}
    
    # Must match bond/deal - try bond_code first, then bond_name
    if bond_code:
        query["bond_code"] = {"$regex": bond_code, "$options": "i"}
    elif bond_name:
        query["bond_name"] = {"$regex": bond_name, "$options": "i"}
    
    trades = await db.Ncd_Investment_Details.find(query, {"_id": 0}).to_list(500)
    
    for trade in trades:
        # Use investment_date, trade_date, or created_at as fallback
        inv_date = trade.get('investment_date') or trade.get('trade_date') or trade.get('created_at', '')
        if inv_date:
            investments.append({
                "date": str(inv_date)[:10],
                "amount": trade.get('total_amount', 0) or trade.get('amount', 0) or 0,
                "type": "investment",
                "source": "trade",
                "bond_name": trade.get('bond_name', ''),
                "bond_code": trade.get('bond_code', ''),
                "client_name": trade.get('client_name', '')
            })
    
    # Deduplicate by date and sort by date descending
    seen_dates = {}
    for inv in investments:
        date_key = inv['date']
        if date_key not in seen_dates or inv['amount'] > seen_dates[date_key]['amount']:
            seen_dates[date_key] = inv
    
    unique_investments = sorted(seen_dates.values(), key=lambda x: x['date'], reverse=True)
    
    return {"investments": unique_investments}


class ProcessRepaymentRequest(BaseModel):
    email_log_id: str
    transaction_date: str
    payment_type: str  # "normal" or "prepayment"
    gross_amount: Optional[float] = 0
    net_amount: Optional[float] = 0
    tds_amount: Optional[float] = 0
    client_id: Optional[str] = None
    client_name: Optional[str] = None
    bond_id: Optional[str] = None
    bond_name: Optional[str] = None


@api_router.post("/email-engagement/process-repayment")
async def process_email_repayment(
    request: ProcessRepaymentRequest,
    current_user: dict = Depends(get_current_user)
):
    """
    Process a repayment from email read logs.
    - Adds to actual_repayments collection
    - Updates holding_cashflows to mark as repaid
    - For prepayments: adjusts XIRR and reduces final maturity payout
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can process repayments")
    
    # Get the email log
    email_log = await db.email_read_logs.find_one({"id": request.email_log_id}, {"_id": 0})
    if not email_log:
        raise HTTPException(status_code=404, detail="Email log not found")
    
    # Get trade info if trade_id is provided
    trade_info = None
    if request.trade_id:
        trade_info = await db.Ncd_Investment_Details.find_one({"id": request.trade_id}, {"_id": 0})
    elif email_log.get('matched_trade_id'):
        trade_info = await db.Ncd_Investment_Details.find_one({"id": email_log.get('matched_trade_id')}, {"_id": 0})
    
    # Create actual repayment record
    repayment_id = str(uuid.uuid4())
    repayment_record = {
        "id": repayment_id,
        "client_id": request.client_id or email_log.get('client_id') or (trade_info.get('client_id') if trade_info else None),
        "client_name": request.client_name or email_log.get('client_name') or (trade_info.get('client_name') if trade_info else None),
        "bond_id": request.bond_id or email_log.get('bond_id') or (trade_info.get('bond_id') if trade_info else None),
        "bond_name": request.bond_name or email_log.get('bond_name') or (trade_info.get('bond_name') if trade_info else None),
        "trade_id": request.trade_id or email_log.get('matched_trade_id') or (trade_info.get('id') if trade_info else None),  # CRITICAL: Set trade_id
        "investment_date": trade_info.get('investment_date') if trade_info else None,  # CRITICAL: Set investment_date
        "repayment_date": request.transaction_date,
        "gross_amount": request.gross_amount or email_log.get('gross_amount', 0),
        "net_amount": request.net_amount or email_log.get('net_amount', 0),
        "tds": request.tds_amount or email_log.get('tds_amount', 0),
        "payment_type": request.payment_type,
        "is_prepayment": request.payment_type == "prepayment",
        "email_log_id": request.email_log_id,
        "created_by": current_user.get('id'),
        "created_at": datetime.now(timezone.utc).isoformat(),
        "source": "email_read"
    }
    
    # Insert into actual_repayments
    await db.actual_repayments.insert_one(repayment_record)
    
    # Update the email_read_log to mark as processed
    await db.email_read_logs.update_one(
        {"id": request.email_log_id},
        {
            "$set": {
                "holding_updated": True,
                "holding_updated_at": datetime.now(timezone.utc).isoformat(),
                "payment_type": request.payment_type,
                "actual_repayment_id": repayment_id
            }
        }
    )
    
    # Update matching holding_cashflows
    client_id = request.client_id or email_log.get('client_id')
    bond_id = request.bond_id or email_log.get('bond_id')
    
    if client_id and bond_id:
        # Mark the cashflow as repaid
        await db.holding_cashflows.update_many(
            {
                "client_id": client_id,
                "bond_id": bond_id,
                "date": {"$regex": f"^{request.transaction_date[:10]}"}
            },
            {
                "$set": {
                    "is_repaid": True,
                    "repaid_date": request.transaction_date,
                    "repaid_actual_amount": request.gross_amount,
                    "repaid_net_amount": request.net_amount,
                    "repaid_tds": request.tds_amount,
                    "payment_type": request.payment_type,
                    "email_processed": True,
                    "email_processed_at": datetime.now(timezone.utc).isoformat()
                }
            }
        )
        
        # If prepayment, adjust future cashflows (reduce maturity payout)
        if request.payment_type == "prepayment":
            # Get the bond details to find maturity date
            bond = await db.Ncd_Master.find_one({"id": bond_id}, {"_id": 0})
            if bond:
                maturity_date = bond.get('maturity_date', '')
                
                # Find the maturity cashflow and reduce it
                maturity_cf = await db.holding_cashflows.find_one(
                    {
                        "client_id": client_id,
                        "bond_id": bond_id,
                        "type": {"$in": ["maturity", "principal", "final"]}
                    },
                    {"_id": 0}
                )
                
                if maturity_cf:
                    prepayment_amount = request.gross_amount or 0
                    current_principal = maturity_cf.get('principal', 0) or maturity_cf.get('gross_amount', 0)
                    new_principal = max(0, current_principal - prepayment_amount)
                    
                    await db.holding_cashflows.update_one(
                        {"id": maturity_cf.get('id')},
                        {
                            "$set": {
                                "original_principal": current_principal,
                                "principal": new_principal,
                                "gross_amount": new_principal,
                                "prepayment_adjusted": True,
                                "prepayment_amount": prepayment_amount,
                                "prepayment_date": request.transaction_date
                            }
                        }
                    )
    
    return {
        "success": True,
        "message": f"Repayment processed successfully as {request.payment_type}",
        "repayment_id": repayment_id
    }


async def auto_tag_email_repayments_internal(db_instance):
    """
    Internal auto-tag function that can be called without HTTP context.
    Used after email processing to automatically tag matched emails.
    
    ENHANCED: Now also matches by client name + units when bond_code doesn't find trades.
    """
    # Get all pending email logs (not yet tagged)
    pending_logs = await db_instance.email_read_logs.find(
        {"holding_updated": {"$ne": True}},
        {"_id": 0}
    ).to_list(1000)
    
    if not pending_logs:
        return {"success": True, "message": "No pending emails to tag", "tagged_count": 0}
    
    tagged_count = 0
    duplicate_count = 0
    
    # Group logs by bond_code for efficient processing
    logs_by_bond = {}
    for log in pending_logs:
        bond_code = log.get('bond_code', '')
        if bond_code:
            if bond_code not in logs_by_bond:
                logs_by_bond[bond_code] = []
            logs_by_bond[bond_code].append(log)
    
    # Process each bond's logs
    for bond_code, logs in logs_by_bond.items():
        # Get all trades for this bond - try multiple matching strategies
        trades = await db_instance.trades.find(
            {"bond_code": bond_code, "status": {"$ne": "cancelled"}},
            {"_id": 0}
        ).to_list(100)
        
        # FALLBACK: If no trades found by bond_code, try matching by bond name patterns
        if not trades:
            # Try to find bond by code to get its name
            bond_info = await db_instance.bonds.find_one({"bond_code": bond_code}, {"_id": 0, "name": 1, "bond_name": 1})
            if bond_info:
                bond_name = bond_info.get('name') or bond_info.get('bond_name', '')
                if bond_name:
                    # Search for trades by bond_name (partial match)
                    trades = await db_instance.trades.find(
                        {"bond_name": {"$regex": bond_name[:20], "$options": "i"}, "status": {"$ne": "cancelled"}},
                        {"_id": 0}
                    ).to_list(100)
        
        if not trades:
            continue
        
        # Get bond info for expected per-unit amounts
        bond = await db_instance.bonds.find_one(
            {"bond_code": bond_code},
            {"_id": 0, "cashflows_per_unit": 1, "end_date": 1, "maturity_date": 1}
        )
        
        for log in logs:
            log_id = log.get('id')
            log_gross_amount = log.get('gross_amount', 0)
            log_repayment_date = log.get('repayment_date', '')
            log_client_name = log.get('client_name', '')
            
            if not log_gross_amount or not log_repayment_date:
                continue
            
            # Parse the log repayment date for comparison
            try:
                log_date = datetime.strptime(log_repayment_date[:10], '%Y-%m-%d')
            except (ValueError, TypeError):
                continue
            
            # Check for duplicate with historical repayments
            # Match criteria: same bond, amount within 1%, date within 3 days (same month/year)
            similar_amount_min = log_gross_amount * 0.99
            similar_amount_max = log_gross_amount * 1.01
            
            # Get all historical repayments for this bond
            historical_repayments = await db_instance.actual_repayments.find({
                "bond_code": bond_code,
                "source": {"$in": ["historical", "manual", "historical_upload"]}
            }, {"_id": 0}).to_list(1000)
            
            is_duplicate = False
            matched_historical_id = None
            
            for hist in historical_repayments:
                hist_amount = hist.get('gross_amount', 0) or hist.get('net_amount', 0) or 0
                hist_date_str = (hist.get('repayment_date', '') or hist.get('date', ''))[:10]
                
                # Check amount within 1% tolerance
                if not (similar_amount_min <= hist_amount <= similar_amount_max):
                    continue
                
                # Check date within 3 days and same month/year
                try:
                    hist_date = datetime.strptime(hist_date_str, '%Y-%m-%d')
                    if log_date.year != hist_date.year or log_date.month != hist_date.month:
                        continue
                    if abs((log_date - hist_date).days) > 3:
                        continue
                    
                    # Found a match - this is a duplicate
                    is_duplicate = True
                    matched_historical_id = hist.get('id')
                    break
                except (ValueError, TypeError):
                    continue
            
            if is_duplicate:
                # Mark email as duplicate (linked to historical entry)
                await db_instance.email_read_logs.update_one(
                    {"id": log_id},
                    {"$set": {
                        "holding_updated": True,
                        "holding_updated_at": datetime.now(timezone.utc).isoformat(),
                        "is_duplicate": True,
                        "duplicate_of": matched_historical_id,
                        "duplicate_reason": "Matches historical repayment entry"
                    }}
                )
                duplicate_count += 1
                continue
            
            # Find matching trade - PRIORITY 1: Use pre-matched trade_id from email parsing
            matched_trade = None
            per_unit_amount = None
            
            # PRIORITY 1: Use pre-matched trade from email parsing (most reliable)
            pre_matched_trade_id = log.get('matched_trade_id')
            if pre_matched_trade_id:
                # First try to find in the already-fetched trades list
                matched_trade = next((t for t in trades if t.get('id') == pre_matched_trade_id), None)
                # If not found in list, fetch directly from database (handles edge cases)
                if not matched_trade:
                    matched_trade = await db_instance.trades.find_one(
                        {"id": pre_matched_trade_id, "status": {"$ne": "cancelled"}},
                        {"_id": 0}
                    )
            
            # PRIORITY 2: Match by expected per-unit amount
            if not matched_trade:
                expected_per_unit = None
                if bond and bond.get('cashflows_per_unit'):
                    log_month = log_repayment_date[:7] if log_repayment_date else ''
                    for cf in bond['cashflows_per_unit']:
                        cf_date = (cf.get('date', '') or '')[:10]
                        cf_month = cf_date[:7] if cf_date else ''
                        if cf_month == log_month:
                            expected_per_unit = cf.get('gross_per_unit') or (cf.get('principal_per_unit', 0) + cf.get('interest_per_unit', 0))
                            break
                
                # Find trade with closest expected amount
                if expected_per_unit and expected_per_unit > 0:
                    best_diff = float('inf')
                    for trade in trades:
                        units = trade.get('units', 0)
                        if units <= 0:
                            continue
                        expected_total = units * expected_per_unit
                        diff = abs(log_gross_amount - expected_total)
                        diff_pct = diff / expected_total if expected_total > 0 else float('inf')
                        if diff_pct < 0.05 and diff < best_diff:
                            best_diff = diff
                            matched_trade = trade
            
            # Fallback 2: Match by client name + units (aggressive matching)
            if not matched_trade:
                log_units = log.get('units', 0)
                if log_units > 0 and log_client_name:
                    # Normalize client name for matching
                    log_name_normalized = ' '.join(log_client_name.lower().strip().split())
                    for trade in trades:
                        trade_units = trade.get('units', 0)
                        trade_client_name = trade.get('client_name', '')
                        if trade_units == log_units and trade_client_name:
                            trade_name_normalized = ' '.join(trade_client_name.lower().strip().split())
                            # Check if names match (at least 80% similarity or exact unit match)
                            if trade_name_normalized == log_name_normalized or log_name_normalized in trade_name_normalized or trade_name_normalized in log_name_normalized:
                                matched_trade = trade
                                break
            
            if not matched_trade:
                continue
            
            units = matched_trade.get('units', 0)
            if units > 0:
                per_unit_amount = round(log_gross_amount / units, 2)
            
            # Create actual_repayment
            repayment_id = str(uuid.uuid4())
            repayment_record = {
                "id": repayment_id,
                "client_id": matched_trade.get('client_id'),
                "client_name": matched_trade.get('client_name'),
                "bond_code": bond_code,
                "bond_id": matched_trade.get('bond_id'),
                "trade_id": matched_trade.get('id'),
                "investment_date": matched_trade.get('investment_date'),  # CRITICAL: Set investment_date for proper matching
                "repayment_date": log_repayment_date,
                "gross_amount": log_gross_amount,
                "units": units,
                "per_unit_amount": per_unit_amount,
                "source": "auto_tag",
                "email_log_id": log_id,
                "created_at": datetime.now(timezone.utc).isoformat()
            }
            
            await db_instance.actual_repayments.insert_one(repayment_record)
            
            # Update email log
            await db_instance.email_read_logs.update_one(
                {"id": log_id},
                {"$set": {
                    "holding_updated": True,
                    "holding_updated_at": datetime.now(timezone.utc).isoformat(),
                    "actual_repayment_id": repayment_id
                }}
            )
            
            tagged_count += 1
    
    return {
        "success": True,
        "tagged_count": tagged_count,
        "duplicate_count": duplicate_count
    }


@api_router.post("/email-engagement/auto-tag")
async def auto_tag_email_repayments(
    current_user: dict = Depends(get_current_user)
):
    """
    Auto-tag pending email repayments to actual repayments.
    
    LOGIC:
    1. Deduplicate emails by (client_name, gross_amount, repayment_date) - same repayment may have multiple emails
    2. For each unique repayment, divide amount by each trade's units
    3. If result is an INTEGER → Match found, tag to that transaction
    4. After tagging, update the final maturity cashflow to reduce by prepayment amount
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can auto-tag repayments")
    
    # Get all pending email logs (not yet tagged)
    pending_logs = await db.email_read_logs.find(
        {"holding_updated": {"$ne": True}},
        {"_id": 0}
    ).to_list(1000)
    
    if not pending_logs:
        return {"success": True, "message": "No pending emails to tag", "tagged_count": 0}
    
    tagged_count = 0
    skipped_count = 0
    duplicate_count = 0
    tagged_details = []
    
    # STEP 1: Each email is unique - include email_date in the key
    # Only emails with SAME (bond_code, client_name, gross_amount, repayment_date, email_date) are true duplicates
    # Different email_dates = different transactions even if amounts match
    unique_repayments = {}
    for log in pending_logs:
        key = (
            log.get('bond_code', ''),
            log.get('client_name', ''),
            log.get('gross_amount', 0),
            log.get('repayment_date', ''),
            log.get('email_date', '')  # Include email_date to treat different emails as unique
        )
        if key not in unique_repayments:
            unique_repayments[key] = log
        else:
            duplicate_count += 1
            # Mark duplicate email as processed (linked to the main one)
            await db.email_read_logs.update_one(
                {"id": log.get('id')},
                {
                    "$set": {
                        "holding_updated": True,
                        "holding_updated_at": datetime.now(timezone.utc).isoformat(),
                        "is_duplicate": True,
                        "duplicate_of": unique_repayments[key].get('id')
                    }
                }
            )
    
    # Group unique repayments by bond_code
    deal_logs = {}
    for key, log in unique_repayments.items():
        bond_code = key[0]
        if bond_code not in deal_logs:
            deal_logs[bond_code] = []
        deal_logs[bond_code].append(log)
    
    for bond_code, logs in deal_logs.items():
        if not bond_code:
            continue
        
        # Get all trades for this bond with their units
        trades = await db.Ncd_Investment_Details.find(
            {"bond_code": bond_code, "status": {"$ne": "cancelled"}},
            {"_id": 0}
        ).to_list(1000)
        
        if not trades:
            continue
        
        # Process each email log for this deal
        for log in logs:
            log_id = log.get('id')
            log_client_name = log.get('client_name', '')
            log_gross_amount = log.get('gross_amount', 0) or 0
            log_net_amount = log.get('net_amount', 0) or 0
            log_tds = log.get('tds_amount', 0) or 0
            log_repayment_date = log.get('repayment_date', '')
            
            if log_gross_amount <= 0:
                continue
            
            # IDEMPOTENCY CHECK 1: Skip if this email_log_id already has repayments
            existing_by_email = await db.actual_repayments.find_one({
                "email_log_id": log_id
            })
            if existing_by_email:
                skipped_count += 1
                continue
            
            # Find the matching trade by comparing email amount to expected amounts for each trade
            # For each trade, calculate expected amount = units × per_unit_expected
            # Match to the trade whose expected amount is closest to the email amount
            matched_trade = None
            per_unit_amount = None
            
            # Get bond's expected per-unit amount for this date
            bond_check = await db.Ncd_Master.find_one(
                {"bond_code": bond_code},
                {"_id": 0, "cashflows_per_unit": 1}
            )
            
            expected_per_unit = None
            if bond_check and bond_check.get('cashflows_per_unit'):
                log_month = log_repayment_date[:7] if log_repayment_date else ''
                for cf in bond_check['cashflows_per_unit']:
                    cf_date = (cf.get('date', '') or '')[:10]
                    cf_month = cf_date[:7] if cf_date else ''
                    if cf_month == log_month:
                        expected_per_unit = cf.get('gross_per_unit') or (cf.get('principal_per_unit', 0) + cf.get('interest_per_unit', 0))
                        break
            
            # Find the trade whose expected amount is closest to the email amount
            if expected_per_unit and expected_per_unit > 0:
                best_match = None
                best_diff = float('inf')
                
                for trade in trades:
                    units = trade.get('units', 0)
                    if units <= 0:
                        continue
                    
                    # Calculate expected total for this trade
                    expected_total = units * expected_per_unit
                    
                    # Calculate difference from email amount
                    diff = abs(log_gross_amount - expected_total)
                    diff_pct = diff / expected_total if expected_total > 0 else float('inf')
                    
                    # Only consider if within 5% tolerance
                    if diff_pct < 0.05 and diff < best_diff:
                        best_diff = diff
                        best_match = trade
                
                if best_match:
                    matched_trade = best_match
                    units = matched_trade.get('units', 0)
                    if units > 0:
                        per_unit_amount = round(log_gross_amount / units, 2)
            
            # Fallback: Use pre-matched trade from email processing if no better match found
            if not matched_trade:
                pre_matched_trade_id = log.get('matched_trade_id')
                if pre_matched_trade_id:
                    matched_trade = next((t for t in trades if t.get('id') == pre_matched_trade_id), None)
                    if matched_trade:
                        units = matched_trade.get('units', 0)
                        if units > 0:
                            per_unit_amount = round(log_gross_amount / units, 2)
            
            # Final fallback: Match by client name if only one trade exists
            if not matched_trade:
                client_trades = [t for t in trades if t.get('client_name', '').lower() == log_client_name.lower()]
                if len(client_trades) == 1:
                    matched_trade = client_trades[0]
                    units = matched_trade.get('units', 0)
                    if units > 0:
                        per_unit_amount = round(log_gross_amount / units, 2)
            
            if not matched_trade:
                # No match found - skip this log
                continue
            
            # Get investment date for this trade
            investment_date = matched_trade.get('investment_date') or matched_trade.get('created_at', '')
            investment_date_str = str(investment_date)[:10] if investment_date else ''
            
            # DUPLICATE CHECK 1: Check if this matches a historical repayment
            # Match by: same date, same deal/bond, similar amount (within 1% tolerance)
            # Use aggregation to find entries with similar amounts
            similar_amount_min = log_gross_amount * 0.99
            similar_amount_max = log_gross_amount * 1.01
            
            existing_historical = await db.actual_repayments.find_one({
                "bond_code": bond_code,
                "repayment_date": log_repayment_date,
                "gross_amount": {"$gte": similar_amount_min, "$lte": similar_amount_max}
            })
            if existing_historical:
                # Mark this email log as processed (it matches a historical entry)
                await db.email_read_logs.update_one(
                    {"id": log_id},
                    {
                        "$set": {
                            "holding_updated": True,
                            "holding_updated_at": datetime.now(timezone.utc).isoformat(),
                            "linked_to_historical": True,
                            "linked_to_repayment_id": existing_historical.get('id')
                        }
                    }
                )
                duplicate_count += 1
                continue
            
            # DUPLICATE CHECK 2: Use (client_name, trade_id, gross_amount, repayment_date) as unique combination
            # This allows entries with same amount for different trades of the same client
            existing_by_combo = await db.actual_repayments.find_one({
                "client_name": matched_trade.get('client_name'),
                "trade_id": matched_trade.get('id'),
                "gross_amount": log_gross_amount,
                "repayment_date": log_repayment_date
            })
            if existing_by_combo:
                # Mark this email log as processed (it's a duplicate of an already-processed repayment)
                await db.email_read_logs.update_one(
                    {"id": log_id},
                    {
                        "$set": {
                            "holding_updated": True,
                            "holding_updated_at": datetime.now(timezone.utc).isoformat(),
                            "is_duplicate_repayment": True,
                            "linked_to_repayment_id": existing_by_combo.get('id')
                        }
                    }
                )
                duplicate_count += 1
                continue
            
            # Determine if this is a scheduled repayment or prepayment
            # Logic:
            # 1. Check if payment date matches an expected cashflow date (by month/year)
            # 2. Check if there are other payments from same bond on the same day (indicates regular payout)
            # 3. If amount is pure interest (no principal), it's scheduled
            bond = await db.Ncd_Master.find_one(
                {"$or": [{"bond_code": bond_code}, {"id": matched_trade.get('bond_id')}]},
                {"_id": 0, "cashflows_per_unit": 1, "end_date": 1, "maturity_date": 1, "interest_payments": 1, "coupon_rate": 1, "payment_frequency": 1}
            )
            
            is_scheduled_payment = False
            matched_cf_date = None
            
            # Method 1: Check against explicit cashflow dates
            if bond and bond.get('cashflows_per_unit'):
                for cf in bond['cashflows_per_unit']:
                    cf_date = (cf.get('date', '') or '')[:10]
                    cf_month_year = cf_date[:7] if cf_date else ''
                    log_date_str = (log_repayment_date or '')[:10]
                    log_month_year = log_date_str[:7] if log_date_str else ''
                    
                    # Match by month/year (allow flexibility in exact day)
                    if cf_month_year and log_month_year and cf_month_year == log_month_year:
                        is_scheduled_payment = True
                        matched_cf_date = cf_date
                        break
            
            # Method 2: Check interest_payments array
            if not is_scheduled_payment and bond and bond.get('interest_payments'):
                for ip in bond['interest_payments']:
                    ip_date = (ip.get('date', '') or '')[:10]
                    ip_month_year = ip_date[:7] if ip_date else ''
                    log_month_year = (log_repayment_date or '')[:7]
                    
                    if ip_month_year and log_month_year and ip_month_year == log_month_year:
                        is_scheduled_payment = True
                        matched_cf_date = ip_date
                        break
            
            # Method 3: If bond has monthly payment frequency, assume regular monthly payments are scheduled
            if not is_scheduled_payment and bond:
                payment_freq = bond.get('payment_frequency', '').lower()
                if payment_freq in ['monthly', 'quarterly', 'semi-annual', 'annual']:
                    # Check if this is a monthly payment date (before maturity)
                    maturity_str = bond.get('end_date') or bond.get('maturity_date') or ''
                    maturity_date = None
                    try:
                        maturity_date = datetime.strptime(maturity_str[:10], '%Y-%m-%d')
                    except:
                        pass
                    
                    try:
                        log_date = datetime.strptime(log_repayment_date[:10], '%Y-%m-%d')
                        if maturity_date and log_date < maturity_date:
                            # This is before maturity, likely a scheduled interest payment
                            is_scheduled_payment = True
                            matched_cf_date = log_repayment_date
                    except:
                        pass
            
            # Method 4: Check if multiple clients received payment on same day for same bond = scheduled
            if not is_scheduled_payment:
                same_day_payments = [l for l in logs if l.get('repayment_date') == log_repayment_date]
                if len(same_day_payments) > 1:
                    # Multiple clients paid on same day = scheduled payment
                    is_scheduled_payment = True
                    matched_cf_date = log_repayment_date
            
            # Determine payment type
            payment_type = "scheduled" if is_scheduled_payment else "prepayment"
            is_prepayment = not is_scheduled_payment
            
            # Create the actual_repayment record
            repayment_id = str(uuid.uuid4())
            
            # Calculate principal and interest components based on payment type
            principal_amount = 0
            interest_amount = 0
            if is_scheduled_payment and bond and bond.get('cashflows_per_unit'):
                # For scheduled payments, get principal/interest from expected cashflow
                for cf in bond['cashflows_per_unit']:
                    cf_date = (cf.get('date', '') or '')[:10]
                    if cf_date[:7] == (log_repayment_date or '')[:7]:
                        units = matched_trade.get('units', 0)
                        principal_amount = (cf.get('principal_per_unit', 0) or 0) * units
                        interest_amount = (cf.get('interest_per_unit', 0) or 0) * units
                        break
            else:
                # For prepayments, assume it's all principal
                principal_amount = log_gross_amount
                interest_amount = 0
            
            repayment_record = {
                "id": repayment_id,
                "client_id": matched_trade.get('client_id'),
                "client_name": matched_trade.get('client_name'),
                "original_email_client": log_client_name,
                "bond_id": matched_trade.get('bond_id'),
                "bond_name": matched_trade.get('bond_name'),
                "bond_code": bond_code,
                "repayment_date": log_repayment_date,
                "investment_date": investment_date_str,
                "gross_amount": log_gross_amount,
                "principal": principal_amount,
                "interest": interest_amount,
                "net_amount": log_net_amount,
                "tds": log_tds,
                "units": matched_trade.get('units'),
                "per_unit_amount": per_unit_amount,
                "payment_type": payment_type,
                "is_prepayment": is_prepayment,
                "is_scheduled": is_scheduled_payment,
                "matched_cf_date": matched_cf_date,
                "email_log_id": log_id,
                "trade_id": matched_trade.get('id'),
                "auto_tagged": True,
                "match_method": "units_division",
                "created_by": current_user.get('id'),
                "created_at": datetime.now(timezone.utc).isoformat(),
                "source": "auto_tag"
            }
            
            await db.actual_repayments.insert_one(repayment_record)
            
            # UPDATE FINAL MATURITY CASHFLOW: Only for prepayments
            # For scheduled payments, don't recalculate - just mark as paid
            trade_id = matched_trade.get('id')
            
            if trade_id and is_prepayment:
                # Find ALL cashflows for this trade, sorted by date descending to get the final one
                final_cashflow = await db.holding_cashflows.find_one(
                    {"trade_id": trade_id},
                    {"_id": 0},
                    sort=[("date", -1)]
                )
                
                if final_cashflow:
                    # Get bond details for coupon rate
                    bond = await db.Ncd_Master.find_one(
                        {"id": matched_trade.get('bond_id')},
                        {"_id": 0, "coupon_rate": 1, "end_date": 1}
                    )
                    coupon_rate = (bond.get('coupon_rate', 18.0) / 100) if bond else 0.18
                    
                    # Get maturity date from bond or cashflow
                    maturity_date_str = bond.get('end_date') if bond else final_cashflow.get('date', '')
                    try:
                        maturity_date = datetime.strptime(maturity_date_str[:10], '%Y-%m-%d')
                    except:
                        maturity_date = datetime.now() + timedelta(days=365)
                    
                    # Get BOND START DATE for interest calculation (not investment date)
                    bond_start_date_str = bond.get('start_date', '') if bond else ''
                    try:
                        bond_start_date = datetime.strptime(str(bond_start_date_str)[:10], '%Y-%m-%d')
                    except:
                        # Fallback to investment date if bond start date not available
                        inv_date_str = matched_trade.get('investment_date', '')
                        try:
                            bond_start_date = datetime.strptime(str(inv_date_str)[:10], '%Y-%m-%d')
                        except:
                            bond_start_date = datetime.now() - timedelta(days=365)
                    
                    # Get ALL repayments for this trade, sorted by date
                    # Query by both trade_id AND investment_date to catch all repayments
                    all_repayments = await db.actual_repayments.find(
                        {
                            "$or": [
                                {"trade_id": trade_id},
                                {
                                    "client_name": matched_trade.get('client_name'),
                                    "bond_code": bond_code,
                                    "investment_date": investment_date_str
                                }
                            ]
                        },
                        {"_id": 0}
                    ).sort("repayment_date", 1).to_list(100)
                    
                    # Deduplicate by (repayment_date, gross_amount) in case of overlap
                    seen = set()
                    unique_repayments = []
                    for rep in all_repayments:
                        key = (rep.get('repayment_date'), rep.get('gross_amount'))
                        if key not in seen:
                            seen.add(key)
                            unique_repayments.append(rep)
                    all_repayments = unique_repayments
                    
                    # Store original values if not already stored
                    original_gross = final_cashflow.get('original_gross_amount') or final_cashflow.get('gross_amount', 0)
                    original_net = final_cashflow.get('original_net_amount') or final_cashflow.get('net_amount', 0)
                    
                    # USE FACE VALUE for principal calculation, not investment amount
                    # Face Value = Units × ₹1,00,000 (standard face value per unit)
                    units = matched_trade.get('units', 0)
                    face_value_per_unit = bond.get('face_value', 100000) if bond else 100000
                    original_principal = units * face_value_per_unit
                    
                    # Calculate interest period by period from BOND START DATE
                    total_interest = 0
                    balance_principal = original_principal
                    prev_date = bond_start_date  # Interest starts from bond start date
                    interest_breakdown = []
                    
                    for rep in all_repayments:
                        rep_date_str = rep.get('repayment_date', '')
                        try:
                            rep_date = datetime.strptime(rep_date_str[:10], '%Y-%m-%d')
                        except:
                            continue
                        rep_amount = rep.get('gross_amount', 0)
                        
                        # Include BOTH start and end dates (+1)
                        days = max(0, (rep_date - prev_date).days + 1)
                        interest = balance_principal * coupon_rate * days / 365
                        total_interest += interest
                        
                        interest_breakdown.append({
                            'from': prev_date.strftime('%Y-%m-%d'),
                            'to': rep_date.strftime('%Y-%m-%d'),
                            'days': days,
                            'balance': round(balance_principal, 2),
                            'interest': round(interest, 2),
                            'prepayment': rep_amount
                        })
                        
                        balance_principal -= rep_amount
                        prev_date = rep_date
                    
                    # Final period: Last prepayment to maturity (include both dates)
                    days_final = max(0, (maturity_date - prev_date).days + 1)
                    interest_final = balance_principal * coupon_rate * days_final / 365
                    total_interest += interest_final
                    
                    interest_breakdown.append({
                        'from': prev_date.strftime('%Y-%m-%d'),
                        'to': maturity_date.strftime('%Y-%m-%d'),
                        'days': days_final,
                        'balance': round(balance_principal, 2),
                        'interest': round(interest_final, 2),
                        'prepayment': 0
                    })
                    
                    # Final maturity = remaining principal + total interest
                    new_gross = balance_principal + total_interest
                    total_prepaid = sum(r.get('gross_amount', 0) for r in all_repayments)
                    
                    # TDS is 10% of total interest
                    tds_on_interest = total_interest * 0.10
                    new_net = new_gross - tds_on_interest
                    
                    await db.holding_cashflows.update_one(
                        {"id": final_cashflow.get('id')},
                        {
                            "$set": {
                                "original_gross_amount": original_gross,
                                "original_net_amount": original_net,
                                "gross_amount": round(new_gross, 2),
                                "net_amount": round(new_net, 2),
                                "principal_component": round(balance_principal, 2),
                                "interest_component": round(total_interest, 2),
                                "tds_amount": round(tds_on_interest, 2),
                                "is_prepayment_adjusted": True,
                                "prepayment_adjustment_date": datetime.now(timezone.utc).isoformat(),
                                "total_prepaid": round(total_prepaid, 2),
                                "remaining_principal": round(balance_principal, 2),
                                "prepayment_count": len(all_repayments),
                                "interest_breakdown": interest_breakdown,
                                "coupon_rate_used": coupon_rate,
                                "prepayment_source": "auto_tag"
                            }
                        }
                    )
            
            # Mark email log as processed
            await db.email_read_logs.update_one(
                {"id": log_id},
                {
                    "$set": {
                        "holding_updated": True,
                        "holding_updated_at": datetime.now(timezone.utc).isoformat(),
                        "auto_tagged": True,
                        "matched_trade_id": matched_trade.get('id'),
                        "matched_investment_date": investment_date_str,
                        "matched_units": matched_trade.get('units'),
                        "per_unit_amount": per_unit_amount
                    }
                }
            )
            
            tagged_count += 1
            tagged_details.append({
                "email_client": log_client_name,
                "matched_client": matched_trade.get('client_name'),
                "gross_amount": log_gross_amount,
                "matched_units": matched_trade.get('units'),
                "per_unit_amount": per_unit_amount,
                "investment_date": investment_date_str,
                "trade_id": matched_trade.get('id'),
                "maturity_adjusted": True
            })
    
    # After all tagging is complete, recalculate maturity for ALL affected trades
    # This ensures historical + new repayments are all considered
    if tagged_count > 0:
        # Get unique trade_ids that were tagged
        affected_trade_ids = list(set(d.get('trade_id') for d in tagged_details if d.get('trade_id')))
        
        # Recalculate maturity for each affected trade
        for trade_id in affected_trade_ids:
            trade = await db.Ncd_Investment_Details.find_one({"id": trade_id}, {"_id": 0})
            if trade:
                bond = await db.Ncd_Master.find_one({"bond_code": trade.get('bond_code')}, {"_id": 0})
                await recalculate_maturity_for_trade(trade, bond or {}, db)
    
    # Create notifications for entries that couldn't be auto-tagged
    untaggable_entries = await db.email_read_logs.find({
        "holding_updated": {"$ne": True},
        "matched_client_id": {"$exists": False}
    }, {"_id": 0}).to_list(100)
    
    if untaggable_entries:
        # Get broker_id from current_user
        broker_id = current_user.get('id')
        
        # Group by client name for notification summary
        untaggable_clients = {}
        for entry in untaggable_entries:
            client_name = entry.get('client_name', 'Unknown')
            if client_name not in untaggable_clients:
                untaggable_clients[client_name] = []
            untaggable_clients[client_name].append(entry)
        
        # Create a single notification for all untaggable entries
        notification = {
            "id": str(uuid.uuid4()),
            "type": "email_untaggable",
            "title": f"{len(untaggable_entries)} Email Entries Need Manual Tagging",
            "message": f"Could not auto-tag entries for: {', '.join(list(untaggable_clients.keys())[:3])}{'...' if len(untaggable_clients) > 3 else ''}. Please review in Email Tracker.",
            "link": "/broker/email-engagement",
            "untaggable_count": len(untaggable_entries),
            "client_names": list(untaggable_clients.keys()),
            "user_id": broker_id,
            "user_role": "broker",
            "is_read": False,
            "created_at": datetime.now(timezone.utc).isoformat()
        }
        
        # Check if similar notification already exists (avoid duplicates)
        existing_notification = await db.notifications.find_one({
            "type": "email_untaggable",
            "user_id": broker_id,
            "is_read": False
        })
        
        if not existing_notification:
            await db.notifications.insert_one(notification)
        else:
            # Update existing notification with new count
            await db.notifications.update_one(
                {"id": existing_notification.get('id')},
                {"$set": {
                    "title": f"{len(untaggable_entries)} Email Entries Need Manual Tagging",
                    "untaggable_count": len(untaggable_entries),
                    "client_names": list(untaggable_clients.keys()),
                    "updated_at": datetime.now(timezone.utc).isoformat()
                }}
            )
    
    return {
        "success": True,
        "message": f"Auto-tagged {tagged_count} email repayments ({skipped_count} already tagged, {duplicate_count} duplicates)",
        "tagged_count": tagged_count,
        "skipped_count": skipped_count,
        "duplicate_count": duplicate_count,
        "details": tagged_details,
        "maturity_recalculated": tagged_count > 0,
        "untaggable_count": len(untaggable_entries) if untaggable_entries else 0
    }




@api_router.post("/email-engagement/auto-tag-single")
async def auto_tag_single_email(
    request: dict,
    current_user: dict = Depends(get_current_user)
):
    """
    Auto-tag a single email entry after client has been matched.
    This creates an actual_repayment entry and updates holding_cashflows.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can auto-tag repayments")
    
    log_id = request.get('log_id')
    client_id = request.get('client_id')
    gross_amount = request.get('gross_amount', 0)
    bond_code = request.get('bond_code')
    
    if not log_id or not client_id:
        raise HTTPException(status_code=400, detail="log_id and client_id are required")
    
    # Get the email log
    email_log = await db.email_read_logs.find_one({"id": log_id}, {"_id": 0})
    if not email_log:
        raise HTTPException(status_code=404, detail="Email log not found")
    
    # Get the client
    client = await db.Private_Investor.find_one({"id": client_id}, {"_id": 0})
    if not client:
        raise HTTPException(status_code=404, detail="Client not found")
    
    # Get the trade for this client and bond
    trade = await db.Ncd_Investment_Details.find_one({
        "client_id": client_id,
        "bond_code": bond_code,
        "status": {"$ne": "cancelled"}
    }, {"_id": 0})
    
    if not trade:
        raise HTTPException(status_code=404, detail="No trade found for this client and bond")
    
    # Check if already tagged
    existing = await db.actual_repayments.find_one({
        "email_log_id": log_id
    })
    if existing:
        return {"success": False, "message": "This entry is already tagged"}
    
    # Create actual_repayment entry
    repayment_id = str(uuid.uuid4())
    repayment_date = email_log.get('repayment_date', datetime.now(timezone.utc).strftime('%Y-%m-%d'))
    investment_date = trade.get('investment_date', '')
    
    actual_repayment = {
        "id": repayment_id,
        "trade_id": trade.get('id'),
        "client_id": client_id,
        "client_name": client.get('name', ''),
        "bond_code": bond_code,
        "bond_id": trade.get('bond_id'),
        "investment_date": investment_date,
        "repayment_date": repayment_date,
        "gross_amount": email_log.get('gross_amount', 0),
        "net_amount": email_log.get('net_amount', 0),
        "tds_amount": email_log.get('tds_amount', 0),
        "principal": email_log.get('principal', 0),
        "interest": email_log.get('interest', 0),
        "source": "email_manual_tag",
        "email_log_id": log_id,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "created_by": current_user.get('id')
    }
    
    await db.actual_repayments.insert_one(actual_repayment)
    
    # Update holding_cashflows to mark as repaid
    # Find matching holding_cashflow by amount
    holding_cf = await db.holding_cashflows.find_one({
        "trade_id": trade.get('id'),
        "gross_amount": email_log.get('gross_amount', 0),
        "is_repaid": {"$ne": True}
    })
    
    if holding_cf:
        await db.holding_cashflows.update_one(
            {"id": holding_cf.get('id')},
            {
                "$set": {
                    "is_repaid": True,
                    "repaid_date": repayment_date,
                    "repaid_at": datetime.now(timezone.utc).isoformat(),
                    "actual_repayment_id": repayment_id
                }
            }
        )
    
    # Update email log as processed
    await db.email_read_logs.update_one(
        {"id": log_id},
        {
            "$set": {
                "holding_updated": True,
                "holding_updated_at": datetime.now(timezone.utc).isoformat(),
                "auto_tagged": True,
                "matched_trade_id": trade.get('id'),
                "matched_investment_date": investment_date,
                "matched_client_id": client_id,
                "matched_client_name": client.get('name', '')
            }
        }
    )
    
    # Recalculate maturity for this trade if needed
    bond = await db.Ncd_Master.find_one({"bond_code": bond_code}, {"_id": 0})
    if bond:
        try:
            await recalculate_maturity_for_trade(trade, bond, db)
        except Exception as e:
            logger.error(f"Error recalculating maturity: {e}")
    
    return {
        "success": True,
        "message": f"Entry auto-tagged successfully for {client.get('name', '')}",
        "repayment_id": repayment_id,
        "trade_id": trade.get('id'),
        "investment_date": investment_date
    }


@api_router.post("/email-engagement/reset-client-tags/{client_name}")
async def reset_client_prepayment_tags(
    client_name: str,
    current_user: dict = Depends(get_current_user)
):
    """
    Reset prepayment tags for a specific client to allow retagging.
    This removes actual_repayment entries and resets email_read_logs for the client.
    """
    import urllib.parse
    client_name = urllib.parse.unquote(client_name)
    
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can reset client tags")
    
    # Find and delete actual_repayments for this client (auto-tagged ones)
    deleted_repayments = await db.actual_repayments.delete_many({
        "$or": [
            {"client_name": client_name},
            {"original_email_client": client_name}
        ],
        "source": "auto_tag"
    })
    
    # Reset email_read_logs for this client to allow retagging
    reset_result = await db.email_read_logs.update_many(
        {"client_name": client_name},
        {
            "$set": {
                "holding_updated": False
            },
            "$unset": {
                "holding_updated_at": "",
                "is_duplicate": "",
                "is_duplicate_repayment": "",
                "linked_to_repayment_id": "",
                "auto_tagged": "",
                "matched_trade_id": "",
                "matched_investment_date": "",
                "matched_units": "",
                "per_unit_amount": ""
            }
        }
    )
    
    return {
        "success": True,
        "message": f"Reset tags for client: {client_name}",
        "deleted_repayments": deleted_repayments.deleted_count,
        "reset_email_logs": reset_result.modified_count
    }


@api_router.get("/email-engagement/pending-tags")
async def get_pending_email_tags(
    current_user: dict = Depends(get_current_user)
):
    """
    Get list of pending email logs that haven't been auto-tagged yet.
    Groups by client name for easier review.
    """
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Access denied")
    
    # Get pending email logs
    pending_logs = await db.email_read_logs.find(
        {"holding_updated": {"$ne": True}},
        {"_id": 0}
    ).to_list(1000)
    
    # Group by client name
    by_client = {}
    for log in pending_logs:
        client_name = log.get('client_name', 'Unknown')
        if client_name not in by_client:
            by_client[client_name] = []
        by_client[client_name].append({
            "id": log.get('id'),
            "bond_code": log.get('bond_code'),
            "gross_amount": log.get('gross_amount'),
            "repayment_date": log.get('repayment_date'),
            "net_amount": log.get('net_amount'),
            "tds_amount": log.get('tds_amount')
        })
    
    return {
        "total_pending": len(pending_logs),
        "by_client": by_client,
        "client_count": len(by_client)
    }


# ==================== MATURITY RECALCULATION ====================

async def recalculate_maturity_for_trade(trade: dict, bond: dict, db_instance) -> dict:
    """
    Recalculate maturity amount for a single trade considering ALL prepayments.
    
    Logic:
    1. Interest starts from BOND START DATE (not investment date)
    2. Interest calculated period by period on REDUCING BALANCE
    3. Include BOTH start and end dates (+1 day)
    4. Principal = Face Value (units × face_value_per_unit), NOT investment amount
    5. Consider ALL repayments (historical + auto-tagged)
    """
    from datetime import datetime, timedelta, timezone
    from collections import defaultdict
    
    trade_id = trade.get('id')
    client_name = trade.get('client_name')
    bond_code = trade.get('bond_code')
    units = trade.get('units', 0)
    investment_date_str = str(trade.get('investment_date', ''))[:10]
    
    # Bond details
    coupon_rate = (bond.get('coupon_rate', 18.73) / 100) if bond else 0.1873
    face_value_per_unit = bond.get('face_value', 100000) if bond else 100000
    
    # Get bond start date
    bond_start_date_str = bond.get('start_date', '') if bond else ''
    try:
        bond_start_date = datetime.strptime(str(bond_start_date_str)[:10], '%Y-%m-%d')
    except:
        bond_start_date = datetime(2024, 10, 8)  # Default fallback
    
    # Get maturity date
    maturity_date_str = bond.get('end_date', '') if bond else ''
    try:
        maturity_date = datetime.strptime(str(maturity_date_str)[:10], '%Y-%m-%d')
    except:
        maturity_date = datetime(2026, 4, 8)  # Default fallback
    
    # Face value (principal)
    original_principal = units * face_value_per_unit
    
    # Get ALL repayments for this trade
    all_repayments = await db_instance.actual_repayments.find(
        {
            "$or": [
                {"trade_id": trade_id},
                {
                    "client_name": client_name,
                    "bond_code": bond_code,
                    "investment_date": investment_date_str
                }
            ]
        },
        {"_id": 0}
    ).sort("repayment_date", 1).to_list(100)
    
    # Deduplicate by (repayment_date, gross_amount)
    seen = set()
    unique_repayments = []
    for rep in all_repayments:
        key = (rep.get('repayment_date'), rep.get('gross_amount'))
        if key not in seen:
            seen.add(key)
            unique_repayments.append(rep)
    all_repayments = unique_repayments
    
    # Calculate interest period by period
    balance_principal = original_principal
    prev_date = bond_start_date
    total_interest = 0
    total_prepaid = 0
    interest_breakdown = []
    
    for rep in all_repayments:
        rep_date_str = rep.get('repayment_date', '')
        try:
            rep_date = datetime.strptime(rep_date_str[:10], '%Y-%m-%d')
        except:
            continue
        
        # Get principal component - this is what reduces the balance
        # gross_amount includes both principal + interest, so we need to extract just principal
        rep_principal = rep.get('principal', 0) or 0
        rep_gross = rep.get('gross_amount', 0) or 0
        
        # If principal is not specified, assume gross is all principal (prepayment scenario)
        # This handles legacy data where only gross_amount was recorded
        if rep_principal == 0 and rep_gross > 0:
            rep_principal = rep_gross
        
        # Include BOTH start and end dates (+1)
        days = (rep_date - prev_date).days + 1
        period_interest = balance_principal * coupon_rate * days / 365
        total_interest += period_interest
        total_prepaid += rep_principal  # Track principal prepaid, not gross
        
        interest_breakdown.append({
            'from': prev_date.strftime('%Y-%m-%d'),
            'to': rep_date.strftime('%Y-%m-%d'),
            'days': days,
            'balance': round(balance_principal, 2),
            'interest': round(period_interest, 2),
            'prepayment': rep_principal,  # Principal prepaid
            'gross_received': rep_gross
        })
        
        balance_principal -= rep_principal  # Only subtract principal, not interest
        if balance_principal < 0:
            balance_principal = 0
        prev_date = rep_date
    
    # Final period to maturity
    days_final = (maturity_date - prev_date).days + 1
    final_interest = balance_principal * coupon_rate * days_final / 365
    total_interest += final_interest
    
    interest_breakdown.append({
        'from': prev_date.strftime('%Y-%m-%d'),
        'to': maturity_date.strftime('%Y-%m-%d'),
        'days': days_final,
        'balance': round(balance_principal, 2),
        'interest': round(final_interest, 2),
        'prepayment': 0
    })
    
    # Final maturity = remaining principal + total interest
    final_maturity = balance_principal + total_interest
    
    # TDS on interest (10%)
    tds = total_interest * 0.10
    net_maturity = final_maturity - tds
    
    # Update holding_cashflows
    final_cf = await db_instance.holding_cashflows.find_one(
        {"trade_id": trade_id},
        {"_id": 1, "original_gross_amount": 1, "original_net_amount": 1, "gross_amount": 1, "net_amount": 1},
        sort=[("date", -1)]
    )
    
    if final_cf:
        original_gross = final_cf.get('original_gross_amount') or final_cf.get('gross_amount', 0)
        original_net = final_cf.get('original_net_amount') or final_cf.get('net_amount', 0)
        
        await db_instance.holding_cashflows.update_one(
            {"_id": final_cf['_id']},
            {
                "$set": {
                    "original_gross_amount": original_gross,
                    "original_net_amount": original_net,
                    "gross_amount": round(final_maturity, 2),
                    "net_amount": round(net_maturity, 2),
                    "principal_component": round(balance_principal, 2),
                    "interest_component": round(total_interest, 2),
                    "tds_amount": round(tds, 2),
                    "is_prepayment_adjusted": True,
                    "total_prepaid": round(total_prepaid, 2),
                    "remaining_principal": round(balance_principal, 2),
                    "original_face_value": original_principal,
                    "interest_start_date": bond_start_date.strftime('%Y-%m-%d'),
                    "day_count_convention": "inclusive_both",
                    "interest_breakdown": interest_breakdown,
                    "prepayment_count": len(all_repayments),
                    "prepayment_adjustment_date": datetime.now(timezone.utc).isoformat()
                }
            }
        )
    
    return {
        "trade_id": trade_id,
        "investment_date": investment_date_str,
        "units": units,
        "total_prepaid": round(total_prepaid, 2),
        "remaining_principal": round(balance_principal, 2),
        "total_interest": round(total_interest, 2),
        "final_maturity": round(final_maturity, 2),
        "repayment_count": len(all_repayments)
    }


@api_router.post("/admin/recalculate-maturity")
async def recalculate_all_maturity(
    bond_code: Optional[str] = None,
    client_name: Optional[str] = None,
    current_user: dict = Depends(get_current_user)
):
    """
    Recalculate maturity amounts for all trades with prepayments.
    This fixes any incorrect maturity calculations by re-running the complete calculation.
    
    Parameters:
    - bond_code: Optional filter by bond
    - client_name: Optional filter by client
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can recalculate maturity")
    
    # Build query for trades
    trade_query = {}
    if bond_code:
        trade_query['bond_code'] = bond_code
    if client_name:
        trade_query['client_name'] = client_name
    
    # Get all relevant trades
    trades = await db.Ncd_Investment_Details.find(trade_query, {"_id": 0}).to_list(1000)
    
    if not trades:
        return {"success": True, "message": "No trades found", "updated_count": 0}
    
    # Get unique bond_codes
    bond_codes = list(set(t.get('bond_code') for t in trades if t.get('bond_code')))
    
    # Get bond details
    bonds = {}
    for bc in bond_codes:
        bond = await db.Ncd_Master.find_one({"bond_code": bc}, {"_id": 0})
        if bond:
            bonds[bc] = bond
    
    # Recalculate for each trade
    results = []
    for trade in trades:
        bc = trade.get('bond_code')
        bond = bonds.get(bc, {})
        
        # Only recalculate if trade has repayments
        repayment_count = await db.actual_repayments.count_documents({
            "$or": [
                {"trade_id": trade.get('id')},
                {
                    "client_name": trade.get('client_name'),
                    "bond_code": bc,
                    "investment_date": str(trade.get('investment_date', ''))[:10]
                }
            ]
        })
        
        if repayment_count > 0:
            result = await recalculate_maturity_for_trade(trade, bond, db)
            results.append(result)
    
    # Calculate totals
    total_prepaid = sum(r.get('total_prepaid', 0) for r in results)
    total_maturity = sum(r.get('final_maturity', 0) for r in results)
    
    return {
        "success": True,
        "message": f"Recalculated maturity for {len(results)} trades",
        "updated_count": len(results),
        "total_prepaid": round(total_prepaid, 2),
        "total_maturity": round(total_maturity, 2),
        "grand_total": round(total_prepaid + total_maturity, 2),
        "details": results
    }


@api_router.post("/admin/reset-auto-tag")
async def reset_auto_tag_data(
    bond_code: str,
    current_user: dict = Depends(get_current_user)
):
    """
    Reset all auto-tagged data for a bond:
    1. Delete ALL actual_repayments with source='auto_tag'
    2. Reset email_read_logs holding_updated status
    3. Reset holding_cashflows prepayment adjustments
    
    After this, user can run auto-tag fresh to re-tag all entries correctly.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can reset auto-tag data")
    
    results = {
        "auto_tagged_repayments_deleted": 0,
        "email_logs_reset": 0,
        "cashflows_reset": 0
    }
    
    # Step 1: Delete all auto-tagged actual_repayments
    delete_result = await db.actual_repayments.delete_many({
        "bond_code": bond_code,
        "source": "auto_tag"
    })
    results["auto_tagged_repayments_deleted"] = delete_result.deleted_count
    
    # Step 2: Reset email_read_logs - clear holding_updated and auto_tagged flags
    update_result = await db.email_read_logs.update_many(
        {"bond_code": bond_code},
        {
            "$unset": {
                "holding_updated": "",
                "holding_updated_at": "",
                "auto_tagged": "",
                "matched_trade_id": "",
                "matched_investment_date": "",
                "matched_units": "",
                "per_unit_amount": "",
                "is_duplicate_repayment": "",
                "linked_to_repayment_id": ""
            }
        }
    )
    results["email_logs_reset"] = update_result.modified_count
    
    # Step 3: Reset holding_cashflows - restore original values
    trades = await db.Ncd_Investment_Details.find({"bond_code": bond_code}, {"_id": 0, "id": 1}).to_list(1000)
    trade_ids = [t.get('id') for t in trades]
    
    cashflows = await db.holding_cashflows.find(
        {"trade_id": {"$in": trade_ids}, "is_prepayment_adjusted": True},
        {"_id": 1, "original_gross_amount": 1, "original_net_amount": 1}
    ).to_list(1000)
    
    for cf in cashflows:
        original_gross = cf.get('original_gross_amount', 0)
        original_net = cf.get('original_net_amount', 0)
        
        if original_gross > 0:
            await db.holding_cashflows.update_one(
                {"_id": cf['_id']},
                {
                    "$set": {
                        "gross_amount": original_gross,
                        "net_amount": original_net
                    },
                    "$unset": {
                        "is_prepayment_adjusted": "",
                        "prepayment_adjustment_date": "",
                        "total_prepaid": "",
                        "remaining_principal": "",
                        "interest_breakdown": "",
                        "prepayment_count": "",
                        "principal_component": "",
                        "interest_component": ""
                    }
                }
            )
            results["cashflows_reset"] += 1
    
    return {
        "success": True,
        "message": f"Reset all auto-tag data for {bond_code}. You can now run auto-tag again.",
        "results": results
    }


