@api_router.post("/admin/validate-actual-repayments")
async def validate_actual_repayments(
    fix_issues: bool = False,
    current_user: dict = Depends(get_current_user)
):
    """
    Validate actual_repayments entries and identify issues:
    1. Entries with wrong client_id (doesn't match trade's client_id)
    2. Entries without trade_id
    3. Entries without investment_date
    4. Duplicate entries
    
    If fix_issues=True, removes/fixes invalid entries.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can validate data")
    
    try:
        issues = {
            "wrong_client_id": [],
            "missing_trade_id": [],
            "missing_investment_date": [],
            "duplicates": [],
            "orphaned_entries": []
        }
        
        # Get all actual_repayments
        all_repayments = await db.actual_repayments.find({}, {"_id": 0}).to_list(10000)
        logger.info(f"Validating {len(all_repayments)} actual_repayments")
        
        # Cache trades for lookup
        all_trades = await db.Ncd_Investment_Details.find({}, {"_id": 0, "id": 1, "client_id": 1, "investment_date": 1, "bond_id": 1}).to_list(10000)
        trades_by_id = {t['id']: t for t in all_trades}
        
        # Track seen entries for duplicate detection
        seen_keys = {}
        
        entries_to_delete = []
        
        for rep in all_repayments:
            rep_id = rep.get('id')
            trade_id = rep.get('trade_id')
            client_id = rep.get('client_id')
            investment_date = rep.get('investment_date')
            repayment_date = rep.get('repayment_date', '')[:10]
            gross_amount = rep.get('gross_amount', 0)
            bond_id = rep.get('bond_id')
            
            # Check for missing trade_id
            if not trade_id:
                issues["missing_trade_id"].append({
                    "id": rep_id,
                    "client_id": client_id,
                    "gross_amount": gross_amount,
                    "repayment_date": repayment_date
                })
                if fix_issues:
                    entries_to_delete.append(rep_id)
                continue
            
            # Check for missing investment_date
            if not investment_date:
                issues["missing_investment_date"].append({
                    "id": rep_id,
                    "trade_id": trade_id,
                    "gross_amount": gross_amount,
                    "repayment_date": repayment_date
                })
            
            # Check if trade exists
            trade = trades_by_id.get(trade_id)
            if not trade:
                issues["orphaned_entries"].append({
                    "id": rep_id,
                    "trade_id": trade_id,
                    "gross_amount": gross_amount,
                    "repayment_date": repayment_date,
                    "reason": "Trade not found"
                })
                if fix_issues:
                    entries_to_delete.append(rep_id)
                continue
            
            # Check if client_id matches trade's client_id
            trade_client_id = trade.get('client_id')
            if client_id != trade_client_id:
                issues["wrong_client_id"].append({
                    "id": rep_id,
                    "actual_repayment_client_id": client_id,
                    "trade_client_id": trade_client_id,
                    "trade_id": trade_id,
                    "gross_amount": gross_amount,
                    "repayment_date": repayment_date
                })
                if fix_issues:
                    # Fix the client_id to match trade
                    await db.actual_repayments.update_one(
                        {"id": rep_id},
                        {"$set": {"client_id": trade_client_id, "client_id_fixed": True, "original_client_id": client_id}}
                    )
            
            # Check for duplicates
            dup_key = (client_id, bond_id, repayment_date, gross_amount)
            if dup_key in seen_keys:
                issues["duplicates"].append({
                    "id": rep_id,
                    "duplicate_of": seen_keys[dup_key],
                    "client_id": client_id,
                    "gross_amount": gross_amount,
                    "repayment_date": repayment_date
                })
                if fix_issues:
                    entries_to_delete.append(rep_id)
            else:
                seen_keys[dup_key] = rep_id
        
        # Delete invalid entries if requested
        deleted_count = 0
        if fix_issues and entries_to_delete:
            result = await db.actual_repayments.delete_many({"id": {"$in": entries_to_delete}})
            deleted_count = result.deleted_count
        
        summary = {
            "total_repayments": len(all_repayments),
            "issues_found": {
                "wrong_client_id": len(issues["wrong_client_id"]),
                "missing_trade_id": len(issues["missing_trade_id"]),
                "missing_investment_date": len(issues["missing_investment_date"]),
                "duplicates": len(issues["duplicates"]),
                "orphaned_entries": len(issues["orphaned_entries"])
            },
            "total_issues": sum(len(v) for v in issues.values()),
            "fix_applied": fix_issues,
            "entries_deleted": deleted_count if fix_issues else 0,
            "client_ids_fixed": len(issues["wrong_client_id"]) if fix_issues else 0
        }
        
        logger.info(f"Validation complete: {summary}")
        
        return {
            "success": True,
            "summary": summary,
            "details": issues if not fix_issues else None  # Only show details in validation mode
        }
        
    except Exception as e:
        logger.error(f"Error validating actual_repayments: {e}")
        raise HTTPException(status_code=500, detail=f"Failed to validate: {str(e)}")


