@api_router.get("/admin/actual-repayments/by-client/{client_id}")
async def get_client_actual_repayments(
    client_id: str,
    bond_id: Optional[str] = None,
    current_user: dict = Depends(get_current_user)
):
    """
    Get all actual_repayments for a specific client.
    Useful for debugging actual cashflow issues.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can view this data")
    
    query = {"client_id": client_id}
    if bond_id:
        query["bond_id"] = bond_id
    
    repayments = await db.actual_repayments.find(query, {"_id": 0}).to_list(500)
    
    # Get client name
    client = await db.Private_Investor.find_one({"id": client_id}, {"_id": 0, "name": 1})
    client_name = client.get('name', 'Unknown') if client else 'Unknown'
    
    # Group by trade
    by_trade = {}
    for r in repayments:
        tid = r.get('trade_id', 'NO_TRADE')
        if tid not in by_trade:
            by_trade[tid] = []
        by_trade[tid].append({
            "repayment_date": r.get('repayment_date'),
            "investment_date": r.get('investment_date'),
            "gross_amount": r.get('gross_amount'),
            "net_amount": r.get('net_amount'),
            "principal": r.get('principal'),
            "interest": r.get('interest'),
            "source": r.get('source'),
            "id": r.get('id')
        })
    
    return {
        "client_id": client_id,
        "client_name": client_name,
        "total_repayments": len(repayments),
        "by_trade": by_trade,
        "all_repayments": repayments
    }


