@api_router.post("/admin/reset/ncd-complete")
async def reset_ncd_complete(
    bond_id: str,
    reset_type: str = "all",  # Options: "ncd", "investments", "repayments", "all"
    current_user: dict = Depends(get_current_user)
):
    """
    Complete reset for an NCD with options:
    - ncd: Delete the bond/NCD definition only
    - investments: Delete all trades/investments for this NCD
    - repayments: Delete all historical repayments and email logs for this NCD
    - all: Delete everything related to this NCD
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can reset data")
    
    if reset_type not in ["ncd", "investments", "repayments", "all"]:
        raise HTTPException(status_code=400, detail="reset_type must be: ncd, investments, repayments, or all")
    
    results = {
        "bond_deleted": False,
        "trades_deleted": 0,
        "actual_repayments_deleted": 0,
        "email_logs_deleted": 0,
        "holding_cashflows_deleted": 0
    }
    
    # Get bond info for name
    bond = await db.Ncd_Master.find_one({"id": bond_id}, {"_id": 0, "bond_code": 1, "name": 1})
    if not bond:
        raise HTTPException(status_code=404, detail="Bond not found")
    
    bond_code = bond.get('bond_code', '')
    
    try:
        if reset_type in ["repayments", "all"]:
            # Delete actual_repayments
            rep_result = await db.actual_repayments.delete_many({"bond_id": bond_id})
            results["actual_repayments_deleted"] = rep_result.deleted_count
            
            # Delete email_read_logs
            email_result = await db.email_read_logs.delete_many({"bond_id": bond_id})
            results["email_logs_deleted"] = email_result.deleted_count
            
            # Delete holding_cashflows
            cf_result = await db.holding_cashflows.delete_many({"bond_id": bond_id})
            results["holding_cashflows_deleted"] = cf_result.deleted_count
        
        if reset_type in ["investments", "all"]:
            # Delete trades
            trades_result = await db.Ncd_Investment_Details.delete_many({"bond_id": bond_id})
            results["trades_deleted"] = trades_result.deleted_count
        
        if reset_type in ["ncd", "all"]:
            # Delete the bond itself
            bond_result = await db.Ncd_Master.delete_one({"id": bond_id})
            results["bond_deleted"] = bond_result.deleted_count > 0
        
        logger.info(f"Reset NCD {bond_code}: type={reset_type}, results={results}")
        
        return {
            "success": True,
            "message": f"Reset completed for {bond_code}",
            "reset_type": reset_type,
            "results": results
        }
        
    except Exception as e:
        logger.error(f"Error resetting NCD: {e}")
        raise HTTPException(status_code=500, detail=f"Failed to reset: {str(e)}")


