@api_router.get("/admin/data-summary")
async def get_data_summary(
    bond_code: Optional[str] = None,
    current_user: dict = Depends(get_current_user)
):
    """
    Get summary of data in collections for a bond.
    Useful for debugging and verification.
    """
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can view data summary")
    
    query = {"bond_code": bond_code} if bond_code else {}
    
    # Count records in each collection
    actual_repayments_count = await db.actual_repayments.count_documents(query)
    email_read_logs_count = await db.email_read_logs.count_documents(query)
    
    # For holding_cashflows, we need to match by bond_code in trades
    if bond_code:
        trades = await db.Ncd_Investment_Details.find({"bond_code": bond_code}, {"_id": 0, "id": 1}).to_list(1000)
        trade_ids = [t.get('id') for t in trades]
        holding_cashflows_count = await db.holding_cashflows.count_documents({"trade_id": {"$in": trade_ids}})
    else:
        holding_cashflows_count = await db.holding_cashflows.count_documents({})
    
    # Get breakdown
    auto_tagged = await db.actual_repayments.count_documents({**query, "source": "auto_tag"})
    manual_tagged = await db.actual_repayments.count_documents({**query, "source": "manual"})
    historical = await db.actual_repayments.count_documents({**query, "source": {"$nin": ["auto_tag", "manual"]}})
    
    email_updated = await db.email_read_logs.count_documents({**query, "holding_updated": True})
    email_pending = await db.email_read_logs.count_documents({**query, "holding_updated": {"$ne": True}})
    
    return {
        "bond_code": bond_code or "ALL",
        "actual_repayments": {
            "total": actual_repayments_count,
            "auto_tagged": auto_tagged,
            "manual": manual_tagged,
            "historical": historical
        },
        "email_read_logs": {
            "total": email_read_logs_count,
            "updated": email_updated,
            "pending": email_pending
        },
        "holding_cashflows": {
            "total": holding_cashflows_count
        }
    }


# ==================== EMAIL ENGAGEMENT DASHBOARD ====================

@api_router.get("/email-engagement/dashboard")
async def get_email_engagement_dashboard(
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
    client_id: Optional[str] = None,
    holding_status: Optional[str] = None,  # "updated" or "pending"
    current_user: dict = Depends(get_current_user)
):
    """Get email engagement dashboard data with summary and detailed logs"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can access email engagement data")
    
    # Build query filters for email_read_logs (actual emails read from inbox)
    query = {}
    date_filters = {}
    
    if date_from:
        date_filters['$gte'] = date_from
    if date_to:
        date_filters['$lte'] = date_to + 'T23:59:59'
    
    if date_filters:
        query['email_read_at'] = date_filters
    
    # Get client name for filtering if client_id provided
    client_name_filter = None
    if client_id:
        # First try to get client from clients collection
        client = await db.Private_Investor.find_one({"id": client_id}, {"_id": 0, "name": 1})
        if client:
            client_name_filter = client.get('name', '')
        else:
            # client_id might actually be a client name (for unmatched emails)
            client_name_filter = client_id
    
    # Get all email logs matching date filters first
    all_email_logs = await db.email_read_logs.find(
        query, {"_id": 0}
    ).sort("email_read_at", -1).to_list(500)
    
    # Apply client filter in Python (more reliable than complex MongoDB queries)
    if client_name_filter:
        filtered_logs = []
        for log in all_email_logs:
            log_client_name = (log.get('client_name', '') or '').strip().lower()
            matched_client_id = log.get('matched_client_id', '')
            
            # Match by client name (case-insensitive, partial match) or matched_client_id
            if (client_name_filter.lower() in log_client_name or 
                log_client_name in client_name_filter.lower() or
                matched_client_id == client_id):
                filtered_logs.append(log)
        all_email_logs = filtered_logs
    
    # Each email is unique - no deduplication needed
    # Every email in the mailbox represents a unique transaction
    email_logs = all_email_logs
    
    # Get all actual_repayments that came from email sources to cross-reference
    email_repayments = await db.actual_repayments.find(
        {"source": {"$in": ["email_auto_approval", "auto_tag", "email"]}},
        {"_id": 0, "id": 1, "gross_amount": 1, "client_id": 1, "repayment_date": 1}
    ).to_list(1000)
    
    # Create a set of updated email log IDs for accurate matching
    updated_email_ids = set()
    for rep in email_repayments:
        if rep.get('id'):
            updated_email_ids.add(rep.get('id'))
    
    # Also check holding_cashflows with is_repaid=True
    repaid_cashflows = await db.holding_cashflows.find(
        {"is_repaid": True},
        {"_id": 0, "email_log_id": 1}
    ).to_list(1000)
    
    for cf in repaid_cashflows:
        if cf.get('email_log_id'):
            updated_email_ids.add(cf.get('email_log_id'))
    
    # Calculate summary stats
    total_emails_read = len(email_logs)
    
    # Count duplicates
    duplicates_count = sum(1 for log in email_logs if log.get('is_duplicate'))
    
    # Count existing repayments (duplicate_skipped)
    existing_repayments_count = sum(1 for log in email_logs if log.get('duplicate_skipped'))
    
    # Count clients identified - check if matched_client_id is set (not just name matching)
    # A client is "identified" if their email was matched to an existing client in the system
    unique_client_names = set()
    identified_client_names = set()
    
    for log in email_logs:
        client_name = log.get('client_name', '').strip()
        if client_name:
            unique_client_names.add(client_name.lower())
            # Client is identified if matched_client_id is set
            if log.get('matched_client_id'):
                identified_client_names.add(client_name.lower())
    
    clients_identified = len(identified_client_names)
    clients_not_identified = len(unique_client_names) - clients_identified
    
    # Count holdings updated by checking if email log is tagged or has holding_updated flag
    holdings_updated = 0
    for log in email_logs:
        log_id = log.get('id', '')
        if log_id in updated_email_ids or log.get('holding_updated') or log.get('approved'):
            holdings_updated += 1
    
    holdings_pending = total_emails_read - holdings_updated
    
    # Get total amount stats
    total_gross_amount = sum(log.get('gross_amount', 0) or 0 for log in email_logs)
    total_net_amount = sum(log.get('net_amount', 0) or 0 for log in email_logs)
    total_tds = sum(log.get('tds_amount', 0) or 0 for log in email_logs)
    
    # Add is_auto_tagged field to each log for frontend display
    # Check by log ID or holding_updated flag - NOT by amount (different clients can have same amounts)
    for log in email_logs:
        log_id = log.get('id', '')
        log['is_auto_tagged'] = log_id in updated_email_ids or log.get('holding_updated', False) or log.get('approved', False)
    
    # Check for unlisted NCDs - emails where bond_id doesn't exist in bonds collection
    all_bonds = await db.Ncd_Master.find({}, {"_id": 0, "id": 1, "bond_code": 1}).to_list(1000)
    existing_bond_ids = set(b.get('id') for b in all_bonds if b.get('id'))
    existing_bond_codes = set(b.get('bond_code', '').upper() for b in all_bonds if b.get('bond_code'))
    
    unlisted_ncd_logs = []
    listed_ncd_logs = []
    
    for log in email_logs:
        bond_id = log.get('bond_id', '')
        bond_code = (log.get('bond_code', '') or '').upper()
        
        # Check if bond exists
        is_listed = bond_id in existing_bond_ids or bond_code in existing_bond_codes
        log['is_unlisted_ncd'] = not is_listed and (bond_id or bond_code)
        
        if log['is_unlisted_ncd']:
            unlisted_ncd_logs.append(log)
        else:
            listed_ncd_logs.append(log)
    
    # Get unique unlisted NCD codes for summary
    unlisted_ncd_codes = {}
    for log in unlisted_ncd_logs:
        code = log.get('bond_code', '') or log.get('bond_id', '') or 'Unknown'
        if code not in unlisted_ncd_codes:
            unlisted_ncd_codes[code] = {
                'code': code,
                'name': log.get('bond_name', code),
                'count': 0,
                'total_amount': 0
            }
        unlisted_ncd_codes[code]['count'] += 1
        unlisted_ncd_codes[code]['total_amount'] += log.get('gross_amount', 0) or 0
    
    # Apply holding_status filter AFTER computing is_auto_tagged
    if holding_status == 'updated':
        email_logs = [log for log in email_logs if log.get('is_auto_tagged')]
    elif holding_status == 'pending':
        email_logs = [log for log in email_logs if not log.get('is_auto_tagged')]
    elif holding_status == 'unlisted':
        email_logs = unlisted_ncd_logs
    
    return {
        "summary": {
            "total_emails_read": total_emails_read,
            "clients_identified": clients_identified,
            "clients_not_identified": clients_not_identified,
            "holdings_updated": holdings_updated,
            "holdings_pending": holdings_pending,
            "duplicates_count": duplicates_count,
            "existing_repayments_count": existing_repayments_count,
            "total_gross_amount": total_gross_amount,
            "total_net_amount": total_net_amount,
            "total_tds": total_tds,
            "unlisted_ncds_count": len(unlisted_ncd_logs),
            "unlisted_ncd_codes": list(unlisted_ncd_codes.values())
        },
        "logs": email_logs
    }


@api_router.get("/notifications/email-untaggable")
async def get_email_untaggable_count(current_user: dict = Depends(get_current_user)):
    """
    Get count of email entries that EXPLICITLY need user input.
    
    Only show notification when emails are marked with:
    - requires_manual_review: True
    - requires_input: True
    
    DO NOT show notification for:
    - Auto-processed emails
    - Unmatched clients (they can be handled in Email Tracker page)
    """
    if current_user['role'] != 'broker':
        return {"count": 0}
    
    # Only count emails EXPLICITLY marked as requiring manual review
    count = await db.email_read_logs.count_documents({
        "$or": [
            {"requires_manual_review": True},
            {"requires_input": True}
        ]
    })
    
    return {"count": count}


