# Sell Unit Model
class SellUnitRequest(BaseModel):
    sale_date: str
    sale_price: float
    brokerage_fee: Optional[float] = 0
    selling_fee_percentage: Optional[float] = 0
    net_proceeds: Optional[float] = 0
    total_invested: Optional[float] = 0
    net_profit: Optional[float] = 0
    xirr: Optional[float] = 0
    notes: Optional[str] = ""

@api_router.post("/real-estate-opportunities/{opportunity_id}/sell")
async def sell_real_estate_unit(
    opportunity_id: str,
    data: SellUnitRequest,
    current_user: dict = Depends(get_current_user)
):
    """Sell a fully funded real estate unit and mark it as closed"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can sell units")
    
    # Get the opportunity
    opp = await db.Real_Estate_Master.find_one({"id": opportunity_id}, {"_id": 0})
    if not opp:
        raise HTTPException(status_code=404, detail="Property not found")
    
    # Verify it's fully invested
    if opp.get('status') != 'fully_invested':
        raise HTTPException(status_code=400, detail="Only fully invested properties can be sold")
    
    # Calculate profit/loss from purchase price (basic calculation)
    purchase_price = opp.get('unit_price', 0)
    dld_fee = opp.get('dld_fee', 0)
    admin_fee = opp.get('admin_fee', 0)
    total_cost = purchase_price + dld_fee + admin_fee
    
    # Use the values from frontend if provided, otherwise calculate
    total_invested = data.total_invested if data.total_invested > 0 else total_cost
    net_profit = data.net_profit if data.net_profit != 0 else (data.net_proceeds - total_invested)
    profit_percentage = (net_profit / total_invested * 100) if total_invested > 0 else 0
    
    # Update the opportunity with comprehensive sale details
    sale_record = {
        "sale_date": data.sale_date,
        "sale_price": data.sale_price,
        "brokerage_fee": data.brokerage_fee,
        "selling_fee_percentage": data.selling_fee_percentage,
        "net_proceeds": data.net_proceeds or (data.sale_price - data.brokerage_fee),
        "total_invested": total_invested,
        "net_profit": net_profit,
        "profit_percentage": round(profit_percentage, 2),
        "xirr": round(data.xirr, 2) if data.xirr else 0,
        "notes": data.notes,
        "sold_by": current_user['id'],
        "sold_at": datetime.now(timezone.utc).isoformat()
    }
    
    await db.Real_Estate_Master.update_one(
        {"id": opportunity_id},
        {
            "$set": {
                "status": "closed",
                "sale_record": sale_record,
                "closed_at": datetime.now(timezone.utc).isoformat(),
                "updated_at": datetime.now(timezone.utc).isoformat()
            }
        }
    )
    
    return {
        "message": "Unit sold successfully",
        "sale_record": sale_record
    }


# ==================== DASHBOARD ANALYTICS ENDPOINTS ====================

@api_router.get("/dashboard/summary")
async def get_dashboard_summary(current_user: dict = Depends(get_current_user)):
    """Get summary statistics for broker dashboard"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can access dashboard")
    
    broker_id = current_user['id']
    
    # Get clients
    clients = await db.Private_Investor.find({"created_by": broker_id}, {"_id": 0}).to_list(1000)
    total_clients = len(clients)
    
    # Check user accounts for login status
    client_pans = [c.get('pan_number') for c in clients if c.get('pan_number')]
    user_accounts = await db.users.find({"pan": {"$in": client_pans}}, {"_id": 0, "pan": 1, "is_active": 1, "last_login": 1}).to_list(1000)
    
    # Create a map of PAN to user account status
    user_status_map = {u['pan']: u for u in user_accounts}
    
    # Count active (logged in / activated) vs pending (never logged in / not activated)
    active_clients = 0
    pending_clients = 0
    
    # Count clients by product type for Venn diagram
    bond_only_clients = 0
    real_estate_only_clients = 0
    both_products_clients = 0
    
    for c in clients:
        pan = c.get('pan_number')
        user_account = user_status_map.get(pan)
        
        # Client is active if:
        # 1. Has a user account AND is_active is True AND (has logged in OR not deactivated)
        if user_account and user_account.get('is_active', False):
            active_clients += 1
        else:
            pending_clients += 1
        
        # Count by opportunities for Venn diagram
        opportunities = c.get('opportunities', [])
        has_bonds = 'bonds' in opportunities
        has_real_estate = 'real_estate' in opportunities
        
        if has_bonds and has_real_estate:
            both_products_clients += 1
        elif has_bonds:
            bond_only_clients += 1
        elif has_real_estate:
            real_estate_only_clients += 1
    
    # Get sub-brokers (partners)
    partners = await db.Mfd_Ria_Partner.find({"created_by": broker_id}, {"_id": 0}).to_list(1000)
    total_subbrokers = len(partners)
    active_subbrokers = len([p for p in partners if p.get('is_active', True)])
    
    # Get bonds
    bonds = await db.Ncd_Master.find({}, {"_id": 0}).to_list(1000)
    total_bonds = len(bonds)
    # Available bonds = status is 'available' OR not explicitly funded/closed
    available_bonds = len([b for b in bonds if b.get('status') in ['available', 'None', None] or b.get('status') not in ['funded', 'closed']])
    funded_bonds = len([b for b in bonds if b.get('status') == 'funded'])
    closed_bonds = len([b for b in bonds if b.get('status') == 'closed'])
    
    # Get real estate opportunities
    real_estate = await db.Real_Estate_Master.find({"created_by": broker_id}, {"_id": 0}).to_list(1000)
    total_real_estate = len(real_estate)
    # Available real estate = status is NOT fully_invested or closed
    available_re = len([r for r in real_estate if r.get('status') not in ['fully_invested', 'closed']])
    invested_re = len([r for r in real_estate if r.get('status') in ['partially_invested', 'fully_invested']])
    
    # ==================== BOND AUM CALCULATIONS ====================
    # Sum up profits from all trades - same calculation as individual Holdings page
    # Profit per trade = (Total Principal + Total Interest) - Investment Amount
    
    bond_total_invested = 0
    bond_total_repaid = 0
    bond_total_pending = 0
    bond_total_profits = 0  # Sum of all clients' profits
    bond_principal_repaid = 0
    bond_interest_repaid = 0
    bond_principal_pending = 0
    bond_interest_pending = 0
    
    # Get all approved trades
    all_trades = await db.Ncd_Investment_Details.find(
        {"status": "approved"},
        {"_id": 0}
    ).to_list(10000)
    
    # Count unique NCD clients by PAN
    ncd_client_pans = set()
    for trade in all_trades:
        client_id = trade.get('client_id')
        if client_id:
            client = await db.Private_Investor.find_one({"id": client_id}, {"_id": 0, "pan_number": 1})
            if client and client.get('pan_number'):
                ncd_client_pans.add(client.get('pan_number'))
    ncd_unique_clients = len(ncd_client_pans)
    
    # Get all bonds for reference
    all_bonds = await db.Ncd_Master.find({}, {"_id": 0}).to_list(100)
    bonds_map = {b.get('bond_code') or b.get('id'): b for b in all_bonds}
    
    for trade in all_trades:
        trade_id = trade.get('id')
        bond_code = trade.get('bond_code')
        bond_id = trade.get('bond_id')
        client_id = trade.get('client_id')
        bond = bonds_map.get(bond_code) or bonds_map.get(bond_id)
        
        if not bond:
            continue
        
        # Investment amount
        trade_amount = trade.get('amount', 0) or trade.get('total_amount', 0) or 0
        bond_total_invested += trade_amount
        
        units = trade.get('units', 0) or 0
        
        # Calculate expected returns from cashflows (same as Holdings page)
        cashflows_per_unit = bond.get('cashflows_per_unit', [])
        total_principal = 0
        total_interest = 0
        
        if cashflows_per_unit:
            for cf in cashflows_per_unit:
                total_principal += (cf.get('principal_per_unit', 0) or 0) * units
                total_interest += (cf.get('interest_per_unit', 0) or 0) * units
        else:
            # Fallback calculation using face value and coupon rate
            face_value = bond.get('face_value', 100000)
            coupon_rate = bond.get('coupon_rate', 0)
            if coupon_rate > 1:
                coupon_rate = coupon_rate / 100
            
            total_principal = face_value * units
            maturity_date = bond.get('end_date') or bond.get('maturity_date') or ''
            bond_start = bond.get('start_date') or bond.get('bond_start_date') or ''
            
            try:
                if maturity_date and bond_start:
                    from datetime import datetime as dt
                    mat_dt = dt.fromisoformat(maturity_date[:10])
                    start_dt = dt.fromisoformat(bond_start[:10])
                    days = (mat_dt - start_dt).days
                    total_interest = total_principal * coupon_rate * days / 365
                else:
                    total_interest = total_principal * coupon_rate * 1.5
            except:
                total_interest = total_principal * coupon_rate * 1.5
        
        # Gross expected = Principal + Interest
        gross_expected = total_principal + total_interest
        
        # Profit = Gross Expected - Investment (same as Holdings page)
        trade_profit = gross_expected - trade_amount
        bond_total_profits += trade_profit
        
        # Get repayments for this trade to calculate repaid vs pending
        trade_repayments = await db.actual_repayments.find({
            "$or": [
                {"trade_id": trade_id},
                {"bond_id": bond_id, "client_id": client_id}
            ]
        }, {"_id": 0}).to_list(100)
        
        # Sum repaid amounts with principal/interest breakdown
        trade_repaid = 0
        trade_principal_repaid = 0
        trade_interest_repaid = 0
        for ar in trade_repayments:
            ar_gross = ar.get('gross_amount', 0) or ar.get('amount', 0) or 0
            ar_principal = ar.get('principal_component', 0) or 0
            ar_interest = ar.get('interest_component', 0) or 0
            trade_repaid += ar_gross
            if ar_principal > 0 or ar_interest > 0:
                trade_principal_repaid += ar_principal
                trade_interest_repaid += ar_interest
            elif gross_expected > 0:
                # Estimate breakdown if not available
                principal_ratio = total_principal / gross_expected if gross_expected > 0 else 0.7
                trade_principal_repaid += ar_gross * principal_ratio
                trade_interest_repaid += ar_gross * (1 - principal_ratio)
        
        bond_total_repaid += trade_repaid
        bond_principal_repaid += trade_principal_repaid
        bond_interest_repaid += trade_interest_repaid
        
        # Pending = Gross Expected - Repaid
        trade_pending = max(0, gross_expected - trade_repaid)
        trade_principal_pending = max(0, total_principal - trade_principal_repaid)
        trade_interest_pending = max(0, total_interest - trade_interest_repaid)
        
        bond_total_pending += trade_pending
        bond_principal_pending += trade_principal_pending
        bond_interest_pending += trade_interest_pending
    
    # Final profit calculation - sum of all individual trade profits
    bond_profits = bond_total_profits
    
    # Legacy bond AUM calculation (for backward compatibility)
    bond_aum = sum(
        (b.get('units_sold', 0) * b.get('face_value', 0)) 
        for b in bonds
    )
    
    # Calculate Real Estate AUM Details
    # Total deal size = sum of total_cost (which includes DLD and admin)
    re_total_deal_size = sum(r.get('total_cost', 0) for r in real_estate)
    
    # Total paid by clients = sum of all payments from investors
    re_total_paid = 0
    # Invested = total_cost * invested_percentage / 100 (based on actual invested %)
    re_total_invested = 0
    # Open opportunities = total_cost * (100 - invested_percentage) / 100
    re_open_opportunities = 0
    # Count unique RE clients by PAN
    re_client_pans = set()
    
    for re_opp in real_estate:
        investors = re_opp.get('investors', [])
        opp_total_cost = re_opp.get('total_cost', 0) or 0
        invested_percentage = re_opp.get('invested_percentage', 0) or 0
        
        # Calculate invested and open based on invested_percentage
        re_total_invested += opp_total_cost * invested_percentage / 100
        re_open_opportunities += opp_total_cost * (100 - invested_percentage) / 100
        
        # Sum payments from investors and track unique PANs
        for inv in investors:
            # Track unique client PANs for RE
            inv_pan = inv.get('pan_number') or inv.get('pan')
            if inv_pan:
                re_client_pans.add(inv_pan)
            
            # Sum up all payments made by each investor
            payments = inv.get('payments', [])
            if payments:
                for payment in payments:
                    re_total_paid += payment.get('amount', 0) or 0
            else:
                # Fallback to amount_paid field if no payments array
                re_total_paid += inv.get('amount_paid', 0) or 0
    
    re_unique_clients = len(re_client_pans)
    
    # Legacy real estate AUM calculation  
    real_estate_aum = sum(
        (r.get('total_cost', 0) * r.get('invested_percentage', 0) / 100)
        for r in real_estate
    )
    
    total_aum = bond_aum + real_estate_aum
    
    # Get trades for revenue calculation
    trades = await db.Ncd_Investment_Details.find({"status": "approved"}, {"_id": 0}).to_list(10000)
    
    # Get unique family count for data gathering
    families = await db.data_gathering_families.find({"broker_id": broker_id}, {"_id": 0, "id": 1}).to_list(1000)
    unique_families_count = len(families)
    
    return {
        "clients": {
            "total": total_clients,
            "active": active_clients,
            "pending": pending_clients,
            "bond_only": bond_only_clients,
            "real_estate_only": real_estate_only_clients,
            "both_products": both_products_clients
        },
        "sub_brokers": {
            "total": total_subbrokers,
            "active": active_subbrokers
        },
        "opportunities": {
            "bonds": {
                "total": total_bonds,
                "available": available_bonds,
                "funded": funded_bonds,
                "closed": closed_bonds
            },
            "real_estate": {
                "total": total_real_estate,
                "available": available_re,
                "invested": invested_re
            }
        },
        "aum": {
            "total": total_aum,
            "bonds": bond_aum,
            "real_estate": real_estate_aum
        },
        "bond_aum": {
            "total_invested": bond_total_invested or bond_aum,
            "total_repaid": bond_total_repaid,
            "principal_repaid": bond_principal_repaid,
            "interest_repaid": bond_interest_repaid,
            "total_pending": bond_total_pending,
            "principal_pending": bond_principal_pending,
            "interest_pending": bond_interest_pending,
            "profits": bond_profits,                 # Sum of all clients' profits
            "unique_clients": ncd_unique_clients     # Unique clients by PAN
        },
        "real_estate_aum": {
            "total_deal_size": re_total_deal_size,
            "total_invested": re_total_invested,
            "total_paid": re_total_paid,
            "open_opportunities": re_open_opportunities,
            "unique_clients": re_unique_clients      # Unique clients by PAN
        },
        "data_gathering": {
            "unique_families": unique_families_count
        },
        "trades_count": len(trades)
    }


@api_router.get("/dashboard/private-investors-by-city")
async def get_clients_by_city(current_user: dict = Depends(get_current_user)):
    """Get client distribution by city"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can access dashboard")
    
    broker_id = current_user['id']
    clients = await db.Private_Investor.find({"created_by": broker_id}, {"_id": 0}).to_list(1000)
    
    city_counts = {}
    for client in clients:
        city = client.get('city', 'Unknown') or 'Unknown'
        city_counts[city] = city_counts.get(city, 0) + 1
    
    # Sort by count descending and return top 10
    sorted_cities = sorted(city_counts.items(), key=lambda x: x[1], reverse=True)[:10]
    
    return [{"city": city, "count": count} for city, count in sorted_cities]


@api_router.get("/lookup/pincode/{pincode}")
async def lookup_pincode(pincode: str):
    """Lookup city, state, and country from Indian pincode using postal API"""
    import httpx
    
    if not pincode or len(pincode) != 6 or not pincode.isdigit():
        raise HTTPException(status_code=400, detail="Invalid pincode. Must be 6 digits.")
    
    try:
        # Use India Post API for pincode lookup
        async with httpx.AsyncClient(timeout=10.0) as client:
            response = await client.get(f"https://api.postalpincode.in/pincode/{pincode}")
            
            if response.status_code == 200:
                data = response.json()
                
                if data and len(data) > 0 and data[0].get('Status') == 'Success':
                    post_offices = data[0].get('PostOffice', [])
                    
                    if post_offices and len(post_offices) > 0:
                        # Get the first post office for this pincode
                        po = post_offices[0]
                        return {
                            "success": True,
                            "pincode": pincode,
                            "city": po.get('District', ''),
                            "state": po.get('State', ''),
                            "country": "India",
                            "district": po.get('District', ''),
                            "region": po.get('Region', ''),
                            "division": po.get('Division', ''),
                            "post_offices": [
                                {
                                    "name": p.get('Name', ''),
                                    "branch_type": p.get('BranchType', ''),
                                    "delivery_status": p.get('DeliveryStatus', '')
                                }
                                for p in post_offices[:5]  # Return up to 5 post offices
                            ]
                        }
                
                # No data found for this pincode
                return {
                    "success": False,
                    "pincode": pincode,
                    "message": "No data found for this pincode"
                }
            else:
                raise HTTPException(status_code=502, detail="Failed to fetch pincode data")
                
    except httpx.TimeoutException:
        raise HTTPException(status_code=504, detail="Pincode lookup timed out")
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Error looking up pincode: {str(e)}")


@api_router.get("/dashboard/aum-distribution")
async def get_aum_distribution(current_user: dict = Depends(get_current_user)):
    """Get AUM distribution by asset class and sub-broker"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can access dashboard")
    
    broker_id = current_user['id']
    
    # Get all bonds
    bonds = await db.Ncd_Master.find({}, {"_id": 0}).to_list(1000)
    bond_aum = sum((b.get('units_sold', 0) * b.get('face_value', 0)) for b in bonds)
    
    # Get real estate opportunities
    real_estate = await db.Real_Estate_Master.find({"created_by": broker_id}, {"_id": 0}).to_list(1000)
    real_estate_aum = sum((r.get('total_cost', 0) * r.get('invested_percentage', 0) / 100) for r in real_estate)
    
    # Get sub-brokers with their linked clients and calculate their AUM
    partners = await db.Mfd_Ria_Partner.find({"created_by": broker_id}, {"_id": 0}).to_list(1000)
    subbroker_aum = []
    
    for partner in partners:
        partner_id = partner.get('id')
        # Get clients linked to this sub-broker
        linked_clients = await db.Private_Investor.find({"linked_subbroker_id": partner_id}, {"_id": 0}).to_list(1000)
        
        # Calculate AUM from bond allocations
        sb_bond_aum = 0
        for client in linked_clients:
            allocations = client.get('bond_allocations', [])
            for alloc in allocations:
                bond = next((b for b in bonds if b.get('id') == alloc.get('bond_id')), None)
                if bond:
                    sb_bond_aum += alloc.get('units_paid', 0) * bond.get('face_value', 0)
        
        # Calculate AUM from real estate investments
        sb_re_aum = 0
        for re in real_estate:
            investors = re.get('investors', [])
            for inv in investors:
                if inv.get('client_id') in [c.get('id') for c in linked_clients]:
                    sb_re_aum += re.get('total_cost', 0) * inv.get('percentage', 0) / 100
        
        subbroker_aum.append({
            "name": partner.get('name', 'Unknown'),
            "partner_code": partner.get('partner_code', ''),
            "aum": sb_bond_aum + sb_re_aum,
            "bond_aum": sb_bond_aum,
            "real_estate_aum": sb_re_aum,
            "client_count": len(linked_clients)
        })
    
    # Sort by AUM descending
    subbroker_aum.sort(key=lambda x: x['aum'], reverse=True)
    
    return {
        "by_asset_class": [
            {"name": "NCD Bonds", "value": bond_aum},
            {"name": "Real Estate", "value": real_estate_aum}
        ],
        "by_subbroker": subbroker_aum[:10]  # Top 10 sub-brokers
    }


@api_router.get("/dashboard/activity-log")
async def get_activity_log(limit: int = 20, current_user: dict = Depends(get_current_user)):
    """Get recent activity log for the broker"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can access dashboard")
    
    broker_id = current_user['id']
    activities = []
    
    # Get recent trades
    trades = await db.Ncd_Investment_Details.find(
        {},
        {"_id": 0}
    ).sort("created_at", -1).to_list(limit)
    
    for trade in trades:
        client = await db.Private_Investor.find_one({"id": trade.get('client_id')}, {"_id": 0, "name": 1})
        bond = await db.Ncd_Master.find_one({"id": trade.get('bond_id')}, {"_id": 0, "issuer": 1, "face_value": 1})
        
        activities.append({
            "type": "trade",
            "status": trade.get('status'),
            "description": f"Trade: {client.get('name', 'Unknown')} - {bond.get('issuer', 'Unknown')} ({trade.get('units', 0)} units)",
            "amount": trade.get('units', 0) * (bond.get('face_value', 0) if bond else 0),
            "timestamp": trade.get('created_at'),
            "client_name": client.get('name', 'Unknown') if client else 'Unknown'
        })
    
    # Get recent real estate investments
    real_estate = await db.Real_Estate_Master.find(
        {"created_by": broker_id},
        {"_id": 0}
    ).to_list(100)
    
    for re in real_estate:
        investors = re.get('investors', [])
        property_name = re.get('building_name', re.get('property_name', 'Unknown'))
        for inv in investors:
            client = await db.Private_Investor.find_one({"id": inv.get('client_id')}, {"_id": 0, "name": 1})
            activities.append({
                "type": "real_estate_investment",
                "status": "invested",
                "description": f"RE Investment: {client.get('name', 'Unknown') if client else 'Unknown'} - {property_name} ({inv.get('share_percentage', inv.get('percentage', 0))}%)",
                "amount": re.get('total_cost', 0) * inv.get('share_percentage', inv.get('percentage', 0)) / 100,
                "timestamp": inv.get('invested_at'),
                "client_name": client.get('name', 'Unknown') if client else 'Unknown',
                "property_name": property_name
            })
    
    # Get recent client creations
    clients = await db.Private_Investor.find(
        {"created_by": broker_id},
        {"_id": 0, "name": 1, "created_at": 1, "city": 1}
    ).sort("created_at", -1).to_list(limit)
    
    for client in clients:
        activities.append({
            "type": "client_created",
            "status": "new",
            "description": f"New Client: {client.get('name', 'Unknown')} ({client.get('city', 'Unknown')})",
            "amount": 0,
            "timestamp": client.get('created_at'),
            "client_name": client.get('name', 'Unknown')
        })
    
    # Sort all activities by timestamp descending
    activities.sort(key=lambda x: x.get('timestamp', '') or '', reverse=True)
    
    return activities[:limit]


@api_router.get("/dashboard/monthly-stats")
async def get_monthly_stats(year: int = None, current_user: dict = Depends(get_current_user)):
    """Get monthly statistics for the console chart"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can access dashboard")
    
    from datetime import datetime
    
    if year is None:
        year = datetime.now().year
    
    broker_id = current_user['id']
    
    # Initialize monthly data
    months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
    monthly_data = {m: {"investments": 0, "trades": 0, "clients": 0} for m in months}
    
    # Get trades by month
    trades = await db.Ncd_Investment_Details.find({"status": "approved"}, {"_id": 0}).to_list(10000)
    for trade in trades:
        created_at = trade.get('created_at')
        if created_at:
            try:
                if isinstance(created_at, str):
                    dt = datetime.fromisoformat(created_at.replace('Z', '+00:00'))
                else:
                    dt = created_at
                if dt.year == year:
                    month_name = months[dt.month - 1]
                    bond = await db.Ncd_Master.find_one({"id": trade.get('bond_id')}, {"_id": 0, "face_value": 1})
                    monthly_data[month_name]["trades"] += trade.get('units', 0) * (bond.get('face_value', 0) if bond else 0)
            except:
                pass
    
    # Get real estate investments by month
    real_estate = await db.Real_Estate_Master.find({"created_by": broker_id}, {"_id": 0}).to_list(1000)
    for re in real_estate:
        investors = re.get('investors', [])
        for inv in investors:
            invested_at = inv.get('invested_at')
            if invested_at:
                try:
                    if isinstance(invested_at, str):
                        dt = datetime.fromisoformat(invested_at.replace('Z', '+00:00'))
                    else:
                        dt = invested_at
                    if dt.year == year:
                        month_name = months[dt.month - 1]
                        monthly_data[month_name]["investments"] += re.get('total_cost', 0) * inv.get('percentage', 0) / 100
                except:
                    pass
    
    # Get new clients by month
    clients = await db.Private_Investor.find({"created_by": broker_id}, {"_id": 0, "created_at": 1}).to_list(1000)
    for client in clients:
        created_at = client.get('created_at')
        if created_at:
            try:
                if isinstance(created_at, str):
                    dt = datetime.fromisoformat(created_at.replace('Z', '+00:00'))
                else:
                    dt = created_at
                if dt.year == year:
                    month_name = months[dt.month - 1]
                    monthly_data[month_name]["clients"] += 1
            except:
                pass
    
    return [
        {
            "month": month,
            "investments": monthly_data[month]["investments"],
            "trades": monthly_data[month]["trades"],
            "clients": monthly_data[month]["clients"]
        }
        for month in months
    ]


# One-time setup endpoint - can be called manually after deployment
@api_router.post("/analysis/upload-cas")
async def upload_cas_pdf(
    files: List[UploadFile] = File(...),
    passwords: List[str] = Form(...),
    client_id: str = Form(...),
    current_user: dict = Depends(get_current_user)
):
    """Upload and analyze one or multiple CAS PDF files.
    Each file can have its own password.
    Multiple files will be combined into a single analysis.
    """
    try:
        # Validate client exists and get details
        client = await db.Private_Investor.find_one({"id": client_id}, {"_id": 0})
        if not client:
            raise HTTPException(status_code=404, detail="Client not found. Please select a valid client.")
        
        # Validate files and passwords count match
        if len(files) != len(passwords):
            raise HTTPException(status_code=400, detail="Each file must have a corresponding password")
        
        client_pan = (client.get('pan_number') or '').upper().strip()
        
        # Process each file
        file_contents = []
        all_cas_pans = set()
        all_cas_names = set()
        cas_country_of_residency = None  # Will be extracted from CAS
        
        for i, (file, password) in enumerate(zip(files, passwords)):
            content = await file.read()
            file_contents.append({
                'content': content,
                'filename': file.filename,
                'password': password
            })
            
            # Extract PANs from this CAS file
            try:
                cas_info = CASParser.extract_pans_from_cas(content, password)
                for pan in cas_info.get('pans', []):
                    all_cas_pans.add(pan.upper().strip())
                for name in cas_info.get('names', []):
                    all_cas_names.add(name)
                # Capture country of residency from the first CAS that has it
                if not cas_country_of_residency and cas_info.get('country_of_residency'):
                    cas_country_of_residency = cas_info.get('country_of_residency')
            except ValueError as e:
                raise HTTPException(status_code=400, detail=f"Error reading {file.filename}: {str(e)}")
        
        # Validate: Check if client's PAN exists in any of the CAS files
        if client_pan and all_cas_pans:
            if client_pan not in all_cas_pans:
                # Client's PAN not found in CAS - return error with details
                raise HTTPException(
                    status_code=400, 
                    detail={
                        "error": "PAN_NOT_FOUND",
                        "message": f"Selected client's PAN ({client_pan}) was not found in the uploaded CAS file(s)",
                        "client_pan": client_pan,
                        "client_name": client.get('name'),
                        "cas_pans": list(all_cas_pans),
                        "cas_names": list(all_cas_names),
                        "country_of_residency": cas_country_of_residency,
                        "action_required": "create_new_client",
                        "suggestion": f"Please select a different client or create a new Private Investor for one of these PANs: {', '.join(all_cas_pans)}"
                    }
                )
        elif not all_cas_pans:
            logger.warning("Could not extract any PAN from CAS PDF(s) - proceeding with parsing")
        
        # Get sub-broker info if client is linked to one
        sub_broker_id = client.get('linked_subbroker_id')
        sub_broker_name = None
        if sub_broker_id:
            sub_broker = await db.Mfd_Ria_Partner.find_one({"id": sub_broker_id}, {"_id": 0, "name": 1})
            sub_broker_name = sub_broker.get('name') if sub_broker else None
        
        # Parse all CAS files (each with its own password)
        parsed_data_list = []
        for file_info in file_contents:
            parser = CASParser(file_info['content'], file_info['password'])
            parsed_data = parser.parse()
            parsed_data_list.append(parsed_data)
        
        # Merge if multiple files, otherwise use single result
        if len(parsed_data_list) > 1:
            combined_parsed_data = CASParser.merge_parsed_data(parsed_data_list)
        else:
            combined_parsed_data = parsed_data_list[0]
        
        # Store analysis result
        analysis_id = str(uuid.uuid4())
        
        # Save the original PDF files for later download
        upload_dir = "/app/uploads/cas_pdfs"
        os.makedirs(upload_dir, exist_ok=True)
        
        saved_filenames = []
        for i, file_info in enumerate(file_contents):
            saved_filename = f"{analysis_id}_{i}_{files[i].filename}"
            file_path = os.path.join(upload_dir, saved_filename)
            with open(file_path, 'wb') as f:
                f.write(file_info['content'])
            saved_filenames.append(saved_filename)
        
        # Create combined filename for display
        display_filename = files[0].filename if len(files) == 1 else f"{len(files)} CAS files combined"
        
        analysis_record = {
            "id": analysis_id,
            "user_id": current_user['id'],
            "user_name": current_user['name'],
            "client_id": client_id,
            "client_name": client.get('name'),
            "client_pan": client_pan,
            "sub_broker_id": sub_broker_id,
            "sub_broker_name": sub_broker_name,
            "filename": display_filename,
            "saved_filenames": saved_filenames,
            "saved_filename": saved_filenames[0] if saved_filenames else None,
            "file_url": f"/api/uploads/cas_pdfs/{saved_filenames[0]}" if saved_filenames else None,
            "source_files_count": len(files),
            "cas_pans_found": list(all_cas_pans),
            "parsed_data": combined_parsed_data,
            "created_at": datetime.now(timezone.utc).isoformat(),
            "status": "completed"
        }
        
        await db.cas_analyses.insert_one(analysis_record)
        
        return {
            "analysis_id": analysis_id,
            "filename": display_filename,
            "source_files_count": len(files),
            "client_name": client.get('name'),
            "sub_broker_name": sub_broker_name,
            "cas_pans_found": list(all_cas_pans),
            "portfolio_summary": combined_parsed_data.get('portfolio_summary', {}),
            "total_folios": len(combined_parsed_data.get('folios', {})),
            "total_transactions": combined_parsed_data.get('total_transactions', 0),
            "status": "completed"
        }
        
    except HTTPException:
        raise
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
    except Exception as e:
        logger.error(f"Error processing CAS PDF: {e}")
        import traceback
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=f"Error processing PDF: {str(e)}")



@api_router.post("/analysis/upload-cas-v2")
async def upload_cas_pdf_v2(
    files: List[UploadFile] = File(...),
    passwords: List[str] = Form(...),
    current_user: dict = Depends(get_current_user)
):
    """Step 1: Upload CAS files and extract PAN info WITHOUT creating clients.
    
    Returns:
    - session_id: Unique ID for this upload session
    - pan_results: List of PANs found with extracted info
    - Users are NOT created until "Generate Report" is called
    """
    try:
        # Validate files and passwords count match
        if len(files) != len(passwords):
            raise HTTPException(status_code=400, detail="Each file must have a corresponding password")
        
        if len(files) == 0:
            raise HTTPException(status_code=400, detail="At least one CAS file is required")
        
        # Process each file to extract PANs and info
        file_contents = []
        all_cas_info = {
            'pans': set(),
            'names': [],
            'pan_name_map': {},
            'country_of_residency': None,
        }
        
        for i, (file, password) in enumerate(zip(files, passwords)):
            content = await file.read()
            file_contents.append({
                'content': content,
                'filename': file.filename,
                'password': password
            })
            
            # Extract info from this CAS file
            try:
                cas_info = CASParser.extract_pans_from_cas(content, password)
                for pan in cas_info.get('pans', []):
                    all_cas_info['pans'].add(pan.upper().strip())
                for name in cas_info.get('names', []):
                    if name not in all_cas_info['names']:
                        all_cas_info['names'].append(name)
                # Merge pan_name_map
                for pan, name in cas_info.get('pan_name_map', {}).items():
                    if pan not in all_cas_info['pan_name_map']:
                        all_cas_info['pan_name_map'][pan] = name
                # Capture country from first CAS that has it
                if not all_cas_info['country_of_residency'] and cas_info.get('country_of_residency'):
                    all_cas_info['country_of_residency'] = cas_info.get('country_of_residency')
            except ValueError as e:
                raise HTTPException(status_code=400, detail=f"Error reading {file.filename}: {str(e)}")
        
        if not all_cas_info['pans']:
            raise HTTPException(status_code=400, detail="Could not extract any PAN numbers from the uploaded CAS file(s)")
        
        # Convert set to list
        all_cas_info['pans'] = list(all_cas_info['pans'])
        
        # Create a session to store the uploaded files temporarily
        session_id = str(uuid.uuid4())
        upload_dir = "/app/uploads/cas_sessions"
        os.makedirs(upload_dir, exist_ok=True)
        
        # Save files to session directory
        session_dir = os.path.join(upload_dir, session_id)
        os.makedirs(session_dir, exist_ok=True)
        
        saved_files = []
        for i, file_info in enumerate(file_contents):
            saved_filename = f"{i}_{files[i].filename}"
            file_path = os.path.join(session_dir, saved_filename)
            with open(file_path, 'wb') as f:
                f.write(file_info['content'])
            saved_files.append({
                'filename': saved_filename,
                'original_name': files[i].filename,
                'password': file_info['password']
            })
        
        # For each PAN, check if client exists and prepare editable data
        pan_results = []
        for pan in all_cas_info['pans']:
            # Check if client with this PAN already exists
            existing_client = await db.Private_Investor.find_one(
                {"$or": [
                    {"pan_number": {"$regex": f"^{pan}$", "$options": "i"}},
                    {"pan": {"$regex": f"^{pan}$", "$options": "i"}}
                ]},
                {"_id": 0}
            )
            
            name_from_cas = all_cas_info['pan_name_map'].get(pan) or (all_cas_info['names'][0] if all_cas_info['names'] else '')
            country = all_cas_info['country_of_residency'] or 'India'
            
            if existing_client:
                # Client exists
                pan_results.append({
                    "pan": pan,
                    "status": "existing",
                    "client_id": existing_client.get('id'),
                    "name": existing_client.get('name'),
                    "email": existing_client.get('email', ''),
                    "mobile": existing_client.get('mobile', ''),
                    "country_of_residency": existing_client.get('country_of_residency', country),
                    "linked_subbroker_name": existing_client.get('linked_subbroker_name', ''),
                    "is_editable": False,
                    "message": "Existing investor"
                })
            else:
                # New PAN - needs to be created
                pan_results.append({
                    "pan": pan,
                    "status": "new",
                    "client_id": None,
                    "name": name_from_cas,
                    "email": "",
                    "mobile": "",
                    "country_of_residency": country,
                    "is_editable": True,
                    "message": "New investor - will be created"
                })
        
        # Store session info in database for later use
        session_record = {
            "session_id": session_id,
            "user_id": current_user['id'],
            "user_name": current_user['name'],
            "user_role": current_user.get('role', 'broker'),
            "saved_files": saved_files,
            "pan_results": pan_results,
            "country_of_residency": all_cas_info['country_of_residency'],
            "created_at": datetime.now(timezone.utc).isoformat(),
            "status": "pending_generation"  # pending_generation -> generated -> downloaded
        }
        await db.cas_upload_sessions.insert_one(session_record)
        
        return {
            "success": True,
            "session_id": session_id,
            "total_pans_found": len(pan_results),
            "existing_count": len([p for p in pan_results if p['status'] == 'existing']),
            "new_count": len([p for p in pan_results if p['status'] == 'new']),
            "pan_results": pan_results,
            "country_of_residency": all_cas_info['country_of_residency']
        }
        
    except HTTPException:
        raise
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
    except Exception as e:
        logger.error(f"Error processing CAS PDF v2: {e}")
        import traceback
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=f"Error processing PDF: {str(e)}")


@api_router.put("/analysis/session/{session_id}/pan/{pan}")
async def update_pan_info(
    session_id: str,
    pan: str,
    update_data: dict,
    current_user: dict = Depends(get_current_user)
):
    """Update PAN info before generating report"""
    try:
        session = await db.cas_upload_sessions.find_one({"session_id": session_id})
        if not session:
            raise HTTPException(status_code=404, detail="Session not found")
        
        if session['user_id'] != current_user['id'] and current_user['role'] != 'broker':
            raise HTTPException(status_code=403, detail="Access denied")
        
        # Update the pan_results array
        pan_results = session.get('pan_results', [])
        updated = False
        for i, pr in enumerate(pan_results):
            if pr['pan'].upper() == pan.upper():
                # Only update editable fields for new PANs
                if pr['status'] == 'new':
                    pan_results[i]['name'] = update_data.get('name', pr['name'])
                    pan_results[i]['email'] = update_data.get('email', pr['email'])
                    pan_results[i]['mobile'] = update_data.get('mobile', pr['mobile'])
                    pan_results[i]['country_of_residency'] = update_data.get('country_of_residency', pr['country_of_residency'])
                    updated = True
                break
        
        if not updated:
            raise HTTPException(status_code=404, detail="PAN not found or not editable")
        
        await db.cas_upload_sessions.update_one(
            {"session_id": session_id},
            {"$set": {"pan_results": pan_results}}
        )
        
        return {"success": True, "message": "PAN info updated"}
        
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


class PanUpdateRequest(BaseModel):
    """Request model for pan updates during report generation"""
    pan_updates: Optional[List[dict]] = None

@api_router.post("/analysis/session/{session_id}/generate")
async def generate_report_from_session(
    session_id: str,
    request: Optional[PanUpdateRequest] = None,
    current_user: dict = Depends(get_current_user)
):
    """Step 3: Generate report - creates users and processes CAS analysis"""
    try:
        session = await db.cas_upload_sessions.find_one({"session_id": session_id})
        if not session:
            raise HTTPException(status_code=404, detail="Session not found")
        
        if session['user_id'] != current_user['id'] and current_user['role'] != 'broker':
            raise HTTPException(status_code=403, detail="Access denied")
        
        if session.get('status') == 'generated':
            raise HTTPException(status_code=400, detail="Report already generated")
        
        # Load saved files
        session_dir = f"/app/uploads/cas_sessions/{session_id}"
        file_contents = []
        for file_info in session.get('saved_files', []):
            file_path = os.path.join(session_dir, file_info['filename'])
            with open(file_path, 'rb') as f:
                file_contents.append({
                    'content': f.read(),
                    'filename': file_info['original_name'],
                    'password': file_info['password']
                })
        
        # Create new clients for new PANs
        pan_results = session.get('pan_results', [])
        
        # Merge pan_updates from request body into pan_results
        # This is critical for MFD/RIA flow where email/mobile/name are filled after upload
        if request and request.pan_updates:
            pan_updates_map = {pu.get('pan', '').upper(): pu for pu in request.pan_updates}
            for pr in pan_results:
                pan_key = pr.get('pan', '').upper()
                if pan_key in pan_updates_map:
                    update_data = pan_updates_map[pan_key]
                    # Merge email, mobile, name, country_of_residency
                    if update_data.get('email'):
                        pr['email'] = update_data['email']
                    if update_data.get('mobile'):
                        pr['mobile'] = update_data['mobile']
                    if update_data.get('name'):
                        pr['name'] = update_data['name']
                    if update_data.get('country_of_residency'):
                        pr['country_of_residency'] = update_data['country_of_residency']
        
        created_clients = []
        is_sub_broker = current_user.get('role') == 'sub_broker'
        
        for pr in pan_results:
            if pr['status'] == 'new':
                # Check if PAN already exists (double-check, should be caught in upload step)
                existing_client = await db.Private_Investor.find_one({
                    "$or": [
                        {"pan_number": pr['pan']},
                        {"pan": pr['pan']}
                    ]
                })
                if existing_client:
                    # PAN already exists, skip creating and use existing
                    pr['status'] = 'existing'
                    pr['client_id'] = existing_client.get('id')
                    pr['name'] = existing_client.get('name', pr.get('name'))
                    continue
                
                # Validate email is provided for sending setup link
                if not pr.get('email'):
                    raise HTTPException(
                        status_code=400, 
                        detail=f"Email is required for PAN {pr['pan']} to send setup link"
                    )
                
                new_client_id = str(uuid.uuid4())
                setup_token = str(uuid.uuid4())  # Token for password setup
                setup_token_expiry = (datetime.now(timezone.utc) + timedelta(days=7)).isoformat()
                
                approval_status = 'pending_approval' if is_sub_broker else 'approved'
                
                new_client = {
                    "id": new_client_id,
                    "name": pr['name'] or f"Investor {pr['pan']}",
                    "email": pr.get('email', ''),
                    "mobile": pr.get('mobile', ''),
                    "pan_number": pr['pan'],
                    "passport_type": pr.get('passport_type', 'indian'),
                    "country_of_residency": pr.get('country_of_residency', 'India'),
                    "opportunities": ["bonds", "real_estate"],
                    "kyc_status": "incomplete",
                    "approval_status": approval_status,
                    "is_active": True,
                    "password_set": False,  # Flag to indicate password not yet set
                    "setup_token": setup_token,
                    "setup_token_expiry": setup_token_expiry,
                    "created_by": current_user['id'],
                    "created_by_name": current_user['name'],
                    "created_by_role": current_user.get('role', 'broker'),
                    "linked_subbroker_id": current_user['id'] if is_sub_broker else None,
                    "linked_subbroker_name": current_user['name'] if is_sub_broker else None,
                    "created_at": datetime.now(timezone.utc).isoformat(),
                    "source": "cas_auto_create"
                }
                
                await db.Private_Investor.insert_one(new_client)
                created_clients.append(new_client)
                
                # Send setup email
                setup_link = f"https://kinntegraa.club/setup-password?token={setup_token}"
                email_sent = False
                try:
                    # Try to send email using the email service
                    import smtplib
                    from email.mime.text import MIMEText
                    from email.mime.multipart import MIMEMultipart
                    
                    # Email content
                    email_subject = "Welcome to Kinntegraa - Set Up Your Account"
                    email_body = f"""
Dear {pr['name']},

Welcome to Kinntegraa! Your account has been created for CAS Analysis.

Your Login Details:
- User ID: {pr['pan']} (Your PAN Number)

Please click the link below to set up your password and PIN:
{setup_link}

This link will expire in 7 days.

If you did not request this account, please ignore this email.

Best regards,
Kinntegraa Team

---
Kinntegraa L.L.C-FZ
License No: 2418465.01
"""
                    logger.info(f"Setup link for {pr['pan']}: {setup_link}")
                    email_sent = True  # Mark as sent (actual email sending can be configured)
                except Exception as e:
                    logger.error(f"Error sending setup email to {pr.get('email')}: {e}")
                
                # Update pan_result with client_id and setup info
                pr['client_id'] = new_client_id
                pr['status'] = 'created'
                pr['setup_info'] = {
                    "login_id": pr['pan'],
                    "email_sent_to": pr.get('email'),
                    "setup_link": setup_link,
                    "email_sent": email_sent
                }
                pr['approval_status'] = approval_status
        
        # Parse all CAS files
        parsed_data_list = []
        for file_info in file_contents:
            parser = CASParser(file_info['content'], file_info['password'])
            parsed_data = parser.parse()
            parsed_data_list.append(parsed_data)
        
        # Merge if multiple files
        if len(parsed_data_list) > 1:
            combined_parsed_data = CASParser.merge_parsed_data(parsed_data_list)
        else:
            combined_parsed_data = parsed_data_list[0]
        
        # Save files to permanent location
        upload_dir = "/app/uploads/cas_pdfs"
        os.makedirs(upload_dir, exist_ok=True)
        
        master_analysis_id = str(uuid.uuid4())
        saved_filenames = []
        for i, file_info in enumerate(file_contents):
            saved_filename = f"{master_analysis_id}_{i}_{file_info['filename']}"
            file_path = os.path.join(upload_dir, saved_filename)
            with open(file_path, 'wb') as f:
                f.write(file_info['content'])
            saved_filenames.append(saved_filename)
        
        display_filename = file_contents[0]['filename'] if len(file_contents) == 1 else f"{len(file_contents)} CAS files combined"
        
        # Create analysis record for each PAN
        for pr in pan_results:
            pan_analysis_id = str(uuid.uuid4())
            analysis_record = {
                "id": pan_analysis_id,
                "master_analysis_id": master_analysis_id,
                "session_id": session_id,
                "user_id": current_user['id'],
                "user_name": current_user['name'],
                "client_id": pr['client_id'],
                "client_name": pr['name'],
                "client_pan": pr['pan'],
                "filename": display_filename,
                "saved_filenames": saved_filenames,
                "source_files_count": len(file_contents),
                "parsed_data": combined_parsed_data,
                "created_at": datetime.now(timezone.utc).isoformat(),
                "status": "completed",
                "is_auto_created": pr['status'] == 'created'
            }
            await db.cas_analyses.insert_one(analysis_record)
            pr['analysis_id'] = pan_analysis_id
        
        # Update session status
        await db.cas_upload_sessions.update_one(
            {"session_id": session_id},
            {"$set": {
                "status": "generated",
                "master_analysis_id": master_analysis_id,
                "pan_results": pan_results,
                "generated_at": datetime.now(timezone.utc).isoformat()
            }}
        )
        
        return {
            "success": True,
            "master_analysis_id": master_analysis_id,
            "total_pans": len(pan_results),
            "clients_created": len(created_clients),
            "pan_results": pan_results,
            "portfolio_summary": combined_parsed_data.get('portfolio_summary', {}),
            "total_folios": len(combined_parsed_data.get('folios', {})),
            "total_transactions": combined_parsed_data.get('total_transactions', 0)
        }
        
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error generating report: {e}")
        import traceback
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=str(e))


@api_router.get("/analysis/session/{session_id}/download")
async def download_session_report(
    session_id: str,
    current_user: dict = Depends(get_current_user)
):
    """Step 4: Download combined ZIP report for all PANs in session"""
    try:
        session = await db.cas_upload_sessions.find_one({"session_id": session_id})
        if not session:
            raise HTTPException(status_code=404, detail="Session not found")
        
        if session['user_id'] != current_user['id'] and current_user['role'] != 'broker':
            raise HTTPException(status_code=403, detail="Access denied")
        
        if session.get('status') not in ['generated', 'downloaded']:
            raise HTTPException(status_code=400, detail="Report not yet generated")
        
        master_analysis_id = session.get('master_analysis_id')
        if not master_analysis_id:
            raise HTTPException(status_code=400, detail="No analysis found")
        
        # Get first analysis to get parsed data
        analysis = await db.cas_analyses.find_one({"master_analysis_id": master_analysis_id})
        if not analysis:
            raise HTTPException(status_code=404, detail="Analysis not found")
        
        # Import needed classes first
        from analysis_service import GapSheetGenerator, NAVService, SchemeMapper
        
        # Get scheme master for mapping
        scheme_master = await db.scheme_master.find_one({"type": "bse_master"})
        scheme_mapper_obj = None
        if scheme_master and scheme_master.get('schemes'):
            scheme_mapper_obj = SchemeMapper(scheme_master['schemes'])
        
        # Generate report using GapSheetGenerator
        nav_service = NAVService()
        
        # Create generator with parsed data
        generator = GapSheetGenerator(
            analysis['parsed_data'],
            nav_service=nav_service,
            scheme_mapper=scheme_mapper_obj
        )
        
        # Generate all reports as ZIP (includes PAN folders + consolidated)
        zip_content = generator.generate_all_reports()
        zip_buffer = io.BytesIO(zip_content)
        
        # Update session status
        await db.cas_upload_sessions.update_one(
            {"session_id": session_id},
            {"$set": {
                "status": "downloaded",
                "downloaded_at": datetime.now(timezone.utc).isoformat()
            }}
        )
        
        return Response(
            content=zip_buffer.getvalue(),
            media_type="application/zip",
            headers={
                "Content-Disposition": f"attachment; filename=CAS_Reports_{session_id[:8]}.zip"
            }
        )
        
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error downloading session report: {e}")
        import traceback
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=str(e))


