@api_router.get("/analysis/{analysis_id}/download")
async def download_gap_sheet(
    analysis_id: str,
    all_pans: bool = False,
    consolidated: bool = False,
    current_user: dict = Depends(get_current_user)
):
    """Download the generated Gap Sheet Excel file - optionally filtered by client's PAN
    
    Args:
        analysis_id: The analysis ID to download
        all_pans: If True, include all PANs from the analysis (not just the client's PAN)
        consolidated: If True, include consolidated files at root level even for single PAN
    """
    try:
        logger.info(f"Download request for analysis: {analysis_id}, all_pans={all_pans}, consolidated={consolidated}")
        
        # Get analysis record
        analysis = await db.cas_analyses.find_one({"id": analysis_id})
        
        if not analysis:
            logger.warning(f"Analysis not found: {analysis_id}")
            raise HTTPException(status_code=404, detail="Analysis not found")
        
        # Get client_pan to filter data (unless all_pans is requested)
        client_pan = analysis.get('client_pan', '').upper() if not all_pans else None
        
        # Filter parsed_data by client_pan if needed
        original_parsed_data = analysis.get('parsed_data', {})
        all_folios = original_parsed_data.get('folios', {})
        
        if client_pan:
            # Filter folios to only include this client's PAN
            filtered_folios = {k: v for k, v in all_folios.items() if v.get('pan', '').upper() == client_pan}
            
            # Also filter transactions if present at top level
            all_transactions = original_parsed_data.get('transactions', [])
            filtered_transactions = [t for t in all_transactions if t.get('pan', '').upper() == client_pan or 
                                     any(t.get('folio') == f.get('folio_number') for f in filtered_folios.values())]
            
            parsed_data = {
                'folios': filtered_folios,
                'transactions': filtered_transactions,
                'portfolio_summary': original_parsed_data.get('portfolio_summary', {}),
                'report_date': original_parsed_data.get('report_date'),  # CAS NAV date - critical for benchmark comparison
                'investor_info': original_parsed_data.get('investor_info', {})
            }
            logger.info(f"Filtered to {len(filtered_folios)} folios for PAN {client_pan} (from {len(all_folios)} total)")
        else:
            # Include all PANs
            parsed_data = original_parsed_data
            logger.info(f"Including all {len(all_folios)} folios (all PANs)")
        
        logger.info(f"Found analysis with {len(parsed_data.get('folios', {}))} folios")
        
        # Get scheme master for mapping
        scheme_master = await db.scheme_master.find_one({"type": "bse_master"})
        scheme_mapper = None
        if scheme_master and scheme_master.get('schemes'):
            scheme_mapper = SchemeMapper(scheme_master['schemes'])
            logger.info(f"Scheme mapper loaded with {len(scheme_master.get('schemes', []))} schemes")
        else:
            logger.info("No scheme master available")
        
        # Generate Gap Sheet
        logger.info("Starting report generation...")
        nav_service = NAVService()
        generator = GapSheetGenerator(
            parsed_data, 
            nav_service,
            scheme_mapper
        )
        
        # Generate report - only include consolidated files if explicitly requested
        zip_bytes = generator.generate_all_reports(include_consolidated=consolidated)
        logger.info(f"Report generated successfully: {len(zip_bytes)} bytes")
        
        # Return as downloadable ZIP file
        pan_suffix = f"_{client_pan}" if client_pan else "_AllPANs"
        filename = f"GapSheet{pan_suffix}.zip"
        
        return Response(
            content=zip_bytes,
            media_type="application/zip",
            headers={
                "Content-Disposition": f"attachment; filename={filename}",
                "Content-Length": str(len(zip_bytes))
            }
        )
        
    except HTTPException:
        raise
    except Exception as e:
        import traceback
        logger.error(f"Error generating Gap Sheet: {e}")
        logger.error(f"Traceback: {traceback.format_exc()}")
        raise HTTPException(status_code=500, detail=f"Error generating report: {str(e)}")


@api_router.get("/analysis/{analysis_id}/download-pdf")
async def download_original_pdf(
    analysis_id: str,
    current_user: dict = Depends(get_current_user)
):
    """Download the original uploaded CAS PDF file"""
    from fastapi.responses import FileResponse
    
    try:
        # Get analysis record
        analysis = await db.cas_analyses.find_one({"id": analysis_id})
        
        if not analysis:
            raise HTTPException(status_code=404, detail="Analysis not found")
        
        # Check if the user has access
        if current_user['role'] not in ['broker'] and analysis.get('user_id') != current_user['id']:
            raise HTTPException(status_code=403, detail="Not authorized to access this file")
        
        # Get the saved filename
        saved_filename = analysis.get('saved_filename')
        original_filename = analysis.get('filename', 'CAS_Statement.pdf')
        
        if not saved_filename:
            raise HTTPException(status_code=404, detail="Original PDF file not available. This analysis was created before PDF storage was enabled.")
        
        file_path = f"/app/uploads/cas_pdfs/{saved_filename}"
        
        if not os.path.exists(file_path):
            raise HTTPException(status_code=404, detail="PDF file not found on server")
        
        return FileResponse(
            path=file_path,
            filename=original_filename,
            media_type="application/pdf"
        )
        
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error downloading PDF: {e}")
        raise HTTPException(status_code=500, detail=f"Error downloading PDF: {str(e)}")


