@api_router.get("/analysis/{analysis_id}/dashboard")
async def get_analysis_dashboard(
    analysis_id: str,
    current_user: dict = Depends(get_current_user)
):
    """Get dashboard data for an analysis - formatted for visualization"""
    try:
        analysis = await db.cas_analyses.find_one({"id": analysis_id}, {"_id": 0})
        
        if not analysis:
            raise HTTPException(status_code=404, detail="Analysis not found")
        
        parsed_data = analysis.get('parsed_data', {})
        all_folios = parsed_data.get('folios', {})
        
        # Filter folios by client_pan - only show data for this client's PAN
        client_pan = analysis.get('client_pan', '').upper()
        if client_pan:
            folios = {k: v for k, v in all_folios.items() if v.get('pan', '').upper() == client_pan}
        else:
            folios = all_folios
        
        # Get scheme master for type categorization
        scheme_master = await db.scheme_master.find_one({"type": "bse_master"})
        scheme_mapper = None
        if scheme_master and scheme_master.get('schemes'):
            scheme_mapper = SchemeMapper(scheme_master['schemes'])
        
        # Calculate dashboard metrics
        total_investment = 0
        total_current_value = 0
        total_redemptions = 0
        advisor_breakdown = {}
        scheme_breakdown = []
        holdings_by_type = {'Equity': 0, 'Debt': 0, 'Hybrid': 0, 'Other': 0}
        monthly_investments = {}
        
        for folio_key, folio_data in folios.items():
            scheme_name = folio_data.get('scheme', '')
            isin = folio_data.get('isin', '')
            closing_balance = folio_data.get('closing_balance', 0)
            current_nav = folio_data.get('current_nav', 0)
            market_value = folio_data.get('market_value', 0)
            
            # If market_value not available, calculate from NAV
            if not market_value and closing_balance > 0 and current_nav > 1:
                market_value = closing_balance * current_nav
            
            # Categorize by fund type using scheme master
            if scheme_mapper:
                fund_type = scheme_mapper.get_asset_category(isin=isin, scheme_name=scheme_name)
            else:
                # Fallback to keyword matching if no scheme master
                scheme_lower = scheme_name.lower()
                equity_keywords = ['equity', 'index', 'nifty', 'sensex', 'midcap', 'smallcap', 
                                  'large cap', 'multi cap', 'flexi cap', 'bluechip', 'elss', 
                                  'tax saver', 'focused', 'value', 'growth fund']
                debt_keywords = ['debt', 'liquid', 'money market', 'ultra short', 'overnight',
                                'gilt', 'bond', 'income', 'credit risk', 'banking', 'corporate bond',
                                'dynamic bond', 'fixed maturity', 'fmp', 'floating rate']
                hybrid_keywords = ['hybrid', 'balanced', 'aggressive', 'conservative', 'arbitrage',
                                  'equity savings', 'multi asset', 'asset allocation']
                
                if any(kw in scheme_lower for kw in equity_keywords):
                    fund_type = 'Equity'
                elif any(kw in scheme_lower for kw in debt_keywords):
                    fund_type = 'Debt'
                elif any(kw in scheme_lower for kw in hybrid_keywords):
                    fund_type = 'Hybrid'
                else:
                    fund_type = 'Other'
            
            holdings_by_type[fund_type] += market_value
            
            # Process transactions
            for trans in folio_data.get('transactions', []):
                amount = abs(trans.get('amount') or 0)  # Handle None for segregated portfolios
                advisor = trans.get('advisor', 'Direct')
                trans_date = trans.get('date', '')
                
                if trans.get('is_redemption'):
                    total_redemptions += amount
                else:
                    total_investment += amount
                    
                    # Advisor breakdown
                    if advisor not in advisor_breakdown:
                        advisor_breakdown[advisor] = {'invested': 0, 'schemes': set()}
                    advisor_breakdown[advisor]['invested'] += amount
                    advisor_breakdown[advisor]['schemes'].add(scheme_name[:30])
                    
                    # Monthly investments trend
                    try:
                        from datetime import datetime
                        dt = datetime.strptime(trans_date, '%d-%b-%Y')
                        month_key = dt.strftime('%Y-%m')
                        if month_key not in monthly_investments:
                            monthly_investments[month_key] = 0
                        monthly_investments[month_key] += amount
                    except:
                        pass
            
            # Add to scheme breakdown if has balance
            if closing_balance > 0 and market_value > 0:
                total_current_value += market_value
                scheme_breakdown.append({
                    'name': scheme_name[:40] + ('...' if len(scheme_name) > 40 else ''),
                    'full_name': scheme_name,
                    'folio': folio_data.get('folio', folio_key),
                    'units': round(closing_balance, 3),
                    'nav': round(current_nav, 4) if current_nav > 1 else None,
                    'value': round(market_value, 2),
                    'type': fund_type
                })
        
        # Sort scheme breakdown by value
        scheme_breakdown.sort(key=lambda x: x['value'], reverse=True)
        
        # Format advisor breakdown
        advisor_list = []
        for advisor, data in advisor_breakdown.items():
            advisor_list.append({
                'name': advisor if advisor else 'Direct',
                'invested': round(data['invested'], 2),
                'schemes_count': len(data['schemes'])
            })
        advisor_list.sort(key=lambda x: x['invested'], reverse=True)
        
        # Format monthly trend (last 12 months)
        sorted_months = sorted(monthly_investments.keys())[-12:]
        monthly_trend = [
            {'month': m, 'amount': monthly_investments.get(m, 0)}
            for m in sorted_months
        ]
        
        # Calculate gains
        total_gains = total_current_value - total_investment + total_redemptions
        gain_percentage = (total_gains / total_investment * 100) if total_investment > 0 else 0
        
        # Count unique folio numbers (not folio+ISIN combinations)
        unique_folios = set(folio_data.get('folio', folio_key) for folio_key, folio_data in folios.items())
        active_schemes_count = len([s for s in scheme_breakdown if s['value'] > 0])
        
        # Get correct client name - first try by PAN, then by client_id
        client_name = analysis.get('client_name')
        if client_pan:
            client_doc = await db.Private_Investor.find_one(
                {"pan_number": client_pan},
                {"_id": 0, "name": 1}
            )
            if client_doc:
                client_name = client_doc.get('name', client_name)
        elif analysis.get('client_id'):
            client_doc = await db.Private_Investor.find_one(
                {"id": analysis.get('client_id')},
                {"_id": 0, "name": 1}
            )
            if client_doc:
                client_name = client_doc.get('name', client_name)
        
        return {
            "analysis_id": analysis_id,
            "client_name": client_name,
            "client_pan": client_pan,
            "filename": analysis.get('filename'),
            "created_at": analysis.get('created_at'),
            "summary": {
                "total_investment": round(total_investment, 2),
                "total_current_value": round(total_current_value, 2),
                "total_redemptions": round(total_redemptions, 2),
                "total_gains": round(total_gains, 2),
                "gain_percentage": round(gain_percentage, 2),
                "total_folios": len(unique_folios),
                "active_schemes": active_schemes_count
            },
            "holdings_by_type": holdings_by_type,
            "top_holdings": scheme_breakdown[:10],
            "all_holdings": scheme_breakdown,
            "advisor_breakdown": advisor_list[:10],
            "monthly_trend": monthly_trend
        }
        
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error generating dashboard: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@api_router.get("/analysis/{analysis_id}/stockwise")
async def get_analysis_stockwise_holdings(
    analysis_id: str,
    current_user: dict = Depends(get_current_user)
):
    """
    Get stockwise holdings for schemes held in a CAS analysis.
    Returns:
    - summary: Overall stock allocation across all MFs
    - scheme_wise: Individual MF scheme stock holdings
    """
    import re
    
    try:
        analysis = await db.cas_analyses.find_one({"id": analysis_id}, {"_id": 0})
        
        if not analysis:
            raise HTTPException(status_code=404, detail="Analysis not found")
        
        parsed_data = analysis.get('parsed_data', {})
        all_folios = parsed_data.get('folios', {})
        
        # Filter folios by client_pan
        client_pan = analysis.get('client_pan', '').upper()
        if client_pan:
            folios = {k: v for k, v in all_folios.items() if v.get('pan', '').upper() == client_pan}
        else:
            folios = all_folios
        
        # Get scheme master for ISIN to AMFI mapping
        scheme_master = await db.scheme_master.find_one({"type": "bse_master"})
        scheme_lookup = {}
        if scheme_master and scheme_master.get('schemes'):
            for s in scheme_master['schemes']:
                if s.get('isin'):
                    scheme_lookup[s['isin']] = s
                if s.get('isin_reinvestment'):
                    scheme_lookup[s['isin_reinvestment']] = s
        
        # Collect ISINs and scheme names from folios with holdings
        scheme_data = []
        for folio_key, folio_data in folios.items():
            closing_balance = folio_data.get('closing_balance', 0)
            if closing_balance <= 0:
                continue
            
            isin = folio_data.get('isin', '')
            scheme_name = folio_data.get('scheme', '')
            market_value = folio_data.get('market_value', 0)
            
            if not market_value:
                nav = folio_data.get('current_nav', 0)
                if nav > 1:
                    market_value = closing_balance * nav
            
            scheme_data.append({
                'isin': isin,
                'scheme_name': scheme_name,
                'market_value': market_value,
                'units': closing_balance
            })
        
        if not scheme_data:
            return {
                "analysis_id": analysis_id,
                "total_schemes": 0,
                "schemes_with_stockwise": 0,
                "summary": [],
                "scheme_wise": []
            }
        
        # For each scheme, fetch stockwise holdings
        scheme_wise_data = []
        all_stocks = {}  # {stock_name: {isin, sector, market_cap, total_value, total_pct}}
        schemes_with_data = 0
        
        for scheme in scheme_data:
            isin = scheme['isin']
            scheme_name = scheme['scheme_name']
            scheme_value = scheme['market_value']
            
            # Try to find stockwise holdings
            holdings = []
            
            # Method 1: Try AMFI code from scheme master
            if isin in scheme_lookup:
                amfi_code = scheme_lookup[isin].get('scheme_code') or scheme_lookup[isin].get('unique_no')
                if amfi_code:
                    holdings = await db.stockwise_holdings.find(
                        {"amfi_code": str(amfi_code)},
                        {"_id": 0}
                    ).sort("pct_to_net_assets", -1).to_list(200)
            
            # Method 2: Try by scheme ISIN
            if not holdings and isin:
                holdings = await db.stockwise_holdings.find(
                    {"scheme_isin": isin},
                    {"_id": 0}
                ).sort("pct_to_net_assets", -1).to_list(200)
            
            # Method 3: Fuzzy name matching
            if not holdings and scheme_name:
                clean_name = scheme_name.replace('Prudential', 'Pru').replace('Mutual Fund', '')
                clean_name = re.sub(r'\s*(Regular|Direct|Growth|Plan|Dividend|IDCW|Non-Demat|\(G\)|\(D\)).*', '', clean_name, flags=re.I)
                clean_name = clean_name.strip()
                
                if len(clean_name) > 5:
                    holdings = await db.stockwise_holdings.find(
                        {"scheme_name": {"$regex": f"^{re.escape(clean_name[:20])}", "$options": "i"}},
                        {"_id": 0}
                    ).sort("pct_to_net_assets", -1).to_list(200)
            
            if holdings:
                schemes_with_data += 1
                
                # Process holdings for this scheme
                scheme_stocks = []
                for h in holdings:
                    stock_name = h.get('instrument_name', '')
                    stock_isin = h.get('instrument_isin', '')
                    sector = h.get('sector', 'Other')
                    market_cap = h.get('market_cap_category', '')
                    pct = h.get('pct_to_net_assets', 0) or 0
                    
                    if not stock_name or pct <= 0:
                        continue
                    
                    # Calculate value in customer's portfolio
                    stock_value = (pct / 100) * scheme_value if scheme_value > 0 else 0
                    
                    scheme_stocks.append({
                        'name': stock_name,
                        'isin': stock_isin,
                        'sector': sector,
                        'market_cap': market_cap,
                        'pct_in_scheme': round(pct, 2),
                        'value_in_portfolio': round(stock_value, 2)
                    })
                    
                    # Aggregate for summary
                    if stock_name not in all_stocks:
                        all_stocks[stock_name] = {
                            'isin': stock_isin,
                            'sector': sector,
                            'market_cap': market_cap,
                            'total_value': 0,
                            'schemes': []
                        }
                    all_stocks[stock_name]['total_value'] += stock_value
                    all_stocks[stock_name]['schemes'].append(scheme_name[:30])
                
                scheme_wise_data.append({
                    'scheme_name': scheme_name,
                    'isin': isin,
                    'scheme_value': round(scheme_value, 2),
                    'stocks_count': len(scheme_stocks),
                    'top_stocks': scheme_stocks[:20]
                })
        
        # Calculate total portfolio value for percentage calculation
        total_portfolio_value = sum(s['market_value'] for s in scheme_data)
        
        # Build summary - aggregated stock holdings
        summary_stocks = []
        for stock_name, data in all_stocks.items():
            pct_of_portfolio = (data['total_value'] / total_portfolio_value * 100) if total_portfolio_value > 0 else 0
            summary_stocks.append({
                'name': stock_name,
                'isin': data['isin'],
                'sector': data['sector'],
                'market_cap': data['market_cap'],
                'value': round(data['total_value'], 2),
                'pct_of_portfolio': round(pct_of_portfolio, 2),
                'held_in_schemes': len(set(data['schemes']))
            })
        
        # Sort by value descending
        summary_stocks.sort(key=lambda x: x['value'], reverse=True)
        
        # Sector breakdown
        sector_breakdown = {}
        for stock in summary_stocks:
            sector = stock['sector'] or 'Other'
            if sector not in sector_breakdown:
                sector_breakdown[sector] = 0
            sector_breakdown[sector] += stock['value']
        
        sector_list = [{'sector': k, 'value': round(v, 2), 'pct': round(v/total_portfolio_value*100, 2) if total_portfolio_value > 0 else 0} 
                       for k, v in sector_breakdown.items()]
        sector_list.sort(key=lambda x: x['value'], reverse=True)
        
        # Market cap breakdown
        market_cap_breakdown = {}
        for stock in summary_stocks:
            mc = stock['market_cap'] or 'Unknown'
            if mc not in market_cap_breakdown:
                market_cap_breakdown[mc] = 0
            market_cap_breakdown[mc] += stock['value']
        
        market_cap_list = [{'market_cap': k, 'value': round(v, 2), 'pct': round(v/total_portfolio_value*100, 2) if total_portfolio_value > 0 else 0}
                          for k, v in market_cap_breakdown.items()]
        market_cap_list.sort(key=lambda x: x['value'], reverse=True)
        
        return {
            "analysis_id": analysis_id,
            "total_schemes": len(scheme_data),
            "schemes_with_stockwise": schemes_with_data,
            "total_portfolio_value": round(total_portfolio_value, 2),
            "summary": {
                "top_stocks": summary_stocks[:50],
                "total_stocks": len(summary_stocks),
                "sector_breakdown": sector_list,
                "market_cap_breakdown": market_cap_list
            },
            "scheme_wise": scheme_wise_data
        }
        
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error fetching stockwise holdings: {e}")
        raise HTTPException(status_code=500, detail=str(e))


