@api_router.get("/analysis/client/{client_id}")
async def get_client_analyses(
    client_id: str,
    current_user: dict = Depends(get_current_user)
):
    """Get all CAS analyses for a specific client - filtered by their PAN only"""
    try:
        # Verify client exists and user has access. Look across legacy +
        # Indian/Foreign passport collections.
        client = None
        for coll in ("Private_Investor", "Private_Investor_Indian_Passport", "Private_Investor_Foreign_Passport"):
            client = await db[coll].find_one({"id": client_id}, {"_id": 0})
            if client:
                break
        if not client:
            raise HTTPException(status_code=404, detail="Client not found")
        
        client_pan = (client.get('pan_number') or client.get('pan') or '').upper()
        
        # Check access - broker can see all, sub_broker sees their own clients, client sees own data
        if current_user['role'] == 'client':
            # Client can only see their own analyses (legacy + 3-way login)
            if current_user.get('client_id') != client_id and current_user.get('id') != client_id:
                raise HTTPException(status_code=403, detail="Access denied")
        elif current_user['role'] == 'sub_broker':
            # Sub-broker can see their linked clients
            if client.get('linked_subbroker_id') != current_user['id']:
                raise HTTPException(status_code=403, detail="Access denied")
        # Broker can see all
        
        # Fetch analyses for this client - ONLY their own PAN's analyses
        # Show unique files only (not per PAN, not consolidated entries)
        query = {"client_id": client_id}
        if client_pan:
            query["client_pan"] = {"$regex": f"^{client_pan}$", "$options": "i"}
        
        all_analyses = await db.cas_analyses.find(
            query,
            {"_id": 0, "parsed_data": 0}  # Exclude large parsed_data for list view
        ).sort("created_at", -1).to_list(length=100)
        
        # Show unique files only - skip consolidated/combined entries
        seen_files = set()
        unique_analyses = []
        
        for analysis in all_analyses:
            filename = analysis.get('filename', '')
            
            # Skip consolidated/combined entries - show only individual file entries
            if 'combined' in filename.lower() or 'consolidated' in filename.lower():
                continue
            
            # Group by filename to show unique files
            if filename and filename not in seen_files:
                seen_files.add(filename)
                unique_analyses.append(analysis)
        
        return unique_analyses
        
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error fetching client analyses: {e}")
        raise HTTPException(status_code=500, detail=str(e))


# Scheme Master Management
@api_router.post("/analysis/upload-scheme-master")
async def upload_scheme_master(
    file: UploadFile = File(...),
    current_user: dict = Depends(get_current_user)
):
    """Upload BSE scheme master file (broker only)"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can upload scheme master")
    
    try:
        content = await file.read()
        text_content = content.decode('utf-8', errors='ignore')
        
        # Parse the scheme master file
        schemes = parse_scheme_master_file(text_content)
        
        if not schemes:
            raise HTTPException(status_code=400, detail="Could not parse scheme master file")
        
        # Update or create scheme master record
        existing = await db.scheme_master.find_one({"type": "bse_master"})
        
        if existing:
            # Merge new schemes with existing (append unique)
            existing_isins = {s.get('isin') for s in existing.get('schemes', [])}
            new_schemes = [s for s in schemes if s.get('isin') not in existing_isins]
            
            await db.scheme_master.update_one(
                {"type": "bse_master"},
                {
                    "$push": {"schemes": {"$each": new_schemes}},
                    "$set": {
                        "last_upload": datetime.now(timezone.utc).isoformat(),
                        "last_upload_by": current_user['id'],
                        "last_filename": file.filename,
                        "total_schemes": len(existing.get('schemes', [])) + len(new_schemes)
                    }
                }
            )
            added_count = len(new_schemes)
        else:
            await db.scheme_master.insert_one({
                "type": "bse_master",
                "schemes": schemes,
                "total_schemes": len(schemes),
                "last_upload": datetime.now(timezone.utc).isoformat(),
                "last_upload_by": current_user['id'],
                "last_filename": file.filename,
                "created_at": datetime.now(timezone.utc).isoformat()
            })
            added_count = len(schemes)
        
        # Save upload history
        await db.upload_history.insert_one({
            "upload_type": "bse_scheme_master",
            "filename": file.filename,
            "uploaded_at": datetime.now(timezone.utc).isoformat(),
            "uploaded_by": current_user['id'],
            "records_processed": len(schemes),
            "schemes_added": added_count
        })
        
        return {
            "message": "Scheme master uploaded successfully",
            "schemes_added": added_count,
            "total_schemes_in_file": len(schemes),
            "filename": file.filename
        }
        
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error uploading scheme master: {e}")
        raise HTTPException(status_code=500, detail=f"Error uploading file: {str(e)}")


@api_router.get("/analysis/scheme-master/status")
async def get_scheme_master_status(current_user: dict = Depends(get_current_user)):
    """Get scheme master file status"""
    try:
        master = await db.scheme_master.find_one(
            {"type": "bse_master"},
            {"_id": 0, "schemes": 0}  # Exclude large data
        )
        
        # Get last 3 upload dates
        upload_history = await db.upload_history.find(
            {"upload_type": "bse_scheme_master"},
            {"_id": 0, "uploaded_at": 1, "filename": 1, "records_processed": 1}
        ).sort("uploaded_at", -1).limit(3).to_list(3)
        
        if not master:
            return {
                "exists": False,
                "total_schemes": 0,
                "last_upload": None,
                "upload_history": upload_history
            }
        
        return {
            "exists": True,
            "total_schemes": master.get('total_schemes', 0),
            "last_upload": master.get('last_upload'),
            "last_filename": master.get('last_filename'),
            "last_upload_by": master.get('last_upload_by'),
            "upload_history": upload_history
        }
        
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


