# ==================== FOREX RATE ENDPOINT ====================

@api_router.get("/forex/aed-to-inr")
async def get_aed_to_inr_rate():
    """Get current AED to INR exchange rate from free API"""
    import aiohttp
    
    try:
        # Using the free exchange rate API
        async with aiohttp.ClientSession() as session:
            # Try primary API first
            try:
                async with session.get(
                    "https://cdn.jsdelivr.net/npm/@fawazahmed0/currency-api@latest/v1/currencies/aed.json",
                    timeout=aiohttp.ClientTimeout(total=5)
                ) as response:
                    if response.status == 200:
                        data = await response.json()
                        inr_rate = data.get('aed', {}).get('inr', 22.5)
                        return {
                            "rate": inr_rate,
                            "source": "fawazahmed0/currency-api",
                            "timestamp": datetime.now(timezone.utc).isoformat()
                        }
            except Exception:
                pass
            
            # Fallback to alternative API
            try:
                async with session.get(
                    "https://api.exchangerate-api.com/v4/latest/AED",
                    timeout=aiohttp.ClientTimeout(total=5)
                ) as response:
                    if response.status == 200:
                        data = await response.json()
                        inr_rate = data.get('rates', {}).get('INR', 22.5)
                        return {
                            "rate": inr_rate,
                            "source": "exchangerate-api",
                            "timestamp": datetime.now(timezone.utc).isoformat()
                        }
            except Exception:
                pass
        
        # Default fallback rate if APIs fail
        return {
            "rate": 22.5,
            "source": "fallback",
            "timestamp": datetime.now(timezone.utc).isoformat()
        }
    except Exception as e:
        # Return fallback rate on any error
        return {
            "rate": 22.5,
            "source": "fallback",
            "timestamp": datetime.now(timezone.utc).isoformat()
        }


# ==================== SUB-BROKER DASHBOARD ENDPOINTS ====================

@api_router.get("/mfd-ria/dashboard/summary")
async def get_sub_broker_dashboard_summary(current_user: dict = Depends(get_current_user)):
    """Get dashboard summary for sub-broker - showing only their linked clients"""
    if current_user['role'] != 'sub_broker':
        raise HTTPException(status_code=403, detail="Only sub-brokers can access this endpoint")
    
    sub_broker_id = current_user['id']
    
    # Get clients linked to this sub-broker
    linked_clients = await db.Private_Investor.find(
        {"linked_subbroker_id": sub_broker_id},
        {"_id": 0}
    ).to_list(1000)
    
    client_ids = [c.get('id') for c in linked_clients]
    total_clients = len(linked_clients)
    active_clients = len([c for c in linked_clients if c.get('is_active', True)])
    
    # Count clients by product type and track unique PANs
    bond_clients = 0
    re_clients = 0
    both_clients = 0
    ncd_unique_pans = set()
    re_unique_pans = set()
    
    for client in linked_clients:
        has_bonds = bool(client.get('bond_allocations', []))
        has_re = False
        # Check real estate investments
        re_opps = await db.Real_Estate_Master.find(
            {"investors.client_id": client.get('id')},
            {"_id": 0}
        ).to_list(1)
        has_re = len(re_opps) > 0
        
        client_pan = client.get('pan_number')
        
        if has_bonds and has_re:
            both_clients += 1
            if client_pan:
                ncd_unique_pans.add(client_pan)
                re_unique_pans.add(client_pan)
        elif has_bonds:
            bond_clients += 1
            if client_pan:
                ncd_unique_pans.add(client_pan)
        elif has_re:
            re_clients += 1
            if client_pan:
                re_unique_pans.add(client_pan)
    
    # Get available opportunities (not funded or closed)
    available_bonds = await db.Ncd_Master.count_documents({
        "status": {"$in": ["available", "open", "active", None]},
        "$or": [
            {"is_funded": {"$ne": True}},
            {"is_funded": {"$exists": False}}
        ]
    })
    available_re = await db.Real_Estate_Master.count_documents({
        "status": {"$in": ["available", "open", "active", None]}
    })
    
    # Get upcoming repayments for all linked clients
    today = datetime.now().strftime("%Y-%m-%d")
    upcoming_repayments = await db.holding_cashflows.find({
        "client_id": {"$in": client_ids},
        "date": {"$gte": today},
        "is_repaid": {"$ne": True}
    }, {"_id": 0, "date": 1, "amount": 1, "type": 1, "bond_name": 1, "client_name": 1}).sort("date", 1).to_list(10)
    
    upcoming_repayments_count = await db.holding_cashflows.count_documents({
        "client_id": {"$in": client_ids},
        "date": {"$gte": today},
        "is_repaid": {"$ne": True}
    })
    
    # Calculate Bond AUM for linked clients with P/I breakdown
    bonds = await db.Ncd_Master.find({}, {"_id": 0}).to_list(1000)
    total_bond_invested = 0
    total_bond_deal_size = 0
    total_bond_repaid = 0
    total_bond_pending = 0
    bond_principal_repaid = 0
    bond_interest_repaid = 0
    bond_principal_pending = 0
    bond_interest_pending = 0
    bond_gross_expected = 0
    bond_profits = 0
    
    # Get trades for linked clients
    trades = await db.Ncd_Investment_Details.find({
        "client_id": {"$in": client_ids},
        "status": {"$in": ["approved", "completed"]}
    }, {"_id": 0}).to_list(1000)
    
    for trade in trades:
        total_bond_invested += trade.get('total_amount', 0) or 0
    
    for client in linked_clients:
        allocations = client.get('bond_allocations', [])
        for alloc in allocations:
            bond = next((b for b in bonds if b.get('id') == alloc.get('bond_id')), None)
            if bond:
                face_value = bond.get('face_value', 0)
                units_paid = alloc.get('units_paid', 0)
                total_bond_deal_size += units_paid * face_value
                
                # Get cashflows for P/I breakdown
                actual_cashflows = await db.actual_repayments.find({
                    "client_id": client.get('id'),
                    "bond_id": alloc.get('bond_id')
                }, {"_id": 0}).to_list(100)
                
                for cf in actual_cashflows:
                    cf_type = cf.get('type', '')
                    amount = cf.get('amount', 0)
                    if 'principal' in cf_type.lower():
                        bond_principal_repaid += amount
                    elif 'interest' in cf_type.lower():
                        bond_interest_repaid += amount
                    total_bond_repaid += amount
    
    if total_bond_invested == 0:
        total_bond_invested = total_bond_deal_size
    
    total_bond_pending = total_bond_deal_size - total_bond_repaid
    bond_gross_expected = total_bond_deal_size
    bond_profits = bond_gross_expected - total_bond_invested
    bond_principal_pending = total_bond_deal_size - bond_principal_repaid
    bond_interest_pending = bond_profits - bond_interest_repaid if bond_profits > bond_interest_repaid else 0
    
    # Calculate Real Estate AUM for linked clients
    real_estate_opps = await db.Real_Estate_Master.find({}, {"_id": 0}).to_list(1000)
    total_re_deal_size = 0
    total_re_paid = 0
    total_re_invested = 0
    re_open_opportunities = 0
    
    for re in real_estate_opps:
        investors = re.get('investors', [])
        for inv in investors:
            if inv.get('client_id') in client_ids:
                share_pct = inv.get('share_percentage', inv.get('percentage', 0))
                total_cost = re.get('total_cost', 0)
                deal_share = total_cost * share_pct / 100
                total_re_deal_size += deal_share
                
                payments = inv.get('payments', [])
                client_paid = sum(p.get('amount', 0) for p in payments)
                total_re_paid += client_paid
                total_re_invested += client_paid
                
                if client_paid < deal_share:
                    re_open_opportunities += deal_share - client_paid
    
    # Get email engagement summary for sub-broker's clients
    email_logs = await db.email_read_logs.find({
        "client_id": {"$in": client_ids}
    }, {"_id": 0}).to_list(1000)
    
    total_emails = len(email_logs)
    holdings_updated = len([e for e in email_logs if e.get('approved') or e.get('is_auto_tagged')])
    holdings_pending = total_emails - holdings_updated
    
    # Get data gathering families for sub-broker
    families = await db.data_gathering_families.find({
        "sub_broker_id": sub_broker_id
    }, {"_id": 0, "id": 1}).to_list(1000)
    unique_families_count = len(families)
    
    # Get CAS summary for sub-broker's clients
    cas_analyses = await db.cas_analyses.find({
        "sub_broker_id": sub_broker_id
    }, {"_id": 0}).to_list(1000)
    
    cas_parsed_count = len(cas_analyses)
    cas_unique_pans = set()
    cas_external_value = 0
    cas_internal_value = 0
    
    for analysis in cas_analyses:
        parsed_data = analysis.get('parsed_data', {})
        investor_info = parsed_data.get('investor_info', {})
        investor_pan = investor_info.get('pan')
        if investor_pan:
            cas_unique_pans.add(investor_pan)
        
        folios = parsed_data.get('folios', {})
        for folio_key, folio_data in folios.items():
            if isinstance(folio_data, dict):
                market_value = folio_data.get('market_value', 0) or 0
                advisor = folio_data.get('advisor', '') or ''
                is_internal = 'ARN-145633' in advisor or '145633' in str(advisor)
                if is_internal:
                    cas_internal_value += market_value
                else:
                    cas_external_value += market_value
    
    return {
        "clients": {
            "total": total_clients,
            "active": active_clients,
            "bond_only": bond_clients,
            "real_estate_only": re_clients,
            "both_products": both_clients
        },
        "opportunities": {
            "bonds": {"available": available_bonds},
            "real_estate": {"available": available_re}
        },
        "upcoming_repayments": {
            "count": upcoming_repayments_count,
            "items": upcoming_repayments
        },
        "bond_aum": {
            "total_deal_size": total_bond_deal_size,
            "total_invested": total_bond_invested,
            "total_repaid": total_bond_repaid,
            "principal_repaid": bond_principal_repaid,
            "interest_repaid": bond_interest_repaid,
            "gross_expected": bond_gross_expected,
            "total_pending": total_bond_pending,
            "principal_pending": bond_principal_pending,
            "interest_pending": bond_interest_pending,
            "profits": bond_profits,
            "unique_clients": len(ncd_unique_pans)
        },
        "real_estate_aum": {
            "total_deal_size": total_re_deal_size,
            "total_invested": total_re_invested,
            "total_paid": total_re_paid,
            "open_opportunities": re_open_opportunities,
            "unique_clients": len(re_unique_pans)
        },
        "email_engagement": {
            "total_emails": total_emails,
            "holdings_updated": holdings_updated,
            "holdings_pending": holdings_pending
        },
        "data_gathering": {
            "unique_families": unique_families_count
        },
        "cas_summary": {
            "cas_parsed_count": cas_parsed_count,
            "unique_pan_count": len(cas_unique_pans),
            "external_portfolio_value": cas_external_value,
            "internal_portfolio_value": cas_internal_value,
            "total_portfolio_value": cas_external_value + cas_internal_value
        }
    }


# ==================== LEADS MANAGEMENT ====================

class CreateLeadRequest(BaseModel):
    """Request model for creating a lead from client interest"""
    opportunity_type: str  # 'bond' or 'real_estate'
    opportunity_id: str
    investment_amount: Optional[float] = None  # For bonds
    interest_percentage: Optional[float] = None  # For real estate
    notes: str = ""


class UpdateLeadStatusRequest(BaseModel):
    """Request model for updating lead status"""
    status: str  # 'open', 'contacted', 'converted', 'not_interested', 'closed'
    reason: Optional[str] = None  # Reason for not_interested status


class SignupInterestRequest(BaseModel):
    """Request model for signup page interest form"""
    name: str
    email: str
    phone: str
    source: str = "signup_page"


@api_router.post("/leads/interest")
async def create_signup_interest(request: SignupInterestRequest):
    """Create a lead from signup page interest form (no auth required)"""
    # Validate required fields
    if not request.name or not request.email or not request.phone:
        raise HTTPException(status_code=400, detail="Name, email and phone are required")
    
    # Check if lead already exists with same email
    existing_lead = await db.leads.find_one({
        "client_email": request.email.lower(),
        "source": "signup_page"
    })
    
    if existing_lead:
        # Update existing lead
        await db.leads.update_one(
            {"id": existing_lead['id']},
            {"$set": {
                "client_name": request.name.strip(),
                "client_mobile": request.phone.strip(),
                "updated_at": datetime.now(timezone.utc).isoformat()
            }}
        )
        return {"message": "Interest updated successfully", "lead_id": existing_lead['id']}
    
    # Create new lead record for signup interest
    lead = {
        "id": str(uuid.uuid4()),
        "client_id": None,  # Not yet a client
        "client_name": request.name.strip(),
        "client_pan": "",
        "client_mobile": request.phone.strip(),
        "client_email": request.email.strip().lower(),
        "client_city": "",
        "opportunity_type": "general",  # General interest, not tied to specific opportunity
        "opportunity_id": None,
        "product_name": "General Interest",
        "product_code": "",
        "investment_amount": None,
        "interest_percentage": None,
        "notes": f"Interested via {request.source}",
        "status": "open",
        "source": request.source,
        "shared_by_id": None,
        "shared_by_name": None,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "updated_at": datetime.now(timezone.utc).isoformat()
    }
    
    await db.leads.insert_one(lead)
    
    # Create notification for broker
    broker = await db.users.find_one({"role": "broker"}, {"_id": 0, "id": 1})
    if broker:
        notification = {
            "id": str(uuid.uuid4()),
            "user_id": broker['id'],
            "type": "new_lead",
            "title": "New Signup Interest!",
            "message": f"{request.name} registered interest via website. Email: {request.email}, Phone: {request.phone}",
            "lead_id": lead['id'],
            "read": False,
            "created_at": datetime.now(timezone.utc).isoformat()
        }
        await db.notifications.insert_one(notification)
    
    return {"message": "Interest recorded successfully", "lead_id": lead['id']}


@api_router.post("/leads")
async def create_lead(request: CreateLeadRequest, current_user: dict = Depends(get_current_user)):
    """Create a new lead when a client expresses interest (Heart button flow).

    Restricted to clients — same rule as the RE-specific /interest endpoint.
    Sub-brokers / brokers are not end-investors and must not generate leads.
    Dedupes per (client_id, opportunity_type, opportunity_id, status='open') so
    repeated taps refresh the existing lead instead of spamming new ones.
    """
    if current_user['role'] != 'client':
        raise HTTPException(
            status_code=403,
            detail="Only clients can express interest."
        )
    
    # Get opportunity details
    if request.opportunity_type == 'bond':
        opportunity = await db.Ncd_Master.find_one({"id": request.opportunity_id}, {"_id": 0})
        if not opportunity:
            raise HTTPException(status_code=404, detail="Bond not found")
        product_name = opportunity.get('name', 'Unknown Bond')
        product_code = opportunity.get('bond_code', '')
    else:
        opportunity = await db.Real_Estate_Master.find_one({"id": request.opportunity_id}, {"_id": 0})
        if not opportunity:
            raise HTTPException(status_code=404, detail="Real estate opportunity not found")
        product_name = f"{opportunity.get('building_name', 'Unknown')} - Unit {opportunity.get('unit_no', '')}"
        product_code = opportunity.get('id', '')[:8]
    
    # Get client details
    client = None
    client_sub_broker_id = None
    if current_user['role'] == 'client':
        client = await db.Private_Investor.find_one({"id": current_user.get('client_id')}, {"_id": 0})
        if client:
            # Get the sub-broker who manages this client (if any)
            client_sub_broker_id = client.get('sub_broker_id') or client.get('created_by_sub_broker')
    
    # Find the sub-broker/broker who shared this with the client (applies to
    # both bond and real_estate opportunities that track explicit shares).
    shared_by_id = None
    shared_by_name = None
    
    shares = opportunity.get('shares', []) or []
    for share in shares:
        if share.get('client_id') == current_user.get('client_id', current_user['id']):
            shared_by_id = share.get('shared_by')
            sharer = await db.users.find_one({"id": shared_by_id}, {"_id": 0, "name": 1}) if shared_by_id else None
            if sharer:
                shared_by_name = sharer.get('name')
            break
    
    # Fallback: use the client's assigned sub-broker
    if not shared_by_id and client_sub_broker_id:
        shared_by_id = client_sub_broker_id
        sharer = await db.users.find_one({"id": shared_by_id}, {"_id": 0, "name": 1})
        if sharer:
            shared_by_name = sharer.get('name')
    
    # De-dupe: if there's already an OPEN lead from this client on this
    # opportunity, just refresh it (updated_at + latest amount/notes) instead
    # of creating another row on repeat taps.
    client_id_for_lead = current_user.get('client_id', current_user['id'])
    existing_lead = await db.leads.find_one({
        "client_id": client_id_for_lead,
        "opportunity_type": request.opportunity_type,
        "opportunity_id": request.opportunity_id,
        "status": "open",
    }, {"_id": 0, "id": 1})
    
    if existing_lead:
        await db.leads.update_one(
            {"id": existing_lead['id']},
            {"$set": {
                "investment_amount": request.investment_amount,
                "interest_percentage": request.interest_percentage,
                "notes": request.notes,
                "updated_at": datetime.now(timezone.utc).isoformat(),
            }}
        )
        return {"message": "Interest updated on existing open lead", "lead_id": existing_lead['id']}
    
    # Create lead record
    lead = {
        "id": str(uuid.uuid4()),
        "client_id": client_id_for_lead,
        "client_name": client.get('name') if client else current_user.get('name', 'Unknown'),
        "client_pan": client.get('pan_number') if client else current_user.get('pan_number', ''),
        "client_mobile": client.get('mobile') if client else '',
        "client_email": client.get('email') if client else '',
        "client_city": client.get('city') if client else '',
        "opportunity_type": request.opportunity_type,
        "opportunity_id": request.opportunity_id,
        "product_name": product_name,
        "product_code": product_code,
        "investment_amount": request.investment_amount,
        "interest_percentage": request.interest_percentage,
        "notes": request.notes,
        "status": "open",
        "shared_by_id": shared_by_id,
        "shared_by_name": shared_by_name,
        "sub_broker_id": client_sub_broker_id,  # Also store the client's sub-broker for easy querying
        "source": "heart_button",
        "created_at": datetime.now(timezone.utc).isoformat(),
        "updated_at": datetime.now(timezone.utc).isoformat()
    }
    
    await db.leads.insert_one(lead)
    
    # Update interested_count on the opportunity
    if request.opportunity_type == 'bond':
        await db.Ncd_Master.update_one(
            {"id": request.opportunity_id},
            {"$inc": {"interested_count": 1}}
        )
    else:
        await db.Real_Estate_Master.update_one(
            {"id": request.opportunity_id},
            {"$inc": {"interested_count": 1}}
        )
    
    # Create notification for broker/sub-broker
    broker = await db.users.find_one({"role": "broker"}, {"_id": 0, "id": 1})
    if broker:
        notification = {
            "id": str(uuid.uuid4()),
            "user_id": shared_by_id or broker['id'],
            "type": "new_lead",
            "title": "New Lead Created!",
            "message": f"{lead['client_name']} expressed interest in {product_name}" + 
                       (f" - ₹{request.investment_amount:,.0f}" if request.investment_amount else "") +
                       (f" - {request.interest_percentage}%" if request.interest_percentage else ""),
            "lead_id": lead['id'],
            "read": False,
            "created_at": datetime.now(timezone.utc).isoformat()
        }
        await db.notifications.insert_one(notification)
    
    return {"message": "Interest recorded successfully", "lead_id": lead['id']}


@api_router.get("/leads")
async def get_leads(
    status: Optional[str] = None,
    opportunity_type: Optional[str] = None,
    current_user: dict = Depends(get_current_user)
):
    """Get all leads - for brokers/mfd-ria/admin"""
    if current_user['role'] == 'client':
        raise HTTPException(status_code=403, detail="Clients cannot access leads")
    
    query = {}
    
    # Sub-brokers see leads from:
    # 1. Opportunities they shared (shared_by_id matches)
    # 2. Their managed clients (sub_broker_id matches)
    if current_user['role'] == 'sub_broker':
        query["$or"] = [
            {"shared_by_id": current_user['id']},
            {"sub_broker_id": current_user['id']}
        ]
    
    if status:
        if current_user['role'] == 'sub_broker':
            # Combine with existing $or query
            query = {"$and": [query, {"status": status}]}
        else:
            query["status"] = status
    if opportunity_type:
        if current_user['role'] == 'sub_broker' and "$and" in query:
            query["$and"].append({"opportunity_type": opportunity_type})
        elif current_user['role'] == 'sub_broker':
            query = {"$and": [query, {"opportunity_type": opportunity_type}]}
        else:
            query["opportunity_type"] = opportunity_type
    
    leads = await db.leads.find(query, {"_id": 0}).sort("created_at", -1).to_list(1000)
    
    # Enrich leads with client contact details if missing
    enriched_leads = []
    for lead in leads:
        # If client_email or client_mobile is empty, fetch from clients collection
        if not lead.get('client_email') or not lead.get('client_mobile'):
            client_id = lead.get('client_id')
            if client_id:
                client = await db.Private_Investor.find_one(
                    {"$or": [{"id": client_id}, {"user_id": client_id}]},
                    {"_id": 0, "email": 1, "mobile": 1, "phone": 1}
                )
                if client:
                    if not lead.get('client_email'):
                        lead['client_email'] = client.get('email', '')
                    if not lead.get('client_mobile'):
                        lead['client_mobile'] = client.get('mobile') or client.get('phone', '')
        enriched_leads.append(lead)
    
    return enriched_leads


@api_router.put("/leads/{lead_id}/status")
async def update_lead_status(
    lead_id: str,
    request: UpdateLeadStatusRequest,
    current_user: dict = Depends(get_current_user)
):
    """Update lead status"""
    if current_user['role'] == 'client':
        raise HTTPException(status_code=403, detail="Clients cannot update leads")
    
    valid_statuses = ['open', 'contacted', 'converted', 'not_interested', 'closed']
    if request.status not in valid_statuses:
        raise HTTPException(status_code=400, detail=f"Invalid status. Must be one of: {valid_statuses}")
    
    lead = await db.leads.find_one({"id": lead_id}, {"_id": 0})
    if not lead:
        raise HTTPException(status_code=404, detail="Lead not found")
    
    # Sub-brokers can update leads they shared OR leads from their managed clients
    if current_user['role'] == 'sub_broker':
        is_shared_by_them = lead.get('shared_by_id') == current_user['id']
        is_their_client = lead.get('sub_broker_id') == current_user['id']
        if not (is_shared_by_them or is_their_client):
            raise HTTPException(status_code=403, detail="You can only update leads from your clients or opportunities you shared")
    
    update_data = {
        "status": request.status,
        "updated_at": datetime.now(timezone.utc).isoformat(),
        "updated_by": current_user['id']
    }
    
    # Add reason if provided (for not_interested status)
    if hasattr(request, 'reason') and request.reason:
        update_data["not_interested_reason"] = request.reason
    
    await db.leads.update_one(
        {"id": lead_id},
        {"$set": update_data}
    )
    
    return {"message": "Lead status updated successfully"}


@api_router.get("/leads/{lead_id}")
async def get_lead(lead_id: str, current_user: dict = Depends(get_current_user)):
    """Get a single lead by ID"""
    if current_user['role'] == 'client':
        raise HTTPException(status_code=403, detail="Clients cannot access leads")
    
    lead = await db.leads.find_one({"id": lead_id}, {"_id": 0})
    if not lead:
        raise HTTPException(status_code=404, detail="Lead not found")
    
    return lead


