# CRM Lead stages in order
CRM_STAGES = ['leads', 'introduction', 'data_gathering', 'account_opened']


def generate_lead_code():
    """Generate a unique lead code like KBS20325066"""
    prefix = "KBS"
    year = datetime.now().strftime("%y")
    random_num = ''.join(random.choices(string.digits, k=6))
    return f"{prefix}{year}{random_num}"


@api_router.post("/crm/leads")
async def create_crm_lead(request: CRMLeadCreate, current_user: dict = Depends(get_current_user)):
    """Create a new CRM lead/prospect"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers and sub-brokers can create leads")
    
    # Generate unique lead code
    lead_code = generate_lead_code()
    
    # Determine advisor
    advisor_id = request.advisor_id or current_user['id']
    advisor = await db.users.find_one({"id": advisor_id}, {"_id": 0, "name": 1})
    advisor_name = advisor.get('name', 'Unknown') if advisor else 'Unknown'
    
    crm_lead = {
        "id": str(uuid.uuid4()),
        "lead_code": lead_code,
        "first_name": request.first_name.strip(),
        "last_name": request.last_name.strip(),
        "full_name": f"{request.first_name.strip()} {request.last_name.strip()}",
        "gender": request.gender,
        "mobile_number": request.mobile_number.strip(),
        "email_id": request.email_id.strip().lower(),
        "passport_type": request.passport_type,
        "opportunities_interested": request.opportunities_interested,
        "country": request.country,
        "address_line_1": request.address_line_1.strip(),
        "address_line_2": request.address_line_2.strip(),
        "pincode": request.pincode.strip(),
        "city": request.city.strip(),
        "state": request.state,
        "advisor_id": advisor_id,
        "advisor_name": advisor_name,
        "stage": "leads",  # Initial stage
        "notes": request.notes,
        "tax_info": "",
        "created_by": current_user['id'],
        "created_by_name": current_user.get('name', ''),
        "created_at": datetime.now(timezone.utc).isoformat(),
        "updated_at": datetime.now(timezone.utc).isoformat(),
        "stage_history": [{
            "stage": "leads",
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "updated_by": current_user['id'],
            "updated_by_name": current_user.get('name', ''),
            "notes": "Lead created"
        }]
    }
    
    await db.crm_leads.insert_one(crm_lead)
    
    # Remove _id before returning
    crm_lead.pop('_id', None)
    return crm_lead


@api_router.get("/crm/leads")
async def get_crm_leads(
    stage: Optional[str] = None,
    advisor_id: Optional[str] = None,
    search: Optional[str] = None,
    date_filter: Optional[str] = "all",  # all, this_month, last_month, this_year
    current_user: dict = Depends(get_current_user)
):
    """Get CRM leads with optional filters"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers and sub-brokers can view leads")
    
    query = {}
    
    # Sub-brokers only see their own leads or leads assigned to them
    if current_user['role'] == 'sub_broker':
        query["$or"] = [
            {"created_by": current_user['id']},
            {"advisor_id": current_user['id']}
        ]
    
    # Stage filter
    if stage and stage != "all":
        if current_user['role'] == 'sub_broker':
            query = {"$and": [query, {"stage": stage}]}
        else:
            query["stage"] = stage
    
    # Advisor filter (broker only)
    if advisor_id and current_user['role'] == 'broker':
        if "$and" in query:
            query["$and"].append({"advisor_id": advisor_id})
        else:
            query["advisor_id"] = advisor_id
    
    # Date filter
    now = datetime.now(timezone.utc)
    if date_filter == "this_month":
        start_of_month = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        date_query = {"created_at": {"$gte": start_of_month.isoformat()}}
        if "$and" in query:
            query["$and"].append(date_query)
        elif query:
            query = {"$and": [query, date_query]}
        else:
            query = date_query
    elif date_filter == "last_month":
        start_of_this_month = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        start_of_last_month = (start_of_this_month - timedelta(days=1)).replace(day=1)
        date_query = {
            "created_at": {
                "$gte": start_of_last_month.isoformat(),
                "$lt": start_of_this_month.isoformat()
            }
        }
        if "$and" in query:
            query["$and"].append(date_query)
        elif query:
            query = {"$and": [query, date_query]}
        else:
            query = date_query
    elif date_filter == "this_year":
        start_of_year = now.replace(month=1, day=1, hour=0, minute=0, second=0, microsecond=0)
        date_query = {"created_at": {"$gte": start_of_year.isoformat()}}
        if "$and" in query:
            query["$and"].append(date_query)
        elif query:
            query = {"$and": [query, date_query]}
        else:
            query = date_query
    
    leads = await db.crm_leads.find(query, {"_id": 0}).sort("created_at", -1).to_list(1000)
    
    # Apply search filter in memory (for name/email/phone)
    if search:
        search_lower = search.lower()
        leads = [
            lead for lead in leads 
            if search_lower in lead.get('full_name', '').lower()
            or search_lower in lead.get('email_id', '').lower()
            or search_lower in lead.get('mobile_number', '')
            or search_lower in lead.get('lead_code', '').lower()
        ]
    
    return leads


@api_router.get("/crm/leads/{lead_id}")
async def get_crm_lead(lead_id: str, current_user: dict = Depends(get_current_user)):
    """Get a single CRM lead by ID"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers and sub-brokers can view leads")
    
    lead = await db.crm_leads.find_one({"id": lead_id}, {"_id": 0})
    if not lead:
        raise HTTPException(status_code=404, detail="Lead not found")
    
    # Sub-brokers can only view their own leads
    if current_user['role'] == 'sub_broker':
        if lead.get('created_by') != current_user['id'] and lead.get('advisor_id') != current_user['id']:
            raise HTTPException(status_code=403, detail="Access denied")
    
    return lead


@api_router.put("/crm/leads/{lead_id}")
async def update_crm_lead(lead_id: str, request: CRMLeadUpdate, current_user: dict = Depends(get_current_user)):
    """Update CRM lead details"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers and sub-brokers can update leads")
    
    lead = await db.crm_leads.find_one({"id": lead_id}, {"_id": 0})
    if not lead:
        raise HTTPException(status_code=404, detail="Lead not found")
    
    # Sub-brokers can only update their own leads
    if current_user['role'] == 'sub_broker':
        if lead.get('created_by') != current_user['id'] and lead.get('advisor_id') != current_user['id']:
            raise HTTPException(status_code=403, detail="Access denied")
    
    # Build update dict from non-None values
    update_data = {}
    for field, value in request.model_dump().items():
        if value is not None:
            update_data[field] = value
    
    if update_data:
        # Update full_name if first or last name changed
        if 'first_name' in update_data or 'last_name' in update_data:
            first = update_data.get('first_name', lead.get('first_name', ''))
            last = update_data.get('last_name', lead.get('last_name', ''))
            update_data['full_name'] = f"{first} {last}"
        
        # Update advisor name if advisor_id changed
        if 'advisor_id' in update_data:
            advisor = await db.users.find_one({"id": update_data['advisor_id']}, {"_id": 0, "name": 1})
            update_data['advisor_name'] = advisor.get('name', 'Unknown') if advisor else 'Unknown'
        
        update_data['updated_at'] = datetime.now(timezone.utc).isoformat()
        
        await db.crm_leads.update_one({"id": lead_id}, {"$set": update_data})
    
    # Return updated lead
    updated_lead = await db.crm_leads.find_one({"id": lead_id}, {"_id": 0})
    return updated_lead


@api_router.put("/crm/leads/{lead_id}/stage")
async def update_crm_lead_stage(lead_id: str, request: CRMLeadStageUpdate, current_user: dict = Depends(get_current_user)):
    """Move CRM lead to a different stage"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers and sub-brokers can update lead stages")
    
    if request.stage not in CRM_STAGES:
        raise HTTPException(status_code=400, detail=f"Invalid stage. Must be one of: {CRM_STAGES}")
    
    lead = await db.crm_leads.find_one({"id": lead_id}, {"_id": 0})
    if not lead:
        raise HTTPException(status_code=404, detail="Lead not found")
    
    # Sub-brokers can only update their own leads
    if current_user['role'] == 'sub_broker':
        if lead.get('created_by') != current_user['id'] and lead.get('advisor_id') != current_user['id']:
            raise HTTPException(status_code=403, detail="Access denied")
    
    # Add to stage history
    stage_entry = {
        "stage": request.stage,
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "updated_by": current_user['id'],
        "updated_by_name": current_user.get('name', ''),
        "notes": request.notes or f"Moved to {request.stage.replace('_', ' ').title()}"
    }
    
    await db.crm_leads.update_one(
        {"id": lead_id},
        {
            "$set": {
                "stage": request.stage,
                "updated_at": datetime.now(timezone.utc).isoformat()
            },
            "$push": {"stage_history": stage_entry}
        }
    )
    
    # Return updated lead
    updated_lead = await db.crm_leads.find_one({"id": lead_id}, {"_id": 0})
    return updated_lead


class DeleteLeadRequest(BaseModel):
    """Request to delete a lead with reason"""
    reason: str


@api_router.delete("/crm/leads/{lead_id}")
async def delete_crm_lead(lead_id: str, request: DeleteLeadRequest, current_user: dict = Depends(get_current_user)):
    """Delete a CRM lead with reason logging"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers and sub-brokers can delete leads")
    
    if not request.reason or len(request.reason.strip()) < 3:
        raise HTTPException(status_code=400, detail="Please provide a valid reason for deletion")
    
    lead = await db.crm_leads.find_one({"id": lead_id}, {"_id": 0})
    if not lead:
        raise HTTPException(status_code=404, detail="Lead not found")
    
    # Sub-brokers can only delete their own leads
    if current_user['role'] == 'sub_broker':
        if lead.get('created_by') != current_user['id']:
            raise HTTPException(status_code=403, detail="Only the creator can delete this lead")
    
    # Log the deletion with reason
    deletion_log = {
        "id": str(uuid.uuid4()),
        "lead_id": lead_id,
        "lead_code": lead.get('lead_code'),
        "lead_name": lead.get('full_name'),
        "lead_email": lead.get('email_id'),
        "lead_phone": lead.get('mobile_number'),
        "reason": request.reason.strip(),
        "deleted_by": current_user['id'],
        "deleted_by_name": current_user.get('name', ''),
        "deleted_by_role": current_user['role'],
        "deleted_at": datetime.now(timezone.utc).isoformat(),
        "lead_data_snapshot": lead  # Keep full lead data for audit
    }
    await db.crm_lead_deletions.insert_one(deletion_log)
    
    # Delete the lead
    await db.crm_leads.delete_one({"id": lead_id})
    
    logger.info(f"Lead {lead.get('lead_code')} deleted by {current_user.get('name')} - Reason: {request.reason}")
    
    return {"message": "Lead deleted successfully", "deletion_id": deletion_log['id']}


@api_router.get("/crm/leads/stats/summary")
async def get_crm_leads_stats(current_user: dict = Depends(get_current_user)):
    """Get CRM leads statistics"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers and sub-brokers can view stats")
    
    query = {}
    if current_user['role'] == 'sub_broker':
        query["$or"] = [
            {"created_by": current_user['id']},
            {"advisor_id": current_user['id']}
        ]
    
    # Get counts by stage
    pipeline = [
        {"$match": query} if query else {"$match": {}},
        {"$group": {"_id": "$stage", "count": {"$sum": 1}}}
    ]
    
    stage_counts = await db.crm_leads.aggregate(pipeline).to_list(100)
    
    stats = {stage: 0 for stage in CRM_STAGES}
    for item in stage_counts:
        if item['_id'] in stats:
            stats[item['_id']] = item['count']
    
    stats['total'] = sum(stats.values())
    
    return stats


@api_router.get("/crm/advisors")
async def get_advisors(current_user: dict = Depends(get_current_user)):
    """Get list of advisors (sub-brokers) for lead assignment"""
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Access denied")
    
    # Get all sub-brokers and the broker
    advisors = []
    
    # Add broker
    broker = await db.users.find_one({"role": "broker"}, {"_id": 0, "id": 1, "name": 1})
    if broker:
        advisors.append({"id": broker['id'], "name": broker['name'], "role": "broker"})
    
    # Add sub-brokers
    sub_brokers = await db.users.find({"role": "sub_broker"}, {"_id": 0, "id": 1, "name": 1}).to_list(1000)
    for sb in sub_brokers:
        advisors.append({"id": sb['id'], "name": sb['name'], "role": "sub_broker"})
    
    return advisors


