async def scheduled_email_processing_job():
    """Background job to process emails automatically and auto-tag prepayments"""
    try:
        logger.info("=" * 50)
        logger.info("SCHEDULED EMAIL PROCESSING STARTED")
        logger.info(f"Time: {datetime.now(timezone.utc).isoformat()}")
        logger.info("=" * 50)
        
        # Step 1: Process emails from last 2 days to catch any missed ones
        result = await process_repayment_emails(db, days_back=2)
        
        # Log email processing result
        email_log_entry = {
            "id": str(uuid.uuid4()),
            "type": "scheduled_email_read",
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "result": result,
            "status": "success" if result.get('status') == 'success' else "error"
        }
        await db.email_scheduler_logs.insert_one(email_log_entry)
        
        logger.info(f"Email processing completed: {result}")
        
        # Step 2: AUTO-TAG prepayments immediately after reading emails
        # This eliminates the need for manual auto-tag button clicks
        logger.info("-" * 30)
        logger.info("AUTO-TAGGING PREPAYMENTS...")
        
        auto_tag_result = await _auto_tag_pending_emails()
        
        # Log auto-tag result
        auto_tag_log_entry = {
            "id": str(uuid.uuid4()),
            "type": "scheduled_auto_tag",
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "result": auto_tag_result,
            "status": "success" if auto_tag_result.get('success') else "error"
        }
        await db.email_scheduler_logs.insert_one(auto_tag_log_entry)
        
        logger.info(f"Auto-tag completed: {auto_tag_result}")
        logger.info("=" * 50)
    except Exception as e:
        logger.error(f"Scheduled email processing failed: {e}")
        # Log the error
        error_log = {
            "id": str(uuid.uuid4()),
            "type": "scheduled_processing",
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "error": str(e),
            "status": "error"
        }
        try:
            await db.email_scheduler_logs.insert_one(error_log)
        except:
            pass


async def _auto_tag_pending_emails():
    """
    Internal function to auto-tag pending email repayments.
    Called automatically after email processing.
    
    LOGIC:
    1. Get pending email logs (not yet tagged)
    2. Deduplicate by (client_name, gross_amount, repayment_date)
    3. For each unique repayment, divide amount by trade units
    4. If result is an INTEGER → Match found, create actual_repayment
    5. Recalculate maturity cashflows
    """
    try:
        # Get all pending email logs (not yet tagged)
        pending_logs = await db.email_read_logs.find(
            {"holding_updated": {"$ne": True}},
            {"_id": 0}
        ).to_list(1000)
        
        if not pending_logs:
            return {"success": True, "message": "No pending emails to tag", "tagged_count": 0, "auto": True}
        
        tagged_count = 0
        skipped_count = 0
        duplicate_count = 0
        
        # Deduplicate emails by (bond_code, client_name, gross_amount, repayment_date)
        unique_repayments = {}
        for log in pending_logs:
            key = (
                log.get('bond_code', ''),
                log.get('client_name', ''),
                log.get('gross_amount', 0),
                log.get('repayment_date', '')
            )
            if key not in unique_repayments:
                unique_repayments[key] = log
            else:
                duplicate_count += 1
                # Mark duplicate as processed
                await db.email_read_logs.update_one(
                    {"id": log.get('id')},
                    {
                        "$set": {
                            "holding_updated": True,
                            "holding_updated_at": datetime.now(timezone.utc).isoformat(),
                            "is_duplicate": True,
                            "duplicate_of": unique_repayments[key].get('id')
                        }
                    }
                )
        
        # Group by bond_code
        deal_logs = {}
        for key, log in unique_repayments.items():
            bond_code = key[0]
            if bond_code not in deal_logs:
                deal_logs[bond_code] = []
            deal_logs[bond_code].append(log)
        
        for bond_code, logs in deal_logs.items():
            if not bond_code:
                continue
            
            # Get all trades for this bond
            all_bond_trades = await db.Ncd_Investment_Details.find(
                {"bond_code": bond_code, "status": {"$ne": "cancelled"}},
                {"_id": 0}
            ).to_list(1000)
            
            if not all_bond_trades:
                continue
            
            for log in logs:
                log_id = log.get('id')
                log_gross_amount = log.get('gross_amount', 0)
                log_repayment_date = log.get('repayment_date', '')
                log_client_name = log.get('client_name', '')
                log_net_amount = log.get('net_amount', log_gross_amount)
                log_tds = log.get('tds_amount', 0)
                log_principal = log.get('principal', 0)  # Principal from email
                log_interest = log.get('interest', 0)    # Interest from email
                
                if not log_gross_amount or not log_repayment_date:
                    continue
                
                # Idempotency check: already processed?
                existing_by_email = await db.actual_repayments.find_one({"email_log_id": log_id})
                if existing_by_email:
                    skipped_count += 1
                    continue
                
                # Filter trades to match the client name from the email
                # Use fuzzy matching to handle name variations
                trades = []
                log_client_lower = log_client_name.lower().strip() if log_client_name else ''
                
                for trade in all_bond_trades:
                    trade_client_name = trade.get('client_name', '').lower().strip()
                    # Match if names are similar (contains or exact match)
                    if (log_client_lower and trade_client_name and 
                        (log_client_lower in trade_client_name or 
                         trade_client_name in log_client_lower or
                         log_client_lower.split()[0] == trade_client_name.split()[0])):  # First name match
                        trades.append(trade)
                
                # If no client-specific match, fall back to all trades for the bond
                # This handles cases where client name might be completely different in email
                if not trades:
                    trades = all_bond_trades
                
                # Find matching trade(s) by units division
                # Strategy 1: Try to match single trade first
                matched_trade = None
                per_unit_amount = None
                
                for trade in trades:
                    units = trade.get('units', 0)
                    if units <= 0:
                        continue
                    
                    result = log_gross_amount / units
                    if abs(result - round(result)) < 0.01:
                        matched_trade = trade
                        per_unit_amount = round(result)
                        break
                
                # Strategy 2: If no single trade match, check if amount divides by TOTAL units
                # This handles cases where a combined prepayment comes for multiple trades
                matched_trades = []
                if not matched_trade:
                    total_units = sum(t.get('units', 0) for t in trades if t.get('units', 0) > 0)
                    if total_units > 0:
                        per_unit_result = log_gross_amount / total_units
                        if abs(per_unit_result - round(per_unit_result)) < 0.01:
                            per_unit_amount = round(per_unit_result)
                            # Distribute proportionally to all trades
                            for trade in trades:
                                units = trade.get('units', 0)
                                if units > 0:
                                    trade_share = per_unit_amount * units
                                    matched_trades.append({
                                        "trade": trade,
                                        "gross_amount": trade_share,
                                        "per_unit_amount": per_unit_amount
                                    })
                
                # If single trade matched, convert to list format
                if matched_trade and not matched_trades:
                    matched_trades = [{
                        "trade": matched_trade,
                        "gross_amount": log_gross_amount,
                        "per_unit_amount": per_unit_amount
                    }]
                
                if not matched_trades:
                    continue
                
                # Process all matched trades (could be 1 or multiple)
                created_repayment_ids = []
                for match_info in matched_trades:
                    trade = match_info["trade"]
                    trade_gross_amount = match_info["gross_amount"]
                    trade_per_unit = match_info["per_unit_amount"]
                    
                    investment_date = trade.get('investment_date') or trade.get('created_at', '')
                    investment_date_str = str(investment_date)[:10] if investment_date else ''
                    
                    # Calculate proportional net and TDS for this trade's share
                    if log_gross_amount > 0:
                        proportion = trade_gross_amount / log_gross_amount
                        trade_net_amount = round(log_net_amount * proportion, 2)
                        trade_tds = round(log_tds * proportion, 2)
                    else:
                        trade_net_amount = trade_gross_amount
                        trade_tds = 0
                    
                    # Calculate principal/interest bifurcation
                    # Priority: 1. Use values from email if available
                    #           2. Calculate from expected cashflow ratios
                    #           3. Assume all principal (prepayment)
                    trade_principal = 0
                    trade_interest = 0
                    
                    # Check if email has principal/interest breakdown
                    if log_principal > 0 or log_interest > 0:
                        # Email has bifurcation - distribute proportionally to this trade's share
                        if log_gross_amount > 0:
                            proportion = trade_gross_amount / log_gross_amount
                            trade_principal = round(log_principal * proportion, 2)
                            trade_interest = round(log_interest * proportion, 2)
                        else:
                            trade_principal = log_principal
                            trade_interest = log_interest
                    else:
                        # No bifurcation in email - try to calculate from expected cashflow
                        expected_cf = await db.holding_cashflows.find_one({
                            "trade_id": trade.get('id'),
                            "date": log_repayment_date
                        })
                        
                        if expected_cf:
                            # Use the ratio from expected cashflow
                            expected_principal = expected_cf.get('principal_component', 0) or 0
                            expected_interest = expected_cf.get('interest_component', 0) or 0
                            expected_gross = expected_principal + expected_interest
                            
                            if expected_gross > 0:
                                trade_principal = trade_gross_amount * (expected_principal / expected_gross)
                                trade_interest = trade_gross_amount * (expected_interest / expected_gross)
                            else:
                                # Assume prepayment if no expected cashflow amount
                                trade_principal = trade_gross_amount
                                trade_interest = 0
                        else:
                            # No matching expected cashflow - assume prepayment (all principal)
                            trade_principal = trade_gross_amount
                            trade_interest = 0
                    
                    # Idempotency check: Use (client_name, trade_id, repayment_date, per_unit_amount) as unique combination
                    existing_by_combo = await db.actual_repayments.find_one({
                        "trade_id": trade.get('id'),
                        "repayment_date": log_repayment_date,
                        "per_unit_amount": trade_per_unit
                    })
                    if existing_by_combo:
                        continue
                    
                    # Create the actual_repayment record for this trade
                    repayment_id = str(uuid.uuid4())
                    repayment_record = {
                        "id": repayment_id,
                        "client_id": trade.get('client_id'),
                        "client_name": trade.get('client_name'),
                        "original_email_client": log_client_name,
                        "bond_id": trade.get('bond_id'),
                        "bond_name": trade.get('bond_name'),
                        "bond_code": bond_code,
                        "repayment_date": log_repayment_date,
                        "investment_date": investment_date_str,
                        "gross_amount": trade_gross_amount,
                        "principal": trade_principal,
                        "interest": trade_interest,
                        "net_amount": trade_net_amount,
                        "tds": trade_tds,
                        "units": trade.get('units'),
                        "per_unit_amount": trade_per_unit,
                        "payment_type": "prepayment",
                        "is_prepayment": True,
                        "email_log_id": log_id,
                        "trade_id": trade.get('id'),
                        "auto_tagged": True,
                        "match_method": "units_division_distributed" if len(matched_trades) > 1 else "units_division",
                        "created_by": "system_scheduler",
                        "created_at": datetime.now(timezone.utc).isoformat(),
                        "source": "auto_tag"
                    }
                    
                    await db.actual_repayments.insert_one(repayment_record)
                    created_repayment_ids.append(repayment_id)
                    tagged_count += 1
                
                # Mark as duplicate if no records were created (all were duplicates)
                if not created_repayment_ids:
                    duplicate_count += 1
                    await db.email_read_logs.update_one(
                        {"id": log_id},
                        {
                            "$set": {
                                "holding_updated": True,
                                "holding_updated_at": datetime.now(timezone.utc).isoformat(),
                                "is_duplicate_repayment": True
                            }
                        }
                    )
                    continue
                
                # Mark email log as processed with linked repayment IDs
                await db.email_read_logs.update_one(
                    {"id": log_id},
                    {
                        "$set": {
                            "holding_updated": True,
                            "holding_updated_at": datetime.now(timezone.utc).isoformat(),
                            "auto_tagged": True,
                            "actual_repayment_ids": created_repayment_ids,
                            "distributed_to_trades": len(matched_trades) > 1
                        }
                    }
                )
        
        return {
            "success": True,
            "tagged_count": tagged_count,
            "skipped_count": skipped_count,
            "duplicate_count": duplicate_count,
            "auto": True,
            "message": f"Auto-tagged {tagged_count} prepayments"
        }
    except Exception as e:
        logger.error(f"Auto-tag error: {e}")
        return {"success": False, "error": str(e), "auto": True}


# =====================================================
# DATA GATHERING APIs
# =====================================================

class FamilyMemberCreate(BaseModel):
    name: str
    date_of_birth: str
    relation: str  # "Primary", "Spouse", "Child", "Parent", etc.
    life_expectancy: int
    retirement_year: Optional[int] = None
    tax_regime: Optional[str] = "New Regime"  # "Old Regime", "New Regime", "NA"
    tax_status: Optional[str] = "Resident"  # "Resident", "NRI with Indian Passport", "NRI with Foreign Passport", "Foreign Passport"
    tax_slab: str

class FamilyCreate(BaseModel):
    # `broker_id` may be omitted by partners (sub_brokers) — the endpoint
    # derives it from the partner's `created_by` / parent broker in that case.
    broker_id: Optional[str] = None
    sub_broker_id: Optional[str] = None
    proceed_option: Optional[str] = "Data Gathering"  # "Data Gathering" or "Proceed to Account Opening"
    primary_holder: FamilyMemberCreate
    members: Optional[List[FamilyMemberCreate]] = []

class IncomeDetailCreate(BaseModel):
    family_id: str
    category: str  # salary, business, rental, etc.
    member_ids: List[str]  # Individual or multiple members
    details: dict  # Category-specific fields

class GoalDetailCreate(BaseModel):
    family_id: str
    member_ids: List[str]
    category: str
    goal_amount: float
    inflation_percent: float
    goal_year: Optional[int] = None  # For backward compatibility
    goal_years: Optional[List[str]] = None  # New: array of years
    is_family_goal: Optional[bool] = False

class ExpenseDetailCreate(BaseModel):
    family_id: str
    member_ids: List[str]
    expense_type: str
    monthly_amount: Optional[float] = None
    annual_amount: float
    upto_year: int
    inflation_percent: float
    consider_post_retirement: Optional[bool] = False
    post_retirement_member: Optional[str] = None
    post_retirement_percent: Optional[float] = 100

class InsurancePremiumCreate(BaseModel):
    family_id: str
    member_ids: List[str]
    category: str  # motor, life
    inflation_percent: float = 0
    # Step-up amount added to the yearly_premium each year (alternative to
    # inflation_percent). Used by health / critical_illness / personal_accident
    # premiums where insurers commonly use a flat annual step-up. Use ONE of
    # inflation_percent or step_up_amount — both non-zero is allowed but
    # discouraged.
    step_up_amount: Optional[float] = 0
    goal_year: int = 2050
    amount_today: float = 0
    yearly_premium: Optional[float] = None
    upto_year: Optional[int] = None
    coverage_amount: Optional[float] = None

class LiabilityCreate(BaseModel):
    family_id: str
    member_ids: List[str]
    category: str  # home_loan, vehicle_loan, etc.
    inflation_percent: float = 0
    goal_year: int = 2050
    amount_today: float = 0
    monthly_emi: Optional[float] = None
    num_installments: Optional[int] = None

class AssetDetailCreate(BaseModel):
    family_id: str
    member_ids: List[str]
    category: str  # real_estate, gold_jewellery, fixed_deposit, etc.
    details: dict  # Category-specific fields


@api_router.get("/data-gathering/families")
async def get_data_gathering_families(current_user: dict = Depends(get_current_user)):
    """Get all families for data gathering based on user role"""
    
    query = {}
    
    if current_user['role'] == 'broker':
        # Broker sees all families
        pass
    elif current_user['role'] == 'sub_broker':
        # Sub-broker sees only their families
        query["sub_broker_id"] = current_user['id']
    elif current_user['role'] == 'client':
        # Client sees only their own family
        query["client_user_id"] = current_user['id']
    else:
        raise HTTPException(status_code=403, detail="Access denied")
    
    families = await db.data_gathering_families.find(query, {"_id": 0}).to_list(1000)
    return {"families": families}


@api_router.get("/data-gathering/family/{family_id}")
async def get_family_details(family_id: str, current_user: dict = Depends(get_current_user)):
    """Get complete family details including all nested data"""
    
    family = await db.data_gathering_families.find_one({"id": family_id}, {"_id": 0})
    if not family:
        raise HTTPException(status_code=404, detail="Family not found")
    
    # Access control
    if current_user['role'] == 'sub_broker' and family.get('sub_broker_id') != current_user['id']:
        raise HTTPException(status_code=403, detail="Access denied")
    elif current_user['role'] == 'client' and family.get('client_user_id') != current_user['id']:
        raise HTTPException(status_code=403, detail="Access denied")
    
    return family


@api_router.post("/data-gathering/family")
async def create_family(request: FamilyCreate, current_user: dict = Depends(get_current_user)):
    """Create a new family for data gathering"""
    
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers and sub-brokers can create families")
    
    # Generate family name from primary holder
    base_family_name = f"{request.primary_holder.name} & Family"
    
    # Check for existing family with same name and add suffix if needed
    existing_count = await db.data_gathering_families.count_documents({
        "family_name": {"$regex": f"^{base_family_name}"}
    })
    
    family_name = base_family_name if existing_count == 0 else f"{base_family_name}{existing_count + 1}"
    
    # Create primary holder
    primary_member_id = str(uuid.uuid4())
    primary_member = {
        "id": primary_member_id,
        "name": request.primary_holder.name,
        "date_of_birth": request.primary_holder.date_of_birth,
        "relation": "Primary",
        "life_expectancy": request.primary_holder.life_expectancy,
        "retirement_year": request.primary_holder.retirement_year,
        "tax_regime": request.primary_holder.tax_regime,
        "tax_status": request.primary_holder.tax_status,
        "tax_slab": request.primary_holder.tax_slab,
        "is_primary": True
    }
    
    # Create other members
    other_members = []
    for member in request.members:
        other_members.append({
            "id": str(uuid.uuid4()),
            "name": member.name,
            "date_of_birth": member.date_of_birth,
            "relation": member.relation,
            "life_expectancy": member.life_expectancy,
            "retirement_year": member.retirement_year,
            "tax_regime": member.tax_regime,
            "tax_status": member.tax_status,
            "tax_slab": member.tax_slab,
            "is_primary": False
        })
    
    family_id = str(uuid.uuid4())
    
    # Resolve broker_id: prefer request value, else fall back to the partner's
    # parent broker (for sub_broker role) or the broker themselves.
    resolved_broker_id = request.broker_id
    if not resolved_broker_id:
        if current_user['role'] == 'broker':
            resolved_broker_id = current_user['id']
        elif current_user['role'] == 'sub_broker':
            resolved_broker_id = current_user.get('broker_id') or current_user.get('created_by')
    
    family_doc = {
        "id": family_id,
        "family_name": family_name,
        "broker_id": resolved_broker_id,
        "sub_broker_id": request.sub_broker_id or (current_user['id'] if current_user['role'] == 'sub_broker' else None),
        "proceed_option": request.proceed_option,
        "created_by": current_user['id'],
        "created_by_role": current_user['role'],
        "created_at": datetime.now(timezone.utc).isoformat(),
        "updated_at": datetime.now(timezone.utc).isoformat(),
        
        # Family members (nested)
        "members": [primary_member] + other_members,
        "primary_holder_id": primary_member_id,
        
        # Data sections (nested - initially empty)
        "income_details": [],
        "goal_details": [],
        "expense_details": [],
        "insurance_premiums": [],
        "liabilities": [],
        
        # Surplus calculations (computed)
        "surplus": {
            "savings": {},
            "investments": {}
        },
        
        # Status
        "status": "draft",  # draft, in_progress, completed
        "client_user_id": None  # Will be set when linked to a client user
    }
    
    await db.data_gathering_families.insert_one(family_doc)
    
    # Remove _id before returning
    family_doc.pop('_id', None)
    
    return {"message": "Family created successfully", "family": family_doc}


@api_router.put("/data-gathering/family/{family_id}")
async def update_family(family_id: str, request: FamilyCreate, current_user: dict = Depends(get_current_user)):
    """Update an existing family's details including members"""
    
    if current_user['role'] not in ['broker', 'sub_broker']:
        raise HTTPException(status_code=403, detail="Only brokers and sub-brokers can update families")
    
    family = await db.data_gathering_families.find_one({"id": family_id})
    if not family:
        raise HTTPException(status_code=404, detail="Family not found")
    
    # Access control
    if current_user['role'] == 'sub_broker' and family.get('sub_broker_id') != current_user['id']:
        raise HTTPException(status_code=403, detail="Access denied")
    
    # Generate new family name if primary holder name changed
    family_name = f"{request.primary_holder.name} & Family"
    
    # Find current primary member ID or create new one
    current_primary_id = family.get('primary_holder_id')
    primary_member_id = current_primary_id or str(uuid.uuid4())
    
    # Build primary member
    primary_member = {
        "id": primary_member_id,
        "name": request.primary_holder.name,
        "date_of_birth": request.primary_holder.date_of_birth,
        "relation": "Primary",
        "life_expectancy": request.primary_holder.life_expectancy,
        "retirement_year": request.primary_holder.retirement_year,
        "tax_regime": request.primary_holder.tax_regime,
        "tax_status": request.primary_holder.tax_status,
        "tax_slab": request.primary_holder.tax_slab,
        "is_primary": True
    }
    
    # Build other members (preserve existing IDs if possible, create new ones for new members)
    other_members = []
    existing_members = {m['id']: m for m in family.get('members', []) if not m.get('is_primary')}
    
    for member in request.members:
        # Try to match by name to preserve ID
        matching_id = None
        for mid, m in existing_members.items():
            if m.get('name') == member.name:
                matching_id = mid
                break
        
        other_members.append({
            "id": matching_id or str(uuid.uuid4()),
            "name": member.name,
            "date_of_birth": member.date_of_birth,
            "relation": member.relation,
            "life_expectancy": member.life_expectancy,
            "retirement_year": member.retirement_year,
            "tax_regime": member.tax_regime,
            "tax_status": member.tax_status,
            "tax_slab": member.tax_slab,
            "is_primary": False
        })
    
    # Update the family document
    update_data = {
        "family_name": family_name,
        "sub_broker_id": request.sub_broker_id,
        "proceed_option": request.proceed_option,
        "members": [primary_member] + other_members,
        "primary_holder_id": primary_member_id,
        "updated_at": datetime.now(timezone.utc).isoformat()
    }
    
    await db.data_gathering_families.update_one(
        {"id": family_id},
        {"$set": update_data}
    )
    
    updated_family = await db.data_gathering_families.find_one({"id": family_id}, {"_id": 0})
    return {"message": "Family updated successfully", "family": updated_family}


