@api_router.get("/re-brokers/stats")
async def get_re_broker_stats(current_user: dict = Depends(get_current_user)):
    """Get RE broker counts by stage"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Access denied")
    
    pipeline = [
        {"$group": {"_id": "$stage", "count": {"$sum": 1}}}
    ]
    stage_counts = await db.Real_Estate_Partner.aggregate(pipeline).to_list(100)
    
    stats = {stage: 0 for stage in RE_BROKER_STAGES}
    for item in stage_counts:
        if item['_id'] in stats:
            stats[item['_id']] = item['count']
    
    stats['total'] = sum(stats.values())
    return stats


