@api_router.post("/mfd-ria/admin/{sub_broker_id}/approve")
async def approve_sub_broker(sub_broker_id: str, current_user: dict = Depends(get_current_user)):
    """Approve a pending sub broker and create their account"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Access denied")
    
    pending = await db.pending_sub_brokers.find_one({"id": sub_broker_id})
    if not pending:
        raise HTTPException(status_code=404, detail="Pending sub broker not found")
    
    # Generate credentials
    password = ''.join(random.choices(string.ascii_letters + string.digits, k=10))
    password_hash = get_password_hash(password)
    pin = ''.join(random.choices(string.digits, k=4))
    pin_hash = get_password_hash(pin)
    
    # Create the sub broker in partners collection
    partner_data = {
        "id": str(uuid.uuid4()),
        "name": pending["name"],
        "email": pending["email"],
        "phone": pending.get("phone"),
        "pan": pending.get("pan"),
        "arn": pending.get("arn"),
        "euin": pending.get("euin"),
        "city": pending.get("city"),
        "state": pending.get("state"),
        "pincode": pending.get("pincode"),
        "address": pending.get("address"),
        "years_of_experience": pending.get("years_of_experience"),
        "current_aum": pending.get("current_aum"),
        "about": pending.get("about"),
        "password": password_hash,
        "pin": pin_hash,
        "broker_id": current_user["id"],
        "is_active": True,
        "source": "public_signup",
        "approved_at": datetime.now(timezone.utc).isoformat(),
        "approved_by": current_user.get("name", "Admin"),
        "created_at": pending.get("created_at"),
    }
    
    await db.Mfd_Ria_Partner.insert_one(partner_data)
    
    # Update pending status
    await db.pending_sub_brokers.update_one(
        {"id": sub_broker_id},
        {"$set": {"status": "approved", "approved_at": datetime.now(timezone.utc).isoformat()}}
    )
    
    # Send credentials email
    try:
        await send_credentials_email(
            pending["email"],
            pending["name"],
            pending["pan"],  # login ID is PAN
            password,
            pin
        )
        logger.info(f"Credentials sent to sub broker: {pending['email']}")
    except Exception as e:
        logger.error(f"Error sending credentials email: {e}")
        return {
            "message": "Sub broker approved but email failed. Please share credentials manually.",
            "credentials": {
                "login_id": pending["pan"],
                "password": password,
                "pin": pin
            }
        }
    
    return {"message": "Sub broker approved successfully. Credentials sent via email."}


