# ==================== PRIVATE INVESTOR SIGNUP ====================

class PrivateInvestorOTPRequest(BaseModel):
    email: str
    full_name: str

class PrivateInvestorRegister(BaseModel):
    full_name: str
    email: str
    mobile_number: str
    country_of_residency: str
    passport_type: str
    pan_number: Optional[str] = None
    passport_number: Optional[str] = None
    otp: str

@api_router.post("/private-investor/send-otp")
async def send_private_investor_otp(request: PrivateInvestorOTPRequest, background_tasks: BackgroundTasks):
    """Send OTP to email for private investor signup"""
    email_lower = request.email.lower().strip()
    
    # Check if email already exists in clients
    existing = await db.Private_Investor.find_one({"email": email_lower})
    if existing:
        raise HTTPException(status_code=400, detail="Email already registered. Please login.")
    
    # Check if already pending approval
    pending = await db.pending_private_investors.find_one({"email": email_lower})
    if pending:
        raise HTTPException(status_code=400, detail="An application with this email is already pending. Please wait for approval.")
    
    # Generate 6-digit OTP
    otp = ''.join(random.choices(string.digits, k=6))
    expires_at = datetime.now(timezone.utc) + timedelta(minutes=10)
    
    # Store OTP
    await db.private_investor_otps.update_one(
        {"email": email_lower},
        {"$set": {
            "email": email_lower,
            "otp": otp,
            "full_name": request.full_name,
            "expires_at": expires_at,
            "created_at": datetime.now(timezone.utc)
        }},
        upsert=True
    )
    
    # Send OTP email
    try:
        from email_service import send_otp_email
        background_tasks.add_task(send_otp_email, email_lower, request.full_name, otp)
    except Exception as e:
        logger.error(f"Error sending OTP email: {e}")
        # Log OTP for development
        logger.info(f"OTP for {email_lower}: {otp}")
    
    return {"message": "OTP sent successfully"}

@api_router.post("/private-investor/register")
async def register_private_investor(request: PrivateInvestorRegister):
    """Register a new private investor (public endpoint with OTP verification)"""
    email_lower = request.email.lower().strip()
    
    # Verify OTP
    otp_record = await db.private_investor_otps.find_one({"email": email_lower})
    if not otp_record:
        raise HTTPException(status_code=400, detail="OTP not found. Please request a new one.")
    
    if otp_record.get("otp") != request.otp:
        raise HTTPException(status_code=400, detail="Invalid OTP")
    
    # Handle both timezone-aware and timezone-naive datetime comparisons
    expires_at = otp_record.get("expires_at")
    if expires_at:
        # If expires_at is naive, make it aware (assume UTC)
        if expires_at.tzinfo is None:
            expires_at = expires_at.replace(tzinfo=timezone.utc)
        if datetime.now(timezone.utc) > expires_at:
            raise HTTPException(status_code=400, detail="OTP has expired. Please request a new one.")
    
    # Check if email already exists
    existing = await db.Private_Investor.find_one({"email": email_lower})
    if existing:
        raise HTTPException(status_code=400, detail="Email already registered")
    
    existing_pending = await db.pending_private_investors.find_one({"email": email_lower})
    if existing_pending:
        raise HTTPException(status_code=400, detail="An application with this email is already pending")
    
    # Create pending private investor record (Steps 1 & 2)
    investor_data = {
        "id": str(uuid.uuid4()),
        "full_name": request.full_name.strip(),
        "email": email_lower,
        "mobile_number": request.mobile_number.strip(),
        "country_of_residency": request.country_of_residency,
        "passport_type": request.passport_type,
        "pan_number": request.pan_number.upper().strip() if request.pan_number else None,
        "passport_number": request.passport_number.upper().strip() if request.passport_number else None,
        "onboarding_step": 2,
        "status": "pending_approval",
        "source": "public_signup",
        "created_at": datetime.now(timezone.utc).isoformat(),
    }
    
    await db.pending_private_investors.insert_one(investor_data)
    
    # Delete used OTP
    await db.private_investor_otps.delete_one({"email": email_lower})
    
    # Notify admin
    await db.notifications.insert_one({
        "id": str(uuid.uuid4()),
        "type": "private_investor_application",
        "title": "New Private Investor Application",
        "message": f"New private investor application from {request.full_name} ({request.country_of_residency})",
        "for_role": "broker",
        "read": False,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "data": {"investor_id": investor_data["id"]}
    })
    
    return {"message": "Registration successful", "investor_id": investor_data["id"]}

@api_router.get("/private-investors/pending-approval")
async def get_pending_private_investors(current_user: dict = Depends(get_current_user)):
    """Get all pending private investor applications (includes both self-signup and MFD/RIA created)"""
    logger.info(f"Getting pending investors, user role: {current_user.get('role')}")
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Access denied")
    
    # Get self-signup pending investors
    pending_self_signup = await db.pending_private_investors.find(
        {"status": "pending_approval"}, 
        {"_id": 0}
    ).sort("created_at", -1).to_list(1000)
    
    # Mark these as from self-signup
    for p in pending_self_signup:
        p['source'] = 'self_signup'
    
    # Get MFD/RIA created pending clients
    pending_subbroker = await db.Private_Investor.find(
        {"approval_status": "pending_approval", "created_by_subbroker": True}, 
        {"_id": 0}
    ).sort("created_at", -1).to_list(1000)
    
    # Get sub-broker names for each
    for p in pending_subbroker:
        p['source'] = 'mfd_ria'
        # Fetch sub-broker name
        if p.get('linked_subbroker_id'):
            partner = await db.Mfd_Ria_Partner.find_one({"id": p['linked_subbroker_id']}, {"_id": 0, "name": 1})
            p['created_by_name'] = partner.get('name') if partner else 'Unknown MFD/RIA'
    
    # Combine both lists
    all_pending = pending_self_signup + pending_subbroker
    
    # Sort by created_at descending
    all_pending.sort(key=lambda x: x.get('created_at', ''), reverse=True)
    
    logger.info(f"Found {len(all_pending)} total pending private investors ({len(pending_self_signup)} self-signup, {len(pending_subbroker)} from MFD/RIA)")
    return all_pending

@api_router.post("/private-investors/{investor_id}/approve")
async def approve_private_investor(investor_id: str, current_user: dict = Depends(get_current_user)):
    """Approve a pending private investor and create their client account"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Access denied")
    
    pending = await db.pending_private_investors.find_one({"id": investor_id})
    if not pending:
        raise HTTPException(status_code=404, detail="Pending investor not found")
    
    # Use PAN from registration (for Indian passport) or passport number (for foreign)
    pan_number = pending.get("pan_number") or pending.get("passport_number") or "TEMP" + ''.join(random.choices(string.ascii_uppercase + string.digits, k=6))
    
    # Check if PAN already exists in users collection (critical duplicate check)
    existing_user = await db.users.find_one({"pan": pan_number.upper()})
    if existing_user:
        raise HTTPException(
            status_code=400, 
            detail=f"Cannot approve: PAN '{pan_number}' is already registered to another user. Please verify the investor's PAN or contact support."
        )
    
    # Generate credentials
    password = ''.join(random.choices(string.ascii_letters + string.digits, k=10))
    password_hash = get_password_hash(password)
    pin = ''.join(random.choices(string.digits, k=4))
    pin_hash = get_password_hash(pin)
    
    # Create client record - Steps 1 & 2 completed during signup
    client_data = {
        "id": str(uuid.uuid4()),
        "name": pending["full_name"],
        "email": pending["email"],
        "mobile": pending["mobile_number"],
        "pan_number": pan_number,
        "password_hash": password_hash,
        "pin_hash": pin_hash,
        "country_of_residency": pending.get("country_of_residency"),
        "passport_type": pending.get("passport_type"),
        "passport_number": pending.get("passport_number"),
        "role": "client",
        "is_active": True,
        "broker_id": current_user['id'],
        "created_by": current_user['id'],
        "onboarding_step": 2,
        "onboarding_status": "active",
        "approval_status": "approved",
        "approved_at": datetime.now(timezone.utc).isoformat(),
        "approved_by": current_user['id'],
        "created_at": datetime.now(timezone.utc).isoformat(),
        "source": "public_signup"
    }
    
    await db.Private_Investor.insert_one(client_data)
    
    # Also create in users collection for login
    user_data = {
        "id": client_data["id"],
        "name": pending["full_name"],
        "email": pending["email"],
        "phone": pending["mobile_number"],
        "pan": pan_number.upper(),  # Login uses 'pan' field
        "pan_number": pan_number,   # Keep for backward compatibility
        "password_hash": password_hash,
        "pin_hash": pin_hash,
        "role": "client",
        "is_active": True,
        "broker_id": current_user['id'],
        "onboarding_status": "active",
        "created_at": datetime.now(timezone.utc).isoformat(),
    }
    await db.users.insert_one(user_data)
    
    # Update pending record status
    await db.pending_private_investors.update_one(
        {"id": investor_id},
        {"$set": {"status": "approved", "approved_at": datetime.now(timezone.utc).isoformat()}}
    )
    
    # Send credentials email to the approved investor
    try:
        from email_service import send_welcome_email_client
        broker_name = current_user.get('name', 'Kinntegraa Team')
        # Use environment variable for login URL, fallback to production
        frontend_url = os.environ.get('FRONTEND_URL', 'https://kinntegraa.club')
        login_url = f"{frontend_url}/login"
        send_welcome_email_client(
            client_name=pending['full_name'],
            client_email=pending['email'],
            pan=pan_number,
            password=password,
            pin=pin,
            broker_name=broker_name,
            login_url=login_url
        )
        logger.info(f"Credentials email sent to {pending['email']} with login URL: {login_url}")
    except Exception as e:
        logger.error(f"Failed to send credentials email to {pending['email']}: {e}")
    
    logger.info(f"Created account for {pending['full_name']}: PAN={pan_number}")
    
    return {"message": "Investor approved successfully", "client_id": client_data["id"]}

