@api_router.post("/private-investors/{investor_id}/approve-subbroker-client")
async def approve_subbroker_created_client(investor_id: str, current_user: dict = Depends(get_current_user)):
    """Approve a client created by a sub-broker (MFD/RIA)"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Access denied")
    
    # Find the pending client in clients collection
    client = await db.Private_Investor.find_one({"id": investor_id, "approval_status": "pending_approval", "created_by_subbroker": True})
    if not client:
        raise HTTPException(status_code=404, detail="Pending client not found")
    
    pan_number = client.get('pan') or client.get('pan_number')
    
    # Check if user already exists with this PAN (shouldn't happen but double check)
    existing_user = await db.users.find_one({"pan": pan_number})
    if existing_user:
        raise HTTPException(
            status_code=400, 
            detail=f"Cannot approve: A user with PAN '{pan_number}' already exists."
        )
    
    # Update client status to approved
    await db.Private_Investor.update_one(
        {"id": investor_id},
        {"$set": {
            "approval_status": "approved",
            "is_active": True,
            "approved_at": datetime.now(timezone.utc).isoformat(),
            "approved_by": current_user['id']
        }}
    )
    
    # Create user record for login
    user_data = {
        "id": client["id"],
        "name": client.get("name", ""),
        "email": client.get("email", ""),
        "phone": client.get("mobile") or client.get("phone", ""),
        "pan": pan_number,  # Login uses 'pan' field
        "pan_number": client.get("pan_number"),
        "password_hash": client.get("password_hash"),
        "pin_hash": client.get("pin_hash"),
        "role": "client",
        "is_active": True,
        "broker_id": client.get("broker_id") or current_user['id'],
        "linked_subbroker_id": client.get("linked_subbroker_id"),
        "onboarding_status": "active",
        "created_at": client.get("created_at", datetime.now(timezone.utc).isoformat()),
    }
    await db.users.insert_one(user_data)
    
    # Send credentials email (using stored default_password and default_pin)
    try:
        from email_service import send_welcome_email_client
        broker_name = current_user.get('name', 'Kinntegraa Team')
        frontend_url = os.environ.get('FRONTEND_URL', 'https://kinntegraa.club')
        login_url = f"{frontend_url}/login"
        
        # Get stored credentials
        password = client.get("default_password")
        pin = client.get("default_pin")
        
        if password and pin:
            send_welcome_email_client(
                client_name=client.get('name', ''),
                client_email=client.get('email', ''),
                pan=pan_number,
                password=password,
                pin=pin,
                broker_name=broker_name,
                login_url=login_url
            )
            logger.info(f"Credentials email sent to {client['email']}")
    except Exception as e:
        logger.error(f"Failed to send credentials email: {e}")
    
    logger.info(f"Approved MFD/RIA created client: {client.get('name')} (PAN: {pan_number})")
    
    return {"message": "Client approved successfully", "client_id": investor_id}


