@api_router.post("/re-broker/agents/create")
async def create_re_broker_agent(
    agent: dict = Body(...),
    current_user: dict = Depends(get_current_user)
):
    """Create a new agent for RE broker with login credentials"""
    if current_user['role'] != 're_broker':
        raise HTTPException(status_code=403, detail="Access denied. RE Broker only.")
    
    re_broker_id = current_user.get('re_broker_id') or current_user.get('id')
    
    # BRN is the login ID
    brn = agent.get("brn", "").upper()
    if not brn:
        raise HTTPException(status_code=400, detail="BRN (Broker Registration Number) is required")
    
    # Check if user with same BRN already exists
    existing_user = await db.users.find_one({"pan": brn})
    if existing_user:
        raise HTTPException(status_code=400, detail="Agent with this BRN already exists")
    
    # Generate random password and PIN
    import random
    import string
    default_password = ''.join(random.choices(string.ascii_letters + string.digits, k=10))
    default_pin = ''.join(random.choices(string.digits, k=4))
    
    # Hash the password and PIN
    password_hash = get_password_hash(default_password)
    pin_hash = get_password_hash(default_pin)
    
    # Create agent in re_broker_agents collection
    agent_id = str(uuid.uuid4())
    agent_data = {
        "id": agent_id,
        "re_broker_id": re_broker_id,
        "name": agent.get("name"),
        "email": agent.get("email", "").lower(),
        "mobile": agent.get("mobile", ""),
        "brn": brn,
        "rera_id": agent.get("rera_id", "").upper(),
        "rera_expiry": agent.get("rera_expiry", ""),
        "agency_name": agent.get("agency_name", ""),
        "experience_years": agent.get("experience_years", ""),
        "specializations": agent.get("specializations", []),
        "areas_covered": agent.get("areas_covered", []),
        "languages": agent.get("languages", ""),
        "nationality": agent.get("nationality", ""),
        "visa_status": agent.get("visa_status", ""),
        "commission_split": agent.get("commission_split", ""),
        "address": agent.get("address", ""),
        "status": "active",
        "listings_count": 0,
        "conversions": 0,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "created_by": current_user['id']
    }
    
    await db.re_broker_agents.insert_one(agent_data)
    
    # Create user account for login
    user_data = {
        "id": str(uuid.uuid4()),
        "name": agent.get("name"),
        "email": agent.get("email", "").lower(),
        "pan": brn,  # BRN is used as login ID
        "password_hash": password_hash,
        "pin_hash": pin_hash,
        "role": "re_agent",
        "re_broker_agent_id": agent_id,
        "re_broker_id": re_broker_id,
        "specializations": agent.get("specializations", []),
        "areas_covered": agent.get("areas_covered", []),
        "status": "active",
        "is_active": True,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "created_by": current_user['id'],
        "created_by_role": "re_broker"
    }
    
    await db.users.insert_one(user_data)
    
    logger.info(f"RE Broker {re_broker_id} created agent: {agent.get('name')} with BRN: {brn}")
    
    return {
        "message": "Agent created successfully",
        "agent_id": agent_id,
        "default_password": default_password,
        "default_pin": default_pin
    }


