@api_router.get("/export/mfd-ria-partners")
async def export_mfd_ria_partners(
    current_user: dict = Depends(get_current_user)
):
    """Export MFD_RIA_PARTNER collection as Excel file"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can export partner data")
    
    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
        from io import BytesIO
        
        # Fetch all partners for this broker
        partners = await db.Mfd_Ria_Partner.find(
            {"created_by": current_user['id']},
            {"_id": 0}
        ).to_list(None)
        
        if not partners:
            raise HTTPException(status_code=404, detail="No partners found")
        
        # Create workbook
        wb = Workbook()
        ws = wb.active
        ws.title = "Mfd_Ria_Partner"
        
        # Define headers - CANONICAL sequence aligned with Add MFD/RIA form,
        # Bulk Upload template, and MFD_RIA_PARTNER DB field order
        headers = [
            "Name", "PAN", "Email", "Mobile", "Partner Code",
            "Partner Type", "ARN", "EUIN",
            "SEBI Registration", "Registration Type",
            "Years of Experience", "Current AUM",
            "Address", "City", "State", "Pincode", "Country", "About",
            # System / metadata (kept for operational export usefulness)
            "Status", "Is Active", "Initial Password", "Initial PIN",
            "Needs Password Reset", "Source", "Created At", "ID"
        ]
        
        # Header styling
        header_fill = PatternFill(start_color="92400E", end_color="92400E", fill_type="solid")
        header_font = Font(bold=True, color="FFFFFF")
        thin_border = Border(
            left=Side(style='thin'),
            right=Side(style='thin'),
            top=Side(style='thin'),
            bottom=Side(style='thin')
        )
        
        # Write headers
        for col, header in enumerate(headers, 1):
            cell = ws.cell(row=1, column=col, value=header)
            cell.fill = header_fill
            cell.font = header_font
            cell.alignment = Alignment(horizontal='center')
            cell.border = thin_border
        
        # Write data
        for row_idx, partner in enumerate(partners, 2):
            # Build a single-line address fallback from address_line1/2 if 'address' missing
            address_line1 = partner.get('address_line1', '') or ''
            address_line2 = partner.get('address_line2', '') or ''
            legacy_address = partner.get('address', '') or ''
            if legacy_address:
                address = legacy_address
            elif address_line1 or address_line2:
                address = (address_line1 + (", " + address_line2 if address_line2 else "")).strip(", ")
            else:
                address = ''
            
            # Canonical field order (matches headers above)
            data = [
                partner.get('name', ''),
                partner.get('pan', ''),
                partner.get('email', ''),
                partner.get('mobile', '') or partner.get('phone', ''),
                partner.get('partner_code', ''),
                partner.get('partner_type', ''),
                partner.get('arn', '') or partner.get('ARN', ''),
                partner.get('euin', '') or partner.get('EUIN', ''),
                partner.get('sebi_registration_number', ''),
                partner.get('registration_type', ''),
                partner.get('years_of_experience', ''),
                partner.get('current_aum', ''),
                address,
                partner.get('city', ''),
                partner.get('state', ''),
                partner.get('pincode', ''),
                partner.get('country', '') or 'India',
                partner.get('about', ''),
                # System / metadata
                partner.get('status', ''),
                'Yes' if partner.get('is_active') else 'No',
                partner.get('initial_password', ''),
                partner.get('initial_pin', ''),
                'Yes' if partner.get('needs_password_reset') else 'No',
                partner.get('source', ''),
                str(partner.get('created_at', ''))[:19] if partner.get('created_at') else '',
                partner.get('id', '')
            ]
            
            for col, value in enumerate(data, 1):
                cell = ws.cell(row=row_idx, column=col, value=value)
                cell.border = thin_border
        
        # Auto-adjust column widths
        for col in ws.columns:
            max_length = 0
            column = col[0].column_letter
            for cell in col:
                try:
                    if len(str(cell.value)) > max_length:
                        max_length = len(str(cell.value))
                except:
                    pass
            adjusted_width = min(max_length + 2, 50)
            ws.column_dimensions[column].width = adjusted_width
        
        # Save to buffer
        buffer = BytesIO()
        wb.save(buffer)
        buffer.seek(0)
        
        # Return as streaming response
        from fastapi.responses import StreamingResponse
        
        return StreamingResponse(
            buffer,
            media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            headers={
                "Content-Disposition": f"attachment; filename=MFD_RIA_PARTNER_Export_{datetime.now().strftime('%Y%m%d_%H%M%S')}.xlsx"
            }
        )
        
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error exporting MFD_RIA_PARTNER: {e}")
        raise HTTPException(status_code=500, detail=str(e))


# ============================================================
# PRIVATE INVESTOR EXPORTS (Indian / Foreign Passport)
# ============================================================

async def _export_private_investors(collection_name: str, filter_query: dict, sheet_title: str, file_prefix: str):
    """Generic helper to export a PRIVATE_INVESTOR_* collection to Excel."""
    from openpyxl import Workbook
    from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
    from io import BytesIO
    from fastapi.responses import StreamingResponse

    collection = db[collection_name]
    investors = await collection.find(filter_query, {"_id": 0}).to_list(None)

    # Note: if empty, we still return a valid (header-only) Excel file rather than 404
    # so the Downloads UI consistently produces a download.

    # Collect the union of all keys across documents (MongoDB docs are schema-less)
    all_keys: list = []
    seen = set()
    # Preferred column order — remaining keys are appended in insertion order
    preferred_order = [
        "id", "name", "photo_id", "pan_number", "passport_number",
        "email", "mobile", "country_of_residency", "passport_type",
        "emirates_id", "emirates_id_expiry",
        "opportunities",
        "bank_name", "account_number", "account_type", "branch",
        "ifsc_code", "demat_account_no",
        "intl_bank_name", "intl_account_number", "intl_iban", "intl_swift_code",
        "passport_valid_from", "passport_valid_until", "passport_country_of_issue",
        "occupation", "date_of_birth", "father_husband_name",
        "address_line1", "address_line2", "city", "state", "country", "pincode",
        "nominee_name", "nominee_dob", "nominee_mobile", "nominee_relationship",
        "linked_subbroker_id", "ucc_list",
        "created_by", "created_at", "status", "is_active", "source",
    ]
    for k in preferred_order:
        for inv in investors:
            if k in inv and k not in seen:
                all_keys.append(k)
                seen.add(k)
                break
    for inv in investors:
        for k in inv.keys():
            if k not in seen:
                all_keys.append(k)
                seen.add(k)

    # Fallback schema when the collection is empty — ensures a valid, header-only Excel
    if not all_keys:
        all_keys = list(preferred_order)

    wb = Workbook()
    ws = wb.active
    ws.title = sheet_title

    header_fill = PatternFill(start_color="7C3AED", end_color="7C3AED", fill_type="solid")
    header_font = Font(bold=True, color="FFFFFF")
    thin_border = Border(
        left=Side(style='thin'), right=Side(style='thin'),
        top=Side(style='thin'), bottom=Side(style='thin')
    )

    for col, key in enumerate(all_keys, 1):
        cell = ws.cell(row=1, column=col, value=key)
        cell.fill = header_fill
        cell.font = header_font
        cell.alignment = Alignment(horizontal='center', wrap_text=True)
        cell.border = thin_border

    for row_idx, inv in enumerate(investors, 2):
        for col, key in enumerate(all_keys, 1):
            value = inv.get(key, "")
            if isinstance(value, (list, dict)):
                value = str(value)
            cell = ws.cell(row=row_idx, column=col, value=value)
            cell.border = thin_border

    for col in ws.columns:
        max_length = 0
        column = col[0].column_letter
        for cell in col:
            try:
                if cell.value and len(str(cell.value)) > max_length:
                    max_length = len(str(cell.value))
            except Exception:
                pass
        ws.column_dimensions[column].width = min(max_length + 2, 50)

    buffer = BytesIO()
    wb.save(buffer)
    buffer.seek(0)

    timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
    return StreamingResponse(
        buffer,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f"attachment; filename={file_prefix}_{timestamp}.xlsx"}
    )


