@api_router.get("/export/real-estate")
async def export_real_estate_opportunities(current_user: dict = Depends(get_current_user)):
    """Export real_estate_opportunities in the same 5-sheet structure as the upload template.
    Each sheet stacks all opportunities with Building Name + Unit No as the join key."""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can export real estate data")
    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
        from openpyxl.utils import get_column_letter
        from io import BytesIO
        from fastapi.responses import StreamingResponse

        opps = await db.Real_Estate_Master.find(
            {}, {"_id": 0, "images": 0, "presentations": 0, "dld_admin_documents": 0, "investor_invoices": 0}
        ).to_list(None)

        wb = Workbook()
        thin = Border(
            left=Side(style='thin'), right=Side(style='thin'),
            top=Side(style='thin'), bottom=Side(style='thin')
        )

        def _style_header(cell, color_hex):
            cell.font = Font(bold=True, color="FFFFFF")
            cell.fill = PatternFill(start_color=color_hex, end_color=color_hex, fill_type="solid")
            cell.alignment = Alignment(horizontal="center", wrap_text=True)
            cell.border = thin

        # ────────── Sheet 1: Basic Information (Blue) ──────────
        ws1 = wb.active
        ws1.title = "Basic Information"
        headers1 = ["Building Name*", "Unit No*", "Property Type*", "Developer Name*", "Location",
                    "Description", "Handover Date", "View 3D URL"]
        for col, h in enumerate(headers1, 1):
            _style_header(ws1.cell(row=1, column=col, value=h), "1D4ED8")
            ws1.column_dimensions[get_column_letter(col)].width = 22
        _ptype_label = {"off_plan": "Off-Plan", "ready": "Ready", "secondary": "Secondary", "rental": "Rental"}
        for row_idx, o in enumerate(opps, 2):
            row = [
                o.get("building_name", ""),
                o.get("unit_no", ""),
                _ptype_label.get((o.get("property_type") or "off_plan").lower(), "Off-Plan"),
                o.get("developer_name", ""),
                o.get("location", ""),
                o.get("description", ""),
                str(o.get("handover_date", ""))[:10],
                o.get("view_3d_url", ""),
            ]
            for col, v in enumerate(row, 1):
                c = ws1.cell(row=row_idx, column=col, value=v)
                c.border = thin

        # ────────── Sheet 2: Pricing & Fees (Green) ──────────
        ws2 = wb.create_sheet("Pricing & Fees")
        headers2 = ["Building Name*", "Unit No*", "Unit Price (AED)*", "DLD Fee (%)*",
                    "Admin Fee (AED)*", "Broker Fee (AED)", "Other Fees (AED)",
                    "Unit Selling Fee (%)", "Developer Discount (AED)", "Developer Discount (%)"]
        for col, h in enumerate(headers2, 1):
            _style_header(ws2.cell(row=1, column=col, value=h), "059669")
            ws2.column_dimensions[get_column_letter(col)].width = 20
        for row_idx, o in enumerate(opps, 2):
            row = [
                o.get("building_name", ""),
                o.get("unit_no", ""),
                o.get("unit_price", 0),
                o.get("dld_fee_percentage", 4),
                o.get("admin_fee", 0),
                o.get("broker_fee") if o.get("broker_fee") is not None else o.get("brokerage_fee", 0),
                o.get("other_fees", 0),
                o.get("selling_fee_percentage") or o.get("unit_selling_fee_percentage", 0),
                o.get("developer_discount", 0),
                o.get("developer_discount_percentage", 0),
            ]
            for col, v in enumerate(row, 1):
                c = ws2.cell(row=row_idx, column=col, value=v)
                c.border = thin

        # ────────── Sheet 3: Unit Details (Purple) ──────────
        ws3 = wb.create_sheet("Unit Details")
        headers3 = ["Building Name*", "Unit No*", "Unit Type*", "Floor*",
                    "Total Area (sqft)*", "Carpet Area (sqft)", "Balcony Area (sqft)",
                    "Parking Spaces"]
        for col, h in enumerate(headers3, 1):
            _style_header(ws3.cell(row=1, column=col, value=h), "7C3AED")
            ws3.column_dimensions[get_column_letter(col)].width = 20
        for row_idx, o in enumerate(opps, 2):
            row = [
                o.get("building_name", ""),
                o.get("unit_no", ""),
                o.get("unit_type", ""),
                o.get("floor", ""),
                o.get("total_area", 0),
                o.get("carpet_area", 0),
                o.get("balcony_area", 0),
                o.get("parking_spaces", 0),
            ]
            for col, v in enumerate(row, 1):
                c = ws3.cell(row=row_idx, column=col, value=v)
                c.border = thin

        # ────────── Sheet 4: Sale Settings (Red) ──────────
        ws4 = wb.create_sheet("Sale Settings")
        headers4 = ["Building Name*", "Unit No*", "Expected Sale Rate (AED/sqft)",
                    "Estimated Sell Date", "Eligible to Sell After (%)"]
        for col, h in enumerate(headers4, 1):
            _style_header(ws4.cell(row=1, column=col, value=h), "DC2626")
            ws4.column_dimensions[get_column_letter(col)].width = 24
        for row_idx, o in enumerate(opps, 2):
            row = [
                o.get("building_name", ""),
                o.get("unit_no", ""),
                o.get("expected_sale_rate", 0),
                str(o.get("estimated_sell_date", ""))[:10],
                o.get("eligible_to_sell_after_percentage", 100),
            ]
            for col, v in enumerate(row, 1):
                c = ws4.cell(row=row_idx, column=col, value=v)
                c.border = thin

        # ────────── Sheet 5: Payment Schedule (Orange) — stacked ──────────
        ws5 = wb.create_sheet("Payment Schedule")
        headers5 = ["Building Name*", "Unit No*", "Payment Description*", "Due Date*", "Percentage*"]
        for col, h in enumerate(headers5, 1):
            _style_header(ws5.cell(row=1, column=col, value=h), "EA580C")
            ws5.column_dimensions[get_column_letter(col)].width = 22
        current_row = 2
        for o in opps:
            bn = o.get("building_name", "")
            un = o.get("unit_no", "")
            for p in (o.get("payment_schedule") or []):
                row = [
                    bn, un,
                    p.get("description", ""),
                    str(p.get("date", ""))[:10],
                    p.get("percentage", 0),
                ]
                for col, v in enumerate(row, 1):
                    c = ws5.cell(row=current_row, column=col, value=v)
                    c.border = thin
                current_row += 1

        buffer = BytesIO()
        wb.save(buffer)
        buffer.seek(0)

        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        return StreamingResponse(
            buffer,
            media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            headers={"Content-Disposition": f"attachment; filename=REAL_ESTATE_OPPORTUNITY_Export_{timestamp}.xlsx"}
        )
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error exporting real_estate_opportunities: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@api_router.get("/export/ncd-master")
async def export_ncd_master(current_user: dict = Depends(get_current_user)):
    """Export NCD_Master (bonds) in the same 4-sheet format as the bulk template.
    All bonds appear stacked in each sheet, with every cashflow row in Sheet 4."""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can export NCD master data")
    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
        from openpyxl.utils import get_column_letter
        from io import BytesIO
        from fastapi.responses import StreamingResponse

        bonds = await db.Ncd_Master.find({}, {"_id": 0}).to_list(None)

        wb = Workbook()
        thin = Border(
            left=Side(style='thin'), right=Side(style='thin'),
            top=Side(style='thin'), bottom=Side(style='thin')
        )

        def _style_header(cell, color_hex):
            cell.font = Font(bold=True, color="FFFFFF")
            cell.fill = PatternFill(start_color=color_hex, end_color=color_hex, fill_type="solid")
            cell.alignment = Alignment(horizontal="center", wrap_text=True)
            cell.border = thin

        # ────────── Sheet 1: Bond Details (Green) ──────────
        ws1 = wb.active
        ws1.title = "Bond Details"
        headers1 = ["Bond Code*", "Bond Name*", "ISIN", "Issuer/Company Name",
                    "Start Date*", "Maturity Date*", "Description"]
        for col, h in enumerate(headers1, 1):
            _style_header(ws1.cell(row=1, column=col, value=h), "059669")
            ws1.column_dimensions[get_column_letter(col)].width = 22
        for row_idx, b in enumerate(bonds, 2):
            row = [
                b.get("bond_code", ""),
                b.get("name", ""),
                b.get("isin", ""),
                b.get("issuer", ""),
                str(b.get("start_date", ""))[:10],
                str(b.get("end_date", ""))[:10],
                b.get("description", ""),
            ]
            for col, v in enumerate(row, 1):
                c = ws1.cell(row=row_idx, column=col, value=v)
                c.border = thin

        # ────────── Sheet 2: Financial Details (Purple) ──────────
        ws2 = wb.create_sheet("Financial Details")
        headers2 = ["Bond Code*", "Coupon Rate (%)", "Primary IRR (%)",
                    "Secondary IRR (%)", "Face Value per Unit"]
        for col, h in enumerate(headers2, 1):
            _style_header(ws2.cell(row=1, column=col, value=h), "7C3AED")
            ws2.column_dimensions[get_column_letter(col)].width = 22
        for row_idx, b in enumerate(bonds, 2):
            row = [
                b.get("bond_code", ""),
                b.get("coupon_rate", ""),
                b.get("primary_irr", ""),
                b.get("secondary_irr", ""),
                b.get("face_value", ""),
            ]
            for col, v in enumerate(row, 1):
                c = ws2.cell(row=row_idx, column=col, value=v)
                c.border = thin

        # ────────── Sheet 3: Units & Limits (Orange) ──────────
        ws3 = wb.create_sheet("Units & Limits")
        headers3 = ["Bond Code*", "Total Units*", "Minimum Units per Order"]
        for col, h in enumerate(headers3, 1):
            _style_header(ws3.cell(row=1, column=col, value=h), "EA580C")
            ws3.column_dimensions[get_column_letter(col)].width = 25
        for row_idx, b in enumerate(bonds, 2):
            row = [
                b.get("bond_code", ""),
                b.get("total_units", ""),
                b.get("minimum_units", b.get("min_units_per_order", 1)),
            ]
            for col, v in enumerate(row, 1):
                c = ws3.cell(row=row_idx, column=col, value=v)
                c.border = thin

        # ────────── Sheet 4: Cashflows Per Unit (Cyan) — every bond stacked ──────────
        ws4 = wb.create_sheet("Cashflows Per Unit")
        headers4 = ["Bond Code*", "Payment Date*", "Interest Per Unit*", "Principal Per Unit*"]
        for col, h in enumerate(headers4, 1):
            _style_header(ws4.cell(row=1, column=col, value=h), "0891B2")
            ws4.column_dimensions[get_column_letter(col)].width = 22
        current_row = 2
        for b in bonds:
            code = b.get("bond_code", "")
            for cf in (b.get("cashflows_per_unit") or []):
                row = [
                    code,
                    str(cf.get("date", ""))[:10],
                    cf.get("interest_per_unit", 0),
                    cf.get("principal_per_unit", 0),
                ]
                for col, v in enumerate(row, 1):
                    c = ws4.cell(row=current_row, column=col, value=v)
                    c.border = thin
                current_row += 1

        # ────────── Sheet 5: Investment Details (trades) — Pink ──────────
        # Headers match the Investment Details upload template, with additional columns appended.
        trades = await db.Ncd_Investment_Details.find({}, {"_id": 0}).to_list(None)
        ws5 = wb.create_sheet("Investment Details")
        headers5 = [
            # ---- Upload template columns (same names) ----
            "Deal ID*", "Date of Investment*", "PAN*", "No of Units*", "Amount*", "UTR",
            # ---- Additional columns retained for downloads ----
            "Bond Name", "Client Name", "Calculated Price", "Status",
            "Is Historical", "Created At",
        ]
        for col, h in enumerate(headers5, 1):
            _style_header(ws5.cell(row=1, column=col, value=h), "DB2777")
            ws5.column_dimensions[get_column_letter(col)].width = 20

        # Build a quick bond_id -> (code, name) map for fallback
        bond_lookup_early = {b.get("id"): (b.get("bond_code", ""), b.get("name", "")) for b in bonds}

        for row_idx, t in enumerate(trades, 2):
            bc = t.get("bond_code") or ""
            bn = t.get("bond_name") or ""
            if (not bc or not bn) and t.get("bond_id") in bond_lookup_early:
                lb_code, lb_name = bond_lookup_early[t["bond_id"]]
                bc = bc or lb_code
                bn = bn or lb_name
            row = [
                # Upload template columns
                bc,                                             # Deal ID*
                str(t.get("investment_date", ""))[:10],         # Date of Investment*
                t.get("client_pan", ""),                        # PAN*
                t.get("units", 0),                              # No of Units*
                t.get("total_amount", ""),                      # Amount*
                t.get("utr_number", ""),                        # UTR
                # Additional
                bn,                                             # Bond Name
                t.get("client_name", ""),                       # Client Name
                t.get("calculated_price", ""),                  # Calculated Price
                t.get("status", ""),                            # Status
                "Yes" if t.get("is_historical") else "No",      # Is Historical
                str(t.get("created_at", ""))[:19] if t.get("created_at") else "",  # Created At
            ]
            for col, v in enumerate(row, 1):
                c = ws5.cell(row=row_idx, column=col, value=v)
                c.border = thin

        # ────────── Sheet 6: Historical Repayments (actual_repayments) — Amber ──────────
        repayments = await db.actual_repayments.find({}, {"_id": 0}).to_list(None)

        # Build lookup maps for rows missing denormalized fields
        bond_lookup = {}
        for b in bonds:
            bond_lookup[b.get("id")] = (b.get("bond_code", ""), b.get("name", ""))
        client_lookup = {}
        for coll in ["Private_Investor", "Private_Investor_Indian_Passport", "Private_Investor_Foreign_Passport"]:
            async for doc in db[coll].find(
                {}, {"_id": 0, "id": 1, "name": 1, "photo_id": 1, "pan_number": 1, "passport_number": 1}
            ):
                cid = doc.get("id")
                if cid and cid not in client_lookup:
                    pan = doc.get("photo_id") or doc.get("pan_number") or doc.get("passport_number") or ""
                    client_lookup[cid] = (pan, doc.get("name", ""))

        ws6 = wb.create_sheet("Historical Repayments")
        # Headers match the Historical Repayments upload template, with additional columns appended.
        headers6 = [
            # ---- Upload template columns (same names) ----
            "Deal ID*", "Date of Investment (optional)", "Repayment Date*", "PAN*",
            "Principal", "Interest", "Gross Amount*", "TDS", "Net Amount*",
            # ---- Additional columns retained for downloads ----
            "Bond Name", "Client Name", "Type", "Is Historical", "Created At",
        ]
        for col, h in enumerate(headers6, 1):
            _style_header(ws6.cell(row=1, column=col, value=h), "D97706")
            ws6.column_dimensions[get_column_letter(col)].width = 20
        for row_idx, r in enumerate(repayments, 2):
            # Fallback to lookup maps when denormalized fields are missing
            bc = r.get("bond_code") or ""
            bn = r.get("bond_name") or ""
            if (not bc or not bn) and r.get("bond_id") in bond_lookup:
                lb_code, lb_name = bond_lookup[r["bond_id"]]
                bc = bc or lb_code
                bn = bn or lb_name

            cp = r.get("client_pan") or ""
            cn = r.get("client_name") or ""
            if (not cp or not cn) and r.get("client_id") in client_lookup:
                lc_pan, lc_name = client_lookup[r["client_id"]]
                cp = cp or lc_pan
                cn = cn or lc_name

            row = [
                # Upload template columns
                bc,                                                # Deal ID*
                str(r.get("investment_date", ""))[:10],            # Date of Investment (optional)
                str(r.get("repayment_date", ""))[:10],             # Repayment Date*
                cp,                                                # PAN*
                r.get("principal", 0),                             # Principal
                r.get("interest", 0),                              # Interest
                r.get("gross_amount", 0),                          # Gross Amount*
                r.get("tds", r.get("tds_amount", 0)),              # TDS
                r.get("net_amount", 0),                            # Net Amount*
                # Additional
                bn,                                                # Bond Name
                cn,                                                # Client Name
                r.get("type") or r.get("source") or "",            # Type
                "Yes" if r.get("is_historical") else "No",         # Is Historical
                str(r.get("created_at", ""))[:19] if r.get("created_at") else "",  # Created At
            ]
            for col, v in enumerate(row, 1):
                c = ws6.cell(row=row_idx, column=col, value=v)
                c.border = thin

        buffer = BytesIO()
        wb.save(buffer)
        buffer.seek(0)

        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        return StreamingResponse(
            buffer,
            media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            headers={"Content-Disposition": f"attachment; filename=NCD_Master_Export_{timestamp}.xlsx"}
        )
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error exporting NCD_Master: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@api_router.get("/export/real-estate-investors")
async def export_real_estate_investors(current_user: dict = Depends(get_current_user)):
    """Export the full `Real_Estate_Investor` collection as a single-sheet
    Excel file. Broker-only."""
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can export Real Estate Investors")
    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
        from openpyxl.utils import get_column_letter
        from io import BytesIO

        rows = await db.Real_Estate_Investor.find({}, {"_id": 0}).sort("synced_at", -1).to_list(None)

        wb = Workbook()
        ws = wb.active
        ws.title = "Real Estate Investors"

        thin = Border(
            left=Side(style="thin"), right=Side(style="thin"),
            top=Side(style="thin"), bottom=Side(style="thin"),
        )
        header_fill = PatternFill(start_color="0F766E", end_color="0F766E", fill_type="solid")
        header_font = Font(bold=True, color="FFFFFF")
        header_align = Alignment(horizontal="center", vertical="center", wrap_text=True)

        headers = [
            "opportunity_id", "opportunity_building_name", "opportunity_unit_no",
            "opportunity_total_cost", "opportunity_unit_price",
            "id", "client_id", "client_name",
            "amount", "share_percentage", "units",
            "invested_at", "recorded_by", "recorded_by_name",
            "nationality", "passport_type",
            "synced_at",
        ]

        # Banner
        banner = (
            f"Real Estate Investors export  •  Total rows: {len(rows)}  •  "
            f"Generated: {datetime.now(timezone.utc).isoformat()}"
        )
        bc = ws.cell(row=1, column=1, value=banner)
        bc.font = Font(italic=True, color="6B7280")

        header_row = 3
        for col_idx, h in enumerate(headers, start=1):
            cell = ws.cell(row=header_row, column=col_idx, value=h)
            cell.fill = header_fill
            cell.font = header_font
            cell.alignment = header_align
            cell.border = thin

        for r_idx, doc in enumerate(rows, start=header_row + 1):
            for c_idx, h in enumerate(headers, start=1):
                val = doc.get(h, "")
                if isinstance(val, (dict, list)):
                    val = str(val)
                cell = ws.cell(row=r_idx, column=c_idx, value=val)
                cell.border = thin
                cell.alignment = Alignment(vertical="center", wrap_text=False)

        # Column widths
        for col_idx, h in enumerate(headers, start=1):
            letter = get_column_letter(col_idx)
            ws.column_dimensions[letter].width = max(14, min(42, len(h) + 6))

        ws.freeze_panes = "A4"

        buf = BytesIO()
        wb.save(buf)
        buf.seek(0)

        filename = f"REAL_ESTATE_INVESTOR_Export_{datetime.now().strftime('%Y%m%d')}.xlsx"
        return StreamingResponse(
            buf,
            media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            headers={"Content-Disposition": f"attachment; filename={filename}"},
        )
    except Exception as e:  # pragma: no cover
        logger.error(f"Error exporting Real_Estate_Investor: {e}")
        raise HTTPException(status_code=500, detail=str(e))




@api_router.get("/export/re-brokers")
async def export_re_brokers(current_user: dict = Depends(get_current_user)):
    """Export REAL_ESTATE_PARTNER collection as Excel file."""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can export partner data")
    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
        from io import BytesIO
        from fastapi.responses import StreamingResponse

        brokers = await db.Real_Estate_Partner.find({}, {"_id": 0}).to_list(None)

        # Canonical column order — matches the REAL_ESTATE_PARTNER_TEMPLATE + Add form
        preferred_order = [
            "id", "full_name", "email", "mobile_number",
            "company_name", "rera_license_number", "rera_expiry_date",
            "emirate", "office_address",
            "specialization", "years_of_experience", "team_size",
            "primary_areas", "website", "linkedin_profile", "about",
            "stage", "source", "is_active",
            "created_at", "updated_at", "notes",
        ]
        all_keys: list = []
        seen = set()
        for k in preferred_order:
            for b in brokers:
                if k in b and k not in seen:
                    all_keys.append(k)
                    seen.add(k)
                    break
        for b in brokers:
            for k in b.keys():
                if k not in seen:
                    all_keys.append(k)
                    seen.add(k)
        if not all_keys:
            all_keys = list(preferred_order)

        wb = Workbook()
        ws = wb.active
        ws.title = "Real Estate Partners"
        header_fill = PatternFill(start_color="0D9488", end_color="0D9488", fill_type="solid")
        header_font = Font(bold=True, color="FFFFFF")
        thin_border = Border(
            left=Side(style='thin'), right=Side(style='thin'),
            top=Side(style='thin'), bottom=Side(style='thin')
        )
        for col, key in enumerate(all_keys, 1):
            cell = ws.cell(row=1, column=col, value=key)
            cell.fill = header_fill
            cell.font = header_font
            cell.alignment = Alignment(horizontal='center', wrap_text=True)
            cell.border = thin_border

        for row_idx, b in enumerate(brokers, 2):
            for col, key in enumerate(all_keys, 1):
                value = b.get(key, "")
                if isinstance(value, (list, dict)):
                    value = str(value)
                cell = ws.cell(row=row_idx, column=col, value=value)
                cell.border = thin_border

        for col in ws.columns:
            max_length = 0
            column = col[0].column_letter
            for cell in col:
                try:
                    if cell.value and len(str(cell.value)) > max_length:
                        max_length = len(str(cell.value))
                except Exception:
                    pass
            ws.column_dimensions[column].width = min(max_length + 2, 50)

        buffer = BytesIO()
        wb.save(buffer)
        buffer.seek(0)

        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        return StreamingResponse(
            buffer,
            media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            headers={"Content-Disposition": f"attachment; filename=REAL_ESTATE_PARTNER_Export_{timestamp}.xlsx"}
        )
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error exporting REAL_ESTATE_PARTNER: {e}")
        raise HTTPException(status_code=500, detail=str(e))





