@api_router.get("/benchmark-sync/scheduler-status")
async def get_benchmark_scheduler_status(
    current_user: dict = Depends(get_current_user)
):
    """Get status of the daily benchmark sync scheduler"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can view scheduler status")
    
    global benchmark_scheduler
    
    if not benchmark_scheduler:
        return {
            "status": "not_initialized",
            "message": "Benchmark scheduler is not running"
        }
    
    jobs = []
    for job in benchmark_scheduler.get_jobs():
        jobs.append({
            "id": job.id,
            "name": job.name,
            "next_run": job.next_run_time.isoformat() if job.next_run_time else None
        })
    
    # Get recent sync logs
    recent_logs = await db.benchmark_sync_logs.find(
        {},
        {"_id": 0}
    ).sort("timestamp", -1).limit(5).to_list(5)
    
    return {
        "status": "running" if benchmark_scheduler.running else "paused",
        "jobs": jobs,
        "recent_syncs": recent_logs
    }


@api_router.post("/benchmark-sync/start-scheduler")
async def start_benchmark_scheduler(
    current_user: dict = Depends(get_current_user)
):
    """Start the daily benchmark sync scheduler (runs at 6 AM IST daily)"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can manage scheduler")
    
    global benchmark_scheduler
    
    if benchmark_scheduler and benchmark_scheduler.running:
        return {"status": "already_running", "message": "Scheduler is already running"}
    
    benchmark_scheduler = AsyncIOScheduler()
    
    # Schedule daily sync at 6:00 AM IST (00:30 UTC)
    async def scheduled_daily_sync():
        logger.info("Running scheduled daily benchmark sync...")
        try:
            result = await run_daily_sync()
            await db.benchmark_sync_logs.insert_one({
                "type": "scheduled_daily",
                "result": result,
                "timestamp": datetime.now(timezone.utc).isoformat()
            })
            logger.info(f"Scheduled sync completed: {result}")
        except Exception as e:
            logger.error(f"Scheduled sync failed: {e}")
            await db.benchmark_sync_logs.insert_one({
                "type": "scheduled_daily",
                "error": str(e),
                "timestamp": datetime.now(timezone.utc).isoformat()
            })
    
    benchmark_scheduler.add_job(
        scheduled_daily_sync,
        CronTrigger(hour=0, minute=30),  # 6:00 AM IST = 00:30 UTC
        id="daily_benchmark_sync",
        name="Daily Benchmark NAV Sync",
        replace_existing=True
    )
    
    benchmark_scheduler.start()
    
    return {
        "status": "started",
        "message": "Benchmark scheduler started. Will sync daily at 6:00 AM IST.",
        "next_run": benchmark_scheduler.get_job("daily_benchmark_sync").next_run_time.isoformat()
    }


@api_router.post("/benchmark-sync/stop-scheduler")
async def stop_benchmark_scheduler(
    current_user: dict = Depends(get_current_user)
):
    """Stop the daily benchmark sync scheduler"""
    if current_user['role'] != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can manage scheduler")
    
    global benchmark_scheduler
    
    if not benchmark_scheduler or not benchmark_scheduler.running:
        return {"status": "not_running", "message": "Scheduler is not running"}
    
    benchmark_scheduler.shutdown()
    benchmark_scheduler = None
    
    return {"status": "stopped", "message": "Benchmark scheduler stopped"}


# ============================================================
# NCD REPAYMENTS EMAIL AUTO-SYNC SCHEDULER
# ============================================================
# Runs the IMAP repayment sync twice a day in Asia/Kolkata timezone:
#   - 10:00 IST  (morning pull)
#   - 18:00 IST  (evening pull)
# Logs every run (manual + scheduled) into Ncd_Repayment_Sync_Log.

ncd_repayment_scheduler: Optional[AsyncIOScheduler] = None

async def _run_ncd_repayment_sync(trigger: str):
    """Single entry point used by the scheduler AND can be reused by the
    on-demand endpoint. Always writes a log row — never raises to the
    scheduler (so one bad mailbox doesn't kill the job)."""
    ran_at = datetime.now(timezone.utc).isoformat()
    try:
        report = await _sync_ncd_repayments_from_email(db, user=None)
        await db.Ncd_Repayment_Sync_Log.insert_one({
            "id": str(uuid.uuid4()),
            "trigger": trigger,                 # "scheduled_morning" | "scheduled_evening" | "manual"
            "ran_at": ran_at,
            "status": "ok" if not report.get("errors") else "partial",
            "report": report,
        })
        logger.info(f"[ncd-repayments] {trigger} sync done: {report}")
    except Exception as e:
        logger.error(f"[ncd-repayments] {trigger} sync failed: {e}")
        try:
            await db.Ncd_Repayment_Sync_Log.insert_one({
                "id": str(uuid.uuid4()),
                "trigger": trigger,
                "ran_at": ran_at,
                "status": "failed",
                "error": f"{type(e).__name__}: {e}",
            })
        except Exception:
            pass


@app.on_event("startup")
async def _start_ncd_repayment_scheduler():
    """Start the twice-a-day NCD repayments email sync scheduler on boot."""
    global ncd_repayment_scheduler
    try:
        import pytz
        tz = pytz.timezone("Asia/Kolkata")
    except Exception:
        tz = timezone.utc  # extremely unlikely; pytz is pulled in by apscheduler
    if ncd_repayment_scheduler and ncd_repayment_scheduler.running:
        return
    ncd_repayment_scheduler = AsyncIOScheduler(timezone=tz)
    ncd_repayment_scheduler.add_job(
        _run_ncd_repayment_sync, CronTrigger(hour=10, minute=0, timezone=tz),
        id="ncd_repayments_morning", name="NCD Repayments Sync @ 10:00 IST",
        kwargs={"trigger": "scheduled_morning"},
        replace_existing=True,
    )
    ncd_repayment_scheduler.add_job(
        _run_ncd_repayment_sync, CronTrigger(hour=18, minute=0, timezone=tz),
        id="ncd_repayments_evening", name="NCD Repayments Sync @ 18:00 IST",
        kwargs={"trigger": "scheduled_evening"},
        replace_existing=True,
    )
    ncd_repayment_scheduler.start()
    logger.info("[ncd-repayments] scheduler started (10:00 & 18:00 IST daily)")


@app.on_event("shutdown")
async def _stop_ncd_repayment_scheduler():
    global ncd_repayment_scheduler
    if ncd_repayment_scheduler and ncd_repayment_scheduler.running:
        ncd_repayment_scheduler.shutdown(wait=False)
        ncd_repayment_scheduler = None


@api_router.get("/ncd-repayments/sync-status")
async def get_ncd_repayment_sync_status(current_user: dict = Depends(get_current_user)):
    """Return the last-N sync log entries + the next scheduled run times.
    Broker-only — used by the UI to show auditors when emails were last
    pulled."""
    if current_user.get('role') != 'broker':
        raise HTTPException(status_code=403, detail="Only brokers can view sync status")
    logs = await db.Ncd_Repayment_Sync_Log.find({}, {"_id": 0}).sort("ran_at", -1).limit(20).to_list(20)
    next_runs = []
    if ncd_repayment_scheduler and ncd_repayment_scheduler.running:
        for job in ncd_repayment_scheduler.get_jobs():
            next_runs.append({
                "id": job.id,
                "name": job.name,
                "next_run_time": job.next_run_time.isoformat() if job.next_run_time else None,
            })
    return {
        "scheduler_running": bool(ncd_repayment_scheduler and ncd_repayment_scheduler.running),
        "next_runs": next_runs,
        "recent_logs": logs,
    }


