@api_router.get("/bulk-upload/real-estate-investors/template")
async def real_estate_investor_upload_template(current_user: dict = Depends(get_current_user)):
    """Return a blank Excel template for bulk-uploading investors into
    Real_Estate_Master / Real_Estate_Investor."""
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can download the template")
    from openpyxl import Workbook
    from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
    from openpyxl.utils import get_column_letter
    from io import BytesIO

    wb = Workbook()
    ws = wb.active
    ws.title = "Real Estate Investors"

    thin = Border(left=Side(style="thin"), right=Side(style="thin"),
                  top=Side(style="thin"), bottom=Side(style="thin"))
    header_fill = PatternFill(start_color="EA580C", end_color="EA580C", fill_type="solid")
    header_font = Font(bold=True, color="FFFFFF")
    header_align = Alignment(horizontal="center", vertical="center", wrap_text=True)

    headers = [
        ("building_name",     "Building Name (required — must match Real_Estate_Master)"),
        ("unit_no",           "Unit No (required — must match Real_Estate_Master)"),
        ("client_pan",        "Client PAN (required — must match Private_Investor.pan_number)"),
        ("share_percentage",  "Share % (required)"),
        ("amount",            "Amount (optional — auto-computed from unit_price × share if blank)"),
        ("units",             "Units (optional — for blocked-unit style allocations)"),
        ("invested_at",       "Invested At (optional — YYYY-MM-DD; defaults to today)"),
    ]

    ws.cell(row=1, column=1, value="Real Estate Investors — Bulk Upload Template").font = Font(bold=True, size=13)
    ws.cell(row=2, column=1, value="Fill starting from row 4. Do not remove the header row.").font = Font(italic=True, color="6B7280")

    header_row = 4
    for col_idx, (_, label) in enumerate(headers, start=1):
        cell = ws.cell(row=header_row, column=col_idx, value=label)
        cell.fill = header_fill
        cell.font = header_font
        cell.alignment = header_align
        cell.border = thin
    # Machine-readable key row
    key_row = 5
    for col_idx, (key, _) in enumerate(headers, start=1):
        cell = ws.cell(row=key_row, column=col_idx, value=key)
        cell.font = Font(bold=True, color="9CA3AF", italic=True)
        cell.alignment = Alignment(horizontal="center")
        cell.border = thin

    # Column widths
    for col_idx, (_, label) in enumerate(headers, start=1):
        ws.column_dimensions[get_column_letter(col_idx)].width = max(18, min(50, len(label) // 2 + 12))

    ws.freeze_panes = "A6"

    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    return StreamingResponse(
        buf,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": "attachment; filename=REAL_ESTATE_INVESTOR_Template.xlsx"},
    )


@api_router.post("/bulk-upload/real-estate-investors")
async def bulk_upload_real_estate_investors(
    file: UploadFile = File(...),
    current_user: dict = Depends(get_current_user),
):
    """Parse the uploaded Excel and add investor allocations in bulk.
    Returns per-row success / error details; mirrors to Real_Estate_Investor
    via the existing sync helper."""
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can bulk-upload investors")

    from openpyxl import load_workbook
    from io import BytesIO

    raw = await file.read()
    try:
        wb = load_workbook(BytesIO(raw), data_only=True)
    except Exception as exc:
        raise HTTPException(status_code=400, detail=f"Unable to read Excel: {exc}")
    ws = wb.active

    # Read key row (row 5) -> column-index map
    expected_keys = [
        "building_name", "unit_no", "client_pan",
        "share_percentage", "amount", "units", "invested_at",
    ]
    key_row_cells = [ws.cell(row=5, column=i + 1).value for i in range(len(expected_keys))]
    col_by_key: Dict[str, int] = {}
    for i, k in enumerate(expected_keys):
        actual = (key_row_cells[i] or "").strip() if isinstance(key_row_cells[i], str) else None
        col_by_key[k] = i + 1 if actual == k else i + 1  # trust column order

    results: List[Dict] = []
    processed_opps: set = set()

    row_idx = 6
    while True:
        if row_idx > ws.max_row:
            break
        row_has_data = any(ws.cell(row=row_idx, column=i + 1).value not in (None, "")
                           for i in range(len(expected_keys)))
        if not row_has_data:
            row_idx += 1
            # Allow some blank rows at the end
            if all(
                ws.cell(row=r, column=1).value in (None, "")
                for r in range(row_idx, min(row_idx + 5, ws.max_row + 1))
            ):
                break
            continue

        def cell(key):
            v = ws.cell(row=row_idx, column=col_by_key[key]).value
            if isinstance(v, str):
                v = v.strip()
            return v

        building_name = cell("building_name")
        unit_no = cell("unit_no")
        client_pan = cell("client_pan")
        share_pct = cell("share_percentage")
        amount = cell("amount")
        units = cell("units")
        invested_at = cell("invested_at")

        row_result = {
            "row": row_idx,
            "building_name": building_name,
            "unit_no": unit_no,
            "client_pan": client_pan,
            "status": "skipped",
            "error": None,
        }

        try:
            if not building_name or not unit_no:
                raise ValueError("building_name and unit_no are required")
            if not client_pan:
                raise ValueError("client_pan is required")
            try:
                share_pct_f = float(share_pct)
            except (TypeError, ValueError):
                raise ValueError("share_percentage must be numeric")
            if share_pct_f <= 0 or share_pct_f > 100:
                raise ValueError("share_percentage must be in (0, 100]")

            # Lookup opportunity
            opp = await db.Real_Estate_Master.find_one(
                {"building_name": building_name, "unit_no": str(unit_no)},
                {"id": 1, "unit_price": 1, "total_cost": 1, "invested_percentage": 1, "investors": 1, "building_name": 1, "unit_no": 1},
            )
            if not opp:
                raise ValueError(f"No Real_Estate_Master for '{building_name}' unit '{unit_no}'")

            # Lookup investor by PAN
            client_doc = await db.Private_Investor.find_one(
                {"pan_number": str(client_pan).upper()},
                {"id": 1, "name": 1, "client_id": 1},
            )
            if not client_doc:
                raise ValueError(f"No Private_Investor with PAN {client_pan}")

            client_id = client_doc.get("id") or client_doc.get("client_id")
            client_name = client_doc.get("name")

            # Resolve amount
            if amount in (None, ""):
                if opp.get("unit_price"):
                    amount_v = opp["unit_price"] * share_pct_f / 100.0
                else:
                    amount_v = (opp.get("total_cost") or 0) * share_pct_f / 100.0
            else:
                amount_v = float(amount)

            # Check share headroom on the opportunity
            new_total_pct = float(opp.get("invested_percentage") or 0) + share_pct_f
            if new_total_pct > 100.0001:
                raise ValueError(
                    f"share_percentage {share_pct_f}% exceeds remaining "
                    f"{100 - float(opp.get('invested_percentage') or 0):.2f}%"
                )

            # Prevent duplicate allocation for same client on same opportunity
            existing_for_client = any(
                (inv.get("client_id") == client_id) for inv in (opp.get("investors") or [])
            )
            if existing_for_client:
                raise ValueError("Investor already exists on this opportunity")

            investor_record = {
                "id": str(uuid.uuid4()),
                "client_id": client_id,
                "client_name": client_name,
                "amount": amount_v,
                "share_percentage": share_pct_f,
                "units": int(units) if units not in (None, "") else None,
                "invested_at": (str(invested_at)[:10] if invested_at else datetime.now(timezone.utc).date().isoformat()),
                "recorded_by": current_user.get("id"),
                "recorded_by_name": current_user.get("name") or current_user.get("email"),
                "payments": [],
            }

            # Update Real_Estate_Master: push investor + recompute aggregates
            update_data = {
                "updated_at": datetime.now(timezone.utc).isoformat(),
                "invested_percentage": new_total_pct,
                "remaining_percentage": 100 - new_total_pct,
                "total_invested": (
                    float(opp.get("total_cost") or 0) * new_total_pct / 100.0
                ),
                "current_investors": len(opp.get("investors") or []) + 1,
                "status": "fully_invested" if abs(new_total_pct - 100) < 0.0001 else "partially_invested",
            }
            await db.Real_Estate_Master.update_one(
                {"id": opp["id"]},
                {"$set": update_data, "$push": {"investors": investor_record}},
            )
            processed_opps.add(opp["id"])

            row_result.update({
                "status": "ok",
                "opportunity_id": opp["id"],
                "investor_id": investor_record["id"],
                "amount": amount_v,
                "share_percentage": share_pct_f,
            })
        except Exception as exc:
            row_result["status"] = "error"
            row_result["error"] = str(exc)

        results.append(row_result)
        row_idx += 1

    # Mirror each touched opportunity to the new collection
    for opp_id in processed_opps:
        await _sync_real_estate_investors_to_collection(opp_id)

    ok = sum(1 for r in results if r["status"] == "ok")
    errors = sum(1 for r in results if r["status"] == "error")
    return {
        "status": "completed",
        "processed": len(results),
        "success": ok,
        "errors": errors,
        "opportunities_touched": len(processed_opps),
        "rows": results,
    }




# =============================================================================
# Real-Estate Uploads — invoices / investor payment details / receipts
# =============================================================================
# Each of the three categories has its own dedicated MongoDB collection with
# strongly-typed, category-specific fields on top of the common scoping fields
# (opportunity_id, investor_id, milestone_date). Files are stored on disk under
# /app/backend/uploads/real_estate/<category>/<upload_id>_<filename>.
#
#   real-estate-invoices        -> db.real_estate_invoices
#   investor-payment-details    -> db.investor_payment_details
#   investor-payment-receipts   -> db.investor_payment_receipts

from fastapi import UploadFile, File, Form  # noqa: E402
import shutil  # noqa: E402

_RE_UPLOAD_ROOT = Path("/app/backend/uploads/real_estate")
_RE_UPLOAD_ROOT.mkdir(parents=True, exist_ok=True)

# category slug -> MongoDB collection name
_RE_UPLOAD_CATEGORY_COLLECTIONS = {
    "real-estate-invoices": "real_estate_invoices",
    "investor-payment-details": "investor_payment_details",
    "investor-payment-receipts": "investor_payment_receipts",
}


def _re_upload_collection(category: str):
    coll_name = _RE_UPLOAD_CATEGORY_COLLECTIONS.get(category)
    if not coll_name:
        return None
    return db[coll_name]


def _coerce_float(v):
    if v is None or v == "":
        return None
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


def _extract_category_fields(category: str, metadata: dict) -> dict:
    """Pull the strongly-typed, category-specific fields out of the metadata
    payload sent by the frontend. Returns a flat dict that will be merged into
    the DB record."""
    if category == "real-estate-invoices":
        return {
            "invoice_number": (metadata.get("invoice_number") or "").strip(),
            "invoice_date": (metadata.get("invoice_date") or "").strip(),
            "due_date": (metadata.get("due_date") or "").strip(),
            "amount_due": _coerce_float(metadata.get("amount_due")),
            "notes": (metadata.get("notes") or "").strip(),
        }
    if category == "investor-payment-details":
        return {
            "transfer_date": (metadata.get("transfer_date") or "").strip(),
            "currency": (metadata.get("currency") or "AED").strip().upper(),
            "home_currency_amount": _coerce_float(metadata.get("home_currency_amount")),
            "aed_amount": _coerce_float(metadata.get("aed_amount")),
            "notes": (metadata.get("notes") or "").strip(),
        }
    if category == "investor-payment-receipts":
        return {
            "receipt_number": (metadata.get("receipt_number") or "").strip(),
            "receipt_date": (metadata.get("receipt_date") or "").strip(),
            "payment_amount": _coerce_float(metadata.get("payment_amount")),
            "paid_on": (metadata.get("paid_on") or "").strip(),
            "notes": (metadata.get("notes") or "").strip(),
        }
    return {}


@api_router.post("/real-estate-uploads")
async def upload_real_estate_file(
    category: str = Form(...),
    opportunity_id: str = Form(...),
    milestone_date: str = Form(...),
    milestone_description: str = Form(""),
    investor_id: Optional[str] = Form(None),
    metadata_json: Optional[str] = Form(None),
    file: UploadFile = File(...),
    current_user: dict = Depends(get_current_user),
):
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can upload")
    coll = _re_upload_collection(category)
    if coll is None:
        raise HTTPException(status_code=400, detail=f"Invalid category: {category}")

    # Verify opportunity
    opp = await db.Real_Estate_Master.find_one({"id": opportunity_id}, {"id": 1, "building_name": 1, "unit_no": 1, "investors": 1})
    if not opp:
        raise HTTPException(status_code=404, detail="Opportunity not found")

    # All three categories are investor-scoped per the latest spec
    if not investor_id:
        raise HTTPException(status_code=400, detail="investor_id is required")
    inv = next((i for i in (opp.get("investors") or []) if i.get("id") == investor_id or i.get("client_id") == investor_id), None)
    if not inv:
        raise HTTPException(status_code=404, detail="Investor not found on this opportunity")
    investor_name = inv.get("client_name")
    investor_client_id = inv.get("client_id")

    metadata: dict = {}
    if metadata_json:
        try:
            import json as _json
            parsed = _json.loads(metadata_json)
            if isinstance(parsed, dict):
                metadata = parsed
        except Exception:
            metadata = {}

    cat_fields = _extract_category_fields(category, metadata)

    # Save file to persistent object storage
    upload_id = str(uuid.uuid4())
    safe_name = (file.filename or "file").replace("/", "_")
    ext = safe_name.rsplit(".", 1)[-1] if "." in safe_name else "bin"
    object_key = build_object_path("real_estate", category, f"{upload_id}.{ext}")
    try:
        content = await file.read()
    finally:
        await file.close()
    result = await put_object_async(object_key, content, file.content_type or "application/octet-stream")

    file_size = result.get("size", len(content))

    record = {
        "id": upload_id,
        "category": category,
        "opportunity_id": opportunity_id,
        "opportunity_building_name": opp.get("building_name"),
        "opportunity_unit_no": opp.get("unit_no"),
        "investor_id": investor_id,
        "investor_client_id": investor_client_id,
        "investor_name": investor_name,
        "milestone_date": milestone_date,
        "milestone_description": milestone_description,
        # category-specific typed fields
        **cat_fields,
        # raw metadata kept for forward-compat / future fields
        "metadata": metadata,
        # file + audit
        "original_filename": file.filename,
        "storage_path": result["path"],
        "content_type": file.content_type,
        "file_size": file_size,
        "is_deleted": False,
        "uploaded_by": current_user.get("id"),
        "uploaded_by_name": current_user.get("name") or current_user.get("email"),
        "uploaded_at": datetime.now(timezone.utc).isoformat(),
    }
    await coll.insert_one(record)
    record.pop("_id", None)
    return {"status": "ok", "record": record}


async def _find_re_upload(upload_id: str):
    """Look up an upload by id across all three category-specific collections.
    Returns (doc, category) or (None, None)."""
    for cat, coll_name in _RE_UPLOAD_CATEGORY_COLLECTIONS.items():
        doc = await db[coll_name].find_one({"id": upload_id})
        if doc:
            return doc, cat
    return None, None


@api_router.get("/real-estate-uploads")
async def list_real_estate_uploads(
    category: Optional[str] = None,
    opportunity_id: Optional[str] = None,
    investor_id: Optional[str] = None,
    current_user: dict = Depends(get_current_user),
):
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can list uploads")

    # Which collections to read from
    if category:
        coll = _re_upload_collection(category)
        if coll is None:
            raise HTTPException(status_code=400, detail=f"Invalid category: {category}")
        collections = [coll]
    else:
        collections = [db[c] for c in _RE_UPLOAD_CATEGORY_COLLECTIONS.values()]

    q: dict = {}
    if opportunity_id:
        q["opportunity_id"] = opportunity_id
    if investor_id:
        q["investor_id"] = investor_id

    rows: list = []
    for c in collections:
        rows.extend(
            await c.find(q, {"_id": 0, "stored_path": 0}).sort("uploaded_at", -1).to_list(1000)
        )
    rows.sort(key=lambda r: r.get("uploaded_at", ""), reverse=True)
    return {"count": len(rows), "rows": rows}


@api_router.get("/real-estate-uploads/{upload_id}/download")
async def download_real_estate_upload(
    upload_id: str,
    current_user: dict = Depends(get_current_user),
):
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can download")
    doc, _cat = await _find_re_upload(upload_id)
    if not doc or doc.get("is_deleted"):
        raise HTTPException(status_code=404, detail="Upload not found")

    storage_path = doc.get("storage_path")
    if storage_path:
        try:
            data, ctype = await get_object_async(storage_path)
        except Exception as exc:
            logger.warning(f"[real-estate-uploads] storage fetch failed: {exc}")
            raise HTTPException(status_code=404, detail="File not found in storage")
        from fastapi.responses import Response
        filename = doc.get("original_filename") or storage_path.rsplit("/", 1)[-1]
        return Response(
            content=data,
            media_type=doc.get("content_type") or ctype or "application/octet-stream",
            headers={"Content-Disposition": f'attachment; filename="{filename}"'},
        )

    # Legacy disk-stored records (pre-object-storage). If the file is still
    # around, stream it; otherwise surface 410 so the UI prompts a re-upload.
    legacy_path = Path(doc.get("stored_path", ""))
    if legacy_path.exists():
        return FileResponse(
            str(legacy_path),
            media_type=doc.get("content_type") or "application/octet-stream",
            filename=doc.get("original_filename") or legacy_path.name,
        )
    raise HTTPException(status_code=410, detail="File was stored on ephemeral disk and is no longer available. Please re-upload.")


@api_router.delete("/real-estate-uploads/{upload_id}")
async def delete_real_estate_upload(
    upload_id: str,
    current_user: dict = Depends(get_current_user),
):
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can delete uploads")
    doc, cat = await _find_re_upload(upload_id)
    if not doc:
        raise HTTPException(status_code=404, detail="Upload not found")

    # Object storage has no delete — keep the object, just drop the DB record.
    # For legacy disk rows, best-effort unlink.
    legacy = doc.get("stored_path")
    if legacy:
        try:
            p = Path(legacy)
            if p.exists():
                p.unlink()
        except Exception as exc:
            logger.warning(f"[real-estate-uploads] file unlink failed: {exc}")
    await db[_RE_UPLOAD_CATEGORY_COLLECTIONS[cat]].delete_one({"id": upload_id})
    return {"status": "ok"}


