async def _export_re_category(category: str):
    """Build an Excel file for one of the three RE upload categories."""
    cfg = _RE_EXPORT_CONFIGS[category]
    from openpyxl import Workbook
    from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
    from openpyxl.utils import get_column_letter
    from io import BytesIO

    rows = await db[cfg["collection"]].find({}, {"_id": 0, "stored_path": 0, "metadata": 0}).sort("uploaded_at", -1).to_list(None)

    wb = Workbook()
    ws = wb.active
    ws.title = cfg["sheet"]

    thin = Border(
        left=Side(style="thin"), right=Side(style="thin"),
        top=Side(style="thin"), bottom=Side(style="thin"),
    )
    header_fill = PatternFill(start_color=cfg["fill"], end_color=cfg["fill"], fill_type="solid")
    header_font = Font(bold=True, color="FFFFFF")
    header_align = Alignment(horizontal="center", vertical="center", wrap_text=True)

    banner = (
        f"{cfg['sheet']} export  •  Total rows: {len(rows)}  •  "
        f"Generated: {datetime.now(timezone.utc).isoformat()}"
    )
    bc = ws.cell(row=1, column=1, value=banner)
    bc.font = Font(italic=True, color="6B7280")

    header_row = 3
    for col_idx, h in enumerate(cfg["headers"], start=1):
        cell = ws.cell(row=header_row, column=col_idx, value=h)
        cell.fill = header_fill
        cell.font = header_font
        cell.alignment = header_align
        cell.border = thin

    for r_idx, doc in enumerate(rows, start=header_row + 1):
        for c_idx, h in enumerate(cfg["headers"], start=1):
            val = doc.get(h, "")
            if isinstance(val, (dict, list)):
                val = str(val)
            cell = ws.cell(row=r_idx, column=c_idx, value=val)
            cell.border = thin
            cell.alignment = Alignment(vertical="center", wrap_text=False)

    for col_idx, h in enumerate(cfg["headers"], start=1):
        letter = get_column_letter(col_idx)
        ws.column_dimensions[letter].width = max(14, min(42, len(h) + 6))
    ws.freeze_panes = "A4"

    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)

    filename = f"{cfg['filename']}_{datetime.now().strftime('%Y%m%d')}.xlsx"
    return StreamingResponse(
        buf,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f"attachment; filename={filename}"},
    )


