@api_router.get("/export/ncd-presentations")
async def export_ncd_presentations(current_user: dict = Depends(get_current_user)):
    """Bundle every non-deleted NCD presentation into a single ZIP named by
    Deal ID. Files inside the ZIP use the Deal-ID-based filename so recipients
    can immediately tell which bond a presentation belongs to."""
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can export")

    import zipfile
    from io import BytesIO

    rows = await db.NCD_Presentations.find(
        {"is_deleted": {"$ne": True}},
        {"_id": 0, "id": 1, "bond_code": 1, "storage_path": 1,
         "deal_filename": 1, "original_filename": 1, "content_type": 1}
    ).sort("bond_code", 1).to_list(None)

    buf = BytesIO()
    included = 0
    errors = []
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        for row in rows:
            sp = row.get("storage_path")
            if not sp:
                continue
            try:
                data, _ct = await get_object_async(sp)
            except Exception as exc:
                errors.append(f"{row.get('bond_code')}: {exc}")
                continue
            name = row.get("deal_filename") or (
                f"{row.get('bond_code') or 'UNKNOWN'}_{row.get('id','')[:8]}.pdf"
            )
            zf.writestr(name, data)
            included += 1
        if errors:
            zf.writestr("_errors.txt", "\n".join(errors))

    buf.seek(0)
    filename = f"NCD_Presentations_{datetime.now().strftime('%Y%m%d')}.zip"
    return StreamingResponse(
        buf,
        media_type="application/zip",
        headers={
            "Content-Disposition": f'attachment; filename="{filename}"',
            "X-Presentations-Included": str(included),
            "X-Presentations-Errors": str(len(errors)),
        },
    )


# =============================================================================
# Bulk Excel + PDF Attach — Real-Estate Invoices / Payment Details / Receipts
# =============================================================================
# Two-step flow modelled on NCD bulk historical trades:
#   Step 1 – POST /api/bulk/{category}           (Excel: rows keyed by deal_id+pan)
#   Step 2 – POST /api/bulk/{category}/attach-pdfs (files named <deal_id>_<pan>*.*)
#
# Each row is inserted into its dedicated collection
# (real_estate_invoices / investor_payment_details / investor_payment_receipts)
# with `pdf_uploaded: false` until Step 2 attaches a physical file.

import re as _re_bulk  # noqa: E402

