def _bulk_re_build_template(category: str) -> "StreamingResponse":
    """Build a one-sheet Excel template for the given bulk RE category."""
    from openpyxl import Workbook
    from openpyxl.styles import Font, Alignment, PatternFill
    from openpyxl.utils import get_column_letter
    from io import BytesIO

    cfg = _BULK_RE_TEMPLATE_SPECS[category]
    wb = Workbook()
    ws = wb.active
    ws.title = cfg["sheet"]

    fill = PatternFill(start_color=cfg["fill"], end_color=cfg["fill"], fill_type="solid")
    for col, h in enumerate(cfg["headers"], start=1):
        c = ws.cell(row=1, column=col, value=h)
        c.font = Font(bold=True, color="FFFFFF")
        c.fill = fill
        c.alignment = Alignment(horizontal="center", wrap_text=True)
        ws.column_dimensions[get_column_letter(col)].width = max(16, min(34, len(h) + 4))
    for col, v in enumerate(cfg["sample"], start=1):
        ws.cell(row=2, column=col, value=v)

    # Instruction block
    inst_row = 4
    instructions = [
        "BULK UPLOAD INSTRUCTIONS",
        "1. Each row is looked up by (Deal ID + PAN). Deal ID must match an existing Real Estate opportunity.",
        "2. PAN must belong to an investor allocation on that opportunity.",
        "3. Milestone Date must match a date in the opportunity's payment schedule (YYYY-MM-DD).",
        f"4. PDF filename convention for Step 2 is: {cfg['pdf_convention']}",
        "5. Dates must be ISO (YYYY-MM-DD); numeric amounts in AED unless otherwise labelled.",
    ]
    for i, text in enumerate(instructions):
        c = ws.cell(row=inst_row + i, column=1, value=text)
        c.font = Font(bold=(i == 0), color="6B7280")

    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    fn = f"{cfg['sheet'].replace(' ', '_')}_Template_{datetime.now().strftime('%Y%m%d')}.xlsx"
    return StreamingResponse(
        buf,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f"attachment; filename={fn}"},
    )


