def _to_date_str(val) -> str:
    """Normalise a pandas/date value to YYYY-MM-DD or empty string."""
    import pandas as _pd
    if val is None or (isinstance(val, float) and _pd.isna(val)):
        return ""
    if hasattr(val, "strftime"):
        return val.strftime("%Y-%m-%d")
    s = str(val).strip()
    try:
        return _pd.to_datetime(s).strftime("%Y-%m-%d")
    except Exception:
        return s


async def _bulk_re_ingest(category: str, file: "UploadFile", current_user: dict) -> dict:
    """Shared parser for the 3 bulk-data uploads. Returns a structured summary."""
    import pandas as _pd
    cfg = _BULK_RE_TEMPLATE_SPECS[category]
    coll = db[_RE_UPLOAD_CATEGORY_COLLECTIONS[category]]

    # Read excel
    content = await file.read()
    from io import BytesIO as _BIO
    try:
        xls = _pd.ExcelFile(_BIO(content))
        df = _pd.read_excel(xls, sheet_name=0)
    except Exception as exc:
        raise HTTPException(status_code=400, detail=f"Unreadable Excel: {exc}")

    # Normalise column names
    def _norm(c: str) -> str:
        c = str(c).strip().lower().replace("*", "").replace("(", "").replace(")", "")
        c = _re_bulk.sub(r"[^a-z0-9]+", "_", c).strip("_")
        return c
    df.columns = [_norm(c) for c in df.columns]

    summary = {"success": 0, "failed": 0, "errors": [], "inserted_ids": []}

    # Pre-load opportunities referenced (by deal_id) for efficient lookup
    deal_ids = [str(v).strip().upper() for v in df.get("deal_id", []) if str(v).strip()]
    opps = {}
    if deal_ids:
        async for o in db.Real_Estate_Master.find(
            {"deal_id": {"$in": deal_ids}},
            {"_id": 0, "id": 1, "deal_id": 1, "building_name": 1, "unit_no": 1,
             "investors": 1, "payment_schedule": 1},
        ):
            opps[o.get("deal_id")] = o

    for idx, row in df.iterrows():
        rownum = idx + 2  # excel row
        try:
            # Validate required
            missing = [k for k in cfg["required"] if _pd.isna(row.get(k)) or str(row.get(k)).strip() == ""]
            if missing:
                summary["errors"].append(f"Row {rownum}: missing required fields {missing}")
                summary["failed"] += 1
                continue

            deal_id = str(row["deal_id"]).strip().upper()
            pan = str(row["pan"]).strip().upper()
            opp = opps.get(deal_id)
            if not opp:
                summary["errors"].append(f"Row {rownum}: Deal ID '{deal_id}' not found")
                summary["failed"] += 1
                continue

            # Find investor on the opportunity by PAN
            inv = None
            for i in (opp.get("investors") or []):
                inv_pan = (i.get("pan") or "").strip().upper() if i.get("pan") else ""
                if inv_pan == pan:
                    inv = i
                    break
            if not inv:
                # Fallback: look up the client across common collections by PAN.
                # The opportunity's investor.client_id can reference either the
                # Private_Investor_* doc id OR the users.id OR the
                # Private_Investor.id — collect ALL matching ids and try each.
                candidate_ids = set()
                for coll_name in (
                    "Private_Investor_Indian_Passport",
                    "Private_Investor_Foreign_Passport",
                    "Private_Investor",
                    "users",
                ):
                    cand = await db[coll_name].find_one(
                        {"pan": pan}, {"_id": 0, "id": 1, "user_id": 1}
                    )
                    if cand:
                        if cand.get("id"): candidate_ids.add(cand["id"])
                        if cand.get("user_id"): candidate_ids.add(cand["user_id"])
                if candidate_ids:
                    for i in (opp.get("investors") or []):
                        if i.get("client_id") in candidate_ids:
                            inv = i; break
            if not inv:
                summary["errors"].append(
                    f"Row {rownum}: PAN '{pan}' is not an investor on Deal ID '{deal_id}'"
                )
                summary["failed"] += 1
                continue

            milestone_date = _to_date_str(row.get("milestone_date"))
            milestone_desc = str(row.get("milestone_description") or "").strip()

            # Category-specific flat fields
            cat_fields: dict = {}
            for src_col, dest_key in cfg["field_map"].items():
                v = row.get(src_col)
                if _pd.isna(v):
                    v = None
                # coerce dates
                if dest_key in {"invoice_date", "due_date", "transfer_date",
                                "receipt_date", "paid_on"}:
                    cat_fields[dest_key] = _to_date_str(v) if v is not None else ""
                elif dest_key in {"amount_due", "aed_amount", "home_currency_amount", "payment_amount"}:
                    try:
                        cat_fields[dest_key] = float(v) if v is not None and str(v) != "" else None
                    except (TypeError, ValueError):
                        cat_fields[dest_key] = None
                else:
                    cat_fields[dest_key] = str(v).strip() if v is not None else ""

            pdf_filename = str(row.get(cfg["filename_col"]) or "").strip() if not _pd.isna(row.get(cfg["filename_col"])) else ""

            upload_id = str(uuid.uuid4())
            record = {
                "id": upload_id,
                "category": category,
                "opportunity_id": opp["id"],
                "opportunity_deal_id": deal_id,
                "opportunity_building_name": opp.get("building_name"),
                "opportunity_unit_no": opp.get("unit_no"),
                "investor_id": inv.get("id") or inv.get("client_id"),
                "investor_client_id": inv.get("client_id"),
                "investor_name": inv.get("client_name"),
                "investor_pan": pan,
                "milestone_date": milestone_date,
                "milestone_description": milestone_desc,
                **cat_fields,
                "metadata": {},
                "pdf_filename_expected": pdf_filename,
                "original_filename": None,
                "stored_path": None,
                "content_type": None,
                "file_size": 0,
                "pdf_uploaded": False,
                "source": "bulk_excel",
                "uploaded_by": current_user.get("id"),
                "uploaded_by_name": current_user.get("name") or current_user.get("email"),
                "uploaded_at": datetime.now(timezone.utc).isoformat(),
            }
            await coll.insert_one(record)
            summary["success"] += 1
            summary["inserted_ids"].append(upload_id)

            # Mirror the entry into `Real_Estate_Master.investor_invoices` /
            # `investor_payments` so the Holdings → Real Estate View Details
            # Payments header surfaces bulk-uploaded rows. The legacy
            # single-file upload endpoints already populate these subdoc
            # arrays; without this mirror, bulk-uploaded data lives only in
            # the new dedicated collections and is invisible to the existing
            # frontend reader.
            #
            # We resolve the milestone_index by matching the row's
            # `milestone_date` against entries in `opp.payment_schedule`.
            schedule = opp.get("payment_schedule") or []
            milestone_index = next(
                (i for i, m in enumerate(schedule)
                 if (m.get("date") or "")[:10] == (milestone_date or "")[:10]),
                None,
            )
            if milestone_index is not None:
                if category == "real-estate-invoices":
                    mirrored = {
                        "id": upload_id,
                        "milestone_index": milestone_index,
                        "investor_id": inv.get("client_id"),
                        "investor_name": inv.get("client_name"),
                        "invoice_number": cat_fields.get("invoice_number") or "",
                        "invoice_date": cat_fields.get("invoice_date") or "",
                        "due_date": cat_fields.get("due_date") or "",
                        "amount": cat_fields.get("amount_due") or 0,
                        "notes": cat_fields.get("notes") or "",
                        "source": "bulk_excel",
                        "uploaded_by": current_user.get("id"),
                        "uploaded_at": datetime.now(timezone.utc).isoformat(),
                    }
                    await db.Real_Estate_Master.update_one(
                        {"id": opp["id"]},
                        {"$push": {"investor_invoices": mirrored}}
                    )
                elif category in ("investor-payment-details", "investor-payment-receipts"):
                    mirrored = {
                        "id": upload_id,
                        "milestone_index": milestone_index,
                        "investor_id": inv.get("client_id"),
                        "investor_name": inv.get("client_name"),
                        "amount": (
                            cat_fields.get("payment_amount")
                            or cat_fields.get("aed_amount")
                            or cat_fields.get("home_currency_amount")
                            or 0
                        ),
                        "payment_date": (
                            cat_fields.get("paid_on")
                            or cat_fields.get("receipt_date")
                            or cat_fields.get("transfer_date")
                            or ""
                        ),
                        "status": "pending_verification",
                        "category": category,
                        "notes": cat_fields.get("notes") or "",
                        "source": "bulk_excel",
                        "uploaded_by": current_user.get("id"),
                        "uploaded_at": datetime.now(timezone.utc).isoformat(),
                    }
                    await db.Real_Estate_Master.update_one(
                        {"id": opp["id"]},
                        {"$push": {"investor_payments": mirrored}}
                    )
        except Exception as exc:
            summary["errors"].append(f"Row {rownum}: {exc}")
            summary["failed"] += 1

    return summary


