@api_router.post("/admin/real-estate/backfill-mirrors")
async def backfill_re_mirrors(current_user: dict = Depends(get_current_user)):
    """One-shot backfill: for every legacy `real_estate_invoices` /
    `investor_payment_details` / `investor_payment_receipts` row that was
    bulk-uploaded BEFORE the mirror logic was added to `_bulk_re_ingest`,
    push the corresponding entry into
    `Real_Estate_Master.investor_invoices` / `investor_payments` so the
    Holdings → Real Estate → View Details page can surface it. Idempotent."""
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can backfill")
    summary = {"invoices_added": 0, "payments_added": 0, "skipped": 0, "errors": []}

    # ---- Invoices ----------------------------------------------------------
    async for r in db.real_estate_invoices.find({}, {"_id": 0}):
        try:
            oid = r.get("opportunity_id")
            uid = r.get("id")
            if not oid or not uid:
                summary["skipped"] += 1; continue
            opp = await db.Real_Estate_Master.find_one(
                {"id": oid}, {"_id": 0, "id": 1, "payment_schedule": 1, "investor_invoices": 1})
            if not opp:
                summary["skipped"] += 1; continue
            if any((i or {}).get("id") == uid for i in (opp.get("investor_invoices") or [])):
                summary["skipped"] += 1; continue
            schedule = opp.get("payment_schedule") or []
            mdate = (r.get("milestone_date") or "")[:10]
            milestone_index = next(
                (i for i, m in enumerate(schedule)
                 if (m.get("date") or "")[:10] == mdate), None)
            if milestone_index is None:
                summary["errors"].append(
                    f"invoice {uid}: milestone_date {mdate} not found in payment_schedule")
                continue
            mirrored = {
                "id": uid,
                "milestone_index": milestone_index,
                "investor_id": r.get("investor_client_id"),
                "investor_name": r.get("investor_name"),
                "invoice_number": r.get("invoice_number") or "",
                "invoice_date": r.get("invoice_date") or "",
                "due_date": r.get("due_date") or "",
                "amount": r.get("amount_due") or 0,
                "notes": r.get("notes") or "",
                "source": r.get("source") or "bulk_excel",
                "uploaded_by": r.get("uploaded_by"),
                "uploaded_at": r.get("uploaded_at"),
                "pdf_uploaded": bool(r.get("pdf_uploaded")),
                "original_filename": r.get("original_filename"),
            }
            await db.Real_Estate_Master.update_one(
                {"id": oid}, {"$push": {"investor_invoices": mirrored}})
            summary["invoices_added"] += 1
        except Exception as exc:
            summary["errors"].append(f"invoice row error: {exc}")

    # ---- Payments (details + receipts) -------------------------------------
    for source_coll, cat in (
        ("investor_payment_details", "investor-payment-details"),
        ("investor_payment_receipts", "investor-payment-receipts"),
    ):
        async for r in db[source_coll].find({}, {"_id": 0}):
            try:
                oid = r.get("opportunity_id")
                uid = r.get("id")
                if not oid or not uid:
                    summary["skipped"] += 1; continue
                opp = await db.Real_Estate_Master.find_one(
                    {"id": oid}, {"_id": 0, "id": 1, "payment_schedule": 1, "investor_payments": 1})
                if not opp:
                    summary["skipped"] += 1; continue
                if any((p or {}).get("id") == uid for p in (opp.get("investor_payments") or [])):
                    summary["skipped"] += 1; continue
                schedule = opp.get("payment_schedule") or []
                mdate = (r.get("milestone_date") or "")[:10]
                milestone_index = next(
                    (i for i, m in enumerate(schedule)
                     if (m.get("date") or "")[:10] == mdate), None)
                if milestone_index is None:
                    summary["errors"].append(
                        f"{cat} {uid}: milestone_date {mdate} not in payment_schedule")
                    continue
                mirrored = {
                    "id": uid,
                    "milestone_index": milestone_index,
                    "investor_id": r.get("investor_client_id"),
                    "investor_name": r.get("investor_name"),
                    "amount": (r.get("payment_amount") or r.get("aed_amount")
                               or r.get("home_currency_amount") or 0),
                    "payment_date": (r.get("paid_on") or r.get("receipt_date")
                                     or r.get("transfer_date") or ""),
                    "status": "pending_verification",
                    "category": cat,
                    "notes": r.get("notes") or "",
                    "source": r.get("source") or "bulk_excel",
                    "uploaded_by": r.get("uploaded_by"),
                    "uploaded_at": r.get("uploaded_at"),
                    "pdf_uploaded": bool(r.get("pdf_uploaded")),
                    "original_filename": r.get("original_filename"),
                }
                await db.Real_Estate_Master.update_one(
                    {"id": oid}, {"$push": {"investor_payments": mirrored}})
                summary["payments_added"] += 1
            except Exception as exc:
                summary["errors"].append(f"{cat} row error: {exc}")

    return summary


