# Third filename segment per category — enables a unique
# <DealID>_<PAN>_<SEGMENT> match so multiple rows for the same (deal_id, pan)
# milestone combo can each be attached to their own PDF.
_RE_PDF_THIRD_SEGMENT = {
    "real-estate-invoices": "invoice_number",
    "investor-payment-details": "transfer_date",
    "investor-payment-receipts": "receipt_number",
}


def _norm_seg(s) -> str:
    """Normalise a filename segment for case/whitespace/dash-insensitive match."""
    if s is None:
        return ""
    import re as _rr
    return _rr.sub(r"[^A-Za-z0-9]", "", str(s)).upper()


async def _attach_pdfs_to_category(category: str, files: "List[UploadFile]", current_user: dict) -> dict:
    """Step 2 of bulk flow — match each file to a pending row via filename
    convention `<DealID>_<PAN>_<SEGMENT>.<ext>` where SEGMENT is:
      real-estate-invoices       -> invoice_number
      investor-payment-details   -> transfer_date (YYYY-MM-DD accepted)
      investor-payment-receipts  -> receipt_number
    Skips rows already attached."""
    coll = db[_RE_UPLOAD_CATEGORY_COLLECTIONS[category]]
    seg_key = _RE_PDF_THIRD_SEGMENT[category]
    summary = {"matched": 0, "skipped": 0, "errors": []}

    for f in files:
        try:
            name = f.filename or ""
            stem = name.rsplit(".", 1)[0]
            # Expect "<DEAL_ID>_<PAN>_<SEGMENT>" — need at least 3 parts.
            parts = stem.split("_")
            if len(parts) < 3:
                summary["errors"].append(
                    f"{name}: filename must start with <DealID>_<PAN>_<{seg_key.replace('_', ' ').title()}>"
                )
                continue
            deal_id = parts[0].strip().upper()
            pan = parts[1].strip().upper()
            # Everything after the 2nd underscore is the SEGMENT (allows
            # segments that contain underscores, e.g. INV_001 or dates like
            # 2024_10_05). Normalised for comparison.
            segment_raw = "_".join(parts[2:]).strip()
            segment_norm = _norm_seg(segment_raw)

            if not segment_norm:
                summary["errors"].append(
                    f"{name}: missing <{seg_key.replace('_', ' ').title()}> segment"
                )
                continue

            # Fetch all pending rows for (deal_id, pan) and match the third
            # segment in-memory (normalised). This handles dates stored as
            # "2024-10-05" vs filenames "2024-10-05" or "20241005".
            base_query = {
                "opportunity_deal_id": deal_id,
                "investor_pan": pan,
                "pdf_uploaded": {"$ne": True},
            }
            candidates = await coll.find(base_query).to_list(500)
            target = None
            for c in candidates:
                if _norm_seg(c.get(seg_key)) == segment_norm:
                    target = c
                    break
            if not target:
                # fallback: exact pdf_filename_expected match (any segment)
                target = await coll.find_one({**base_query, "pdf_filename_expected": name})
            if not target:
                summary["errors"].append(
                    f"{name}: no pending row for Deal ID '{deal_id}', PAN '{pan}', "
                    f"{seg_key.replace('_', ' ')} '{segment_raw}'"
                )
                continue

            # Persist to object storage
            upload_id = target["id"]
            ext = name.rsplit(".", 1)[-1] if "." in name else "bin"
            object_key = build_object_path("real_estate", category, f"{upload_id}.{ext}")
            try:
                content = await f.read()
            finally:
                await f.close()
            result = await put_object_async(object_key, content, f.content_type or "application/octet-stream")

            await coll.update_one(
                {"id": upload_id},
                {"$set": {
                    "original_filename": name,
                    "storage_path": result["path"],
                    "content_type": f.content_type,
                    "file_size": result.get("size", len(content)),
                    "pdf_uploaded": True,
                    "is_deleted": False,
                    "pdf_attached_at": datetime.now(timezone.utc).isoformat(),
                }},
            )

            # Also flip the matching mirror on `Real_Estate_Master` so the
            # Holdings → View Details UI can show "PDF attached" state.
            opp_id = target.get("opportunity_id")
            if opp_id:
                if category == "real-estate-invoices":
                    await db.Real_Estate_Master.update_one(
                        {"id": opp_id, "investor_invoices.id": upload_id},
                        {"$set": {
                            "investor_invoices.$.pdf_uploaded": True,
                            "investor_invoices.$.original_filename": name,
                        }},
                    )
                elif category in ("investor-payment-details", "investor-payment-receipts"):
                    await db.Real_Estate_Master.update_one(
                        {"id": opp_id, "investor_payments.id": upload_id},
                        {"$set": {
                            "investor_payments.$.pdf_uploaded": True,
                            "investor_payments.$.original_filename": name,
                        }},
                    )
            summary["matched"] += 1
        except Exception as exc:
            summary["errors"].append(f"{getattr(f, 'filename', '?')}: {exc}")

    return summary


