# =============================================================================
# NAV Master scheduler (AMFI daily + 3Y + 5Y)
# =============================================================================
from nav_master_service import (  # noqa: E402
    run_nav_master_sync as _run_nav_master_sync,
    get_nav_master_status as _get_nav_master_status,
    fetch_31jan_2018_navs as _fetch_31jan_2018_navs,
)
import asyncio  # noqa: E402

nav_master_scheduler: Optional[AsyncIOScheduler] = None


async def _run_nav_master_job(trigger: str = "scheduled"):
    """Run NAV Master sync in a thread (blocking HTTP + pymongo inside)."""
    logger.info(f"[nav-master] starting ({trigger})")
    try:
        # Use motor's underlying pymongo client (sync) to avoid awaiting inside
        # the service. db.delegate yields the sync Database object.
        sync_db = db.delegate if hasattr(db, "delegate") else None
        if sync_db is None:
            # Fallback: build a short-lived sync client from MONGO_URL
            from pymongo import MongoClient
            sync_client = MongoClient(os.environ["MONGO_URL"])
            sync_db = sync_client[os.environ["DB_NAME"]]
        result = await asyncio.to_thread(_run_nav_master_sync, sync_db)
        logger.info(f"[nav-master] finished: {result}")
    except Exception as exc:
        logger.exception(f"[nav-master] failed: {exc}")


@app.on_event("startup")
async def _start_nav_master_scheduler():
    """Start the daily NAV Master scheduler on boot (2:30 AM IST)."""
    global nav_master_scheduler
    try:
        import pytz
        tz = pytz.timezone("Asia/Kolkata")
    except Exception:
        tz = timezone.utc
    if nav_master_scheduler and nav_master_scheduler.running:
        return
    nav_master_scheduler = AsyncIOScheduler(timezone=tz)
    nav_master_scheduler.add_job(
        _run_nav_master_job, CronTrigger(hour=2, minute=30, timezone=tz),
        id="nav_master_daily", name="NAV Master (AMFI) Sync @ 02:30 IST",
        kwargs={"trigger": "scheduled_daily"},
        replace_existing=True,
    )
    nav_master_scheduler.start()
    logger.info("[nav-master] scheduler started (02:30 IST daily)")


@app.on_event("shutdown")
async def _stop_nav_master_scheduler():
    global nav_master_scheduler
    if nav_master_scheduler and nav_master_scheduler.running:
        nav_master_scheduler.shutdown(wait=False)
        nav_master_scheduler = None


@api_router.post("/nav-master/run-now")
async def nav_master_run_now(current_user: dict = Depends(get_current_user)):
    """Trigger NAV Master sync (AMFI daily + 3Y + 5Y). Broker-only."""
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can run NAV Master sync")
    # Fire-and-forget; the job writes its own log entry.
    asyncio.create_task(_run_nav_master_job(trigger="manual"))
    return {"status": "started", "message": "NAV Master sync kicked off in background"}


@api_router.get("/nav-master/status")
async def nav_master_status(current_user: dict = Depends(get_current_user)):
    """Return NAV Master stats + next scheduled run + recent log entries."""
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can view NAV Master status")

    from pymongo import MongoClient
    sync_client = MongoClient(os.environ["MONGO_URL"])
    sync_db = sync_client[os.environ["DB_NAME"]]
    try:
        stats = _get_nav_master_status(sync_db)
    finally:
        sync_client.close()

    next_runs = []
    if nav_master_scheduler and nav_master_scheduler.running:
        for job in nav_master_scheduler.get_jobs():
            next_runs.append({
                "id": job.id,
                "name": job.name,
                "next_run_time": job.next_run_time.isoformat() if job.next_run_time else None,
            })

    recent_logs = await db.nav_master_logs.find({}, {"_id": 0}).sort("started_at", -1).limit(10).to_list(10)

    return {
        "scheduler_running": bool(nav_master_scheduler and nav_master_scheduler.running),
        "schedule": "Daily at 2:30 AM IST",
        "next_runs": next_runs,
        "stats": stats,
        "recent_logs": recent_logs,
    }


@api_router.post("/nav-master/fetch-31jan-2018")
async def nav_master_fetch_31jan_2018(current_user: dict = Depends(get_current_user)):
    """
    Fetch 31-Jan-2018 NAVs (LTCG grandfathering) from AMFI's historical
    endpoint and store into `nav_master.nav_2018` + `nav_master_history`.
    Broker-only. Runs synchronously so the caller sees the actual counts.
    """
    if current_user.get("role") != "broker":
        raise HTTPException(status_code=403, detail="Only brokers can fetch 31-Jan-2018 NAVs")

    from pymongo import MongoClient
    sync_client = MongoClient(os.environ["MONGO_URL"])
    sync_db = sync_client[os.environ["DB_NAME"]]
    try:
        result = await asyncio.to_thread(_fetch_31jan_2018_navs, sync_db)
    finally:
        sync_client.close()
    return {"status": "ok", "result": result}


@api_router.get("/nav-master/scheme/{scheme_code}")
async def nav_master_scheme(scheme_code: str, current_user: dict = Depends(get_current_user)):
    """Return the NAV Master document for a single scheme_code."""
    doc = await db.nav_master.find_one({"scheme_code": scheme_code}, {"_id": 0})
    if not doc:
        raise HTTPException(status_code=404, detail="Scheme not found in NAV Master")
    return doc


# Include the API router - MUST be at the end after all routes are defined
app.include_router(api_router)
